  for (const skill of kadocCrypterSkills) {
    for (const eventType of skill.passiveEventTypes ?? []) {
      if (eventType !== "game.started" && eventType !== "combat.resolved") continue;
      passives.register({
        skill,
        eventType,
        mandatory: true,
        condition: (state, event, playerId) => {
          if (!state.players[playerId]) return false;
          if (eventType === "game.started") return true;
          const winnerIds = (event.payload as { winnerIds?: unknown }).winnerIds;
          return Array.isArray(winnerIds) && winnerIds.includes(playerId);
        },
        handler: useKadocCrypter,
      });
    }
  }
