export const useSaberMagicResistance: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const abilityId = (payload as { abilityId?: unknown } | undefined)?.abilityId;
  if (abilityId === "noble-bloom") {
    if (!definitions) throw new Error("CARD_DEFINITIONS_CONTEXT_REQUIRED");
    const locationId = player.locationId;
    if (locationId !== "mountain" && locationId !== "city") throw new Error("NOBLE_BLOOM_NOT_IN_BATTLE");
    const participantIds = (state.board.locations[locationId] ?? []).filter((id) => !state.players[id]?.eliminated);
    const battleNobles = participantIds.flatMap((participantId) => {
      const participant = state.players[participantId];
      return participant.attack.map((instanceId) => {
        const instance = state.cards[instanceId];
        const definition = definitions[instance?.definitionId ?? ""];
        if (!instance?.active || instance.face !== "up" || !definition || !getCardAttributes(definition).includes("宝具")) return null;
        const manaCost = instance.paidCost ?? getCardPlayCost(state, definition, participant, instance, definitions);
        return { participantId, instance, manaCost };
      }).filter((entry): entry is NonNullable<typeof entry> => entry !== null);
    });
    if (battleNobles.length === 0) throw new Error("NOBLE_BLOOM_NO_NOBLE_PHANTASM");
    const highestCost = Math.max(...battleNobles.map((entry) => entry.manaCost));
    const ownsHighestPlayedThisRound = battleNobles.some((entry) => entry.participantId === player.id
      && entry.instance.playedRound === state.round
      && entry.manaCost === highestCost);
    if (!ownsHighestPlayedThisRound) throw new Error("NOBLE_BLOOM_NOT_HIGHEST");
    gainVictoryPoints(player, highestCost >= 4 ? 2 : 1);
    return;
  }
  if (abilityId === "magic-resistance") {
    if (!definitions) throw new Error("CARD_DEFINITIONS_CONTEXT_REQUIRED");
    const locationId = player.locationId;
    if (locationId !== "mountain" && locationId !== "city") throw new Error("MAGIC_RESISTANCE_NOT_IN_BATTLE");
    const opponentIds = (state.board.locations[locationId] ?? []).filter((id) => id !== player.id && !state.players[id]?.eliminated);
    const targets = opponentIds.flatMap((opponentId) => state.players[opponentId].attack)
      .map((instanceId) => ({ instance: state.cards[instanceId], definition: definitions[state.cards[instanceId]?.definitionId ?? ""] }))
      .filter(({ instance, definition }) => Boolean(instance?.active && instance.face === "up" && definition && getCardAttributes(definition).includes("魔术")));
    if (targets.length === 0) throw new Error("MAGIC_RESISTANCE_NO_TARGET");
    for (const { instance } of targets) {
      const modifiers = instance!.powerModifiers ?? [];
      const modifierId = `${skill.id}:magic-resistance:${instance!.instanceId}`;
      const withoutPrevious = modifiers.filter((modifier) => modifier.id !== modifierId);
      instance!.powerModifiers = [...withoutPrevious, { id: modifierId, sourceId: skill.id, kind: "set", value: 0, duration: "round" }];
    }
    return;
  }
  throw new Error("SABER_ABILITY_INVALID");
};

export const isSaberMagicResistanceLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  if (!definitions) return false;
  const player = state.players[playerId];
  const locationId = player?.locationId;
  if (!player || (locationId !== "mountain" && locationId !== "city")) return false;
  if (ability?.id === "noble-bloom") {
    const participantIds = (state.board.locations[locationId] ?? []).filter((id) => !state.players[id]?.eliminated);
    const battleNobles = participantIds.flatMap((participantId) => {
      const participant = state.players[participantId];
      return participant.attack.map((instanceId) => {
        const instance = state.cards[instanceId];
        const definition = definitions[instance?.definitionId ?? ""];
        if (!instance?.active || instance.face !== "up" || !definition || !getCardAttributes(definition).includes("宝具")) return null;
        const manaCost = instance.paidCost ?? getCardPlayCost(state, definition, participant, instance, definitions);
        return { participantId, instance, manaCost };
      }).filter((entry): entry is NonNullable<typeof entry> => entry !== null);
    });
    if (battleNobles.length === 0) return false;
    const highestCost = Math.max(...battleNobles.map((entry) => entry.manaCost));
    return battleNobles.some((entry) => entry.participantId === playerId
      && entry.instance.playedRound === state.round
      && entry.manaCost === highestCost);
  }
  if (ability?.id === "magic-resistance") {
    return (state.board.locations[locationId] ?? []).some((opponentId) => opponentId !== playerId && !state.players[opponentId]?.eliminated
      && state.players[opponentId].attack.some((instanceId) => {
        const instance = state.cards[instanceId];
        const definition = definitions[instance?.definitionId ?? ""];
        return Boolean(instance?.active && instance.face === "up" && definition && getCardAttributes(definition).includes("魔术"));
      }));
  }
  return false;
};


export const moveToNonWorkshop: SkillHandler = function moveToNonWorkshopHandler({ state, player, payload }) {
  const target = (payload as { locationId?: string } | undefined)?.locationId;
  if (!target || !nonWorkshopLocations.has(target)) throw new Error("SKILL_TARGET_LOCATION_INVALID");
  if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("SKILL_WINDOW_FORBIDDEN");
  if (player.flags.movementBlockedRound === state.round) throw new Error("PLAYER_MOVEMENT_BLOCKED");
  if (state.board.locations[target].length >= (capacities[target] ?? Number.MAX_SAFE_INTEGER)) {
    throw new Error("LOCATION_FULL");
  }

  removeFromAllLocations(state, player.id);
  state.board.locations[target].push(player.id);
  player.locationId = target;
  player.flags.deploymentBonusActive = false;
  state.step = "play-batch-draft";
};

export const isIndependentActionLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  if (player?.flags.independentActionDeferredRound === state.round) return false;
  return isIndependentActionOrderAllowed(state, playerId);
};

function isIndependentActionOrderAllowed(state: GameState, playerId: string): boolean {
  const eligibleOrder = state.turnOrder.filter((id) => !state.players[id]?.eliminated);
  const firstHalfCount = Math.floor(eligibleOrder.length / 2);
  const index = eligibleOrder.indexOf(playerId);
  return index >= 0 && index < firstHalfCount;
}

export const useIndependentAction: SkillHandler = ({ state, player }) => {
  if (player.flags.independentActionDeferredRound === state.round) throw new Error("INDEPENDENT_ACTION_DEFERRED");
  if (!isIndependentActionOrderAllowed(state, player.id)) throw new Error("SKILL_TURN_ORDER_FORBIDDEN");
  gainVictoryPoints(player, 3);
  player.flags.independentActionPenaltyRound = state.round;
};

const EURYALE_ARCHER_ID = "servant.euryale.skill.sc-euryale-1";
const EURYALE_SIREN_ID = "servant.euryale.skill.sc-euryale-2";
const EURYALE_EYE_ID = "servant.euryale.skill.sc-euryale-3";
const EURYALE_SIREN_HANDLER = "core.euryale-siren-song";
const EURYALE_EYE_HANDLER = "core.euryale-eye";
const EURYALE_EYE_RESOLVE = "core.euryale-eye-resolve";

function euryaleOwnedRestingSkillId(state: GameState, player: PlayerState, definitionId: string): string | undefined {
  return player.servantSkills.find((instanceId) => state.cards[instanceId]?.definitionId === definitionId);
}

function euryaleSirenPlayIds(state: GameState, player: PlayerState): [string, string] | undefined {
  const siren = euryaleOwnedRestingSkillId(state, player, EURYALE_SIREN_ID);
  const archer = euryaleOwnedRestingSkillId(state, player, EURYALE_ARCHER_ID);
  return siren && archer ? [siren, archer] : undefined;
}

export const isEuryaleSirenSongLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !definitions || ability?.id !== "siren-song-duet" || state.phase !== "outpost" || state.activePlayerId !== playerId || player.mana < 8) return false;
  const ids = euryaleSirenPlayIds(state, player);
  if (!ids) return false;
  try {
    let total = 0;
    for (const instanceId of ids) {
      const definition = assertCardCanEnterAttack({
        state, playerId, instanceId, definitions, faceDown: false,
        allowedSourceZones: ["servant-skills"], bypassTiming: true,
      });
      total += getCardPlayCost(state, definition, player, state.cards[instanceId], definitions);
    }
    return player.flags.infiniteMana === true || total <= player.mana;
  } catch {
    return false;
  }
};

/** Euryale Siren Song: outpost double play plus replacement of Archer Class for this round. */
export const useEuryaleSirenSong: SkillHandler = ({ state, player, skill, payload, definitions, emitEvent }) => {
  if (!definitions) throw new Error("EURYALE_SIREN_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "phase.transitioned") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
    if (event.previousPhase !== "action" || event.transition !== "next-phase" || state.phase !== "combat"
      || Number(player.flags.independentActionDeferredRound ?? -1) !== state.round
      || Number(player.flags.independentActionDeferredResolvedRound ?? -1) === state.round) return;
    player.flags.independentActionDeferredResolvedRound = state.round;
    if (player.locationId === "mountain" || player.locationId === "city") gainVictoryPoints(player, 3);
    return;
  }

  const abilityId = readSkillAbilityId(payload);
  if (abilityId !== "siren-song-duet" || !isEuryaleSirenSongLegal(state, player.id, skill, { id: abilityId } as SkillAbilityDefinition, definitions)) {
    throw new Error("EURYALE_SIREN_FORBIDDEN");
  }
  const ids = euryaleSirenPlayIds(state, player);
  if (!ids) throw new Error("EURYALE_SIREN_CARDS_REQUIRED");
  for (const instanceId of ids) {
    const definition = definitions[state.cards[instanceId].definitionId];
    const { paidMana } = addCardToAttack(state, player.id, instanceId, definitions, {
      payCost: true,
      allowedSourceZones: ["servant-skills"],
      bypassTiming: true,
      bypassFaceUpPlayLimit: true,
      recordFaceUpPlay: false,
    });
    emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: definition.id, face: "up", paidMana, attributes: getCardAttributes(definition), method: "euryale-siren" });
    emitEvent?.("card.used", { playerId: player.id, instanceId, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "euryale-siren" });
  }
  player.flags.independentActionDeferredRound = state.round;
  delete player.flags.independentActionPenaltyRound;
};

export const isEuryaleEyeLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player || ability?.id !== "eye-reveal-luck" || state.phase !== "action" || state.activePlayerId !== playerId) return false;
  return player.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === skill.id && card.controllerPlayerId === playerId && card.active && card.face === "up";
  });
};

function clearEuryaleEyeReveals(state: GameState, instanceIds: string[]): void {
  for (const instanceId of instanceIds) {
    const card = state.cards[instanceId];
    if (card) delete card.publiclyRevealed;
  }
}

const resolveEuryaleEye: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("EURYALE_EYE_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const revealed = Array.isArray(previous.revealedInstanceIds) ? previous.revealedInstanceIds.filter((id): id is string => typeof id === "string") : [];
  const candidates = Array.isArray(previous.candidateInstanceIds) ? previous.candidateInstanceIds.filter((id): id is string => typeof id === "string") : [];
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  clearEuryaleEyeReveals(state, revealed);
  if (selections.length === 0) return;
  if (selections.length !== 1 || !candidates.includes(selections[0])) throw new Error("EURYALE_EYE_SELECTION_INVALID");
  const instanceId = selections[0];
  const card = state.cards[instanceId];
  const owner = card?.ownerPlayerId ? state.players[card.ownerPlayerId] : undefined;
  const definition = card ? definitions[card.definitionId] : undefined;
  if (!card || !owner || !definition || !owner.hand.includes(instanceId) || definition.id !== "card.cardluck") throw new Error("EURYALE_EYE_LUCK_UNAVAILABLE");
  const paidMana = card.ownerPlayerId === player.id
    ? addCardToAttack(state, player.id, instanceId, definitions, { payCost: true, allowedSourceZones: ["hand"], bypassTiming: true }).paidMana
    : playBorrowedHandCardToAttack(state, player.id, instanceId, definitions).paidMana;
  emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: definition.id, face: "up", paidMana, attributes: getCardAttributes(definition), method: "euryale-eye" });
  emitEvent?.("card.used", { playerId: player.id, instanceId, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "euryale-eye" });
};

/** Euryale Eye: publicly reveal all co-located hands, then optionally play one revealed Luck. */
export const useEuryaleEye: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions || readSkillAbilityId(payload) !== "eye-reveal-luck" || !isEuryaleEyeLegal(state, player.id, skill, { id: "eye-reveal-luck" } as SkillAbilityDefinition)) {
    throw new Error("EURYALE_EYE_FORBIDDEN");
  }
  const locationId = player.locationId;
  if (!locationId) throw new Error("EURYALE_EYE_LOCATION_REQUIRED");
  const playerIds = (state.board.locations[locationId] ?? []).filter((id) => state.players[id] && !state.players[id].eliminated);
  const revealedInstanceIds = playerIds.flatMap((id) => [...state.players[id].hand]);
  for (const instanceId of revealedInstanceIds) state.cards[instanceId].publiclyRevealed = true;
  const candidateInstanceIds = revealedInstanceIds.filter((instanceId) => state.cards[instanceId]?.definitionId === "card.cardluck");
  if (candidateInstanceIds.length === 0) {
    clearEuryaleEyeReveals(state, revealedInstanceIds);
    return;
  }
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${EURYALE_EYE_ID}:resolve`;
  state.effectQueue.unshift({
    effectId,
    handlerId: EURYALE_EYE_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { revealedInstanceIds, candidateInstanceIds },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "euryale-eye-luck",
    options: candidateInstanceIds.map((instanceId) => {
      const card = state.cards[instanceId];
      const owner = card.ownerPlayerId ? state.players[card.ownerPlayerId] : undefined;
      return { id: instanceId, label: `${owner?.name ?? "?"} · ${definitions[card.definitionId]?.name ?? instanceId}` };
    }),
    min: 0,
    max: 1,
    allowCancel: true,
    continuationEffectId: effectId,
    submissions: {},
  });
};


export const useTerritoryCreation: SkillHandler = ({ state, player, skill, payload }) => {
  const trigger = payload as { eventId?: string; eventType?: string; event?: { playerId?: string; locationId?: string } };
  if (trigger.eventType !== "player.deployed" || trigger.event?.playerId !== player.id || trigger.event.locationId !== "workshop") {
    throw new Error("TERRITORY_CREATION_TRIGGER_INVALID");
  }
  if (!trigger.eventId) throw new Error("TERRITORY_CREATION_EVENT_ID_REQUIRED");
  state.effectQueue.push(createEffectFrame({
    effectId: `${trigger.eventId}:resources:${skill.id}:${player.id}`,
    handlerId: GAIN_RESOURCES_EFFECT,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { mana: 1, victoryPoints: 2 },
    state,
  }));
};

interface PendingCombatResolution {
  snapshot: CombatPowerSnapshot;
  responderIds: string[];
  nextResponderIndex: number;
}

function pendingCombat(state: GameState): PendingCombatResolution | null {
  const pending = state.modeState.pendingCombatResolution as PendingCombatResolution | undefined;
  return pending?.snapshot && Array.isArray(pending.responderIds) ? pending : null;
}

const SCATHACH_WISDOM_ID = "servant.scathach.skill.sc-scathach-1";
const SCATHACH_WISDOM_RESOLVE = "core.scathach-wisdom-resolve";
type ScathachWisdomMode = "zero-magic" | "move-anywhere" | "strict-second";

function scathachWisdomSource(state: GameState, playerId: string): string | undefined {
  return state.players[playerId]?.attack.find((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === SCATHACH_WISDOM_ID && card.active && card.face === "up";
  });
}

function scathachWisdomMode(state: GameState, playerId: string): ScathachWisdomMode | undefined {
  const sourceInstanceId = scathachWisdomSource(state, playerId);
  if (!sourceInstanceId) return undefined;
  const prefix = `scathach-wisdom-mode:${state.round}:`;
  const marker = state.cards[sourceInstanceId].modifiers.find((item) => item.startsWith(prefix));
  const mode = marker?.slice(prefix.length);
  return mode === "zero-magic" || mode === "move-anywhere" || mode === "strict-second" ? mode : undefined;
}

function scathachWisdomMoveCandidates(state: GameState, playerId: string, definitions?: Record<string, CardDefinition>): string[] {
  return ["workshop", "mountain", "city", "scouting"].filter((locationId) => {
    const draft = structuredClone(state) as GameState;
    try {
      movePlayerByEffect(draft, playerId, locationId, definitions);
      return true;
    } catch {
      return false;
    }
  });
}

export const useScathachWisdom: SkillHandler = ({ state, player, skill, payload, openDecision, definitions, emitEvent }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "card.played") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
    const sourceInstanceId = typeof event.instanceId === "string" ? event.instanceId : undefined;
    if (event.playerId !== player.id || event.definitionId !== skill.id || event.face !== "up" || !sourceInstanceId) return;
    const source = state.cards[sourceInstanceId];
    if (!source || source.zone !== "attack" || !source.active || source.face !== "up") throw new Error("SCATHACH_WISDOM_SOURCE_INVALID");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:mode`;
    state.effectQueue.unshift({
      effectId,
      handlerId: SCATHACH_WISDOM_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { kind: "mode", sourceInstanceId, round: state.round },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "scathach-wisdom-mode",
      options: [
        { id: "zero-magic", label: "将交战对手的魔术攻击威力变为0" },
        { id: "move-anywhere", label: "移动至任意地点" },
        { id: "strict-second", label: "按【气息遮断】的战力条件判定" },
      ],
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }

  const abilityId = readSkillAbilityId(payload);
  const mode = scathachWisdomMode(state, player.id);
  const sourceInstanceId = scathachWisdomSource(state, player.id);
  if (!sourceInstanceId || !mode) throw new Error("SCATHACH_WISDOM_MODE_NOT_SELECTED");
  if (abilityId === "wisdom-zero-magic") {
    if (mode !== "zero-magic" || state.phase !== "combat" || state.step !== "player-window" || state.activePlayerId !== player.id || !definitions) {
      throw new Error("SCATHACH_WISDOM_ZERO_MAGIC_FORBIDDEN");
    }
    const locationId = player.locationId;
    if (locationId !== "mountain" && locationId !== "city") throw new Error("SCATHACH_WISDOM_NOT_IN_BATTLE");
    for (const opponentId of sameBattlefieldOpponentIds(state, player.id, locationId)) {
      for (const instanceId of state.players[opponentId].attack) {
        const card = state.cards[instanceId];
        const definition = card ? definitions[card.definitionId] : undefined;
        if (!card?.active || card.face !== "up" || !definition || !getCardAttributes(definition).includes("魔术")) continue;
        const modifierId = `${skill.id}:zero-magic:${state.round}:${instanceId}`;
        card.powerModifiers = [
          ...(card.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
          { id: modifierId, sourceId: skill.id, kind: "set", value: 0, duration: "round" },
        ];
      }
    }
    return;
  }
  if (abilityId === "wisdom-move-anywhere") {
    if (mode !== "move-anywhere" || state.phase !== "action" || state.step !== "player-window" || state.activePlayerId !== player.id) {
      throw new Error("SCATHACH_WISDOM_MOVE_FORBIDDEN");
    }
    const candidates = scathachWisdomMoveCandidates(state, player.id, definitions);
    if (candidates.length === 0) throw new Error("SCATHACH_WISDOM_MOVE_UNAVAILABLE");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:move`;
    state.effectQueue.unshift({
      effectId,
      handlerId: SCATHACH_WISDOM_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { kind: "move", sourceInstanceId, round: state.round, candidates },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "scathach-wisdom-move",
      options: candidates.map((id) => ({ id, label: id })),
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  if (abilityId === "wisdom-strict-second") {
    if (mode !== "strict-second") throw new Error("SCATHACH_WISDOM_STRICT_SECOND_FORBIDDEN");
    const pending = pendingCombat(state);
    if (!pending || state.phase !== "combat" || state.step !== "post-power-response" || state.activePlayerId !== player.id
      || pending.responderIds[pending.nextResponderIndex] !== player.id || !strictSecondPowerCondition(pending.snapshot, player.id)) {
      throw new Error("SCATHACH_WISDOM_STRICT_SECOND_CONDITION_NOT_MET");
    }
    if (!definitions) throw new Error("SCATHACH_WISDOM_DEFINITIONS_REQUIRED");
    defeatStrictSecondHighestOpponents(state, pending.snapshot, player.id, definitions, emitEvent, SCATHACH_WISDOM_ID);
    return;
  }
  throw new Error("SCATHACH_WISDOM_ABILITY_INVALID");
};

const resolveScathachWisdom: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("SCATHACH_WISDOM_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) throw new Error("SCATHACH_WISDOM_DECISION_INVALID");
  const sourceInstanceId = typeof previous.sourceInstanceId === "string" ? previous.sourceInstanceId : undefined;
  const round = Number(previous.round);
  if (!sourceInstanceId || round !== state.round) throw new Error("SCATHACH_WISDOM_DECISION_STALE");
  const source = state.cards[sourceInstanceId];
  if (!source || source.ownerPlayerId !== player.id || source.definitionId !== SCATHACH_WISDOM_ID || source.zone !== "attack" || !source.active) {
    throw new Error("SCATHACH_WISDOM_SOURCE_INVALID");
  }
  const selected = decision.selections[0];
  if (previous.kind === "mode") {
    if (selected !== "zero-magic" && selected !== "move-anywhere" && selected !== "strict-second") throw new Error("SCATHACH_WISDOM_MODE_INVALID");
    const prefix = `scathach-wisdom-mode:${state.round}:`;
    source.modifiers = [...source.modifiers.filter((item) => !item.startsWith(prefix)), `${prefix}${selected}`];
    return;
  }
  if (previous.kind === "move") {
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    if (typeof selected !== "string" || !candidates.includes(selected)) throw new Error("SCATHACH_WISDOM_MOVE_TARGET_INVALID");
    const movement = movePlayerByEffect(state, player.id, selected, definitions);
    emitEvent?.("player.moved", { playerId: player.id, ...movement, sourceId: SCATHACH_WISDOM_ID });
    emitEvent?.("player.entered-location", { playerId: player.id, ...movement, method: "effect", sourceId: SCATHACH_WISDOM_ID });
    return;
  }
  throw new Error("SCATHACH_WISDOM_DECISION_INVALID");
};

export const isScathachWisdomLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || !scathachWisdomSource(state, playerId)) return false;
  const mode = scathachWisdomMode(state, playerId);
  if (ability.id === "wisdom-zero-magic") {
    return mode === "zero-magic" && state.phase === "combat" && state.step === "player-window" && state.activePlayerId === playerId
      && (player.locationId === "mountain" || player.locationId === "city");
  }
  if (ability.id === "wisdom-move-anywhere") {
    return mode === "move-anywhere" && state.phase === "action" && state.step === "player-window" && state.activePlayerId === playerId
      && scathachWisdomMoveCandidates(state, playerId, definitions).length > 0;
  }
  if (ability.id === "wisdom-strict-second") {
    const pending = pendingCombat(state);
    return Boolean(mode === "strict-second" && pending && state.phase === "combat" && state.step === "post-power-response"
      && state.activePlayerId === playerId && pending.responderIds[pending.nextResponderIndex] === playerId
      && strictSecondPowerCondition(pending.snapshot, playerId));
  }
  return false;
};

function scathachWisdomResponderCondition(state: GameState, playerId: string, snapshot: CombatPowerSnapshot): boolean {
  return scathachWisdomMode(state, playerId) === "strict-second" && strictSecondPowerCondition(snapshot, playerId);
}

const SERENITY_DANCE_ID = "servant.hassanser.skill.sc-hassanser-3";
const SERENITY_POISON_ID = "servant.hassanser.skill.sc-hassanser-2";
const SERENITY_WORKSHOP_BLOCK_HANDLER = "core.serenity-workshop-resource-block";


export const useSerenityDance: SkillHandler = ({ state, player, skill, payload, definitions, emitEvent }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType === "card.played") {
    if (event.playerId !== player.id || event.definitionId !== skill.id || event.face !== "up") return;
    const overrideId = `${skill.id}:double-poison:${state.round}`;
    player.skillUsageLimitOverrides = [
      ...(player.skillUsageLimitOverrides ?? []).filter((candidate) => candidate.id !== overrideId),
      { id: overrideId, sourceId: skill.id, targetSkillId: SERENITY_POISON_ID, limit: "twice-per-round", round: state.round },
    ];
    return;
  }

  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId === "serenity-dance-move") {
    if (!definitions || state.phase !== "action" || state.step !== "player-window" || state.activePlayerId !== player.id) throw new Error("SERENITY_DANCE_MOVE_WINDOW_INVALID");
    if (player.locationId !== "mountain" && player.locationId !== "city") throw new Error("SERENITY_DANCE_MOVE_SOURCE_INVALID");
    const destination = player.locationId === "mountain" ? "city" : "mountain";
    const movement = movePlayerByEffect(state, player.id, destination, definitions);
    emitEvent?.("player.moved", { playerId: player.id, ...movement, sourceId: skill.id });
    return movement;
  }
  if (abilityId === "serenity-dance-workshop-block") {
    if (state.phase !== "combat" || state.step !== "player-window" || state.activePlayerId !== player.id) throw new Error("SERENITY_DANCE_BLOCK_WINDOW_INVALID");
    scheduleEffect(state, {
      scheduleId: `${skill.id}:workshop-resource-block:${state.round + 1}:${player.id}`,
      sourceId: skill.id,
      handlerId: SERENITY_WORKSHOP_BLOCK_HANDLER,
      controllerPlayerId: player.id,
      payload: { targetRound: state.round + 1 },
      triggerEventType: "round.started",
      triggerRound: state.round + 1,
      expiresAfterRound: state.round + 1,
      once: true,
    });
    return;
  }
  throw new Error("SERENITY_DANCE_ABILITY_INVALID");
};

export const isSerenityDanceLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  if (!player || !ability) return false;
  if (ability.id === "serenity-dance-move") {
    return state.phase === "action" && state.step === "player-window" && state.activePlayerId === playerId
      && (player.locationId === "mountain" || player.locationId === "city");
  }
  if (ability.id === "serenity-dance-workshop-block") {
    return state.phase === "combat" && state.step === "player-window" && state.activePlayerId === playerId;
  }
  return false;
};

/** Generic scheduled effect: during its target round, nobody at Workshop can gain mana or victory points. */
export const useWorkshopResourceGainBlock: SkillHandler = ({ state, payload }) => {
  const scheduled = isRecord(payload) && isRecord(payload.scheduled) ? payload.scheduled : {};
  const targetRound = Number(scheduled.targetRound ?? state.round);
  if (targetRound !== state.round) throw new Error("WORKSHOP_RESOURCE_BLOCK_ROUND_INVALID");
  for (const target of Object.values(state.players)) target.flags.workshopResourceGainBlocked = true;
};


export const isPresenceConcealmentLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  if (!isPresenceConcealmentBaseLegal(state, playerId, skill)) return false;
  return isUsageAvailable(state.players[playerId].usage[skill.id], skill.limit, state.round, state.phase);
};

function isPresenceConcealmentBaseLegal(state: GameState, playerId: string, skill: import("./skill-types.ts").SkillDefinition): boolean {
  const pending = pendingCombat(state);
  if (!pending || state.phase !== "combat" || state.step !== "post-power-response") return false;
  if (state.activePlayerId !== playerId || pending.responderIds[pending.nextResponderIndex] !== playerId) return false;
  const player = state.players[playerId];
  const forbiddenTag = typeof player?.flags.skillUseForbiddenTag === "string" ? player.flags.skillUseForbiddenTag : undefined;
  if (forbiddenTag && skill.tags?.includes(forbiddenTag)) return false;
  const snapshot = pending.snapshot;
  if (!strictSecondPowerCondition(snapshot, playerId)) return false;
  return player.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === skill.id && card.active && card.face === "up";
  });
};

function presenceConcealmentCondition(
  state: GameState,
  playerId: string,
  skill: import("./skill-types.ts").SkillDefinition,
  snapshot: CombatPowerSnapshot,
): boolean {
  if (!strictSecondPowerCondition(snapshot, playerId)) return false;
  const player = state.players[playerId];
  if (player?.servantId !== skill.ownerId) return false;
  const forbiddenTag = typeof player.flags.skillUseForbiddenTag === "string" ? player.flags.skillUseForbiddenTag : undefined;
  if (forbiddenTag && skill.tags?.includes(forbiddenTag)) return false;
  if (!player.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === skill.id && card.active && card.face === "up";
  })) return false;
  if (!isUsageAvailable(player.usage[skill.id], skill.limit, state.round, state.phase)) return false;
  return true;
}

export const usePresenceConcealment: SkillHandler = ({ state, player, skill, definitions, emitEvent }) => {
  if (!isPresenceConcealmentBaseLegal(state, player.id, skill)) throw new Error("PRESENCE_CONCEALMENT_CONDITION_NOT_MET");
  if (!definitions) throw new Error("PRESENCE_CONCEALMENT_DEFINITIONS_REQUIRED");
  const snapshot = pendingCombat(state)!.snapshot;
  defeatStrictSecondHighestOpponents(state, snapshot, player.id, definitions, emitEvent, skill.id);
  player.flags[`presenceConcealmentUsedRound`] = state.round;
};

export function getPresenceConcealmentResponderIds(
  state: GameState,
  registry: SkillRegistry,
  snapshot: CombatPowerSnapshot,
): string[] {
  const skills = registry.list().filter((skill) => skill.handlerId === "core.presence-concealment" && skill.supportLevel === "FULL");
  return state.turnOrder.filter((playerId) => skills.some((skill) => presenceConcealmentCondition(state, playerId, skill, snapshot)));
}

/** All currently supported post-power responders, ordered by turn order. */
export function getCombatResponseResponderIds(
  state: GameState,
  registry: SkillRegistry,
  snapshot: CombatPowerSnapshot,
  definitions: Record<string, CardDefinition>,
): string[] {
  const presence = new Set(getPresenceConcealmentResponderIds(state, registry, snapshot));
  const scathach = new Set(state.turnOrder.filter((playerId) => scathachWisdomResponderCondition(state, playerId, snapshot)));
  return state.turnOrder.filter((playerId) => presence.has(playerId) || scathach.has(playerId)
    || isMisfortuneResponseAvailable(state, playerId, definitions, snapshot)
    || isNitocrisOfferingResponseAvailable(state, playerId, definitions, snapshot)
    || isKoyanskayaNf00ResponseAvailable(state, playerId, definitions, snapshot));
}

export const isRidingLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  if (state.phase !== "action" || state.activePlayerId !== playerId) return false;
  if (!skill.appendFromHand) return false;
  return state.players[playerId].attack.some((instanceId) => {
    const card = state.cards[instanceId];
    return (card?.definitionId === skill.id || card?.definitionId === `card.skill.${skill.id}`)
      && card.active
      && card.face === "up";
  });
};


export const useRiding: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!isRidingLegal(state, player.id, skill)) throw new Error("RIDING_CONDITION_NOT_MET");
  const instanceIds = (payload as { instanceIds?: unknown } | undefined)?.instanceIds;
  if (!Array.isArray(instanceIds) || instanceIds.some((id) => typeof id !== "string")) throw new Error("APPEND_CARD_LIST_INVALID");
  if (!definitions) throw new Error("CARD_DEFINITIONS_CONTEXT_REQUIRED");
  return addCardsToAttack(state, player.id, instanceIds, definitions, skill.appendFromHand!);
};


export const useSelfPlayCard: SkillHandler = ({ state, player, skill, definitions }) => {
  if (!definitions) throw new Error("CARD_DEFINITIONS_CONTEXT_REQUIRED");
  const instanceId = player.servantSkills.find((candidate) => state.cards[candidate]?.definitionId === skill.id);
  if (!instanceId) throw new Error("SELF_PLAY_CARD_NOT_AVAILABLE");
  const result = addCardToAttack(state, player.id, instanceId, definitions, { payCost: true, bypassSkillEightMana: true });
  return {
    cards: [{
      instanceId,
      definitionId: skill.id,
      paidMana: result.paidMana,
      revealsTrueName: false,
    }],
  };
};

const LADY_AVALON_PRETENDER_ID = "servant.ladyavalon.skill.sc-ladyavalon-2";
const LADY_AVALON_CLOSE_ABILITY = "ideal-land-close";

function ladyAvalonPretenderPrintedPower(state: GameState, player: PlayerState): number {
  const locked = Number(player.flags[`pretenderClassX:${LADY_AVALON_PRETENDER_ID}`]);
  return Number.isInteger(locked) && locked >= 0 ? locked : state.round;
}

function ladyAvalonMatchingAttackIds(
  state: GameState,
  player: PlayerState,
  skillId: string,
  definitions: Record<string, CardDefinition>,
): string[] {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") return [];
  const printedPower = ladyAvalonPretenderPrintedPower(state, player);
  return (state.board.locations[locationId] ?? []).flatMap((playerId) => state.players[playerId]?.attack ?? [])
    .filter((instanceId) => {
      const instance = state.cards[instanceId];
      const definition = instance ? definitions[instance.definitionId] : undefined;
      if (!instance?.active || instance.face !== "up" || !definition) return false;
      const linkedSkillId = definition.linkedSkillId ?? definition.id;
      if (linkedSkillId === skillId) return false;
      return Number(definition.cost ?? 0) === printedPower;
    });
}


export const useLadyAvalonIdealLand: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "game.started") {
    player.flags.climaxEventVictoryPointGainBlocked = true;
    return;
  }
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== LADY_AVALON_CLOSE_ABILITY) throw new Error("LADY_AVALON_IDEAL_LAND_ABILITY_INVALID");
  if (!definitions) throw new Error("LADY_AVALON_IDEAL_LAND_DEFINITIONS_REQUIRED");
  const instanceIds = ladyAvalonMatchingAttackIds(state, player, skill.id, definitions);
  if (instanceIds.length === 0) throw new Error("LADY_AVALON_IDEAL_LAND_NO_TARGET");
  for (const instanceId of instanceIds) {
    const ownerPlayerId = state.cards[instanceId]?.ownerPlayerId;
    if (!ownerPlayerId || !state.players[ownerPlayerId]) throw new Error("LADY_AVALON_IDEAL_LAND_TARGET_INVALID");
    closePlayerCard(state, ownerPlayerId, instanceId, definitions);
  }
};

export const isLadyAvalonIdealLandLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && ability?.id === LADY_AVALON_CLOSE_ABILITY && state.phase === "combat"
    && (player.locationId === "mountain" || player.locationId === "city")
    && ladyAvalonMatchingAttackIds(state, player, _skill.id, definitions).length > 0);
};


export const usePretenderClass: SkillHandler = ({ state, player, skill, payload }) => {
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (event.playerId !== player.id) return;
  const triggeredFlag = `pretenderClassTriggered:${skill.id}`;
  if (player.flags[triggeredFlag] === true) return;
  const instanceId = player.servantSkills.find((candidate) => state.cards[candidate]?.definitionId === skill.id);
  if (!instanceId) return;
  const xFlag = `pretenderClassX:${skill.id}`;
  const locked = Number(player.flags[xFlag]);
  const amount = Number.isInteger(locked) && locked >= 0 ? locked : state.round;
  player.flags[xFlag] = amount;
  player.flags[triggeredFlag] = true;
  gainVictoryPoints(player, amount);

  const instance = state.cards[instanceId];
  movePlayerCard(state, player.id, instanceId, "attack");
  instance.face = "up";
  instance.active = true;
  instance.residual = false;
  instance.paidCost = 0;
  instance.playedRound = state.round;
  const modifierId = `pretender-class:${skill.id}`;
  instance.powerModifiers = [
    ...(instance.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
    { id: modifierId, sourceId: skill.id, kind: "set", value: amount, duration: "game" },
  ];
  player.flags.illyaRoundAttackCommitted = true;
  player.flags.illyaRoundFaceUpAttack = true;
};

function findOwnedPhysicalSkill(state: GameState, playerId: string, skillId: string): string | undefined {
  const player = state.players[playerId];
  if (!player) return undefined;
  return [...player.masterSkills, ...player.servantSkills, ...player.hand, ...player.attack, ...player.discard]
    .find((instanceId) => state.cards[instanceId]?.definitionId === skillId && state.cards[instanceId]?.zone !== "removed");
}


export const useHelenaSearchUnknown: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType === "combat.resolved") {
    const locationId = typeof event.locationId === "string" ? event.locationId : undefined;
    const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds.filter((id): id is string => typeof id === "string") : [];
    const qualifyingWinner = winnerIds.some((winnerId) => winnerId !== player.id
      && !state.players[winnerId]?.eliminated
      && didPlayerRevealSkillThisRound(state, winnerId));
    if (locationId === player.locationId && qualifyingWinner) gainVictoryPoints(player, 2);
    return;
  }
  if (eventType !== "card.played" && eventType !== "servant.true-name-revealed") return;
  if (!definitions) throw new Error("HELENA_SEARCH_UNKNOWN_DEFINITIONS_REQUIRED");
  const rewardFlag = `helenaAllSkillsRevealedRewarded:${skill.id}`;
  if (player.flags[rewardFlag] === true) return;
  if (!areAllInGameSkillCardsFaceUp(state, definitions)) return;
  gainVictoryPoints(player, 5);
  player.flags[rewardFlag] = true;
};

/**
 * Generic residual template: while the source is active, positive mana gains
 * are replaced by equal power on that source.  At combat start every player at
 * the source location loses two mana; if anyone had less than two beforehand,
 * the residual source closes after the losses resolve.
 */
export const useManaGainReplacementResidual: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "card.played") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
    if (event.playerId !== player.id || event.definitionId !== skill.id || event.face !== "up") return;
    const sourceInstanceId = player.attack.find((instanceId) => {
      const card = state.cards[instanceId];
      return card?.definitionId === skill.id && card.active && card.face === "up";
    });
    if (!sourceInstanceId) throw new Error("MANA_GAIN_REPLACEMENT_SOURCE_NOT_ACTIVE");
    player.flags.manaGainReplacementSourceInstanceId = sourceInstanceId;
    player.flags.manaGainReplacementPower = 0;
    return;
  }
  if (eventType !== "phase.transitioned") return;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (event.previousPhase !== "action" || event.transition !== "next-phase" || state.phase !== "combat") return;
  const sourceInstanceId = player.flags.manaGainReplacementSourceInstanceId;
  if (typeof sourceInstanceId !== "string") return;
  const source = state.cards[sourceInstanceId];
  if (!source || source.definitionId !== skill.id || source.zone !== "attack" || !source.active || source.face !== "up") return;
  if (!player.locationId) return;
  const affectedPlayerIds = (state.board.locations[player.locationId] ?? []).filter((playerId) => !state.players[playerId]?.eliminated);
  const shouldClose = affectedPlayerIds.some((playerId) => state.players[playerId].mana < 2);
  for (const playerId of affectedPlayerIds) loseMana(state.players[playerId], 2);
  if (shouldClose) {
    if (!definitions) throw new Error("MANA_GAIN_REPLACEMENT_DEFINITIONS_REQUIRED");
    closePlayerCard(state, player.id, sourceInstanceId, definitions);
  }
};

function resolveOwnerAscensionTarget(
  player: PlayerState,
  definitions: Record<string, CardDefinition>,
): { skillId: string; definition: CardDefinition } | null {
  if (!player.masterId) return null;
  const candidateIds = [...new Set(Object.values(definitions)
    .filter((definition) => definition.isSkill
      && definition.skillOwnerType === "master"
      && definition.ownerDefinitionId === player.masterId
      && definition.tags?.includes("ascension"))
    .map((definition) => definition.linkedSkillId ?? definition.id))];
  if (candidateIds.length !== 1) return null;
  const skillId = candidateIds[0];
  const definition = definitions[skillId]
    ?? Object.values(definitions).find((candidate) => candidate.linkedSkillId === skillId);
  return definition ? { skillId, definition } : null;
}

/** Generic action ability that unlocks the current master's catalogue-only ascension skill. */
export const useUnlockOwnerAscension: SkillHandler = ({ state, player, definitions, emitEvent }) => {
  if (!definitions || !player.masterId) throw new Error("ASCENSION_UNLOCK_CONTEXT_REQUIRED");
  const target = resolveOwnerAscensionTarget(player, definitions);
  if (!target) throw new Error("ASCENSION_UNLOCK_TARGET_INVALID");
  const targetSkillId = target.skillId;
  if (target.definition.unlockLatestRound !== undefined && state.round > target.definition.unlockLatestRound) {
    throw new Error("ASCENSION_UNLOCK_WINDOW_CLOSED");
  }
  if (Object.values(state.cards).some((card) => card.ownerPlayerId === player.id
    && (card.definitionId === targetSkillId || definitions[card.definitionId]?.linkedSkillId === targetSkillId))) {
    throw new Error("ASCENSION_ALREADY_UNLOCKED");
  }
  const instanceId = `${player.id}:unlocked:${targetSkillId}`;
  createOwnedCardInstance(state, player.id, {
    instanceId,
    definitionId: targetSkillId,
    zone: "master-skills",
    face: "up",
    active: false,
  });
  emitEvent?.("skill.unlocked", {
    playerId: player.id,
    skillId: targetSkillId,
    definitionId: targetSkillId,
    instanceId,
    ownerDefinitionId: player.masterId,
  });
  return { instanceId, definitionId: targetSkillId };
};

export const isUnlockOwnerAscensionLegal: SkillLegalityPredicate = (state, playerId, _skill, _ability, definitions) => {
  const player = state.players[playerId];
  if (!player?.masterId || !definitions) return false;
  const target = resolveOwnerAscensionTarget(player, definitions);
  if (!target) return false;
  if (target.definition.unlockLatestRound !== undefined && state.round > target.definition.unlockLatestRound) return false;
  const targetSkillId = target.skillId;
  return !Object.values(state.cards).some((card) => card.ownerPlayerId === playerId
    && (card.definitionId === targetSkillId || definitions[card.definitionId]?.linkedSkillId === targetSkillId));
};

/** Move one same-battlefield opponent later in turn order one arrow forward. */
export const useMoveLaterSeatOpponent: SkillHandler = ({ state, player, skill, payload, definitions, emitEvent }) => {
  const source = player.attack.map((instanceId) => state.cards[instanceId])
    .find((card) => {
      const definition = card && definitions ? definitions[card.definitionId] : undefined;
      return (card?.definitionId === skill.id || definition?.linkedSkillId === skill.id) && card?.active && card.face === "up";
    });
  if (!source) throw new Error("MOVE_LATER_SEAT_SOURCE_REQUIRED");
  if (state.phase === "action" && source.reversed !== true) throw new Error("MOVE_LATER_SEAT_REVERSE_REQUIRED");
  if (state.phase === "combat" && source.reversed === true) throw new Error("MOVE_LATER_SEAT_NORMAL_FACE_REQUIRED");
  if (state.phase !== "action" && state.phase !== "combat") throw new Error("MOVE_LATER_SEAT_WINDOW_INVALID");
  if (player.locationId !== "mountain" && player.locationId !== "city") throw new Error("MOVE_LATER_SEAT_BATTLEFIELD_REQUIRED");
  const targetPlayerId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
  const sourceSeat = state.turnOrder.indexOf(player.id);
  const targetSeat = targetPlayerId ? state.turnOrder.indexOf(targetPlayerId) : -1;
  if (!target || target.eliminated || target.id === player.id || target.locationId !== player.locationId || sourceSeat < 0 || targetSeat <= sourceSeat) {
    throw new Error("MOVE_LATER_SEAT_TARGET_INVALID");
  }
  const targetLocationId = player.locationId === "mountain" ? "city" : "scouting";
  const movement = movePlayerByEffect(state, target.id, targetLocationId, definitions);
  emitEvent?.("player.moved", { playerId: target.id, ...movement });
  return movement;
};

export const isMoveLaterSeatOpponentLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  const source = player.attack.map((instanceId) => state.cards[instanceId])
    .find((card) => card?.definitionId === skill.id && card.active && card.face === "up");
  if (!source) return false;
  if (state.phase === "action" && source.reversed !== true) return false;
  if (state.phase === "combat" && source.reversed === true) return false;
  if (state.phase !== "action" && state.phase !== "combat") return false;
  const sourceSeat = state.turnOrder.indexOf(playerId);
  if (sourceSeat < 0) return false;
  if (player.locationId === "city" && state.board.locations.scouting.length >= 1) return false;
  return (state.board.locations[player.locationId] ?? []).some((targetId) => targetId !== playerId
    && !state.players[targetId]?.eliminated
    && state.turnOrder.indexOf(targetId) > sourceSeat
    && state.players[targetId]?.flags.movementBlockedRound !== state.round);
};

function readAttachedSupplyConfig(skill: SkillDefinition, payload: unknown): NonNullable<SkillDefinition["attachedSupplyAppend"]> | undefined {
  if (skill.attachedSupplyAppend) return skill.attachedSupplyAppend;
  const data = isRecord(payload) && isRecord(payload.attachedSupplyAppend) ? payload.attachedSupplyAppend : undefined;
  const definitionIds = Array.isArray(data?.definitionIds) ? data.definitionIds.filter((id): id is string => typeof id === "string") : undefined;
  if (!definitionIds?.length) return undefined;
  return {
    definitionIds,
    drawAfterAppend: Number.isInteger(data?.drawAfterAppend) ? Number(data.drawAfterAppend) : undefined,
    sourceEvent: data?.sourceEvent === "card.played" ? "card.played" : undefined,
  };
}

function findAttachedSupplyHost(state: GameState, playerId: string, skillId: string, payload: unknown): string | undefined {
  const data = isRecord(payload) && isRecord(payload.data) ? payload.data : isRecord(payload) ? payload : {};
  const requestedHost = typeof data.hostInstanceId === "string" ? data.hostInstanceId : undefined;
  if (requestedHost) {
    const card = state.cards[requestedHost];
    if (card?.ownerPlayerId !== playerId || card.zone === "removed") throw new Error("ATTACHED_SUPPLY_HOST_INVALID");
    if (card.definitionId !== skillId && card.definitionId !== `card.skill.${skillId}`) throw new Error("ATTACHED_SUPPLY_HOST_INVALID");
    return requestedHost;
  }
  return findOwnedPhysicalSkill(state, playerId, skillId);
}

function findAttachedSupplyCards(
  state: GameState,
  hostInstanceId: string,
  definitionIds: string[],
): string[] {
  return Object.values(state.cards)
    .filter((card) => card.zone === "attached"
      && card.attachedToInstanceId === hostInstanceId
      && definitionIds.includes(card.definitionId))
    .map((card) => card.instanceId);
}

function seedAttachedSupplyCards(
  state: GameState,
  playerId: string,
  skill: SkillDefinition,
  hostInstanceId: string,
  definitionIds: string[],
  definitions: Record<string, import("./content-types.ts").CardDefinition>,
): string[] {
  const sourceEffectId = `${skill.id}:attached-supply:${hostInstanceId}`;
  const existing = Object.values(state.cards).filter((card) => card.createdByEffectId === sourceEffectId);
  if (existing.length > 0) return existing.map((card) => card.instanceId);
  const created: string[] = [];
  for (const [index, definitionId] of definitionIds.entries()) {
    if (!definitions[definitionId]) throw new Error("ATTACHED_SUPPLY_CARD_DEFINITION_NOT_FOUND");
    const instanceId = `${playerId}:attached-supply:${skill.id}:${index + 1}`;
    const card = createDerivedCardInstance(state, playerId, {
      instanceId,
      definitionId,
      zone: "master-skills",
      face: "up",
      sourceEffectId,
    });
    attachCard(state, card.instanceId, hostInstanceId, "up");
    created.push(card.instanceId);
  }
  return created;
}

export const isAttachedSupplyAppendLegal: SkillLegalityPredicate = (state, playerId, skill, _ability, definitions) => {
  if (state.phase !== "action" || state.activePlayerId !== playerId || !definitions || !skill.attachedSupplyAppend?.definitionIds.length) return false;
  const hostInstanceId = findAttachedSupplyHost(state, playerId, skill.id, {});
  return Boolean(hostInstanceId && findAttachedSupplyCards(state, hostInstanceId, skill.attachedSupplyAppend.definitionIds).length > 0);
};

export const useAttachedSupplyAppend: SkillHandler = ({ state, player, skill, payload, randomInt, definitions, emitEvent }) => {
  if (!definitions) throw new Error("ATTACHED_SUPPLY_CARD_DEFINITIONS_REQUIRED");
  const config = readAttachedSupplyConfig(skill, payload);
  if (!config?.definitionIds.length) throw new Error("ATTACHED_SUPPLY_CONFIG_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "card.played") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
    const hostInstanceId = isRecord(payload) && typeof payload.hostInstanceId === "string"
      ? payload.hostInstanceId
      : typeof event.instanceId === "string"
        ? event.instanceId
        : undefined;
    if (!hostInstanceId) throw new Error("ATTACHED_SUPPLY_HOST_REQUIRED");
    return { created: seedAttachedSupplyCards(state, player.id, skill, hostInstanceId, config.definitionIds, definitions) };
  }

  const hostInstanceId = findAttachedSupplyHost(state, player.id, skill.id, payload);
  if (!hostInstanceId) throw new Error("ATTACHED_SUPPLY_HOST_REQUIRED");
  const candidates = findAttachedSupplyCards(state, hostInstanceId, config.definitionIds);
  if (candidates.length === 0) throw new Error("ATTACHED_SUPPLY_EMPTY");
  const data = isRecord(payload) && isRecord(payload.data) ? payload.data : isRecord(payload) ? payload : {};
  const requested = typeof data.instanceId === "string"
    ? data.instanceId
    : typeof data.attachedCardInstanceId === "string"
      ? data.attachedCardInstanceId
      : undefined;
  const requestedDefinitionId = typeof data.definitionId === "string" ? data.definitionId : undefined;
  const selected = requested
    ? requested
    : requestedDefinitionId
      ? candidates.find((instanceId) => state.cards[instanceId]?.definitionId === requestedDefinitionId)
      : candidates.length === 1
        ? candidates[0]
        : undefined;
  if (!selected || !candidates.includes(selected)) throw new Error("ATTACHED_SUPPLY_CARD_SELECTION_REQUIRED");
  const definition = definitions[state.cards[selected].definitionId];
  const { paidMana } = addCardToAttack(state, player.id, selected, definitions, { payCost: true, allowedSourceZones: ["attached"] });
  const drawCount = Math.max(0, Number(config.drawAfterAppend ?? 0));
  const drawn = drawCount > 0 ? drawCards(state, player.id, drawCount, randomInt ?? (() => 0), definitions) : [];
  emitEvent?.("card.played", { playerId: player.id, instanceId: selected, definitionId: definition.id, face: "up", paidMana, attributes: getCardAttributes(definition), method: "effect" });
  emitEvent?.("card.used", { playerId: player.id, instanceId: selected, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "effect" });
  return { hostInstanceId, card: { instanceId: selected, definitionId: definition.id, paidMana }, drawn };
};

function readSkillAbilityId(payload: unknown): string | undefined {
  if (!isRecord(payload)) return undefined;
  if (typeof payload.abilityId === "string") return payload.abilityId;
  return isRecord(payload.data) && typeof payload.data.abilityId === "string" ? payload.data.abilityId : undefined;
}

function selectedInstanceId(payload: unknown): string | undefined {
  const data = isRecord(payload) && isRecord(payload.data) ? payload.data : isRecord(payload) ? payload : {};
  return typeof data.instanceId === "string"
    ? data.instanceId
    : typeof data.targetInstanceId === "string"
      ? data.targetInstanceId
      : undefined;
}

function activeOwnedAttackIds(state: GameState, playerId: string): string[] {
  const player = state.players[playerId];
  if (!player) return [];
  return player.attack.filter((instanceId) => {
    const instance = state.cards[instanceId];
    return instance?.ownerPlayerId === playerId && instance.controllerPlayerId === playerId && instance.zone === "attack" && instance.active && instance.face === "up";
  });
}

function isCurrentRoundBasicAttack(
  state: GameState,
  playerId: string,
  instanceId: string,
  definitions: Record<string, CardDefinition>,
): boolean {
  const instance = state.cards[instanceId];
  const definition = definitions[instance?.definitionId ?? ""];
  return Boolean(instance
    && definition?.basic === true
    && instance.ownerPlayerId === playerId
    && instance.controllerPlayerId === playerId
    && instance.zone === "attack"
    && instance.active
    && instance.face === "up"
    && instance.playedRound === state.round);
}

export const isActiveAttackLifecycleBoostLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const config = skill.activeAttackLifecycleBoost;
  if (!config || !definitions) return false;
  if (ability?.id === config.residualAbilityId) {
    return activeOwnedAttackIds(state, playerId).some((instanceId) => isCurrentRoundBasicAttack(state, playerId, instanceId, definitions));
  }
  if (ability?.id === config.boostAbilityId) return activeOwnedAttackIds(state, playerId).length > 0;
  return false;
};

export const useActiveAttackLifecycleBoost: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("ACTIVE_ATTACK_DEFINITIONS_REQUIRED");
  const config = skill.activeAttackLifecycleBoost;
  if (!config) throw new Error("ACTIVE_ATTACK_LIFECYCLE_CONFIG_REQUIRED");
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === config.residualAbilityId) {
    const targetId = selectedInstanceId(payload);
    if (!targetId) throw new Error("ACTIVE_ATTACK_TARGET_REQUIRED");
    if (!isCurrentRoundBasicAttack(state, player.id, targetId, definitions)) throw new Error("ACTIVE_ATTACK_TARGET_INVALID");
    const target = state.cards[targetId];
    const expiresRound = state.round + Math.max(0, config.residualRoundOffset);
    target.residual = true;
    const prefix = "residual-until-round-end:";
    target.modifiers = [
      ...(target.modifiers ?? []).filter((marker) => !marker.startsWith(prefix)),
      `${prefix}${expiresRound}:${skill.id}`,
    ];
    return { targetInstanceId: targetId, residualUntilRoundEnd: expiresRound };
  }
  if (abilityId === config.boostAbilityId) {
    const boosted: string[] = [];
    for (const instanceId of activeOwnedAttackIds(state, player.id)) {
      const instance = state.cards[instanceId];
      const definition = definitions[instance.definitionId];
      if (!definition) continue;
      const attributes = normalizeCardAttributes([...(instance.attributeOverrides ?? getCardAttributes(definition)), config.boostAttribute]);
      instance.attributeOverrides = attributes;
      const modifierId = `${skill.id}:${config.boostAbilityId}:${state.round}:${instanceId}`;
      instance.powerModifiers = [
        ...(instance.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
        { id: modifierId, sourceId: skill.id, kind: "add", value: config.boostPower, duration: "round" },
      ];
      const prefix = "attribute-overrides-until-round-end:";
      instance.modifiers = [
        ...(instance.modifiers ?? []).filter((marker) => !marker.startsWith(prefix)),
        `${prefix}${state.round}:${skill.id}:${config.boostAttribute}`,
      ];
      boosted.push(instanceId);
    }
    return { boostedInstanceIds: boosted, attribute: config.boostAttribute, power: config.boostPower };
  }
  throw new Error("ACTIVE_ATTACK_ABILITY_INVALID");
};

function consumePhysicalSkill(state: GameState, playerId: string, skillId: string): void {
  const instanceId = findOwnedPhysicalSkill(state, playerId, skillId);
  if (!instanceId) throw new Error("CONSUMABLE_SKILL_CARD_NOT_FOUND");
  movePlayerCard(state, playerId, instanceId, "removed");
  const card = state.cards[instanceId];
  card.active = false;
  card.residual = false;
  card.face = "down";
}


export const useRevealTargetTrueNameAndExile: SkillHandler = ({ state, player, skill, payload }) => {
  const targetId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetId ? state.players[targetId] : undefined;
  if (!target || target.eliminated || !target.servantId || target.trueNameRevealed) throw new Error("TRUE_NAME_TARGET_INVALID");
  revealPlayerTrueName(state, target.id);
  consumePhysicalSkill(state, player.id, skill.id);
};

export const isRevealTargetTrueNameAndExileLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  return Boolean(findOwnedPhysicalSkill(state, playerId, skill.id)
    && Object.values(state.players).some((target) => !target.eliminated && Boolean(target.servantId) && !target.trueNameRevealed));
};


export const useBlockMovementAndExile: SkillHandler = ({ state, player, skill, payload }) => {
  const targetId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetId ? state.players[targetId] : undefined;
  if (!target || target.eliminated) throw new Error("MOVEMENT_BLOCK_TARGET_INVALID");
  target.flags.movementBlockedRound = state.round;
  consumePhysicalSkill(state, player.id, skill.id);
};

export const isBlockMovementAndExileLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  return Boolean(findOwnedPhysicalSkill(state, playerId, skill.id)
    && Object.values(state.players).some((target) => !target.eliminated));
};


export const useDavinciBlackKey: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "phase.transitioned") {
    const targetId = typeof player.flags.davinciBlackKeyTargetId === "string" ? player.flags.davinciBlackKeyTargetId : undefined;
    const target = targetId ? state.players[targetId] : undefined;
    const locationId = player.locationId;
    if (target && !target.eliminated && target.id !== player.id
      && (locationId === "mountain" || locationId === "city")
      && target.locationId === locationId) {
      target.defeated = true;
    }
    delete player.flags.davinciBlackKeyRound;
    delete player.flags.davinciBlackKeyTargetId;
    return;
  }
  const targetId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetId ? state.players[targetId] : undefined;
  if (!target || target.eliminated || target.id === player.id) throw new Error("DAVINCI_BLACK_KEY_TARGET_INVALID");
  player.flags.davinciBlackKeyRound = state.round;
  player.flags.davinciBlackKeyTargetId = target.id;
  consumePhysicalSkill(state, player.id, skill.id);
};

export const isDavinciBlackKeyLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  return Boolean(findOwnedPhysicalSkill(state, playerId, skill.id)
    && Object.values(state.players).some((target) => target.id !== playerId && !target.eliminated));
};


export const useZeroTargetStrengthAndExile: SkillHandler = ({ state, player, skill, payload }) => {
  const targetId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetId ? state.players[targetId] : undefined;
  if (!target || target.eliminated || target.id === player.id || !player.locationId || target.locationId !== player.locationId) {
    throw new Error("DAVINCI_SOUVENIR_TARGET_INVALID");
  }
  target.flags.davinciZeroStrengthRound = state.round;
  consumePhysicalSkill(state, player.id, skill.id);
};

export const isZeroTargetStrengthAndExileLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  return Boolean(player?.locationId && findOwnedPhysicalSkill(state, playerId, skill.id)
    && Object.values(state.players).some((target) => target.id !== playerId && !target.eliminated && target.locationId === player.locationId));
};


export const useImaginarySubmarineAndExile: SkillHandler = ({ state, player, skill, payload, emitEvent, definitions }) => {
  state.modeState.intrinsicFieldsNullifiedRound = state.round;
  const locationId = isRecord(payload) && typeof payload.locationId === "string" ? payload.locationId : undefined;
  if (locationId !== undefined) {
    const movement = movePlayerByEffect(state, player.id, locationId, definitions);
    emitEvent?.("player.moved", { playerId: player.id, ...movement });
  }
  consumePhysicalSkill(state, player.id, skill.id);
};


export const useSpiritronTransferAndExile: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("SPIRITRON_TRANSFER_CONTEXT_REQUIRED");
  const instanceId = isRecord(payload) && typeof payload.instanceId === "string" ? payload.instanceId : undefined;
  const card = instanceId ? state.cards[instanceId] : undefined;
  const definition = card ? definitions[card.definitionId] : undefined;
  if (!card || card.ownerPlayerId !== player.id || card.zone === "removed" || !definition || !getCardAttributes(definition).includes("宝具")) {
    throw new Error("SPIRITRON_TRANSFER_TARGET_INVALID");
  }
  addCardRuleModifier(player, {
    id: `${skill.id}:${state.round}:${instanceId}`,
    sourceId: skill.id,
    targetDefinitionIds: [card.definitionId],
    targetInstanceIds: [card.instanceId],
    waiveEightMana: true,
    costOverride: 0,
    duration: "round",
  });
  consumePhysicalSkill(state, player.id, skill.id);
};

export const isSpiritronTransferAndExileLegal: SkillLegalityPredicate = (state, playerId, skill, _ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && findOwnedPhysicalSkill(state, playerId, skill.id)
    && [...player.hand, ...player.attack, ...player.servantSkills].some((instanceId) => {
      const card = state.cards[instanceId];
      const definition = definitions[card?.definitionId ?? ""];
      return Boolean(definition && getCardAttributes(definition).includes("宝具"));
    }));
};


export const useInstantEnhancement: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("INSTANT_ENHANCEMENT_CONTEXT_REQUIRED");
  const instanceId = isRecord(payload) && typeof payload.instanceId === "string" ? payload.instanceId : undefined;
  const target = instanceId ? state.cards[instanceId] : undefined;
  const definition = target ? definitions[target.definitionId] : undefined;
  if (!target || target.ownerPlayerId !== player.id || target.zone !== "attack" || !target.active || target.face !== "up" || !definition) {
    throw new Error("INSTANT_ENHANCEMENT_TARGET_INVALID");
  }
  const sourceId = findOwnedPhysicalSkill(state, player.id, skill.id);
  if (!sourceId) throw new Error("CONSUMABLE_SKILL_CARD_NOT_FOUND");
  target.powerModifiers = [...(target.powerModifiers ?? []), {
    id: `${skill.id}:double:${instanceId}:${state.round}`,
    sourceId: skill.id,
    kind: "add",
    value: definition.basePower,
    duration: "round",
  }];
  const marker = `remove-at-round-end:${state.round}`;
  if (!target.modifiers.includes(marker)) target.modifiers.push(marker);
  if (!state.cards[sourceId].modifiers.includes(marker)) state.cards[sourceId].modifiers.push(marker);
};

export const isInstantEnhancementLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  return Boolean(player && findOwnedPhysicalSkill(state, playerId, skill.id)
    && player.attack.some((instanceId) => state.cards[instanceId]?.active && state.cards[instanceId]?.face === "up"));
};


export const useEmergencyTreatmentAndExile: SkillHandler = ({ state, player, skill, payload, randomInt, definitions }) => {
  const drawCount = isRecord(payload) && Number.isInteger(payload.drawCount) ? Number(payload.drawCount) : NaN;
  const discardIds = isRecord(payload) && Array.isArray(payload.discardInstanceIds)
    ? payload.discardInstanceIds.filter((id): id is string => typeof id === "string")
    : undefined;
  if (!Number.isInteger(drawCount) || drawCount < 0 || drawCount > 6 || !discardIds || new Set(discardIds).size !== discardIds.length) {
    throw new Error("EMERGENCY_TREATMENT_INPUT_INVALID");
  }
  drawCards(state, player.id, drawCount, randomInt ?? (() => 0), definitions);
  if (discardIds.some((instanceId) => !player.hand.includes(instanceId))) throw new Error("EMERGENCY_TREATMENT_DISCARD_INVALID");
  for (const instanceId of discardIds) movePlayerCard(state, player.id, instanceId, "discard");
  consumePhysicalSkill(state, player.id, skill.id);
  return { drawn: drawCount, discarded: [...discardIds] };
};


export const useDavinciFocus: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "round.ended") {
    player.flags.davinciFocusCount = Math.max(0, Number(player.flags.davinciFocusCount ?? 0)) + 1;
    return;
  }
  const count = Math.max(0, Number(player.flags.davinciFocusCount ?? 0));
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + count;
  consumePhysicalSkill(state, player.id, skill.id);
};

export const isDavinciFocusLegal: SkillLegalityPredicate = (state, playerId, skill) => Boolean(findOwnedPhysicalSkill(state, playerId, skill.id));


export const useAttachPowerUpgrade: SkillHandler = ({ state, player, skill, payload }) => {
  const hostInstanceId = isRecord(payload) && typeof payload.hostInstanceId === "string" ? payload.hostInstanceId : undefined;
  const host = hostInstanceId ? state.cards[hostInstanceId] : undefined;
  const sourceId = findOwnedPhysicalSkill(state, player.id, skill.id);
  if (!sourceId || !host || host.ownerPlayerId !== player.id || host.instanceId === sourceId || host.zone === "removed") {
    throw new Error("POWER_UPGRADE_TARGET_INVALID");
  }
  attachCard(state, sourceId, host.instanceId, "up");
};

export const isAttachPowerUpgradeLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  const sourceId = findOwnedPhysicalSkill(state, playerId, skill.id);
  return Boolean(player && sourceId && [...player.masterSkills, ...player.servantSkills, ...player.attack]
    .some((instanceId) => instanceId !== sourceId && state.cards[instanceId]?.zone !== "removed"));
};


export const useAlterEgoTransform: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("ALTER_EGO_CONTEXT_REQUIRED");
  const targetInstanceId = isRecord(payload) && typeof payload.targetInstanceId === "string" ? payload.targetInstanceId : undefined;
  const target = targetInstanceId ? state.cards[targetInstanceId] : undefined;
  const targetDefinition = target ? definitions[target.definitionId] : undefined;
  const sourceInstanceId = player.attack.find((instanceId) => {
    const instance = state.cards[instanceId];
    return instance?.definitionId === skill.id && instance.active && instance.face === "up";
  });
  if (!sourceInstanceId || !target || !targetDefinition || target.instanceId === sourceInstanceId
    || target.controllerPlayerId !== player.id || target.zone !== "attack" || target.face !== "up"
    || (target.playedRound !== state.round && target.joinedAttackRound !== state.round)) throw new Error("ALTER_EGO_TARGET_INVALID");
  const reverse = isRecord(payload) && payload.reverse === true;
  if (targetDefinition.hasReversalEffect) {
    if (!reverse) throw new Error("ALTER_EGO_REVERSE_REQUIRED");
    target.reversed = true;
    if (targetDefinition.revealsTrueNameOnReverse === true) revealPlayerTrueName(state, player.id);
    const prefix = "reversed-until-close:";
    target.modifiers = [
      ...(target.modifiers ?? []).filter((marker) => !marker.startsWith(prefix)),
      `${prefix}${skill.id}`,
    ];
  } else {
    if (reverse) throw new Error("ALTER_EGO_REVERSE_NOT_AVAILABLE");
    const attributes = isRecord(payload) && Array.isArray(payload.attributes) ? payload.attributes : undefined;
    if (!attributes || attributes.some((attribute) => typeof attribute !== "string" || !["力量", "迅捷", "魔术"].includes(attribute))
      || new Set(attributes).size !== attributes.length) throw new Error("ALTER_EGO_ATTRIBUTES_INVALID");
    target.attributeOverrides = [...attributes] as string[];
    const prefix = "attribute-overrides-until-close:";
    target.modifiers = [
      ...(target.modifiers ?? []).filter((marker) => !marker.startsWith(prefix)),
      `${prefix}${skill.id}`,
    ];
  }
  if (skill.alterEgoCloseSource !== false) closePlayerCard(state, player.id, sourceInstanceId, definitions);
};

export const isAlterEgoTransformLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player) return false;
  const source = player.attack.find((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === skill.id && card.active && card.face === "up";
  });
  return Boolean(source && player.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    return instanceId !== source && card?.controllerPlayerId === playerId && card.face === "up"
      && (card.playedRound === state.round || card.joinedAttackRound === state.round);
  }));
};


export const useKarnaVictoryForPower: SkillHandler = ({ player, payload }) => {
  const amount = isRecord(payload) && Number.isInteger(payload.amount) ? Number(payload.amount) : NaN;
  if (!Number.isInteger(amount) || amount < 0 || amount > 5 || amount > player.victoryPoints) {
    throw new Error("KARNA_VICTORY_AMOUNT_INVALID");
  }
  player.victoryPoints -= amount;
  gainMana(player, amount);
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + amount * 3;
};

const KARNA_ARMOR_EXILE_ABILITY = "exile-armor";
const KARNA_ARMOR_COMBAT_ABILITY = "glory-armor";


export const useKarnaSunArmor: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId === KARNA_ARMOR_EXILE_ABILITY) {
    consumePhysicalSkill(state, player.id, skill.id);
    return;
  }
  if (abilityId !== KARNA_ARMOR_COMBAT_ABILITY) throw new Error("KARNA_ARMOR_ABILITY_INVALID");
  if (!definitions) throw new Error("KARNA_ARMOR_DEFINITIONS_REQUIRED");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("KARNA_ARMOR_NOT_IN_BATTLEFIELD");
  if (!findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("KARNA_ARMOR_SOURCE_INACTIVE");
  const opponentIds = sameBattlefieldOpponentIds(state, player.id, locationId);
  if (opponentIds.length === 0) throw new Error("KARNA_ARMOR_NO_OPPONENT");
  const targets = opponentIds.flatMap((opponentId) => state.players[opponentId].attack.flatMap((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    return instance?.active && instance.face === "up" && definition?.basic === true ? [{ instanceId, instance }] : [];
  }));
  payManaCost(state, player, opponentIds.length, definitions);
  if (opponentIds.length > 0) player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + opponentIds.length;
  for (const { instanceId, instance } of targets) {
    const modifierId = `${skill.id}:${KARNA_ARMOR_COMBAT_ABILITY}:${state.round}:${instanceId}`;
    instance.powerModifiers = [
      ...(instance.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
      { id: modifierId, sourceId: skill.id, kind: "set", value: 0, duration: "round" },
    ];
  }
};

export const isKarnaSunArmorLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player) return false;
  if (ability?.id === KARNA_ARMOR_EXILE_ABILITY) return Boolean(findOwnedPhysicalSkill(state, playerId, skill.id));
  if (ability?.id !== KARNA_ARMOR_COMBAT_ABILITY || !definitions) return false;
  const locationId = player.locationId;
  if ((locationId !== "mountain" && locationId !== "city") || !findActiveOwnedSkillAttack(state, playerId, skill.id)) return false;
  const opponentCount = sameBattlefieldOpponentIds(state, playerId, locationId).length;
  if (opponentCount <= 0) return false;
  const draft = structuredClone(state) as GameState;
  try {
    payManaCost(draft, draft.players[playerId], opponentCount, definitions);
    return true;
  } catch {
    return false;
  }
};

function isLuckCard(definition: { name?: string }): boolean {
  // Lucky is a named basic card, not one of the five canonical attributes.
  return definition.name === "幸运";
}

export const isKarnaVictoryForPowerLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  return Boolean(player && state.phase === "action" && state.activePlayerId === playerId && player.victoryPoints >= 0);
};


export const useArjunaJudgment: SkillHandler = ({ state, player, skill, definitions }) => {
  if (!definitions) throw new Error("ARJUNA_JUDGMENT_CONTEXT_REQUIRED");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("ARJUNA_JUDGMENT_NOT_IN_BATTLE");
  const opponents = (state.board.locations[locationId] ?? [])
    .filter((id) => id !== player.id && !state.players[id]?.eliminated && !state.players[id]?.defeated);
  if (opponents.length === 0) throw new Error("ARJUNA_JUDGMENT_NO_OPPONENT");
  for (const instanceId of [...player.attack]) {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    if (instance?.active && instance.face === "up" && definition && isLuckCard(definition)) {
      closePlayerCard(state, player.id, instanceId, definitions);
    }
  }
  for (const opponentId of opponents) {
    const opponent = state.players[opponentId];
    const hasActiveNoblePhantasm = opponent.attack.some((instanceId) => {
      const instance = state.cards[instanceId];
      const definition = definitions[instance?.definitionId ?? ""];
      return Boolean(instance?.active && instance.face === "up" && definition
        && getCardAttributes(definition).includes("宝具"));
    });
    if (!hasActiveNoblePhantasm) opponent.defeated = true;
  }
};

export const isArjunaJudgmentLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  if (!player || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return (state.board.locations[player.locationId] ?? []).some((id) => id !== playerId
    && !state.players[id]?.eliminated && !state.players[id]?.defeated);
};


export const useBillyLuckDouble: SkillHandler = ({ state, player, payload, definitions, skill }) => {
  if (!definitions) throw new Error("BILLY_LUCK_CONTEXT_REQUIRED");
  const instanceId = isRecord(payload) && typeof payload.instanceId === "string" ? payload.instanceId : undefined;
  if (!instanceId) throw new Error("BILLY_LUCK_TARGET_REQUIRED");
  const instance = state.cards[instanceId];
  const definition = definitions[instance?.definitionId ?? ""];
  if (!instance || instance.ownerPlayerId !== player.id || instance.zone !== "attack"
    || instance.face !== "down" || instance.active || !definition?.basic
    || !isLuckCard(definition)) throw new Error("BILLY_LUCK_TARGET_INVALID");
  instance.face = "up";
  instance.active = true;
  const modifierId = `${skill.id}:double-luck:${instanceId}:${state.round}`;
  instance.powerModifiers = [
    ...(instance.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
    { id: modifierId, sourceId: skill.id, kind: "add", value: definition.basePower, duration: "round" },
  ];
};

export const isBillyLuckDoubleLegal: SkillLegalityPredicate = (state, playerId, _skill, _ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !definitions || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return player.attack.some((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    return Boolean(instance?.face === "down" && !instance.active && definition?.basic
      && isLuckCard(definition));
  });
};


export const useOrionLuckExile: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions) throw new Error("ORION_LUCK_CONTEXT_REQUIRED");
  const instanceIds = isRecord(payload) && Array.isArray(payload.instanceIds) ? payload.instanceIds : undefined;
  if (!instanceIds || instanceIds.length < 1 || instanceIds.length > 2 || instanceIds.some((id) => typeof id !== "string")) {
    throw new Error("ORION_LUCK_LIST_INVALID");
  }
  if (new Set(instanceIds).size !== instanceIds.length) throw new Error("DUPLICATE_CARD_INSTANCE");
  for (const instanceId of instanceIds) {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    if (!instance || instance.ownerPlayerId !== player.id || !["hand", "discard"].includes(instance.zone)
      || !definition || !isLuckCard(definition)) throw new Error("ORION_LUCK_TARGET_INVALID");
  }
  for (const instanceId of instanceIds) {
    movePlayerCard(state, player.id, instanceId, "removed");
    const instance = state.cards[instanceId];
    instance.face = "down";
    instance.active = false;
  }
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + instanceIds.length * 6;
};

export const isOrionLuckExileLegal: SkillLegalityPredicate = (state, playerId, _skill, _ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !definitions) return false;
  return [...player.hand, ...player.discard].some((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    return Boolean(definition && isLuckCard(definition));
  });
};


export const useScathachManaGate: SkillHandler = ({ state, player, definitions }) => {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("SCATHACH_MANA_GATE_NOT_IN_BATTLE");
  const opponents = (state.board.locations[locationId] ?? [])
    .filter((id) => id !== player.id && !state.players[id]?.eliminated && !state.players[id]?.defeated);
  if (opponents.length === 0) throw new Error("SCATHACH_MANA_GATE_NO_OPPONENT");
  for (const opponentId of opponents) {
    const opponent = state.players[opponentId];
    // Gate of Skye only counts mana actually lost to this ability. In particular,
    // Corrupted Grail Sakura cannot lose mana, so she loses 0 here and is defeated.
    const lost = loseMana(opponent, opponent.mana);
    if (lost < 8) {
      if (!definitions) throw new Error("SCATHACH_MANA_GATE_DEFINITIONS_REQUIRED");
      defeatPlayerByEffect(state, opponentId, player.id, definitions, undefined, { sourceId: "servant.scathach.skill.sc-scathach-3", manaLostByAbility: lost });
    }
  }
};

export const isScathachManaGateLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  if (!player || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return (state.board.locations[player.locationId] ?? []).some((id) => id !== playerId
    && !state.players[id]?.eliminated && !state.players[id]?.defeated);
};

/** Create an explicitly sized batch of temporary attacks from a phase ability. */
export const useCreateTemporaryAttacks: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const batch = skill.derivedAttackBatch;
  if (!batch || !Number.isInteger(batch.count) || batch.count <= 0 || !batch.definitionIds.length) {
    throw new Error("DERIVED_ATTACK_BATCH_INVALID");
  }
  if (!definitions) throw new Error("DERIVED_ATTACK_DEFINITIONS_REQUIRED");
  const requested = isRecord(payload) && Array.isArray(payload.attributes)
    ? payload.attributes.filter((value): value is string => typeof value === "string")
    : undefined;
  let definitionIds: string[];
  if (batch.definitionIds.length === 1) {
    definitionIds = Array.from({ length: batch.count }, () => batch.definitionIds[0]);
  } else {
    if (!requested || requested.length !== batch.count) throw new Error("DERIVED_ATTACK_ATTRIBUTES_REQUIRED");
    const attributeMap: Record<string, string> = { "力量": batch.definitionIds[0], "迅捷": batch.definitionIds[1] };
    definitionIds = requested.map((attribute) => attributeMap[attribute]).filter((id): id is string => Boolean(id));
    if (definitionIds.length !== batch.count) throw new Error("DERIVED_ATTACK_ATTRIBUTE_INVALID");
  }
  if (definitionIds.some((id) => !definitions[id])) throw new Error("DERIVED_ATTACK_DEFINITION_MISSING");
  const sourceEffectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}`;
  const options = definitionIds.map((definitionId, index) => ({
    instanceId: `${player.id}:derived-attack:${skill.id}:round-${state.round}:${index + 1}`,
    definitionId,
    zone: "attack" as const,
    face: "up" as const,
    active: true,
    residual: false,
    temporary: true,
    sourceEffectId,
  }));
  const instances = createDerivedCardInstances(state, player.id, options);
  player.flags.illyaRoundAttackCommitted = true;
  player.flags.illyaRoundFaceUpAttack = true;
  return {
    cards: instances.map((instance) => ({
      instanceId: instance.instanceId,
      definitionId: instance.definitionId,
      paidMana: 0,
      revealsTrueName: false,
    })),
  };
};

export const useSameBattlefieldOpponentPower: SkillHandler = ({ state, player, skill }) => {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("OPPONENT_POWER_NOT_IN_BATTLE");
  const amount = Number(skill.opponentCombatPowerBonus);
  if (!Number.isInteger(amount)) throw new Error("OPPONENT_POWER_BONUS_INVALID");
  const opponents = (state.board.locations[locationId] ?? [])
    .filter((id) => id !== player.id && !state.players[id]?.eliminated && !state.players[id]?.defeated)
    .map((id) => state.players[id])
    .filter((candidate): candidate is NonNullable<typeof candidate> => Boolean(candidate))
    .filter((candidate) => isOpponentPowerTargetEligible(candidate, skill, state.round));
  if (opponents.length === 0) throw new Error("OPPONENT_POWER_NO_TARGET");
  for (const opponent of opponents) opponent.flags.roundPowerBonus = Number(opponent.flags.roundPowerBonus ?? 0) + amount;
};

export const isSameBattlefieldOpponentPowerLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  const opponents = (state.board.locations[player.locationId] ?? []).filter((id) => id !== playerId
    && !state.players[id]?.eliminated && !state.players[id]?.defeated
    && isOpponentPowerTargetEligible(state.players[id], skill, state.round));
  return opponents.length > 0;
};

function isOpponentPowerTargetEligible(player: GameState["players"][string] | undefined, skill: Parameters<SkillLegalityPredicate>[2], round: number): boolean {
  if (!player) return false;
  if (skill.opponentRequiresNoDeploymentBonus === true && player.flags.deploymentBonusActive === true) return false;
  if (skill.opponentRequiresNoCommandSealThisRound === true && Number(player.flags.commandSealUsedRound ?? 0) === round) return false;
  return true;
}

export const usePowerBonusAndForwardMove: SkillHandler = ({ state, player, skill, emitEvent, definitions }) => {
  const amount = Number(skill.combatPowerBonus ?? 0);
  if (!Number.isInteger(amount)) throw new Error("COMBAT_POWER_BONUS_INVALID");
  if (amount !== 0) applyRoundPowerBonus(player, amount);
  const steps = Number(skill.moveForwardSteps ?? 0);
  if (!Number.isInteger(steps) || steps < 0) throw new Error("FORWARD_MOVE_STEPS_INVALID");
  const fallbackAmount = skill.combatPowerBonusIfMoveImpossible;
  if (fallbackAmount !== undefined && !Number.isInteger(fallbackAmount)) throw new Error("COMBAT_POWER_FALLBACK_BONUS_INVALID");
  const target = getForwardLocation(player.locationId, steps);
  if (!target) {
    if (fallbackAmount !== undefined) applyRoundPowerBonus(player, fallbackAmount);
    return;
  }
  try {
    const movement = movePlayerByEffect(state, player.id, target, definitions);
    emitEvent?.("player.moved", { playerId: player.id, ...movement });
    emitEvent?.("player.entered-location", { playerId: player.id, ...movement, method: "effect" });
  } catch (error) {
    if (error instanceof Error && ["LOCATION_FULL", "LOCATION_FORBIDDEN_BY_SITUATION", "PLAYER_MOVEMENT_BLOCKED", "PLAYER_NOT_ON_BOARD"].includes(error.message)) {
      if (fallbackAmount !== undefined) applyRoundPowerBonus(player, fallbackAmount);
      return;
    }
    throw error;
  }
};

function applyRoundPowerBonus(player: GameState["players"][string], amount: number): void {
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + amount;
}

function getForwardLocation(locationId: string | undefined, steps: number): string | undefined {
  if (!locationId || steps <= 0) return undefined;
  const currentIndex = forwardLocationOrder.indexOf(locationId as typeof forwardLocationOrder[number]);
  if (currentIndex < 0) return undefined;
  return forwardLocationOrder[currentIndex + steps];
}

const DIARMUID_YELLOW_ROSE_SKILL_ID = "servant.diarmuid.skill.sc-diarmuid-1";

export const useDiarmuidRedRose: SkillHandler = (context) => {
  const { state, player, skill, payload, definitions } = context;
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId === "add-yellow-rose") {
    if (!definitions) throw new Error("DIARMUID_RED_ROSE_CONTEXT_REQUIRED");
    const redRoseInstanceId = player.attack.find((instanceId) => {
      const card = state.cards[instanceId];
      return card?.definitionId === skill.id && card.active && card.face === "up";
    });
    if (!redRoseInstanceId) throw new Error("DIARMUID_RED_ROSE_NOT_ACTIVE");
    const yellowRoseInstanceId = player.servantSkills.find((instanceId) => {
      const card = state.cards[instanceId];
      return card?.definitionId === DIARMUID_YELLOW_ROSE_SKILL_ID && !card.active;
    });
    if (!yellowRoseInstanceId) throw new Error("DIARMUID_YELLOW_ROSE_NOT_AVAILABLE");
    closePlayerCard(state, player.id, redRoseInstanceId, definitions);
    const yellowRose = state.cards[yellowRoseInstanceId];
    movePlayerCard(state, player.id, yellowRoseInstanceId, "attack");
    yellowRose.face = "up";
    yellowRose.active = true;
    yellowRose.residual = false;
    yellowRose.paidCost = 0;
    yellowRose.playedRound = state.round;
    return {
      cards: [{
        instanceId: yellowRoseInstanceId,
        definitionId: DIARMUID_YELLOW_ROSE_SKILL_ID,
        paidMana: 0,
        revealsTrueName: false,
      }],
    };
  }
  if (abilityId === "zero-noble-phantasm") {
    return useZeroOpponentAttribute(context);
  }
  throw new Error("DIARMUID_RED_ROSE_ABILITY_INVALID");
};

export const isDiarmuidRedRoseLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player) return false;
  if (ability?.id === "add-yellow-rose") {
    const cost = ability.abilityCost ?? skill.abilityCost ?? 0;
    return player.mana >= cost
      && player.attack.some((instanceId) => {
        const card = state.cards[instanceId];
        return card?.definitionId === skill.id && card.active && card.face === "up";
      })
      && player.servantSkills.some((instanceId) => {
        const card = state.cards[instanceId];
        return card?.definitionId === DIARMUID_YELLOW_ROSE_SKILL_ID && !card.active;
      });
  }
  if (ability?.id === "zero-noble-phantasm") return isZeroOpponentAttributeLegal(state, playerId, skill, ability, definitions);
  return false;
};

const ANGRA_ALL_EVILS_ID = "servant.angra.skill.sc-angra-1";
const ANGRA_ALL_EVILS_HANDLER = "core.angra-all-evils";
const ANGRA_ALL_EVILS_RESOLVE = "core.angra-all-evils-resolve";
const ANGRA_ETERNAL_BINDING_ID = "servant.angra.skill.sc-angra-2";
const ANGRA_ETERNAL_BINDING_HANDLER = "core.angra-eternal-binding";
const ANGRA_AVENGER_DEFINITION_ID = "card.card-avenger";

function openAngraStealDecision(
  state: GameState,
  player: PlayerState,
  winnerIds: string[],
  remaining: number,
  openDecision: SkillContext["openDecision"],
): void {
  if (remaining <= 0) return;
  const eligibleWinnerIds = winnerIds.filter((id) => {
    const target = state.players[id];
    return Boolean(target && !target.eliminated && id !== player.id && target.victoryPoints > 0);
  });
  if (eligibleWinnerIds.length === 0) return;
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${ANGRA_ALL_EVILS_ID}:steal:${remaining}`;
  state.effectQueue.unshift({
    effectId,
    handlerId: ANGRA_ALL_EVILS_RESOLVE,
    sourceId: ANGRA_ALL_EVILS_ID,
    controllerPlayerId: player.id,
    payload: { stage: "steal", winnerIds: [...winnerIds], remaining },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "angra-all-evils-steal",
    options: [
      ...eligibleWinnerIds.map((id) => ({ id, label: state.players[id].name })),
      { id: "skip", label: "不选择" },
    ],
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
}

function resolveAngraDiscard(
  state: GameState,
  player: PlayerState,
  instanceIds: string[],
  winnerIds: string[],
  openDecision: SkillContext["openDecision"],
): void {
  if (new Set(instanceIds).size !== instanceIds.length || instanceIds.some((id) => !player.hand.includes(id))) {
    throw new Error("ANGRA_ALL_EVILS_DISCARD_INVALID");
  }
  let avengerCount = 0;
  for (const instanceId of instanceIds) {
    const instance = state.cards[instanceId];
    if (!instance) throw new Error("ANGRA_ALL_EVILS_DISCARD_INVALID");
    if (instance.definitionId === ANGRA_AVENGER_DEFINITION_ID) avengerCount += 1;
    movePlayerCard(state, player.id, instanceId, "discard");
    instance.face = "up";
    instance.active = false;
    instance.residual = false;
  }
  if (player.flags.combatLossRound === state.round && avengerCount > 0) {
    openAngraStealDecision(state, player, winnerIds, avengerCount, openDecision);
  }
}

function resolveAngraAllEvilsAtCombatEnd(
  state: GameState,
  player: PlayerState,
  payload: unknown,
  openDecision: SkillContext["openDecision"],
): void {
  if (player.flags.angraAllEvilsRound !== state.round) return;
  delete player.flags.angraAllEvilsRound;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  const previousLocations = isRecord(event.previousLocations) ? event.previousLocations : {};
  const winnersByLocation = isRecord(event.combatWinnerIdsByLocation) ? event.combatWinnerIdsByLocation : {};
  const locationId = typeof previousLocations[player.id] === "string" ? String(previousLocations[player.id]) : player.locationId;
  const rawWinners = locationId && Array.isArray(winnersByLocation[locationId]) ? winnersByLocation[locationId] : [];
  const winnerIds = rawWinners.filter((id): id is string => typeof id === "string" && id !== player.id && Boolean(state.players[id]));
  const discardCount = Math.min(4, player.hand.length);
  if (discardCount === 0) return;
  if (player.hand.length <= 4) {
    resolveAngraDiscard(state, player, [...player.hand], winnerIds, openDecision);
    return;
  }
  const candidates = [...player.hand];
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${ANGRA_ALL_EVILS_ID}:discard`;
  state.effectQueue.unshift({
    effectId,
    handlerId: ANGRA_ALL_EVILS_RESOLVE,
    sourceId: ANGRA_ALL_EVILS_ID,
    controllerPlayerId: player.id,
    payload: { stage: "discard", candidates, winnerIds },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "angra-all-evils-discard",
    options: candidates.map((id) => ({ id, label: id })),
    min: 4,
    max: 4,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
}

export const useAngraAllEvils: SkillHandler = ({ state, player, payload, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "combat.ending") {
    resolveAngraAllEvilsAtCombatEnd(state, player, payload, openDecision);
    return;
  }
  if (state.phase !== "action") throw new Error("ANGRA_ALL_EVILS_WINDOW_INVALID");
  player.flags.angraAllEvilsRound = state.round;
};

export const isAngraAllEvilsLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  return Boolean(player && state.phase === "action" && state.activePlayerId === playerId);
};

const resolveAngraAllEvils: SkillHandler = ({ state, player, payload, openDecision }) => {
  if (!isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("ANGRA_ALL_EVILS_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved") throw new Error("ANGRA_ALL_EVILS_DECISION_INVALID");
  if (previous.stage === "discard") {
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const winnerIds = Array.isArray(previous.winnerIds) ? previous.winnerIds.filter((id): id is string => typeof id === "string") : [];
    if (selections.length !== 4 || new Set(selections).size !== 4 || selections.some((id) => !candidates.includes(id))) {
      throw new Error("ANGRA_ALL_EVILS_DISCARD_INVALID");
    }
    resolveAngraDiscard(state, player, selections, winnerIds, openDecision);
    return;
  }
  if (previous.stage === "steal") {
    if (selections.length !== 1) throw new Error("ANGRA_ALL_EVILS_STEAL_INVALID");
    const winnerIds = Array.isArray(previous.winnerIds) ? previous.winnerIds.filter((id): id is string => typeof id === "string") : [];
    const remaining = Number(previous.remaining);
    if (!Number.isInteger(remaining) || remaining <= 0) throw new Error("ANGRA_ALL_EVILS_STEAL_INVALID");
    const selected = selections[0];
    if (selected !== "skip") {
      if (!winnerIds.includes(selected) || !state.players[selected] || state.players[selected].eliminated) throw new Error("ANGRA_ALL_EVILS_STEAL_INVALID");
      const target = state.players[selected];
      const stolen = Math.min(2, Math.max(0, target.victoryPoints));
      target.victoryPoints -= stolen;
      gainVictoryPoints(player, stolen);
    }
    openAngraStealDecision(state, player, winnerIds, remaining - 1, openDecision);
    return;
  }
  throw new Error("ANGRA_ALL_EVILS_STAGE_INVALID");
};

export const useAngraEternalBinding: SkillHandler = ({ state, player, definitions }) => {
  if (!definitions) throw new Error("ANGRA_ETERNAL_BINDING_DEFINITIONS_REQUIRED");
  const avengerIds = player.discard.filter((instanceId) => state.cards[instanceId]?.definitionId === ANGRA_AVENGER_DEFINITION_ID);
  if (avengerIds.length === 0) return;
  if (player.flags.combatLossRound === state.round - 1) {
    for (const instanceId of [...avengerIds]) {
      joinOwnedCardToAttack(state, player.id, instanceId, definitions, { allowedSourceZones: ["discard"] });
    }
    return;
  }
  for (const instanceId of [...avengerIds]) {
    movePlayerCard(state, player.id, instanceId, "hand");
    const instance = state.cards[instanceId];
    instance.face = "down";
    instance.active = false;
    instance.residual = false;
  }
};

export const isAngraEternalBindingLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  return Boolean(player && state.phase === "action" && state.activePlayerId === playerId
    && player.discard.some((instanceId) => state.cards[instanceId]?.definitionId === ANGRA_AVENGER_DEFINITION_ID));
};

const MUSASHI_SIX_REALMS_ID = "servant.musashi.skill.sc-musashi-1";
const MUSASHI_MASTERY_HANDLER = "core.musashi-mastery";
const MUSASHI_NITEN_HANDLER = "core.musashi-niten-ichiryu";


export const useMusashiMastery: SkillHandler = ({ state, player, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType !== "combat.resolved" || !event || !Array.isArray(event.winnerIds) || !isRecord(event.powers)) return;
  if (!event.winnerIds.includes(player.id) || !Object.prototype.hasOwnProperty.call(event.powers, player.id)) return;
  const opponentCount = Object.keys(event.powers).filter((id) => id !== player.id && Boolean(state.players[id])).length;
  const alreadyGained = player.flags.musashiBoundaryGainRound === state.round
    ? Number(player.flags.musashiBoundaryGainedThisRound ?? 0)
    : 0;
  if (!Number.isInteger(alreadyGained) || alreadyGained < 0) throw new Error("MUSASHI_MASTERY_ROUND_COUNT_INVALID");
  const gain = Math.max(0, Math.min(3 - alreadyGained, 1 + opponentCount));
  if (gain <= 0) return;
  const current = Number(player.flags.musashiBoundaryMarkers ?? 0);
  if (!Number.isInteger(current) || current < 0) throw new Error("MUSASHI_MASTERY_COUNT_INVALID");
  player.flags.musashiBoundaryMarkers = current + gain;
  player.flags.musashiBoundaryGainRound = state.round;
  player.flags.musashiBoundaryGainedThisRound = alreadyGained + gain;
};


export const useMusashiNitenIchiryu: SkillHandler = () => undefined;

const BILLY_THUNDERER_PASSIVE_ID = "servant.billy.skill.sc-billy-1";
const BILLY_THUNDERER_PASSIVE_HANDLER = "core.billy-thunderer-hidden-attacks";
const BILLY_THUNDERER_PASSIVE_RESOLVE = "core.billy-thunderer-hidden-attacks-resolve";
const BILLY_QUICK_DRAW_ID = "servant.billy.skill.sc-billy-3";
const BILLY_QUICK_DRAW_HANDLER = "core.billy-quick-draw";
const BILLY_QUICK_DRAW_RESOLVE = "core.billy-quick-draw-resolve";
const BILLY_QUICK_DRAW_ABILITY_ID = "quick-draw";

function clearBillyQuickDrawUsage(player: PlayerState): void {
  // Quick Draw explicitly permits repeating this action up to six times in the
  // same round. The generic phase-action default is once per round, so the
  // handler owns the printed six-use cap and clears only that synthetic marker.
  delete player.usage[`${BILLY_QUICK_DRAW_ID}:${BILLY_QUICK_DRAW_ABILITY_ID}`];
}

function billyHiddenAgilityBasicIds(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return player.attack.filter((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    return Boolean(instance && definition?.basic === true && instance.face === "down" && !instance.active
      && getCardAttributes(definition).includes("迅捷"));
  });
}

function closeBillyActiveSkillCards(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): void {
  for (const instanceId of [...player.attack]) {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    if (!instance?.active || instance.face !== "up" || definition?.isSkill !== true || definition.ownerDefinitionId !== "servant.billy") continue;
    closePlayerCard(state, player.id, instanceId, definitions);
  }
}

function activateBillyHiddenAttacks(state: GameState, player: PlayerState, instanceIds: string[], definitions: Record<string, CardDefinition>): void {
  if (new Set(instanceIds).size !== instanceIds.length) throw new Error("BILLY_THUNDERER_DUPLICATE_ATTACK");
  const candidates = new Set(billyHiddenAgilityBasicIds(state, player, definitions));
  if (instanceIds.some((id) => !candidates.has(id))) throw new Error("BILLY_THUNDERER_ATTACK_INVALID");
  closeBillyActiveSkillCards(state, player, definitions);
  for (const instanceId of instanceIds) {
    const instance = state.cards[instanceId];
    const definition = definitions[instance.definitionId];
    instance.face = "up";
    instance.active = true;
    instance.residual = definition.residual === true;
  }
}

function openBillyThundererCardDecision(
  state: GameState,
  player: PlayerState,
  candidates: string[],
  definitions: Record<string, CardDefinition>,
  openDecision: SkillContext["openDecision"],
): void {
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${BILLY_THUNDERER_PASSIVE_ID}:cards`;
  state.effectQueue.unshift({
    effectId,
    handlerId: BILLY_THUNDERER_PASSIVE_RESOLVE,
    sourceId: BILLY_THUNDERER_PASSIVE_ID,
    controllerPlayerId: player.id,
    payload: { stage: "cards", candidates: [...candidates] },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "billy-thunderer-hidden-attacks",
    options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
    min: 1,
    max: Math.min(2, candidates.length),
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
}

export const useBillyThundererHiddenAttacks: SkillHandler = ({ state, player, definitions, openDecision }) => {
  if (!definitions) throw new Error("BILLY_THUNDERER_DEFINITIONS_REQUIRED");
  const candidates = billyHiddenAgilityBasicIds(state, player, definitions);
  if (candidates.length === 0) throw new Error("BILLY_THUNDERER_NO_HIDDEN_ATTACK");
  if (candidates.length <= 2) {
    openBillyThundererCardDecision(state, player, candidates, definitions, openDecision);
    return;
  }
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${BILLY_THUNDERER_PASSIVE_ID}:mode`;
  state.effectQueue.unshift({
    effectId,
    handlerId: BILLY_THUNDERER_PASSIVE_RESOLVE,
    sourceId: BILLY_THUNDERER_PASSIVE_ID,
    controllerPlayerId: player.id,
    payload: { stage: "mode", candidates: [...candidates] },
    createdAtRevision: state.revision,
  });
  const options = [{ id: "up-to-two", label: "免费激活至多2张暗置迅捷基础攻击" }];
  if (player.mana >= 3 || player.flags.infiniteMana === true) options.push({ id: "all-for-three", label: "支付3点魔力，激活全部暗置迅捷基础攻击" });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "billy-thunderer-mode",
    options,
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isBillyThundererHiddenAttacksLegal: SkillLegalityPredicate = (state, playerId, _skill, _ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && state.phase === "combat" && state.activePlayerId === playerId
    && billyHiddenAgilityBasicIds(state, player, definitions).length > 0);
};

const resolveBillyThundererHiddenAttacks: SkillHandler = ({ state, player, payload, definitions, openDecision }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("BILLY_THUNDERER_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved") throw new Error("BILLY_THUNDERER_DECISION_INVALID");
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  if (previous.stage === "mode") {
    if (selections.length !== 1 || (selections[0] !== "up-to-two" && selections[0] !== "all-for-three")) throw new Error("BILLY_THUNDERER_MODE_INVALID");
    if (selections[0] === "all-for-three") {
      payManaCost(state, player, 3, definitions);
      player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + 3;
      activateBillyHiddenAttacks(state, player, candidates, definitions);
      return;
    }
    openBillyThundererCardDecision(state, player, candidates, definitions, openDecision);
    return;
  }
  if (previous.stage === "cards") {
    if (selections.length < 1 || selections.length > 2 || selections.some((id) => !candidates.includes(id))) throw new Error("BILLY_THUNDERER_ATTACK_SELECTION_INVALID");
    activateBillyHiddenAttacks(state, player, selections, definitions);
    return;
  }
  throw new Error("BILLY_THUNDERER_STAGE_INVALID");
};

function billyQuickDrawCount(player: PlayerState, round: number): number {
  if (player.flags.billyQuickDrawRound !== round) return 0;
  const count = Number(player.flags.billyQuickDrawCount ?? 0);
  if (!Number.isInteger(count) || count < 0 || count > 6) throw new Error("BILLY_QUICK_DRAW_COUNT_INVALID");
  return count;
}

function resolveBillyQuickDrawCard(
  state: GameState,
  player: PlayerState,
  instanceId: string,
  definitions: Record<string, CardDefinition>,
  randomInt: (maxExclusive: number) => number,
): void {
  if (!player.hand.includes(instanceId) || state.cards[instanceId]?.ownerPlayerId !== player.id) throw new Error("BILLY_QUICK_DRAW_HAND_CARD_REQUIRED");
  const used = billyQuickDrawCount(player, state.round);
  if (used >= 6) throw new Error("BILLY_QUICK_DRAW_LIMIT_REACHED");
  if (used > 0) {
    payManaCost(state, player, 1, definitions);
    player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + 1;
  }
  movePlayerCard(state, player.id, instanceId, "attack");
  const card = state.cards[instanceId];
  card.face = "down";
  card.active = false;
  card.residual = false;
  card.paidCost = 0;
  card.playedRound = state.round;
  card.playCount = Number(card.playCount ?? 0) + 1;
  player.flags.billyQuickDrawRound = state.round;
  player.flags.billyQuickDrawCount = used + 1;
  drawCards(state, player.id, 1, randomInt, definitions);
}

export const useBillyQuickDraw: SkillHandler = ({ state, player, payload, definitions, openDecision, randomInt }) => {
  if (!definitions) throw new Error("BILLY_QUICK_DRAW_DEFINITIONS_REQUIRED");
  const instanceId = isRecord(payload) && typeof payload.instanceId === "string" ? payload.instanceId : undefined;
  if (instanceId) {
    resolveBillyQuickDrawCard(state, player, instanceId, definitions, randomInt ?? ((max) => new StateRandom().integer(state, max)));
    clearBillyQuickDrawUsage(player);
    return;
  }
  if (player.hand.length === 0) throw new Error("BILLY_QUICK_DRAW_HAND_EMPTY");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${BILLY_QUICK_DRAW_ID}:card`;
  state.effectQueue.unshift({
    effectId,
    handlerId: BILLY_QUICK_DRAW_RESOLVE,
    sourceId: BILLY_QUICK_DRAW_ID,
    controllerPlayerId: player.id,
    payload: { candidates: [...player.hand] },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "billy-quick-draw-card",
    options: player.hand.map((id) => ({ id, label: definitions[state.cards[id]?.definitionId ?? ""]?.name ?? "未知卡牌" })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isBillyQuickDrawLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  if (!player || state.phase !== "action" || state.activePlayerId !== playerId || player.hand.length === 0) return false;
  const used = billyQuickDrawCount(player, state.round);
  return used < 6 && (used === 0 || player.mana >= 1 || player.flags.infiniteMana === true);
};

const resolveBillyQuickDraw: SkillHandler = ({ state, player, payload, definitions, randomInt }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("BILLY_QUICK_DRAW_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || selections.length !== 1 || !candidates.includes(selections[0])) throw new Error("BILLY_QUICK_DRAW_DECISION_INVALID");
  resolveBillyQuickDrawCard(state, player, selections[0], definitions, randomInt ?? ((max) => new StateRandom().integer(state, max)));
  clearBillyQuickDrawUsage(player);
};

const JAGUARMAN_DARK_FOREST_ID = "servant.jaguarman.skill.sc-jaguarman-2";
const JAGUARMAN_DARK_FOREST_HANDLER = "core.jaguarman-dark-forest";
const JAGUARMAN_DARK_FOREST_RESOLVE = "core.jaguarman-dark-forest-resolve";
const JAGUARMAN_DEATH_CLAW_ID = "servant.jaguarman.skill.sc-jaguarman-3";
const JAGUARMAN_DEATH_CLAW_HANDLER = "core.jaguarman-death-claw";
const JAGUARMAN_DEATH_CLAW_RESOLVE = "core.jaguarman-death-claw-resolve";
const JAGUARMAN_DEATH_CLAW_ABILITY = "death-claw-pull";

function jaguarmanDarkForestRestingInstance(state: GameState, player: PlayerState): string | undefined {
  return player.servantSkills.find((instanceId) => state.cards[instanceId]?.definitionId === JAGUARMAN_DARK_FOREST_ID);
}

function openJaguarmanDarkForestDecision(
  state: GameState,
  player: PlayerState,
  instanceId: string,
  definitions: Record<string, CardDefinition>,
  openDecision: SkillContext["openDecision"],
): void {
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${JAGUARMAN_DARK_FOREST_ID}:join`;
  state.effectQueue.unshift({
    effectId,
    handlerId: JAGUARMAN_DARK_FOREST_RESOLVE,
    sourceId: JAGUARMAN_DARK_FOREST_ID,
    controllerPlayerId: player.id,
    payload: { instanceId },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "jaguarman-dark-forest-join",
    options: [{ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? "【潜伏豹子的暗黑森林】" }],
    min: 1,
    max: 1,
    allowCancel: true,
    continuationEffectId: effectId,
    submissions: {},
  });
}


export const useJaguarmanDarkForest: SkillHandler = ({ state, player, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("JAGUARMAN_DARK_FOREST_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "player.entered-location") {
    if (!event || event.playerId !== player.id || event.locationId !== "scouting") return;
    const instanceId = jaguarmanDarkForestRestingInstance(state, player);
    if (instanceId) openJaguarmanDarkForestDecision(state, player, instanceId, definitions, openDecision);
    return;
  }
  if (eventType === "combat.resolved") {
    if (!event || event.locationId !== player.locationId || !isRecord(event.powers)
      || !Object.prototype.hasOwnProperty.call(event.powers, player.id)) return;
    const opponentCount = Object.keys(event.powers).filter((id) => id !== player.id && Boolean(state.players[id])).length;
    if (opponentCount <= 0) return;
    const active = findActiveOwnedSkillAttack(state, player.id, JAGUARMAN_DARK_FOREST_ID);
    if (active) closePlayerCard(state, player.id, active, definitions);
    return;
  }
};

const resolveJaguarmanDarkForest: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("JAGUARMAN_DARK_FOREST_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status === "cancelled") return;
  const instanceId = typeof previous.instanceId === "string" ? previous.instanceId : undefined;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || !instanceId || selections.length !== 1 || selections[0] !== instanceId
    || jaguarmanDarkForestRestingInstance(state, player) !== instanceId || player.locationId !== "scouting") {
    throw new Error("JAGUARMAN_DARK_FOREST_DECISION_INVALID");
  }
  joinOwnedCardToAttack(state, player.id, instanceId, definitions, { manaCost: 0, allowedSourceZones: ["servant-skills"] });
};

function isJaguarmanOpponentEngaged(state: GameState, playerId: string): boolean {
  const target = state.players[playerId];
  if (!target || target.eliminated || (target.locationId !== "mountain" && target.locationId !== "city")) return false;
  return (state.board.locations[target.locationId] ?? []).some((id) => id !== playerId && Boolean(state.players[id]) && !state.players[id].eliminated);
}

function jaguarmanDeathClawCandidates(state: GameState, player: PlayerState): string[] {
  if (player.locationId !== "mountain" && player.locationId !== "city") return [];
  const sourceIndex = forwardLocationOrder.indexOf(player.locationId);
  return state.turnOrder.filter((id) => {
    if (id === player.id) return false;
    const target = state.players[id];
    if (!target || target.eliminated || !target.locationId || isJaguarmanOpponentEngaged(state, id)) return false;
    const targetIndex = forwardLocationOrder.indexOf(target.locationId as typeof forwardLocationOrder[number]);
    return sourceIndex >= 0 && targetIndex >= 0 && Math.abs(targetIndex - sourceIndex) === 1;
  });
}

function readJaguarmanDeathClawPending(state: GameState, playerId: string): string[] {
  const map = state.modeState.jaguarmanDeathClawLowPowerByPlayer;
  if (!isRecord(map)) return [];
  const value = map[playerId];
  return Array.isArray(value) ? value.filter((id): id is string => typeof id === "string") : [];
}

function writeJaguarmanDeathClawPending(state: GameState, playerId: string, targetIds: string[]): void {
  const current = isRecord(state.modeState.jaguarmanDeathClawLowPowerByPlayer)
    ? state.modeState.jaguarmanDeathClawLowPowerByPlayer
    : {};
  state.modeState.jaguarmanDeathClawLowPowerByPlayer = { ...current, [playerId]: [...new Set(targetIds)] };
}

function clearJaguarmanDeathClawPending(state: GameState, playerId: string): void {
  const current = isRecord(state.modeState.jaguarmanDeathClawLowPowerByPlayer)
    ? { ...state.modeState.jaguarmanDeathClawLowPowerByPlayer }
    : {};
  delete current[playerId];
  if (Object.keys(current).length === 0) delete state.modeState.jaguarmanDeathClawLowPowerByPlayer;
  else state.modeState.jaguarmanDeathClawLowPowerByPlayer = current;
}


export const useJaguarmanDeathClaw: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, emitEvent }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "combat.resolved") {
    if (!event || event.locationId !== player.locationId || !isRecord(event.powers)
      || !Object.prototype.hasOwnProperty.call(event.powers, player.id)) return;
    const lowPowerIds = Object.entries(event.powers)
      .filter(([id, power]) => id !== player.id && Boolean(state.players[id]) && Number.isFinite(Number(power)) && Number(power) < 12)
      .map(([id]) => id);
    if (lowPowerIds.length > 0) writeJaguarmanDeathClawPending(state, player.id, lowPowerIds);
    return;
  }
  if (eventType === "combat.ending") {
    const targetIds = readJaguarmanDeathClawPending(state, player.id);
    for (const targetId of targetIds) {
      const target = state.players[targetId];
      if (target && !target.eliminated) adjustVictoryPoints(target, -2);
    }
    clearJaguarmanDeathClawPending(state, player.id);
    return;
  }

  const wrapped = isRecord(payload) ? payload : {};
  if (isRecord(wrapped.previous) && isRecord(wrapped.decision)) {
    if (!definitions) throw new Error("JAGUARMAN_DEATH_CLAW_DEFINITIONS_REQUIRED");
    const previous = wrapped.previous;
    const decision = wrapped.decision;
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
    if (decision.status !== "resolved" || selections.length !== 1 || !candidates.includes(selections[0])
      || !jaguarmanDeathClawCandidates(state, player).includes(selections[0])) throw new Error("JAGUARMAN_DEATH_CLAW_TARGET_INVALID");
    if (player.locationId !== "mountain" && player.locationId !== "city") throw new Error("JAGUARMAN_DEATH_CLAW_BATTLEFIELD_REQUIRED");
    const moved = movePlayerByEffect(state, selections[0], player.locationId, definitions);
    emitEvent?.("player.moved", { playerId: selections[0], ...moved, method: "effect", sourceId: skill.id });
    emitEvent?.("player.entered-location", { playerId: selections[0], ...moved, method: "effect", sourceId: skill.id });
    return;
  }

  const abilityId = typeof wrapped.abilityId === "string" ? wrapped.abilityId : undefined;
  if (abilityId !== JAGUARMAN_DEATH_CLAW_ABILITY) throw new Error("JAGUARMAN_DEATH_CLAW_ABILITY_INVALID");
  const candidates = jaguarmanDeathClawCandidates(state, player);
  if (candidates.length === 0) throw new Error("JAGUARMAN_DEATH_CLAW_NO_TARGET");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${JAGUARMAN_DEATH_CLAW_ID}:pull`;
  state.effectQueue.unshift({
    effectId,
    handlerId: JAGUARMAN_DEATH_CLAW_RESOLVE,
    sourceId: JAGUARMAN_DEATH_CLAW_ID,
    controllerPlayerId: player.id,
    payload: { candidates: [...candidates] },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "jaguarman-death-claw-target",
    options: candidates.map((id) => ({ id, label: state.players[id]?.name ?? id })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isJaguarmanDeathClawLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === JAGUARMAN_DEATH_CLAW_ABILITY && state.phase === "action" && state.activePlayerId === playerId
    && jaguarmanDeathClawCandidates(state, player).length > 0);
};

const resolveJaguarmanDeathClaw: SkillHandler = (context) => useJaguarmanDeathClaw(context);

const CORDAY_FOOLISH_PLAN_ID = "servant.corday.skill.sc-corday-2";
const CORDAY_FOOLISH_PLAN_HANDLER = "core.corday-foolish-plan";
const CORDAY_FOOLISH_PLAN_RESOLVE = "core.corday-foolish-plan-resolve";
const CORDAY_DREAM_ID = "servant.corday.skill.sc-corday-3";
const CORDAY_DREAM_HANDLER = "core.corday-dream";
const CORDAY_DREAM_RESOLVE = "core.corday-dream-resolve";
const CORDAY_DREAM_PLAY_SPECIALS = "dream-play-specials";
const CORDAY_DREAM_DEFEAT_TARGET = "dream-defeat-target";

function cordayPlanTargetCandidates(state: GameState, playerId: string): string[] {
  return state.turnOrder.filter((id) => id !== playerId && Boolean(state.players[id]) && !state.players[id].eliminated);
}

function openCordayPlanTargetDecision(state: GameState, player: PlayerState, openDecision: SkillContext["openDecision"]): void {
  const candidates = cordayPlanTargetCandidates(state, player.id);
  if (candidates.length === 0) return;
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${CORDAY_FOOLISH_PLAN_ID}:target`;
  state.effectQueue.unshift({
    effectId,
    handlerId: CORDAY_FOOLISH_PLAN_RESOLVE,
    sourceId: CORDAY_FOOLISH_PLAN_ID,
    controllerPlayerId: player.id,
    payload: { candidates },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "corday-foolish-plan-target",
    options: candidates.map((id) => ({ id, label: state.players[id]?.name ?? id })),
    min: 1,
    max: 1,
    allowCancel: true,
    continuationEffectId: effectId,
    submissions: {},
  });
}


export const useCordayFoolishPlan: SkillHandler = ({ state, player, payload, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "phase.transitioned") {
    if (!event || state.phase !== "outpost" || event.transition !== "next-phase" || player.locationId !== "workshop") return;
    if (player.flags.cordayPlanTargetRound === state.round) return;
    openCordayPlanTargetDecision(state, player, openDecision);
    return;
  }
  if (eventType === "combat.resolved") {
    if (!event || player.flags.cordayPlanTargetRound !== state.round) return;
    const targetPlayerId = typeof player.flags.cordayPlanTargetPlayerId === "string" ? player.flags.cordayPlanTargetPlayerId : undefined;
    if (!targetPlayerId || !Array.isArray(event.winnerIds) || !event.winnerIds.includes(player.id) || !isRecord(event.powers)) return;
    if (!Object.prototype.hasOwnProperty.call(event.powers, player.id) || !Object.prototype.hasOwnProperty.call(event.powers, targetPlayerId)) return;
    if (player.flags.cordayPlanRewardRound === state.round) return;
    gainVictoryPoints(player, 2);
    player.flags.cordayPlanRewardRound = state.round;
    return;
  }
};

const resolveCordayFoolishPlan: SkillHandler = ({ state, player, payload }) => {
  if (!isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("CORDAY_PLAN_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status === "cancelled") {
    player.flags.cordayPlanTargetRound = state.round;
    delete player.flags.cordayPlanTargetPlayerId;
    return;
  }
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || selections.length !== 1 || !candidates.includes(selections[0])
    || !cordayPlanTargetCandidates(state, player.id).includes(selections[0])) throw new Error("CORDAY_PLAN_DECISION_INVALID");
  player.flags.cordayPlanTargetRound = state.round;
  player.flags.cordayPlanTargetPlayerId = selections[0];
};

function cordayBasicSpecialHandCandidates(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return player.hand.filter((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    return Boolean(instance && definition?.basic === true && getCardAttributes(definition).includes("特殊"));
  });
}

function validateCordaySpecialBatch(
  state: GameState,
  player: PlayerState,
  instanceIds: string[],
  definitions: Record<string, CardDefinition>,
): Array<{ instanceId: string; cost: number }> {
  if (instanceIds.length === 0 || new Set(instanceIds).size !== instanceIds.length) throw new Error("CORDAY_DREAM_SPECIAL_SELECTION_INVALID");
  const candidates = new Set(cordayBasicSpecialHandCandidates(state, player, definitions));
  return instanceIds.map((instanceId) => {
    if (!candidates.has(instanceId)) throw new Error("CORDAY_DREAM_SPECIAL_SELECTION_INVALID");
    const definition = assertCardCanEnterAttack({ state, playerId: player.id, instanceId, definitions, faceDown: false });
    return { instanceId, cost: getCardPlayCost(state, definition, player, state.cards[instanceId], definitions) };
  });
}

function playCordaySpecialBatch(state: GameState, player: PlayerState, instanceIds: string[], definitions: Record<string, CardDefinition>): void {
  const validated = validateCordaySpecialBatch(state, player, instanceIds, definitions);
  const totalCost = validated.reduce((sum, item) => sum + item.cost, 0);
  payManaCost(state, player, totalCost, definitions);
  if (totalCost > 0) player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + totalCost;
  for (const { instanceId, cost } of validated) {
    addCardToAttack(state, player.id, instanceId, definitions, { payCost: false, bypassFaceUpPlayLimit: true });
    state.cards[instanceId].paidCost = cost;
  }
}

function cordayCurrentCombatTargetIds(state: GameState, player: PlayerState): string[] {
  if (player.flags.cordayPlanTargetRound !== state.round) return [];
  const targetId = typeof player.flags.cordayPlanTargetPlayerId === "string" ? player.flags.cordayPlanTargetPlayerId : undefined;
  if (!targetId || player.locationId !== "mountain" && player.locationId !== "city") return [];
  const target = state.players[targetId];
  if (!target || target.eliminated || target.locationId !== player.locationId) return [];
  return [targetId];
}


export const useCordayDream: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, emitEvent }) => {
  if (!definitions) throw new Error("CORDAY_DREAM_DEFINITIONS_REQUIRED");
  const wrapped = isRecord(payload) ? payload : {};
  if (isRecord(wrapped.previous) && isRecord(wrapped.decision)) {
    const previous = wrapped.previous;
    const decision = wrapped.decision;
    if (previous.stage !== "specials") throw new Error("CORDAY_DREAM_DECISION_INVALID");
    if (decision.status === "cancelled") return;
    const allowed = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
    if (decision.status !== "resolved" || selections.length === 0 || selections.some((id) => !allowed.includes(id))) throw new Error("CORDAY_DREAM_DECISION_INVALID");
    playCordaySpecialBatch(state, player, selections, definitions);
    return;
  }

  const abilityId = typeof wrapped.abilityId === "string" ? wrapped.abilityId : undefined;
  if (abilityId === CORDAY_DREAM_PLAY_SPECIALS) {
    const candidates = cordayBasicSpecialHandCandidates(state, player, definitions);
    if (candidates.length === 0) throw new Error("CORDAY_DREAM_NO_SPECIAL_ATTACK");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${CORDAY_DREAM_ID}:specials`;
    state.effectQueue.unshift({
      effectId,
      handlerId: CORDAY_DREAM_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "specials", candidates: [...candidates] },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "corday-dream-special-attacks",
      options: candidates.map((id) => ({ id, label: definitions[state.cards[id]?.definitionId ?? ""]?.name ?? id })),
      min: 1,
      max: candidates.length,
      allowCancel: true,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  if (abilityId === CORDAY_DREAM_DEFEAT_TARGET) {
    const targets = cordayCurrentCombatTargetIds(state, player);
    if (targets.length !== 1) throw new Error("CORDAY_DREAM_TARGET_NOT_ENGAGED");
    defeatPlayerByEffect(state, targets[0], player.id, definitions, emitEvent, { reason: "effect", sourceSkillId: skill.id });
    return;
  }
  throw new Error("CORDAY_DREAM_ABILITY_INVALID");
};

export const isCordayDreamLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || !definitions) return false;
  if (ability.id === CORDAY_DREAM_PLAY_SPECIALS) return state.phase === "action" && state.activePlayerId === playerId
    && cordayBasicSpecialHandCandidates(state, player, definitions).length > 0;
  if (ability.id === CORDAY_DREAM_DEFEAT_TARGET) return state.phase === "combat" && state.activePlayerId === playerId
    && cordayCurrentCombatTargetIds(state, player).length > 0;
  return false;
};

const resolveCordayDream: SkillHandler = (context) => useCordayDream(context);

const OKITA_SINCERITY_ID = "servant.okita.skill.sc-okita-1";
const OKITA_SINCERITY_HANDLER = "core.okita-sincerity-flag";
const OKITA_SINCERITY_RESOLVE = "core.okita-sincerity-flag-resolve";
const OKITA_SINCERITY_ABILITY = "sincerity-play-and-draw";
const OKITA_WEAK_ID = "servant.okita.skill.sc-okita-4";
const OKITA_WEAK_HANDLER = "core.okita-weak-constitution";
const OKITA_WEAK_CARD_ID = "card.x-weak";

function okitaSincerityCount(player: PlayerState, round: number): number {
  if (player.flags.okitaSincerityRound !== round) return 0;
  const count = Number(player.flags.okitaSincerityCount ?? 0);
  if (!Number.isInteger(count) || count < 0 || count > 3) throw new Error("OKITA_SINCERITY_COUNT_INVALID");
  return count;
}

function clearOkitaSinceritySyntheticUsage(player: PlayerState): void {
  delete player.usage[`${OKITA_SINCERITY_ID}:${OKITA_SINCERITY_ABILITY}`];
}

function okitaSincerityPlayableHandIds(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return player.hand.filter((instanceId) => {
    try {
      const definition = assertCardCanEnterAttack({ state, playerId: player.id, instanceId, definitions, faceDown: false });
      const cost = getCardPlayCost(state, definition, player, state.cards[instanceId], definitions);
      return player.flags.infiniteMana === true || player.mana >= cost;
    } catch {
      return false;
    }
  });
}


export const useOkitaSincerityFlag: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, randomInt }) => {
  if (!definitions) throw new Error("OKITA_SINCERITY_DEFINITIONS_REQUIRED");
  const wrapped = isRecord(payload) ? payload : {};
  if (isRecord(wrapped.previous) && isRecord(wrapped.decision)) {
    const previous = wrapped.previous;
    const decision = wrapped.decision;
    if (decision.status === "cancelled") {
      clearOkitaSinceritySyntheticUsage(player);
      return;
    }
    const allowed = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
    if (decision.status !== "resolved" || selections.length !== 1 || !allowed.includes(selections[0])
      || !okitaSincerityPlayableHandIds(state, player, definitions).includes(selections[0])) throw new Error("OKITA_SINCERITY_CARD_INVALID");
    addCardToAttack(state, player.id, selections[0], definitions, { payCost: true, bypassFaceUpPlayLimit: true });
    drawCards(state, player.id, 1, randomInt ?? ((max) => new StateRandom().integer(state, max)), definitions);
    const used = okitaSincerityCount(player, state.round) + 1;
    player.flags.okitaSincerityRound = state.round;
    player.flags.okitaSincerityCount = used;
    if (used < 3) clearOkitaSinceritySyntheticUsage(player);
    return;
  }

  if (wrapped.abilityId !== OKITA_SINCERITY_ABILITY) throw new Error("OKITA_SINCERITY_ABILITY_INVALID");
  if (okitaSincerityCount(player, state.round) >= 3) throw new Error("OKITA_SINCERITY_LIMIT_REACHED");
  const candidates = okitaSincerityPlayableHandIds(state, player, definitions);
  if (candidates.length === 0) throw new Error("OKITA_SINCERITY_NO_CARD");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${OKITA_SINCERITY_ID}:card`;
  state.effectQueue.unshift({
    effectId,
    handlerId: OKITA_SINCERITY_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { candidates },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "okita-sincerity-card",
    options: candidates.map((id) => ({ id, label: definitions[state.cards[id]?.definitionId ?? ""]?.name ?? id })),
    min: 1,
    max: 1,
    allowCancel: true,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isOkitaSincerityFlagLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === OKITA_SINCERITY_ABILITY && definitions
    && state.phase === "action" && state.activePlayerId === playerId
    && okitaSincerityCount(player, state.round) < 3
    && okitaSincerityPlayableHandIds(state, player, definitions).length > 0);
};

const resolveOkitaSincerityFlag: SkillHandler = (context) => useOkitaSincerityFlag(context);


export const useOkitaWeakConstitution: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType !== "game.started") return;
  for (const card of Object.values(state.cards)) {
    if (card.ownerPlayerId !== player.id) continue;
    const linkedSkillId = definitions?.[card.definitionId]?.linkedSkillId;
    if (card.definitionId !== OKITA_WEAK_CARD_ID && card.definitionId !== skill.id && linkedSkillId !== skill.id) continue;
    card.zoneMoveReplacement = {
      sourceId: skill.id,
      requestedDestination: "removed",
      replacementDestination: "discard",
    };
    card.combatHandRule = {
      sourceId: skill.id,
      revealWhenOwnerFights: true,
      setControllerCombatPowerToZero: true,
      discardAfterCombat: true,
    };
  }
};

const TRISTAN_LAMENT_ID = "servant.tristan.skill.sc-tristan-1";
const TRISTAN_LAMENT_HANDLER = "core.tristan-lament";
const TRISTAN_LAMENT_ABILITY = "lament-resonance";
const TRISTAN_LOVE_ID = "servant.tristan.skill.sc-tristan-2";
const TRISTAN_LOVE_HANDLER = "core.tristan-love";
const TRISTAN_LOVE_SHUFFLE_RESOLVE = "core.tristan-love-shuffle-resolve";
const TRISTAN_LOVE_UPKEEP_RESOLVE = "core.tristan-love-upkeep-resolve";

function tristanLoveXKey(sourceInstanceId: string): string {
  return `tristanLoveX:${sourceInstanceId}`;
}

function tristanLoveResetMarker(sourceInstanceId: string): string {
  const key = tristanLoveXKey(sourceInstanceId);
  return `structuredChoiceResetOnClose:${sourceInstanceId}:${key}`;
}

function activeTristanLoveInstance(state: GameState, player: PlayerState): string | undefined {
  return findActiveOwnedSkillAttack(state, player.id, TRISTAN_LOVE_ID);
}

function isPlayerInContestedBattlefield(state: GameState, player: PlayerState): boolean {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") return false;
  return (state.board.locations[locationId] ?? []).some((id) => id !== player.id && !state.players[id]?.eliminated);
}


export const useTristanLament: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("TRISTAN_LAMENT_DEFINITIONS_REQUIRED");
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== TRISTAN_LAMENT_ABILITY) throw new Error("TRISTAN_LAMENT_ABILITY_INVALID");
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("TRISTAN_LAMENT_SOURCE_NOT_ACTIVE");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("TRISTAN_LAMENT_NOT_IN_BATTLEFIELD");

  const combatCards: Array<{ instanceId: string; ownerPlayerId: string; basePower: number; residual: boolean }> = [];
  for (const participantId of state.board.locations[locationId] ?? []) {
    const participant = state.players[participantId];
    if (!participant || participant.eliminated) continue;
    for (const instanceId of participant.attack) {
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      if (!card || !definition || !card.active || card.face !== "up") continue;
      combatCards.push({
        instanceId,
        ownerPlayerId: participantId,
        basePower: calculateCombatCardBasePower(state, participant, instanceId, definitions),
        residual: card.residual === true || definition.residual === true,
      });
    }
  }
  const counts = new Map<number, number>();
  for (const card of combatCards) counts.set(card.basePower, (counts.get(card.basePower) ?? 0) + 1);
  const targets = combatCards.filter((card) => card.instanceId !== sourceInstanceId && !card.residual && (counts.get(card.basePower) ?? 0) >= 2);
  if (targets.length > 0) {
    const draft = structuredClone(state) as GameState;
    for (const target of targets) {
      closePlayerCard(draft, target.ownerPlayerId, target.instanceId, definitions, { closedByPlayerId: player.id });
    }
    for (const target of targets) {
      closePlayerCard(state, target.ownerPlayerId, target.instanceId, definitions, { closedByPlayerId: player.id });
    }
    return;
  }
  for (let index = 0; index < 3 && player.deck.length > 0; index += 1) {
    movePlayerCard(state, player.id, player.deck[0], "discard");
  }
};

export const isTristanLamentLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === TRISTAN_LAMENT_ABILITY && state.phase === "combat"
    && findActiveOwnedSkillAttack(state, playerId, skill.id) && isPlayerInContestedBattlefield(state, player));
};

function setTristanLoveX(player: PlayerState, sourceInstanceId: string, x: number): void {
  if (!Number.isInteger(x) || x < 2) throw new Error("TRISTAN_LOVE_X_INVALID");
  player.flags[tristanLoveXKey(sourceInstanceId)] = x;
  player.flags[tristanLoveResetMarker(sourceInstanceId)] = true;
}

function resolveTristanLoveDecision(context: SkillContext): void {
  const { state, player, payload, definitions, randomInt } = context;
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) {
    throw new Error("TRISTAN_LOVE_DECISION_INVALID");
  }
  const previous = payload.previous;
  const decision = payload.decision;
  const stage = typeof previous.stage === "string" ? previous.stage : undefined;
  const sourceInstanceId = typeof previous.sourceInstanceId === "string" ? previous.sourceInstanceId : undefined;
  if (!sourceInstanceId) throw new Error("TRISTAN_LOVE_SOURCE_INVALID");

  if (stage === "shuffle") {
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const selections = decision.status === "cancelled" ? []
      : Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
    if (decision.status !== "resolved" && decision.status !== "cancelled") throw new Error("TRISTAN_LOVE_SHUFFLE_DECISION_INVALID");
    if (new Set(selections).size !== selections.length || selections.some((id) => !candidates.includes(id) || !player.discard.includes(id))) {
      throw new Error("TRISTAN_LOVE_SHUFFLE_SELECTION_INVALID");
    }
    for (const instanceId of selections) movePlayerCard(state, player.id, instanceId, "deck");
    if (selections.length > 0) shuffleStructuredDeck(player.deck, randomInt ?? ((max) => new StateRandom().integer(state, max)));
    setTristanLoveX(player, sourceInstanceId, selections.length + 2);
    return;
  }

  if (stage === "upkeep") {
    const x = Number(previous.x);
    const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
    if (decision.status !== "resolved" || selections.length !== 1 || !["pay", "close"].includes(selections[0]) || !Number.isInteger(x) || x < 2) {
      throw new Error("TRISTAN_LOVE_UPKEEP_DECISION_INVALID");
    }
    const source = state.cards[sourceInstanceId];
    if (!source || source.ownerPlayerId !== player.id || source.definitionId !== TRISTAN_LOVE_ID || source.zone !== "attack" || !source.active || source.face !== "up") {
      throw new Error("TRISTAN_LOVE_SOURCE_NOT_ACTIVE");
    }
    if (selections[0] === "close") {
      closePlayerCard(state, player.id, sourceInstanceId, definitions);
      return;
    }
    payManaCost(state, player, x, definitions, "TRISTAN_LOVE_INSUFFICIENT_MANA");
    player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + x;
    return;
  }
  throw new Error("TRISTAN_LOVE_STAGE_INVALID");
}


export const useTristanLove: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("TRISTAN_LOVE_DEFINITIONS_REQUIRED");
  if (isRecord(payload) && isRecord(payload.previous) && isRecord(payload.decision)) {
    resolveTristanLoveDecision({ state, player, skill, payload, definitions, openDecision });
    return;
  }
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "card.played") {
    const sourceInstanceId = event && typeof event.instanceId === "string" ? event.instanceId : activeTristanLoveInstance(state, player);
    if (!sourceInstanceId || state.cards[sourceInstanceId]?.definitionId !== skill.id) return;
    const candidates = [...player.discard];
    if (candidates.length === 0) {
      setTristanLoveX(player, sourceInstanceId, 2);
      return;
    }
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:shuffle`;
    state.effectQueue.unshift({
      effectId,
      handlerId: TRISTAN_LOVE_SHUFFLE_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "shuffle", sourceInstanceId, candidates },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "tristan-love-shuffle",
      options: candidates.map((id) => ({ id, label: definitions[state.cards[id]?.definitionId ?? ""]?.name ?? id })),
      min: 0,
      max: candidates.length,
      allowCancel: true,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  if (eventType === "phase.transitioned") {
    const sourceInstanceId = activeTristanLoveInstance(state, player);
    if (!sourceInstanceId || !isPlayerInContestedBattlefield(state, player)) return;
    const x = Number(player.flags[tristanLoveXKey(sourceInstanceId)] ?? 2);
    if (!Number.isInteger(x) || x < 2) throw new Error("TRISTAN_LOVE_X_INVALID");
    if (player.flags.infiniteMana !== true && player.mana < x) {
      closePlayerCard(state, player.id, sourceInstanceId, definitions);
      return;
    }
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:upkeep`;
    state.effectQueue.unshift({
      effectId,
      handlerId: TRISTAN_LOVE_UPKEEP_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "upkeep", sourceInstanceId, x },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "tristan-love-upkeep",
      options: [{ id: "pay", label: `支付${x}点魔力` }, { id: "close", label: "关闭【高声颂爱】" }],
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
  }
};

const resolveTristanLoveShuffle: SkillHandler = (context) => resolveTristanLoveDecision(context);
const resolveTristanLoveUpkeep: SkillHandler = (context) => resolveTristanLoveDecision(context);

