function isLuckCardInstance(
  state: GameState,
  card: GameState["cards"][string],
  definition: CardDefinition,
  definitions: Record<string, CardDefinition>,
): boolean {
  return definition.id === "card.cardluck" || getCardInstanceAttributes(card, definition, state, definitions).includes("幸运");
}

function installInstanceCardPowerBonus(
  state: GameState,
  player: PlayerState,
  sourceInstanceId: string,
  sourceId: string,
  modifierKey: string,
  value: number,
): void {
  const id = `${modifierKey}:${sourceInstanceId}`;
  state.activeRuleModifiers = (state.activeRuleModifiers ?? []).filter((modifier) => modifier.id !== id);
  if (value === 0) return;
  state.activeRuleModifiers.push({
    id,
    sourceId,
    controllerPlayerId: player.id,
    sourceInstanceId,
    operation: "add",
    rule: "card_power",
    scope: { subject: "controller", cards: { instanceIds: [sourceInstanceId] } },
    value,
    duration: "while-source-active",
    createdRound: state.round,
  });
}

function activeArtoriaAltCurseInstance(state: GameState, player: PlayerState): string | undefined {
  return player.attack.find((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === ARTORIA_ALT_CURSE_ID && card.ownerPlayerId === player.id && card.face === "up" && card.active;
  });
}


export const useArtoriaAltExcaliburMorgan: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "card.played") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
    const instanceId = typeof event?.instanceId === "string" ? event.instanceId : undefined;
    if (!instanceId || event?.playerId !== player.id || event.definitionId !== skill.id || event.face !== "up") return;
    const lastRound = Number(player.flags.artoriaAltExcaliburLastPlayedRound ?? Number.NEGATIVE_INFINITY);
    const previousChain = Number(player.flags.artoriaAltExcaliburConsecutiveRounds ?? 0);
    const chain = lastRound === state.round
      ? Math.max(1, previousChain)
      : lastRound === state.round - 1
        ? Math.max(1, previousChain) + 1
        : 1;
    player.flags.artoriaAltExcaliburLastPlayedRound = state.round;
    player.flags.artoriaAltExcaliburConsecutiveRounds = chain;
    return;
  }
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== ARTORIA_ALT_EXCALIBUR_ABILITY) throw new Error("ARTORIA_ALT_EXCALIBUR_ABILITY_INVALID");
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("ARTORIA_ALT_EXCALIBUR_SOURCE_NOT_ACTIVE");
  const chainRound = Number(player.flags.artoriaAltExcaliburLastPlayedRound ?? Number.NEGATIVE_INFINITY);
  const chain = chainRound === state.round ? Number(player.flags.artoriaAltExcaliburConsecutiveRounds ?? 0) : 0;
  if (!Number.isInteger(chain) || chain < 1) throw new Error("ARTORIA_ALT_EXCALIBUR_CHAIN_INVALID");
  installInstanceCardPowerBonus(state, player, sourceInstanceId, skill.id, "artoria-alt-excalibur-chain", chain * 3);
  return { sourceInstanceId, consecutiveRounds: chain, powerBonus: chain * 3 };
};

export const isArtoriaAltExcaliburMorganLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player || ability?.id !== ARTORIA_ALT_EXCALIBUR_ABILITY || state.phase !== "action" || state.activePlayerId !== playerId) return false;
  return Boolean(findActiveOwnedSkillAttack(state, playerId, skill.id)
    && Number(player.flags.artoriaAltExcaliburLastPlayedRound ?? Number.NEGATIVE_INFINITY) === state.round
    && Number(player.flags.artoriaAltExcaliburConsecutiveRounds ?? 0) >= 1);
};


export const useArtoriaAltBlackeningCurse: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions) throw new Error("ARTORIA_ALT_CURSE_DEFINITIONS_REQUIRED");
  const sourceInstanceId = activeArtoriaAltCurseInstance(state, player);
  if (!sourceInstanceId || !isRecord(payload)) return;
  const eventType = typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload.event) ? payload.event : undefined;
  if (!event || event.playerId !== player.id) return;
  if (eventType === "attack.committed") {
    const committed = Array.isArray(event.committed) ? event.committed.filter((id): id is string => typeof id === "string") : [];
    if (committed.includes(sourceInstanceId)) return;
    const usedNoblePhantasm = committed.some((instanceId) => {
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      return Boolean(card?.face === "up" && definition && getCardInstanceAttributes(card, definition, state, definitions).includes("宝具"));
    });
    if (usedNoblePhantasm) closePlayerCard(state, player.id, sourceInstanceId, definitions);
    return;
  }
  if (eventType !== "card.used" || event.method === "play") return;
  const attributes = Array.isArray(event.attributes) ? event.attributes.map(String) : [];
  const definitionId = typeof event.definitionId === "string" ? event.definitionId : undefined;
  const definition = definitionId ? definitions[definitionId] : undefined;
  if (attributes.includes("宝具") || (definition && getCardAttributes(definition).includes("宝具"))) {
    closePlayerCard(state, player.id, sourceInstanceId, definitions);
  }
};


export const useKingGilGateOfBabylon: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("KING_GIL_GATE_DEFINITIONS_REQUIRED");
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== KING_GIL_GATE_ABILITY) throw new Error("KING_GIL_GATE_ABILITY_INVALID");
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("KING_GIL_GATE_SOURCE_NOT_ACTIVE");
  const source = state.cards[sourceInstanceId];
  const sourceDefinition = definitions[source.definitionId];
  if (!sourceDefinition) throw new Error("KING_GIL_GATE_SOURCE_DEFINITION_MISSING");
  const gainedAttributes = new Set<string>();
  const discarded = [...player.hand];
  for (const instanceId of discarded) {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    if (!card || !definition) throw new Error("KING_GIL_GATE_HAND_CARD_INVALID");
    for (const attribute of getCardInstanceAttributes(card, definition, state, definitions)) gainedAttributes.add(attribute);
  }
  for (const instanceId of discarded) movePlayerCard(state, player.id, instanceId, "discard");
  source.attributeOverrides = normalizeCardAttributes([...getCardAttributes(sourceDefinition), ...gainedAttributes]);
  const prefix = "attribute-overrides-until-close:";
  source.modifiers = [
    ...(source.modifiers ?? []).filter((marker) => !marker.startsWith(prefix)),
    `${prefix}${skill.id}`,
  ];
  return { discardedInstanceIds: discarded, gainedAttributes: [...gainedAttributes] };
};

export const isKingGilGateOfBabylonLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  return Boolean(ability?.id === KING_GIL_GATE_ABILITY && state.phase === "action" && state.activePlayerId === playerId
    && findActiveOwnedSkillAttack(state, playerId, skill.id));
};

const resolveKingGilMelammuDingir: SkillHandler = ({ state, player, payload, definitions, randomInt }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("KING_GIL_MELAMMU_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (previous.stage !== "prep-draw" || decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) {
    throw new Error("KING_GIL_MELAMMU_DECISION_INVALID");
  }
  const count = Number(decision.selections[0]);
  if (!Number.isInteger(count) || count < 0 || count > 2 || Number(previous.round) !== state.round) throw new Error("KING_GIL_MELAMMU_DRAW_COUNT_INVALID");
  if (count > 0) {
    const random = new StateRandom();
    drawCards(state, player.id, count, randomInt ?? ((maxExclusive) => random.integer(state, maxExclusive)), definitions);
  }
  return { extraDrawCount: count, optionalExtraStandardAttackCards: Number(player.flags.optionalExtraStandardAttackCards ?? 0) };
};


export const useKingGilMelammuDingir: SkillHandler = ({ state, player, payload, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "card.played") {
    if (!event || event.playerId !== player.id || event.definitionId !== KING_GIL_MELAMMU_ID || event.face !== "up") return;
    player.flags.kingGilMelammuPendingRound = state.round + 1;
    return;
  }
  if (eventType !== "round.started" || !event || Number(event.round) !== state.round
    || Number(player.flags.kingGilMelammuPendingRound ?? Number.NEGATIVE_INFINITY) !== state.round) return;
  delete player.flags.kingGilMelammuPendingRound;
  player.flags.optionalExtraStandardAttackCards = Math.max(1, Number(player.flags.optionalExtraStandardAttackCards ?? 0));
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${KING_GIL_MELAMMU_ID}:prep-draw`;
  state.effectQueue.unshift({
    effectId,
    handlerId: KING_GIL_MELAMMU_RESOLVE,
    sourceId: KING_GIL_MELAMMU_ID,
    controllerPlayerId: player.id,
    payload: { stage: "prep-draw", round: state.round },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "king-gil-melammu-prep-draw",
    options: [0, 1, 2].map((count) => ({ id: String(count), label: `额外抽${count}张牌` })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

function arjunaEndowedHeroCandidates(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return [...player.deck, ...player.discard].filter((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(card && card.ownerPlayerId === player.id && definition?.basic === true);
  });
}

function canArjunaEndowedHeroPlay(
  state: GameState,
  player: PlayerState,
  instanceId: string,
  definitions: Record<string, CardDefinition>,
): boolean {
  const draft = structuredClone(state) as GameState;
  try {
    payManaCost(draft, draft.players[player.id], 2, definitions);
    addCardToAttack(draft, player.id, instanceId, definitions, {
      payCost: true,
      allowedSourceZones: ["hand"],
      bypassFaceUpPlayLimit: true,
      bypassTiming: true,
    });
    return true;
  } catch {
    return false;
  }
}


export const useArjunaEndowedHero: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("ARJUNA_ENDOWED_DEFINITIONS_REQUIRED");
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== ARJUNA_ENDOWED_ABILITY) throw new Error("ARJUNA_ENDOWED_ABILITY_INVALID");
  const candidates = arjunaEndowedHeroCandidates(state, player, definitions);
  if (candidates.length === 0) throw new Error("ARJUNA_ENDOWED_NO_BASIC_CARD");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:choose`;
  state.effectQueue.unshift({
    effectId,
    handlerId: ARJUNA_ENDOWED_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { stage: "choose", candidates },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "arjuna-endowed-basic-card",
    options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isArjunaEndowedHeroLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && ability?.id === ARJUNA_ENDOWED_ABILITY
    && state.phase === "action" && state.activePlayerId === playerId
    && arjunaEndowedHeroCandidates(state, player, definitions).length > 0);
};

const resolveArjunaEndowedHero: SkillHandler = ({ state, player, payload, definitions, openDecision, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("ARJUNA_ENDOWED_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || selections.length !== 1) throw new Error("ARJUNA_ENDOWED_DECISION_INVALID");
  if (previous.stage === "choose") {
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const instanceId = selections[0];
    if (!candidates.includes(instanceId) || !arjunaEndowedHeroCandidates(state, player, definitions).includes(instanceId)) throw new Error("ARJUNA_ENDOWED_CARD_INVALID");
    movePlayerCard(state, player.id, instanceId, "hand");
    if (!canArjunaEndowedHeroPlay(state, player, instanceId, definitions)) return { instanceId, played: false };
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${ARJUNA_ENDOWED_ID}:play`;
    state.effectQueue.unshift({
      effectId,
      handlerId: ARJUNA_ENDOWED_RESOLVE,
      sourceId: ARJUNA_ENDOWED_ID,
      controllerPlayerId: player.id,
      payload: { stage: "play", instanceId },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "arjuna-endowed-play-card",
      options: [{ id: "play", label: "支付2点魔力并立即打出" }, { id: "keep", label: "加入手牌" }],
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  if (previous.stage !== "play") throw new Error("ARJUNA_ENDOWED_STAGE_INVALID");
  const instanceId = typeof previous.instanceId === "string" ? previous.instanceId : undefined;
  if (!instanceId || !player.hand.includes(instanceId)) throw new Error("ARJUNA_ENDOWED_CARD_NOT_IN_HAND");
  if (selections[0] === "keep") return { instanceId, played: false };
  if (selections[0] !== "play" || !canArjunaEndowedHeroPlay(state, player, instanceId, definitions)) throw new Error("ARJUNA_ENDOWED_PLAY_INVALID");
  const definition = definitions[state.cards[instanceId].definitionId];
  payManaCost(state, player, 2, definitions);
  player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + 2;
  const { paidMana } = addCardToAttack(state, player.id, instanceId, definitions, {
    payCost: true,
    allowedSourceZones: ["hand"],
    bypassFaceUpPlayLimit: true,
    bypassTiming: true,
  });
  emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: definition.id, face: "up", paidMana, attributes: getCardAttributes(definition), method: "endowed-hero" });
  emitEvent?.("card.used", { playerId: player.id, instanceId, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "endowed-hero" });
  if (definition.revealsTrueNameOnPlay === true && !player.trueNameRevealed) revealPlayerTrueName(state, player.id);
  return { instanceId, played: true, paidMana };
};

function arjunaAgniSourceActive(state: GameState, player: PlayerState): boolean {
  const sourceInstanceId = typeof player.flags.arjunaAgniSourceInstanceId === "string" ? player.flags.arjunaAgniSourceInstanceId : undefined;
  const source = sourceInstanceId ? state.cards[sourceInstanceId] : undefined;
  return Boolean(source && source.ownerPlayerId === player.id && source.definitionId === ARJUNA_AGNI_ID
    && source.zone === "attack" && source.face === "up" && source.active);
}

function arjunaPrintedHandPowerSum(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): number {
  return player.hand.reduce((sum, instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return sum + (definition ? getPrintedCardBasePower(state, player, definition) : 0);
  }, 0);
}


export const useArjunaAgniGandiva: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("ARJUNA_AGNI_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "card.played") {
    if (Number(player.flags.arjunaAgniArmedRound ?? Number.NEGATIVE_INFINITY) !== state.round || !arjunaAgniSourceActive(state, player) || player.hand.length === 0) return;
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
    const targetPlayerId = typeof event?.playerId === "string" ? event.playerId : undefined;
    const instanceId = typeof event?.instanceId === "string" ? event.instanceId : undefined;
    if (!targetPlayerId || targetPlayerId === player.id || event?.face !== "up" || !instanceId || !state.players[targetPlayerId] || state.players[targetPlayerId].eliminated) return;
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    if (!card || !definition || getPrintedCardBasePower(state, state.players[targetPlayerId], definition) !== arjunaPrintedHandPowerSum(state, player, definitions)) return;
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:defeat:${targetPlayerId}:${instanceId}`;
    state.effectQueue.unshift({
      effectId,
      handlerId: ARJUNA_AGNI_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "defeat", targetPlayerId, triggerInstanceId: instanceId, round: state.round },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "arjuna-agni-defeat-response",
      options: [{ id: "defeat", label: "弃置全部手牌并令目标【败北】" }, { id: "decline", label: "不发动" }],
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== ARJUNA_AGNI_ABILITY) throw new Error("ARJUNA_AGNI_ABILITY_INVALID");
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("ARJUNA_AGNI_SOURCE_NOT_ACTIVE");
  const candidates = [...player.hand];
  if (candidates.length === 0) {
    player.flags.arjunaAgniArmedRound = state.round;
    player.flags.arjunaAgniSourceInstanceId = sourceInstanceId;
    return;
  }
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:discard`;
  state.effectQueue.unshift({
    effectId,
    handlerId: ARJUNA_AGNI_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { stage: "discard", candidates, sourceInstanceId, round: state.round },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "arjuna-agni-discard",
    options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
    min: 0,
    max: Math.min(3, candidates.length),
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isArjunaAgniGandivaLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  return Boolean(ability?.id === ARJUNA_AGNI_ABILITY && state.phase === "action" && state.activePlayerId === playerId
    && findActiveOwnedSkillAttack(state, playerId, skill.id));
};

const resolveArjunaAgniGandiva: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("ARJUNA_AGNI_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections)) throw new Error("ARJUNA_AGNI_DECISION_INVALID");
  const selections = decision.selections.filter((id): id is string => typeof id === "string");
  if (selections.length !== decision.selections.length) throw new Error("ARJUNA_AGNI_DECISION_INVALID");
  if (previous.stage === "discard") {
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const sourceInstanceId = typeof previous.sourceInstanceId === "string" ? previous.sourceInstanceId : undefined;
    if (Number(previous.round) !== state.round || !sourceInstanceId || selections.length > 3 || new Set(selections).size !== selections.length
      || selections.some((id) => !candidates.includes(id) || !player.hand.includes(id))) throw new Error("ARJUNA_AGNI_DISCARD_INVALID");
    for (const instanceId of selections) {
      movePlayerCard(state, player.id, instanceId, "discard");
      state.cards[instanceId].face = "up";
      state.cards[instanceId].active = false;
    }
    player.flags.arjunaAgniArmedRound = state.round;
    player.flags.arjunaAgniSourceInstanceId = sourceInstanceId;
    return { discardedInstanceIds: selections };
  }
  if (previous.stage !== "defeat" || selections.length !== 1) throw new Error("ARJUNA_AGNI_STAGE_INVALID");
  if (selections[0] === "decline") return { defeated: false };
  if (selections[0] !== "defeat" || Number(previous.round) !== state.round || !arjunaAgniSourceActive(state, player) || player.hand.length === 0) {
    throw new Error("ARJUNA_AGNI_DEFEAT_INVALID");
  }
  const targetPlayerId = typeof previous.targetPlayerId === "string" ? previous.targetPlayerId : undefined;
  const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
  if (!target || targetPlayerId === player.id || target.eliminated) throw new Error("ARJUNA_AGNI_TARGET_INVALID");
  const discarded = [...player.hand];
  for (const instanceId of discarded) {
    movePlayerCard(state, player.id, instanceId, "discard");
    state.cards[instanceId].face = "up";
    state.cards[instanceId].active = false;
  }
  const defeated = defeatPlayerByEffect(state, targetPlayerId, player.id, definitions, emitEvent, { sourceId: ARJUNA_AGNI_ID, method: "prophetic-shot" });
  return { defeated, targetPlayerId, discardedInstanceIds: discarded };
};

function findActiveMuramasaEdgeSource(state: GameState, player: PlayerState): GameState["cards"][string] | undefined {
  return player.attack
    .map((instanceId) => state.cards[instanceId])
    .find((card) => card?.definitionId === MURAMASA_EDGE_ID && card.ownerPlayerId === player.id && card.zone === "attack" && card.face === "up" && card.active);
}


export const useMuramasaImperfectEdge: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, randomInt }) => {
  if (!definitions) throw new Error("MURAMASA_EDGE_DEFINITIONS_REQUIRED");
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  const source = findActiveMuramasaEdgeSource(state, player);
  if (!source) throw new Error("MURAMASA_EDGE_SOURCE_NOT_ACTIVE");

  if (abilityId === MURAMASA_EDGE_TRIAL_ABILITY) {
    if (state.phase !== "combat" || source.reversed === true) throw new Error("MURAMASA_EDGE_TRIAL_WINDOW_INVALID");
    const candidates = [...player.hand];
    if (candidates.length === 0) return { removedInstanceIds: [], powerGain: 0 };
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:trial`;
    state.effectQueue.unshift({
      effectId,
      handlerId: MURAMASA_EDGE_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "trial", sourceInstanceId: source.instanceId, candidates, round: state.round },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "muramasa-sword-trial-remove",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
      min: 0,
      max: Math.min(3, candidates.length),
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }

  if (abilityId === MURAMASA_EDGE_ALTER_ABILITY) {
    if (state.phase !== "action" || state.activePlayerId !== player.id || source.reversed !== true) throw new Error("MURAMASA_EDGE_ALTER_WINDOW_INVALID");
    const random = new StateRandom();
    const drawn = drawCards(state, player.id, 4, randomInt ?? ((maxExclusive) => random.integer(state, maxExclusive)), definitions);
    if (player.hand.length < 3) throw new Error("MURAMASA_EDGE_DISCARD_COUNT_UNAVAILABLE");
    const candidates = [...player.hand];
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:alter`;
    state.effectQueue.unshift({
      effectId,
      handlerId: MURAMASA_EDGE_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "alter-discard", sourceInstanceId: source.instanceId, candidates, drawn, round: state.round },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "muramasa-edge-discard-three",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
      min: 3,
      max: 3,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return { drawn };
  }
  throw new Error("MURAMASA_EDGE_ABILITY_INVALID");
};

export const isMuramasaImperfectEdgeLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  const source = player ? findActiveMuramasaEdgeSource(state, player) : undefined;
  if (!player || !source || !ability) return false;
  if (ability.id === MURAMASA_EDGE_TRIAL_ABILITY) return state.phase === "combat" && source.reversed !== true;
  if (ability.id === MURAMASA_EDGE_ALTER_ABILITY) return state.phase === "action" && state.activePlayerId === playerId && source.reversed === true;
  return false;
};

const resolveMuramasaImperfectEdge: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("MURAMASA_EDGE_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections)) throw new Error("MURAMASA_EDGE_DECISION_INVALID");
  const selections = decision.selections.filter((instanceId): instanceId is string => typeof instanceId === "string");
  if (selections.length !== decision.selections.length || new Set(selections).size !== selections.length) throw new Error("MURAMASA_EDGE_DECISION_INVALID");
  const sourceInstanceId = typeof previous.sourceInstanceId === "string" ? previous.sourceInstanceId : undefined;
  const source = sourceInstanceId ? state.cards[sourceInstanceId] : undefined;
  if (!source || source.ownerPlayerId !== player.id || source.definitionId !== MURAMASA_EDGE_ID || source.zone !== "attack" || source.face !== "up" || !source.active) {
    throw new Error("MURAMASA_EDGE_SOURCE_NOT_ACTIVE");
  }
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((instanceId): instanceId is string => typeof instanceId === "string") : [];

  if (previous.stage === "trial") {
    if (Number(previous.round) !== state.round || source.reversed === true || selections.length > 3
      || selections.some((instanceId) => !candidates.includes(instanceId) || !player.hand.includes(instanceId))) throw new Error("MURAMASA_EDGE_TRIAL_SELECTION_INVALID");
    let powerGain = 0;
    for (const instanceId of selections) {
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      if (!card || !definition) throw new Error("MURAMASA_EDGE_CARD_INVALID");
      powerGain += getPrintedCardBasePower(state, player, definition);
    }
    for (const instanceId of selections) movePlayerCard(state, player.id, instanceId, "removed");
    if (powerGain > 0) {
      const modifierId = `${MURAMASA_EDGE_ID}:trial:${sourceInstanceId}:${state.round}`;
      source.powerModifiers = [
        ...(source.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
        { id: modifierId, sourceId: MURAMASA_EDGE_ID, kind: "add", value: powerGain, duration: "round" },
      ];
    }
    const cumulative = Number(player.flags.muramasaSwordTrialExiledPower ?? 0) + powerGain;
    if (!Number.isInteger(cumulative) || cumulative < 0) throw new Error("MURAMASA_EDGE_CUMULATIVE_POWER_INVALID");
    player.flags.muramasaSwordTrialExiledPower = cumulative;
    return { removedInstanceIds: selections, powerGain, cumulativePower: cumulative };
  }

  if (previous.stage === "alter-discard") {
    if (Number(previous.round) !== state.round || source.reversed !== true || selections.length !== 3
      || selections.some((instanceId) => !candidates.includes(instanceId) || !player.hand.includes(instanceId))) throw new Error("MURAMASA_EDGE_ALTER_DISCARD_INVALID");
    for (const instanceId of selections) {
      movePlayerCard(state, player.id, instanceId, "discard");
      state.cards[instanceId].face = "up";
      state.cards[instanceId].active = false;
    }
    return { discardedInstanceIds: selections, drawnInstanceIds: Array.isArray(previous.drawn) ? previous.drawn : [] };
  }
  throw new Error("MURAMASA_EDGE_STAGE_INVALID");
};

function findActiveConstantineWallsSource(state: GameState, player: PlayerState): GameState["cards"][string] | undefined {
  return player.attack
    .map((instanceId) => state.cards[instanceId])
    .find((card) => card?.definitionId === CONSTANTINE_WALLS_ID && card.ownerPlayerId === player.id && card.zone === "attack" && card.face === "up" && card.active);
}

const resolveConstantineTripleWalls: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("CONSTANTINE_WALLS_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((value): value is string => typeof value === "string") : [];
  if (previous.stage !== "faith-wall" || decision.status !== "resolved" || selections.length !== 1) throw new Error("CONSTANTINE_WALLS_DECISION_INVALID");
  if (selections[0] === "decline") return { blessed: false };
  if (selections[0] !== "bless") throw new Error("CONSTANTINE_WALLS_DECISION_INVALID");
  const source = findActiveConstantineWallsSource(state, player);
  const instanceId = typeof previous.instanceId === "string" ? previous.instanceId : undefined;
  const card = instanceId ? state.cards[instanceId] : undefined;
  const definition = card ? definitions[card.definitionId] : undefined;
  if (!source || !card || !definition || card.ownerPlayerId !== player.id || card.zone !== "hand" || definition.basic !== true
    || Number(player.flags.constantineFaithWallUsedRound ?? Number.NEGATIVE_INFINITY) === state.round) throw new Error("CONSTANTINE_WALLS_BLESS_INVALID");
  payManaCost(state, player, 3, definitions, "CONSTANTINE_WALLS_INSUFFICIENT_MANA");
  player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + 3;
  player.flags.constantineFaithWallUsedRound = state.round;
  card.face = "up";
  installStructuredRuleModifier(
    state,
    player.id,
    CONSTANTINE_WALLS_ID,
    card.instanceId,
    "faith-wall",
    {
      id: `faith-wall-double:${card.instanceId}`,
      operation: "multiply",
      rule: "card_power",
      scope: { subject: "controller", cards: { instanceIds: [card.instanceId] } },
      value: 2,
      lifecycle: { duration: "while_active" },
    },
  );
  return { blessed: true, instanceId: card.instanceId };
};


export const useConstantineTripleWalls: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("CONSTANTINE_WALLS_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  const source = findActiveConstantineWallsSource(state, player);
  if (!source || !event) return;
  if (eventType === "combat.resolved") {
    const powers = isRecord(event.powers) ? event.powers : {};
    const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds.filter((value): value is string => typeof value === "string") : [];
    if (Object.prototype.hasOwnProperty.call(powers, player.id) && !winnerIds.includes(player.id)) gainVictoryPoints(player, 3);
    return;
  }
  if (eventType !== "card.drawn" || event.ownerPlayerId !== player.id || event.fromZone !== "deck") return;
  if (Number(player.flags.constantineFaithWallUsedRound ?? Number.NEGATIVE_INFINITY) === state.round || player.mana < 3) return;
  const instanceId = typeof event.instanceId === "string" ? event.instanceId : undefined;
  const card = instanceId ? state.cards[instanceId] : undefined;
  const definition = card ? definitions[card.definitionId] : undefined;
  if (!card || !definition || card.ownerPlayerId !== player.id || card.zone !== "hand" || definition.basic !== true) return;
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:faith-wall:${instanceId}`;
  state.effectQueue.unshift({
    effectId,
    handlerId: CONSTANTINE_WALLS_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { stage: "faith-wall", instanceId, round: state.round },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "constantine-faith-wall",
    options: [{ id: "bless", label: "支付3点魔力并展示此牌" }, { id: "decline", label: "不发动" }],
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

function findActiveTeslaSource(state: GameState, player: PlayerState, definitionId: string): GameState["cards"][string] | undefined {
  return player.attack
    .map((instanceId) => state.cards[instanceId])
    .find((card) => card?.definitionId === definitionId && card.ownerPlayerId === player.id && card.zone === "attack" && card.face === "up" && card.active);
}


export const useTeslaLightningHand: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions) throw new Error("TESLA_LIGHTNING_HAND_DEFINITIONS_REQUIRED");
  const source = findActiveTeslaSource(state, player, TESLA_LIGHTNING_HAND_ID);
  if (!source || !isRecord(payload)) return;
  const eventType = typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "player.mana.spent") {
    const spenderId = typeof event?.playerId === "string" ? event.playerId : undefined;
    const amount = Number(event?.amount);
    const spender = spenderId ? state.players[spenderId] : undefined;
    if (!spender || spenderId === player.id || !Number.isInteger(amount) || amount < 2 || !player.locationId || spender.locationId !== player.locationId) return;
    gainMana(player, 2);
    return;
  }
  if (eventType === "player.mana-gain-overflow") {
    if (event?.playerId !== player.id) return;
    player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + 5;
    player.flags.teslaLightningHandCloseRound = state.round;
    return;
  }
  if (eventType === "combat.ending" && Number(player.flags.teslaLightningHandCloseRound ?? Number.NEGATIVE_INFINITY) === state.round) {
    closePlayerCard(state, player.id, source.instanceId, definitions);
    delete player.flags.teslaLightningHandCloseRound;
  }
};


export const useTeslaLightningDescent: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload)) throw new Error("TESLA_LIGHTNING_DESCENT_DEFINITIONS_REQUIRED");
  const eventType = typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload.event) ? payload.event : undefined;
  const source = findActiveTeslaSource(state, player, TESLA_LIGHTNING_DESCENT_ID);
  if (!source || !event) return;
  if (eventType === "card.played") {
    if (event.playerId !== player.id || event.definitionId !== TESLA_LIGHTNING_DESCENT_ID || event.face !== "up") return;
    const lost = loseMana(player, Math.max(0, player.mana));
    if (lost > 0) player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + lost;
    return;
  }
  if (eventType !== "player.mana-gain-overflow") return;
  const targetPlayerId = typeof event.playerId === "string" ? event.playerId : undefined;
  const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
  if (!target || targetPlayerId === player.id || target.eliminated || (player.locationId !== "mountain" && player.locationId !== "city") || target.locationId !== player.locationId) return;
  defeatPlayerByEffect(state, targetPlayerId, player.id, definitions, emitEvent, { sourceId: TESLA_LIGHTNING_DESCENT_ID, method: "overload" });
};

function activePassionlipSource(state: GameState, player: PlayerState, skillId: string): GameState["cards"][string] | undefined {
  return player.attack.map((instanceId) => state.cards[instanceId]).find((card) => card?.definitionId === skillId && card.ownerPlayerId === player.id && card.zone === "attack" && card.face === "up" && card.active);
}


export const usePassionlipMasochism: SkillHandler = ({ state, player, skill, definitions }) => {
  if (!definitions) throw new Error("PASSIONLIP_MASOCHISM_DEFINITIONS_REQUIRED");
  const source = activePassionlipSource(state, player, skill.id);
  const locationId = player.locationId;
  if (!source || (locationId !== "mountain" && locationId !== "city")) throw new Error("PASSIONLIP_MASOCHISM_SOURCE_INVALID");
  const ownActive = player.attack.filter((instanceId) => state.cards[instanceId]?.active && state.cards[instanceId]?.face === "up");
  const ownHighest = ownActive.length > 0 ? Math.max(...ownActive.map((instanceId) => calculateCombatCardPower(state, player, instanceId, definitions, locationId))) : 0;
  let higherOpponentAttacks = 0;
  for (const targetId of state.board.locations[locationId] ?? []) {
    if (targetId === player.id || state.players[targetId]?.eliminated) continue;
    const target = state.players[targetId];
    for (const instanceId of target.attack) {
      const card = state.cards[instanceId];
      if (!card?.active || card.face !== "up") continue;
      if (calculateCombatCardPower(state, target, instanceId, definitions, locationId) > ownHighest) higherOpponentAttacks += 1;
    }
  }
  if (higherOpponentAttacks > 0) gainVictoryPoints(player, higherOpponentAttacks);
  if (source.reversed === true && higherOpponentAttacks > 0) {
    player.flags.nextRoundTotalPowerBonus = Number(player.flags.nextRoundTotalPowerBonus ?? 0) + higherOpponentAttacks * 3;
  }
  return { higherOpponentAttacks, reversed: source.reversed === true, nextRoundPowerBonus: source.reversed === true ? higherOpponentAttacks * 3 : 0 };
};

export const isPassionlipMasochismLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  return Boolean(player && state.phase === "combat" && (player.locationId === "mountain" || player.locationId === "city") && activePassionlipSource(state, player, skill.id));
};

function applyPassionlipArmorPowerSet(state: GameState, instanceId: string, skillId: string, value: number): void {
  const card = state.cards[instanceId];
  if (!card) throw new Error("PASSIONLIP_ARMOR_CARD_MISSING");
  const id = `${skillId}:set:${instanceId}:${state.round}`;
  card.powerModifiers = [...(card.powerModifiers ?? []).filter((modifier) => modifier.id !== id), { id, sourceId: skillId, kind: "set", value, duration: "round" }];
}

const resolvePassionlipDurgaArmor: SkillHandler = ({ state, player, payload }) => {
  if (!isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("PASSIONLIP_ARMOR_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (previous.stage !== "reverse-select" || decision.status !== "resolved" || !isRecord(decision.submissions)) throw new Error("PASSIONLIP_ARMOR_DECISION_INVALID");
  const participants = Array.isArray(previous.participantIds) ? previous.participantIds.filter((id): id is string => typeof id === "string") : [];
  const selected = new Set<string>();
  for (const participantId of participants) {
    const submitted = decision.submissions[participantId];
    if (!Array.isArray(submitted) || submitted.length !== 1 || typeof submitted[0] !== "string") throw new Error("PASSIONLIP_ARMOR_SELECTION_INVALID");
    const instanceId = submitted[0];
    if (!state.players[participantId]?.attack.includes(instanceId) || !state.cards[instanceId]?.active || state.cards[instanceId]?.face !== "up") throw new Error("PASSIONLIP_ARMOR_SELECTION_INVALID");
    selected.add(instanceId);
  }
  for (const participantId of participants) {
    for (const instanceId of state.players[participantId].attack) {
      const card = state.cards[instanceId];
      if (!card?.active || card.face !== "up" || selected.has(instanceId)) continue;
      applyPassionlipArmorPowerSet(state, instanceId, PASSIONLIP_ARMOR_ID, 0);
    }
  }
  return { selectedInstanceIds: [...selected] };
};


export const usePassionlipDurgaArmor: SkillHandler = ({ state, player, skill, definitions, openDecision }) => {
  if (!definitions) throw new Error("PASSIONLIP_ARMOR_DEFINITIONS_REQUIRED");
  const source = activePassionlipSource(state, player, skill.id);
  const locationId = player.locationId;
  if (!source || (locationId !== "mountain" && locationId !== "city")) throw new Error("PASSIONLIP_ARMOR_SOURCE_INVALID");
  const participants = (state.board.locations[locationId] ?? []).filter((id) => !state.players[id]?.eliminated);
  if (source.reversed === true) revealPlayerTrueName(state, player.id);
  if (source.reversed !== true) {
    const reduced: string[] = [];
    for (const participantId of participants) {
      const participant = state.players[participantId];
      for (const instanceId of participant.attack) {
        const card = state.cards[instanceId];
        if (!card?.active || card.face !== "up") continue;
        if (calculateCombatCardPower(state, participant, instanceId, definitions, locationId) > 9) {
          applyPassionlipArmorPowerSet(state, instanceId, skill.id, 9);
          reduced.push(instanceId);
        }
      }
    }
    return { reducedInstanceIds: reduced };
  }
  const choosers = participants.filter((id) => state.players[id].attack.some((instanceId) => state.cards[instanceId]?.active && state.cards[instanceId]?.face === "up"));
  if (choosers.length === 0) return { selectedInstanceIds: [] };
  const options = choosers.flatMap((chooserId) => state.players[chooserId].attack
    .filter((instanceId) => state.cards[instanceId]?.active && state.cards[instanceId]?.face === "up")
    .map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId].definitionId]?.name ?? instanceId, chooserPlayerIds: [chooserId] })));
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:reverse`;
  state.effectQueue.unshift({ effectId, handlerId: PASSIONLIP_ARMOR_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "reverse-select", participantIds: choosers }, createdAtRevision: state.revision });
  openDecision({ decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: choosers, kind: "passionlip-durga-armor-select", options, min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {} });
};

export const isPassionlipDurgaArmorLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  return Boolean(player && state.phase === "combat" && (player.locationId === "mountain" || player.locationId === "city") && activePassionlipSource(state, player, skill.id));
};

function isSaitouBasicAttribute(definition: CardDefinition | undefined, attribute: "力量" | "迅捷"): boolean {
  return Boolean(definition?.basic === true && getCardAttributes(definition).includes(attribute));
}

const resolveSaitouFlagOfSincerity: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("SAITOU_FLAG_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (previous.stage !== "choose-close-attribute" || decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) {
    throw new Error("SAITOU_FLAG_DECISION_INVALID");
  }
  const attribute = decision.selections[0] === "strength" ? "力量" : decision.selections[0] === "agility" ? "迅捷" : undefined;
  if (!attribute) throw new Error("SAITOU_FLAG_ATTRIBUTE_INVALID");
  const closed: string[] = [];
  for (const instanceId of [...player.attack]) {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    if (!card?.active || card.face !== "up" || !isSaitouBasicAttribute(definition, attribute)) continue;
    closePlayerCard(state, player.id, instanceId, definitions);
    closed.push(instanceId);
  }
  return { closedAttribute: attribute, closedInstanceIds: closed };
};


export const useSaitouFlagOfSincerity: SkillHandler = ({ state, player, skill, definitions, openDecision, randomInt, emitEvent }) => {
  if (!definitions) throw new Error("SAITOU_FLAG_DEFINITIONS_REQUIRED");
  if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("SAITOU_FLAG_WINDOW_INVALID");
  const random = new StateRandom();
  drawCards(state, player.id, 2, randomInt ?? ((maxExclusive) => random.integer(state, maxExclusive)), definitions);
  for (const instanceId of player.hand) {
    const card = state.cards[instanceId];
    if (!card) continue;
    emitEvent?.("card.revealed", { playerId: player.id, instanceId, definitionId: card.definitionId, sourceId: skill.id, method: "reveal-hand" });
  }
  const playable = player.hand.filter((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(definition?.basic === true && (getCardAttributes(definition).includes("力量") || getCardAttributes(definition).includes("迅捷")));
  });
  for (const instanceId of playable) assertCardCanEnterAttack({ state, playerId: player.id, instanceId, definitions, faceDown: false });
  const played: string[] = [];
  for (const instanceId of playable) {
    const definition = definitions[state.cards[instanceId].definitionId];
    addCardToAttack(state, player.id, instanceId, definitions, { payCost: false, bypassFaceUpPlayLimit: true });
    emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: definition.id, face: "up", paidMana: 0, attributes: getCardAttributes(definition), method: "effect", sourceId: skill.id });
    emitEvent?.("card.used", { playerId: player.id, instanceId, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "effect", sourceId: skill.id });
    played.push(instanceId);
  }
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:close-attribute`;
  state.effectQueue.unshift({ effectId, handlerId: SAITOU_FLAG_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "choose-close-attribute", playedInstanceIds: played }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "saitou-flag-close-attribute",
    options: [{ id: "strength", label: "关闭全部基础力量攻击" }, { id: "agility", label: "关闭全部基础迅捷攻击" }],
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
  return { drawnAndRevealedHandCount: player.hand.length, playedInstanceIds: played };
};

function saitouFormlessnessAffectedAttackIds(
  state: GameState,
  player: PlayerState,
  definitions: Record<string, CardDefinition>,
  attribute: "力量" | "迅捷",
): string[] {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") return [];
  const matchingOwnBasicDefinitions = new Set(player.attack.flatMap((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return card?.active && card.face === "up" && isSaitouBasicAttribute(definition, attribute) ? [definition!.id] : [];
  }));
  if (matchingOwnBasicDefinitions.size === 0) return [];
  const affected: string[] = [];
  for (const opponentId of state.board.locations[locationId] ?? []) {
    if (opponentId === player.id || state.players[opponentId]?.eliminated) continue;
    const opponent = state.players[opponentId];
    const hasMatchingBasic = opponent.attack.some((instanceId) => {
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      return Boolean(card?.active && card.face === "up" && isSaitouBasicAttribute(definition, attribute) && matchingOwnBasicDefinitions.has(definition!.id));
    });
    if (hasMatchingBasic) continue;
    for (const instanceId of opponent.attack) {
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      if (card?.active && card.face === "up" && definition && getCardInstanceAttributes(card, definition, state, definitions).includes(attribute)) affected.push(instanceId);
    }
  }
  return affected;
}


export const useSaitouFormlessness: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("SAITOU_FORMLESS_DEFINITIONS_REQUIRED");
  const abilityId = readSkillAbilityId(payload);
  const attribute = abilityId === "iai-agility" ? "迅捷" : abilityId === "iai-strength" ? "力量" : undefined;
  if (!attribute) throw new Error("SAITOU_FORMLESS_ABILITY_INVALID");
  const affected = saitouFormlessnessAffectedAttackIds(state, player, definitions, attribute);
  if (affected.length === 0) throw new Error("SAITOU_FORMLESS_NO_TARGET");
  for (const instanceId of affected) {
    const card = state.cards[instanceId];
    const id = `${skill.id}:${abilityId}:${state.round}:${instanceId}`;
    card.powerModifiers = [...(card.powerModifiers ?? []).filter((modifier) => modifier.id !== id), { id, sourceId: skill.id, kind: "set", value: 0, duration: "round" }];
  }
  return { attribute, affectedInstanceIds: affected };
};

export const isSaitouFormlessnessLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  if (!definitions || !ability) return false;
  const player = state.players[playerId];
  if (!player || state.phase !== "combat" || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  const attribute = ability.id === "iai-agility" ? "迅捷" : ability.id === "iai-strength" ? "力量" : undefined;
  return Boolean(attribute && saitouFormlessnessAffectedAttackIds(state, player, definitions, attribute).length > 0);
};

function findActiveOkitaAltSource(state: GameState, player: PlayerState, definitionId: string): GameState["cards"][string] | undefined {
  return player.attack.map((instanceId) => state.cards[instanceId])
    .find((card) => card?.definitionId === definitionId && card.ownerPlayerId === player.id && card.zone === "attack" && card.face === "up" && card.active);
}


export const useOkitaAltBoundless: SkillHandler = ({ state, player, definitions, randomInt, emitEvent, skill }) => {
  if (!definitions) throw new Error("OKITA_ALT_BOUNDLESS_DEFINITIONS_REQUIRED");
  if (state.phase !== "action" || state.activePlayerId !== player.id || !findActiveOkitaAltSource(state, player, OKITA_ALT_BOUNDLESS_ID)) {
    throw new Error("OKITA_ALT_BOUNDLESS_SOURCE_INVALID");
  }
  const random = new StateRandom();
  const randomFn = randomInt ?? ((maxExclusive: number) => random.integer(state, maxExclusive));
  const joined: string[] = [];
  let stoppedBy: "mismatch" | "mana-zero" | "deck-empty" = "deck-empty";
  while (true) {
    const drawn = drawCards(state, player.id, 1, randomFn, definitions);
    const instanceId = drawn[0];
    if (!instanceId) {
      stoppedBy = "deck-empty";
      break;
    }
    const card = state.cards[instanceId];
    const definition = definitions[card.definitionId];
    const activeAttributes = new Set(player.attack.flatMap((candidateId) => {
      const candidate = state.cards[candidateId];
      const candidateDefinition = candidate ? definitions[candidate.definitionId] : undefined;
      return candidate?.active && candidate.face === "up" && candidateDefinition ? getCardInstanceAttributes(candidate, candidateDefinition, state, definitions) : [];
    }));
    const attributes = getCardAttributes(definition);
    const matches = definition.basic === true && attributes.some((attribute) => activeAttributes.has(attribute));
    if (!matches) {
      movePlayerCard(state, player.id, instanceId, "discard");
      card.face = "up";
      card.active = false;
      stoppedBy = "mismatch";
      emitEvent?.("card.discarded", { playerId: player.id, instanceId, definitionId: definition.id, sourceId: skill.id, method: "boundless-mismatch" });
      break;
    }
    joinOwnedCardToAttack(state, player.id, instanceId, definitions);
    joined.push(instanceId);
    const manaBefore = player.mana;
    loseMana(player, 1);
    if (manaBefore > 0 && player.mana === 0) {
      defeatPlayer(state, player.id, emitEvent, { sourceId: skill.id, method: "boundless-mana-zero" });
      stoppedBy = "mana-zero";
      break;
    }
  }
  return { joinedInstanceIds: joined, stoppedBy };
};

export const isOkitaAltBoundlessLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  return Boolean(player && state.phase === "action" && state.activePlayerId === playerId && findActiveOkitaAltSource(state, player, OKITA_ALT_BOUNDLESS_ID)
    && (player.deck.length > 0 || player.discard.length > 0));
};

const resolveOkitaAltRengoku: SkillHandler = ({ state, player, payload, definitions, randomInt }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("OKITA_ALT_RENGOKU_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (previous.stage !== "return-basics" || decision.status !== "resolved" || selections.length !== 2 || new Set(selections).size !== 2
    || selections.some((id) => !candidates.includes(id) || !player.discard.includes(id) || definitions[state.cards[id]?.definitionId ?? ""]?.basic !== true)) {
    throw new Error("OKITA_ALT_RENGOKU_SELECTION_INVALID");
  }
  for (const instanceId of selections) {
    movePlayerCard(state, player.id, instanceId, "deck");
    const card = state.cards[instanceId];
    card.face = "down";
    card.active = false;
  }
  const random = new StateRandom();
  shufflePlayerDeck(state, player.id, randomInt ?? ((maxExclusive: number) => random.integer(state, maxExclusive)));
  return { returnedInstanceIds: selections };
};


export const useOkitaAltRengoku: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("OKITA_ALT_RENGOKU_DEFINITIONS_REQUIRED");
  const source = findActiveOkitaAltSource(state, player, OKITA_ALT_RENGOKU_ID);
  if (!source || state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("OKITA_ALT_RENGOKU_SOURCE_INVALID");
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === "rengoku-return-basics") {
    if (source.reversed === true) throw new Error("OKITA_ALT_RENGOKU_FACE_INVALID");
    const candidates = player.discard.filter((instanceId) => definitions[state.cards[instanceId]?.definitionId ?? ""]?.basic === true);
    if (candidates.length < 2) throw new Error("OKITA_ALT_RENGOKU_BASIC_DISCARD_REQUIRED");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:return-basics`;
    state.effectQueue.unshift({ effectId, handlerId: OKITA_ALT_RENGOKU_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "return-basics", candidates }, createdAtRevision: state.revision });
    openDecision({
      decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "okita-alt-rengoku-return-basics",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
      min: 2, max: 2, allowCancel: false, continuationEffectId: effectId, submissions: {},
    });
    return;
  }
  if (abilityId === "rengoku-alter-purgatory") {
    if (source.reversed !== true) throw new Error("OKITA_ALT_RENGOKU_FACE_INVALID");
    const removed = [...player.discard];
    for (const instanceId of removed) {
      movePlayerCard(state, player.id, instanceId, "removed");
      state.cards[instanceId].face = "up";
      state.cards[instanceId].active = false;
    }
    if (removed.length >= 2) {
      const id = `${skill.id}:purgatory:${state.round}:${source.instanceId}`;
      source.powerModifiers = [...(source.powerModifiers ?? []).filter((modifier) => modifier.id !== id), { id, sourceId: skill.id, kind: "add", value: 8, duration: "round" }];
    }
    return { removedInstanceIds: removed, powerBonus: removed.length >= 2 ? 8 : 0 };
  }
  throw new Error("OKITA_ALT_RENGOKU_ABILITY_INVALID");
};

export const isOkitaAltRengokuLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  if (!definitions || !ability) return false;
  const player = state.players[playerId];
  if (!player || state.phase !== "action" || state.activePlayerId !== playerId) return false;
  const source = findActiveOkitaAltSource(state, player, OKITA_ALT_RENGOKU_ID);
  if (!source) return false;
  if (ability.id === "rengoku-return-basics") return source.reversed !== true && player.discard.filter((id) => definitions[state.cards[id]?.definitionId ?? ""]?.basic === true).length >= 2;
  if (ability.id === "rengoku-alter-purgatory") return source.reversed === true;
  return false;
};

function findActiveMordredSkill(state: GameState, player: PlayerState, definitionId: string): GameState["cards"][string] | undefined {
  return player.attack.map((instanceId) => state.cards[instanceId])
    .find((card) => card?.definitionId === definitionId && card.ownerPlayerId === player.id && card.zone === "attack" && card.face === "up" && card.active);
}

function mordredHelmPlayableIds(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  const source = findActiveMordredSkill(state, player, MORDRED_HELM_ID);
  if (!source) return [];
  const candidates = [...player.hand, ...player.masterSkills, ...player.servantSkills].filter((instanceId) => instanceId !== source.instanceId);
  return candidates.filter((instanceId) => {
    try {
      const definition = assertCardCanEnterAttack({
        state, playerId: player.id, instanceId, definitions, faceDown: false,
        allowedSourceZones: ["hand", "master-skills", "servant-skills"], bypassTiming: true,
      });
      return getCardPlayCost(state, definition, player, state.cards[instanceId], definitions) <= player.mana;
    } catch {
      return false;
    }
  });
}

const resolveMordredHiddenHelm: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("MORDRED_HELM_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (previous.stage !== "combat-play" || decision.status !== "resolved" || selections.length !== 1 || !candidates.includes(selections[0])) {
    throw new Error("MORDRED_HELM_DECISION_INVALID");
  }
  const source = findActiveMordredSkill(state, player, MORDRED_HELM_ID);
  if (!source || state.phase !== "combat" || state.activePlayerId !== player.id || !mordredHelmPlayableIds(state, player, definitions).includes(selections[0])) {
    throw new Error("MORDRED_HELM_CARD_INVALID");
  }
  const instanceId = selections[0];
  const definition = definitions[state.cards[instanceId].definitionId];
  closePlayerCard(state, player.id, source.instanceId, definitions);
  const { paidMana } = addCardToAttack(state, player.id, instanceId, definitions, {
    payCost: true,
    allowedSourceZones: ["hand", "master-skills", "servant-skills"],
    bypassFaceUpPlayLimit: true,
    bypassTiming: true,
  });
  const modifierId = `${MORDRED_HELM_ID}:action-in-combat:${state.round}:${instanceId}`;
  if (!(player.cardRuleModifiers ?? []).some((modifier) => modifier.id === modifierId)) {
    addCardRuleModifier(player, {
      id: modifierId,
      sourceId: MORDRED_HELM_ID,
      targetDefinitionIds: [definition.id],
      targetInstanceIds: [instanceId],
      allowActionAbilityInCombat: true,
      duration: "round",
    });
  }
  const revealBlocked = player.flags.preventTrueNameReveal === true
    || (player.flags.preventTrueNameRevealWhenNoSeals === true && player.commandSeals === 0);
  if (definition.revealsTrueNameOnPlay === true && !player.trueNameRevealed && !revealBlocked) {
    revealPlayerTrueName(state, player.id);
    emitEvent?.("servant.true-name-revealed", { playerId: player.id, servantId: player.servantId, sourceDefinitionId: definition.id, method: "mordred-helm" });
  }
  emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: definition.id, face: "up", paidMana, attributes: getCardAttributes(definition), method: "effect", sourceId: MORDRED_HELM_ID });
  emitEvent?.("card.used", { playerId: player.id, instanceId, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "effect", sourceId: MORDRED_HELM_ID });
  return { instanceId, definitionId: definition.id, paidMana };
};


export const useMordredHiddenHelm: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("MORDRED_HELM_DEFINITIONS_REQUIRED");
  const abilityId = readSkillAbilityId(payload);
  const source = findActiveMordredSkill(state, player, MORDRED_HELM_ID);
  if (!source) throw new Error("MORDRED_HELM_SOURCE_INVALID");
  if (abilityId === "hide-true-name") {
    if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("MORDRED_HELM_WINDOW_INVALID");
    player.trueNameRevealed = false;
    return { hidden: true };
  }
  if (abilityId === "combat-play") {
    if (state.phase !== "combat" || state.activePlayerId !== player.id) throw new Error("MORDRED_HELM_WINDOW_INVALID");
    const candidates = mordredHelmPlayableIds(state, player, definitions);
    if (candidates.length === 0) throw new Error("MORDRED_HELM_NO_PLAYABLE_CARD");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:combat-play`;
    state.effectQueue.unshift({ effectId, handlerId: MORDRED_HELM_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "combat-play", candidates }, createdAtRevision: state.revision });
    openDecision({
      decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "mordred-helm-combat-play",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
      min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {},
    });
    return;
  }
  throw new Error("MORDRED_HELM_ABILITY_INVALID");
};

export const isMordredHiddenHelmLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  if (!definitions || !ability) return false;
  const player = state.players[playerId];
  if (!player || !findActiveMordredSkill(state, player, MORDRED_HELM_ID)) return false;
  if (ability.id === "hide-true-name") return state.phase === "action" && state.activePlayerId === playerId;
  if (ability.id === "combat-play") return state.phase === "combat" && state.activePlayerId === playerId && mordredHelmPlayableIds(state, player, definitions).length > 0;
  return false;
};

function mordredClarentActionWindowAllowed(state: GameState, player: PlayerState, source: GameState["cards"][string]): boolean {
  return state.phase === "action" || (state.phase === "combat" && cardAllowsActionAbilityInCombat(state, player, source));
}

const resolveMordredClarent: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("MORDRED_CLARENT_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (previous.stage !== "mana-burst" || decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) {
    throw new Error("MORDRED_CLARENT_DECISION_INVALID");
  }
  const amount = Number(decision.selections[0]);
  const maxAmount = Number(previous.maxAmount);
  const source = findActiveMordredSkill(state, player, MORDRED_CLARENT_ID);
  if (!source || !mordredClarentActionWindowAllowed(state, player, source) || state.activePlayerId !== player.id || !Number.isInteger(amount) || amount < 0 || amount > 10
    || !Number.isInteger(maxAmount) || amount > maxAmount || amount > player.mana) throw new Error("MORDRED_CLARENT_AMOUNT_INVALID");
  payManaCost(state, player, amount, definitions);
  if (amount > 0) player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + amount;
  const modifierId = `${MORDRED_CLARENT_ID}:mana-burst:${state.round}:${source.instanceId}`;
  source.powerModifiers = [...(source.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId), {
    id: modifierId, sourceId: MORDRED_CLARENT_ID, kind: "add", value: amount * 2, duration: "round",
  }];
  player.flags.mordredClarentManaBurstRound = state.round;
  player.flags.mordredClarentManaBurstAmount = amount;
  player.flags.mordredClarentManaBurstSourceInstanceId = source.instanceId;
  delete player.flags.mordredClarentRefundedRound;
  return { amount, powerBonus: amount * 2 };
};


export const useMordredClarent: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("MORDRED_CLARENT_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "combat.resolved") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
    if (!event || !Array.isArray(event.winnerIds) || !isRecord(event.powers)) return;
    if (!Object.prototype.hasOwnProperty.call(event.powers, player.id) || event.winnerIds.includes(player.id)) return;
    if (Number(player.flags.mordredClarentManaBurstRound ?? -1) !== state.round || Number(player.flags.mordredClarentRefundedRound ?? -1) === state.round) return;
    const sourceInstanceId = typeof player.flags.mordredClarentManaBurstSourceInstanceId === "string" ? player.flags.mordredClarentManaBurstSourceInstanceId : undefined;
    const source = sourceInstanceId ? state.cards[sourceInstanceId] : undefined;
    if (!source || source.definitionId !== MORDRED_CLARENT_ID || source.zone !== "attack" || !source.active || source.face !== "up") return;
    const amount = Number(player.flags.mordredClarentManaBurstAmount ?? 0);
    if (!Number.isInteger(amount) || amount < 0 || amount > 10) throw new Error("MORDRED_CLARENT_REFUND_STATE_INVALID");
    const requested = Math.ceil(amount / 2);
    const restored = restoreManaUnpreventable(player, requested);
    player.flags.mordredClarentRefundedRound = state.round;
    return { requested, restored };
  }
  const abilityId = readSkillAbilityId(payload);
  if (abilityId !== "mana-burst") throw new Error("MORDRED_CLARENT_ABILITY_INVALID");
  const source = findActiveMordredSkill(state, player, MORDRED_CLARENT_ID);
  if (!source || !mordredClarentActionWindowAllowed(state, player, source) || state.activePlayerId !== player.id) throw new Error("MORDRED_CLARENT_SOURCE_INVALID");
  const maxAmount = Math.min(10, player.mana);
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:mana-burst`;
  state.effectQueue.unshift({ effectId, handlerId: MORDRED_CLARENT_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "mana-burst", maxAmount }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "mordred-clarent-mana-burst",
    options: Array.from({ length: maxAmount + 1 }, (_, amount) => ({ id: String(amount), label: `支付${amount}点魔力` })),
    min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {},
  });
};

export const isMordredClarentLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  if (!player || ability?.id !== "mana-burst" || state.activePlayerId !== playerId) return false;
  const source = findActiveMordredSkill(state, player, MORDRED_CLARENT_ID);
  return Boolean(source && mordredClarentActionWindowAllowed(state, player, source));
};

function activeNobunagaPapiyas(state: GameState, player: PlayerState): GameState["cards"][string] | undefined {
  const instanceId = findActiveOwnedSkillAttack(state, player.id, NOBUNAGA_PAPIYAS_ID);
  const source = instanceId ? state.cards[instanceId] : undefined;
  return source?.residual === true ? source : undefined;
}

function addNobunagaPapiyasGrowth(source: GameState["cards"][string], amount: number): number {
  if (!Number.isInteger(amount) || amount < 0) throw new Error("NOBUNAGA_PAPIYAS_GROWTH_INVALID");
  const modifierId = `${NOBUNAGA_PAPIYAS_ID}:hellfire-growth`;
  const previous = source.powerModifiers?.find((modifier) => modifier.id === modifierId);
  const next = Math.min(7, Number(previous?.value ?? 0) + amount);
  if (!Number.isInteger(next) || next < 0) throw new Error("NOBUNAGA_PAPIYAS_GROWTH_INVALID");
  source.powerModifiers = [
    ...(source.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
    { id: modifierId, sourceId: NOBUNAGA_PAPIYAS_ID, kind: "add", value: next, duration: "game" },
  ];
  return next;
}

const resolveNobunagaPapiyas: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("NOBUNAGA_PAPIYAS_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selection = Array.isArray(decision.selections) ? decision.selections[0] : undefined;
  if (previous.stage !== "upkeep" || Number(previous.round) !== state.round || decision.status !== "resolved" || (selection !== "pay" && selection !== "close")) {
    throw new Error("NOBUNAGA_PAPIYAS_DECISION_INVALID");
  }
  if (state.phase !== "preparation" || state.activePlayerId !== player.id || Number(player.flags.nobunagaPapiyasUpkeepRound ?? -1) === state.round) {
    throw new Error("NOBUNAGA_PAPIYAS_UPKEEP_WINDOW_INVALID");
  }
  const source = activeNobunagaPapiyas(state, player);
  if (!source) throw new Error("NOBUNAGA_PAPIYAS_SOURCE_INVALID");
  if (selection === "pay") {
    payManaCost(state, player, 2, definitions);
    player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + 2;
  } else {
    closePlayerCard(state, player.id, source.instanceId, definitions);
  }
  player.flags.nobunagaPapiyasUpkeepRound = state.round;
  return { choice: selection };
};

function maybeResolveNobunagaPapiyasUpkeep(
  state: GameState,
  player: PlayerState,
  definitions: Record<string, CardDefinition>,
  openDecision: SkillContext["openDecision"],
): void {
  if (state.phase !== "preparation" || state.activePlayerId !== player.id || Number(player.flags.nobunagaPapiyasUpkeepRound ?? -1) === state.round) return;
  const source = activeNobunagaPapiyas(state, player);
  if (!source) return;
  if (player.flags.infiniteMana !== true && player.mana < 2) {
    closePlayerCard(state, player.id, source.instanceId, definitions);
    player.flags.nobunagaPapiyasUpkeepRound = state.round;
    return;
  }
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${NOBUNAGA_PAPIYAS_ID}:upkeep:${state.round}`;
  state.effectQueue.unshift({
    effectId,
    handlerId: NOBUNAGA_PAPIYAS_RESOLVE,
    sourceId: NOBUNAGA_PAPIYAS_ID,
    controllerPlayerId: player.id,
    payload: { stage: "upkeep", round: state.round },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "nobunaga-papiyas-upkeep",
    options: [{ id: "pay", label: "支付2点魔力" }, { id: "close", label: "关闭此牌" }],
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
}


export const useNobunagaPapiyas: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, emitEvent }) => {
  if (!definitions) throw new Error("NOBUNAGA_PAPIYAS_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "round.started" || eventType === "phase.transitioned") {
    maybeResolveNobunagaPapiyasUpkeep(state, player, definitions, openDecision);
    return;
  }
  if (eventType === "player.defeated") {
    const source = activeNobunagaPapiyas(state, player);
    if (!source || typeof event?.playerId !== "string") return;
    return { powerBonus: addNobunagaPapiyasGrowth(source, 1) };
  }
  if (eventType === "round.ended") {
    const source = activeNobunagaPapiyas(state, player);
    const eliminated = Array.isArray(event?.eliminatedThisRound) ? event.eliminatedThisRound.filter((id): id is string => typeof id === "string") : [];
    if (!source || eliminated.length === 0) return;
    return { powerBonus: addNobunagaPapiyasGrowth(source, eliminated.length) };
  }

  const abilityId = readSkillAbilityId(payload);
  if (abilityId !== "desecration") throw new Error("NOBUNAGA_PAPIYAS_ABILITY_INVALID");
  const source = activeNobunagaPapiyas(state, player);
  const locationId = player.locationId;
  if (!source || state.phase !== "combat" || state.activePlayerId !== player.id || (locationId !== "mountain" && locationId !== "city")) {
    throw new Error("NOBUNAGA_PAPIYAS_WINDOW_INVALID");
  }
  const affected: string[] = [];
  for (const targetPlayerId of state.board.locations[locationId] ?? []) {
    if (targetPlayerId === player.id) continue;
    const target = state.players[targetPlayerId];
    if (!target || target.eliminated) continue;
    const luckIds = target.attack.filter((instanceId) => {
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      return Boolean(card && definition && card.zone === "attack" && card.face === "up" && card.active && isLuckCardInstance(state, card, definition, definitions));
    });
    if (luckIds.length === 0) continue;
    if (!isStructuredDefeatIgnored(state, targetPlayerId, definitions)) {
      defeatPlayerByEffect(state, targetPlayerId, player.id, definitions, emitEvent, { reason: "effect", sourceSkillId: skill.id });
    }
    for (const instanceId of luckIds) closePlayerCard(state, targetPlayerId, instanceId, definitions, { closedByPlayerId: player.id });
    affected.push(targetPlayerId);
  }
  return { affectedPlayerIds: affected };
};

export const isNobunagaPapiyasLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  if (!definitions || ability?.id !== "desecration") return false;
  const player = state.players[playerId];
  const locationId = player?.locationId;
  if (!player || state.phase !== "combat" || state.activePlayerId !== playerId || (locationId !== "mountain" && locationId !== "city") || !activeNobunagaPapiyas(state, player)) return false;
  return (state.board.locations[locationId] ?? []).some((targetPlayerId) => targetPlayerId !== playerId && state.players[targetPlayerId]?.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(card && definition && card.face === "up" && card.active && isLuckCardInstance(state, card, definition, definitions));
  }));
};


export const useNobunagaThreeLineFormation: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions || readSkillAbilityId(payload) !== "three-thousand-worlds") throw new Error("NOBUNAGA_THREE_LINE_ABILITY_INVALID");
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, NOBUNAGA_THREE_LINE_ID);
  const locationId = player.locationId;
  if (!sourceInstanceId || state.phase !== "combat" || state.activePlayerId !== player.id || (locationId !== "mountain" && locationId !== "city")) {
    throw new Error("NOBUNAGA_THREE_LINE_WINDOW_INVALID");
  }
  installStructuredRuleModifier(state, player.id, skill.id, sourceInstanceId, "three-thousand-worlds", {
    id: "three-line-non-magic-minus-two",
    operation: "subtract",
    rule: "card_power",
    scope: { subject: "opponents_at_source_battlefield", cards: { attributesNone: ["魔术"], zones: ["attack"] } },
    value: 2,
    lifecycle: { duration: "this_round" },
  });
  installStructuredRuleModifier(state, player.id, skill.id, sourceInstanceId, "three-thousand-worlds", {
    id: "three-line-zero-non-permanent-defeat",
    operation: "set",
    rule: "combat_post_power_defeat",
    scope: { subject: "opponents_at_source_battlefield", cards: { residual: false, zones: ["attack"] } },
    value: 0,
    lifecycle: { duration: "this_round" },
  });
  return { installed: true };
};

export const isNobunagaThreeLineFormationLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "three-thousand-worlds" && state.phase === "combat" && state.activePlayerId === playerId
    && (player.locationId === "mountain" || player.locationId === "city") && findActiveOwnedSkillAttack(state, playerId, NOBUNAGA_THREE_LINE_ID));
};

function orionHunterHasRepeatedAttribute(state: GameState, player: PlayerState, committed: string[], definitions: Record<string, CardDefinition>): boolean {
  const counts = new Map<string, number>();
  for (const instanceId of committed) {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    if (!card || !definition || card.ownerPlayerId !== player.id || card.zone !== "attack") continue;
    for (const attribute of new Set(getCardInstanceAttributes(card, definition, state, definitions))) counts.set(attribute, Number(counts.get(attribute) ?? 0) + 1);
  }
  return [...counts.values()].some((count) => count >= 2);
}


export const useOrionHunterMoon: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions) throw new Error("ORION_HUNTER_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "card.played") {
    if (Number(player.flags.orionHunterArmedRound ?? -1) !== state.round || event?.playerId !== player.id || typeof event.instanceId !== "string") return;
    const card = state.cards[event.instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    if (!card || !definition || definition.basic !== true || card.playedRound !== state.round) return;
    const modifierId = `${ORION_HUNTER_ID}:future-basic:${state.round}:${card.instanceId}`;
    if (!(card.powerModifiers ?? []).some((modifier) => modifier.id === modifierId)) {
      card.powerModifiers = [...(card.powerModifiers ?? []), { id: modifierId, sourceId: ORION_HUNTER_ID, kind: "add", value: 2, duration: "round" }];
    }
    return;
  }
  if (eventType === "attack.committed") {
    if (event?.playerId !== player.id || Number(player.flags.orionHunterPairBonusRound ?? -1) === state.round) return;
    const committed = Array.isArray(event.committed) ? event.committed.filter((id): id is string => typeof id === "string") : [];
    if (!orionHunterHasRepeatedAttribute(state, player, committed, definitions)) return;
    player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + 3;
    player.flags.orionHunterPairBonusRound = state.round;
    return;
  }
  if (readSkillAbilityId(payload) !== ORION_HUNTER_ABILITY || state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("ORION_HUNTER_WINDOW_INVALID");
  if (player.hand.length === 0) throw new Error("ORION_HUNTER_HAND_REQUIRED");
  payManaCost(state, player, 4, definitions);
  player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + 4;
  const discarded = discardRandomCardsFromHand(state, player.id, 1);
  if (discarded.length !== 1) throw new Error("ORION_HUNTER_RANDOM_DISCARD_FAILED");
  player.flags.orionHunterArmedRound = state.round;
  return { discardedInstanceId: discarded[0] };
};

export const isOrionHunterMoonLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === ORION_HUNTER_ABILITY && state.phase === "action" && state.activePlayerId === playerId
    && player.hand.length > 0 && (player.flags.infiniteMana === true || player.mana >= 4));
};

function orionBlessingUseCount(player: PlayerState, round: number): number {
  if (Number(player.flags.orionBlessingRound ?? -1) !== round) return 0;
  const count = Number(player.flags.orionBlessingCount ?? 0);
  if (!Number.isInteger(count) || count < 0 || count > 2) throw new Error("ORION_BLESSING_COUNT_INVALID");
  return count;
}

function orionBlessingCandidates(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return [...player.hand, ...player.deck].filter((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(card && definition?.basic === true && isLuckCardInstance(state, card, definition, definitions));
  });
}

const ORION_BLESSING_MARKER = `effect-until-close:${ORION_BLESSING_ID}:free-love`;

const resolveOrionSeaGodBlessing: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("ORION_BLESSING_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (previous.stage !== "choose-luck" || decision.status !== "resolved" || selections.length !== 1 || !candidates.includes(selections[0])) throw new Error("ORION_BLESSING_DECISION_INVALID");
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, ORION_BLESSING_ID);
  const liveCandidates = orionBlessingCandidates(state, player, definitions);
  const used = orionBlessingUseCount(player, state.round);
  if (!sourceInstanceId || state.phase !== "action" || state.activePlayerId !== player.id || used >= 2 || !liveCandidates.includes(selections[0])) throw new Error("ORION_BLESSING_SOURCE_INVALID");
  if (used === 1) {
    payManaCost(state, player, 4, definitions);
    player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + 4;
  }
  joinOwnedCardToAttack(state, player.id, selections[0], definitions, { manaCost: 0, allowedSourceZones: ["hand", "deck"] });
  const luck = state.cards[selections[0]];
  luck.residual = true;
  if (!luck.modifiers.includes(ORION_BLESSING_MARKER)) luck.modifiers.push(ORION_BLESSING_MARKER);
  player.flags.orionBlessingRound = state.round;
  player.flags.orionBlessingCount = used + 1;
  if (used + 1 < 2) delete player.usage[`${ORION_BLESSING_ID}:${ORION_BLESSING_ABILITY}`];
  return { joinedInstanceId: selections[0], useCount: used + 1, extraManaPaid: used === 1 ? 4 : 0 };
};


export const useOrionSeaGodBlessing: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("ORION_BLESSING_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "combat.ending") {
    const previousLocations = isRecord(event?.previousLocations) ? event.previousLocations : {};
    const locationId = previousLocations[player.id];
    const winnersByLocation = isRecord(event?.combatWinnerIdsByLocation) ? event.combatWinnerIdsByLocation : {};
    const winnerIds = typeof locationId === "string" && Array.isArray(winnersByLocation[locationId]) ? winnersByLocation[locationId] : [];
    const lost = (locationId === "mountain" || locationId === "city") && !winnerIds.includes(player.id);
    if (!player.defeated && !lost) return;
    const closed: string[] = [];
    for (const instanceId of [...player.attack]) {
      const card = state.cards[instanceId];
      if (!card?.active || card.face !== "up" || !card.residual || !card.modifiers.includes(ORION_BLESSING_MARKER)) continue;
      closePlayerCard(state, player.id, instanceId, definitions);
      closed.push(instanceId);
    }
    return { closedInstanceIds: closed };
  }
  if (readSkillAbilityId(payload) !== ORION_BLESSING_ABILITY) throw new Error("ORION_BLESSING_ABILITY_INVALID");
  const used = orionBlessingUseCount(player, state.round);
  if (state.phase !== "action" || state.activePlayerId !== player.id || !findActiveOwnedSkillAttack(state, player.id, skill.id) || used >= 2
    || (used === 1 && player.flags.infiniteMana !== true && player.mana < 4)) throw new Error("ORION_BLESSING_WINDOW_INVALID");
  const candidates = orionBlessingCandidates(state, player, definitions);
  if (candidates.length === 0) throw new Error("ORION_BLESSING_NO_LUCK");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:luck:${used}`;
  state.effectQueue.unshift({ effectId, handlerId: ORION_BLESSING_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "choose-luck", candidates }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "orion-sea-god-blessing-luck",
    options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
    min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {},
  });
};

export const isOrionSeaGodBlessingLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !definitions || ability?.id !== ORION_BLESSING_ABILITY || state.phase !== "action" || state.activePlayerId !== playerId
    || !findActiveOwnedSkillAttack(state, playerId, skill.id)) return false;
  const used = orionBlessingUseCount(player, state.round);
  return used < 2 && (used === 0 || player.flags.infiniteMana === true || player.mana >= 4) && orionBlessingCandidates(state, player, definitions).length > 0;
};

const JEANNE_ALTER_ROUTE = ["workshop", "mountain", "city", "scouting"] as const;

function activeJeanneAlterDragonWitch(state: GameState, player: PlayerState): GameState["cards"][string] | undefined {
  const instanceId = findActiveOwnedSkillAttack(state, player.id, JEANNE_ALTER_DRAGON_WITCH_ID);
  const source = instanceId ? state.cards[instanceId] : undefined;
  return source?.residual === true ? source : undefined;
}

function jeanneAlterAvengerIds(state: GameState, player: PlayerState): string[] {
  return player.attack.filter((instanceId) => {
    const card = state.cards[instanceId];
    return Boolean(card?.ownerPlayerId === player.id && card.active && card.face === "up" && card.definitionId === "card.card-avenger");
  });
}

function jeanneAlterForwardDestinations(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  if (!player.locationId || player.flags.movementBlockedPermanent === true || player.flags.movementBlockedRound === state.round) return [];
  const currentIndex = JEANNE_ALTER_ROUTE.indexOf(player.locationId as typeof JEANNE_ALTER_ROUTE[number]);
  if (currentIndex < 0) return [];
  return [1, 2].map((distance) => JEANNE_ALTER_ROUTE[currentIndex + distance]).filter((locationId): locationId is typeof JEANNE_ALTER_ROUTE[number] => Boolean(locationId))
    .filter((locationId) => canMovePlayerByEffect(state, player.id, locationId, definitions));
}

function jeanneAlterMarchOptions(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): Array<{ id: string; avengerId: string; locationId: string }> {
  const destinations = jeanneAlterForwardDestinations(state, player, definitions);
  return jeanneAlterAvengerIds(state, player).flatMap((avengerId) => destinations.map((locationId) => ({
    id: `${avengerId}::${locationId}`, avengerId, locationId,
  })));
}

const resolveJeanneAlterDragonWitch: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("JEANNE_ALTER_DRAGON_WITCH_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selection = Array.isArray(decision.selections) ? decision.selections[0] : undefined;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  if (previous.stage !== "march" || decision.status !== "resolved" || typeof selection !== "string" || !candidates.includes(selection)) throw new Error("JEANNE_ALTER_DRAGON_WITCH_DECISION_INVALID");
  if (!activeJeanneAlterDragonWitch(state, player) || state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("JEANNE_ALTER_DRAGON_WITCH_SOURCE_INVALID");
  const option = jeanneAlterMarchOptions(state, player, definitions).find((candidate) => candidate.id === selection);
  if (!option) throw new Error("JEANNE_ALTER_DRAGON_WITCH_SELECTION_INVALID");
  closePlayerCard(state, player.id, option.avengerId, definitions);
  const movement = movePlayerByEffect(state, player.id, option.locationId, definitions);
  emitEvent?.("player.moved", { playerId: player.id, ...movement, method: "effect", sourceId: JEANNE_ALTER_DRAGON_WITCH_ID });
  emitEvent?.("player.entered-location", { playerId: player.id, ...movement, method: "effect", sourceId: JEANNE_ALTER_DRAGON_WITCH_ID });
  const affected: string[] = [];
  if (player.locationId === "mountain" || player.locationId === "city") {
    for (const targetPlayerId of state.board.locations[player.locationId] ?? []) {
      if (targetPlayerId === player.id || state.players[targetPlayerId]?.eliminated) continue;
      adjustVictoryPoints(state.players[targetPlayerId], -2);
      affected.push(targetPlayerId);
    }
  }
  return { closedAvengerInstanceId: option.avengerId, movement, affectedPlayerIds: affected };
};


export const useJeanneAlterDragonWitch: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("JEANNE_ALTER_DRAGON_WITCH_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "combat.resolved") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
    if (!event || !isRecord(event.powers) || !Array.isArray(event.winnerIds) || !Object.prototype.hasOwnProperty.call(event.powers, player.id) || event.winnerIds.includes(player.id)) return;
    const source = activeJeanneAlterDragonWitch(state, player);
    if (source) closePlayerCard(state, player.id, source.instanceId, definitions);
    return;
  }
  if (readSkillAbilityId(payload) !== JEANNE_ALTER_DRAGON_WITCH_ABILITY || state.phase !== "action" || state.activePlayerId !== player.id || !activeJeanneAlterDragonWitch(state, player)) {
    throw new Error("JEANNE_ALTER_DRAGON_WITCH_WINDOW_INVALID");
  }
  const options = jeanneAlterMarchOptions(state, player, definitions);
  if (options.length === 0) throw new Error("JEANNE_ALTER_DRAGON_WITCH_NO_OPTION");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:march`;
  state.effectQueue.unshift({ effectId, handlerId: JEANNE_ALTER_DRAGON_WITCH_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "march", candidates: options.map((option) => option.id) }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "jeanne-alter-dragon-witch-march",
    options: options.map((option) => ({
      id: option.id,
      label: `${definitions[state.cards[option.avengerId].definitionId]?.name ?? "复仇者"} → ${option.locationId === "mountain" ? "深山町" : option.locationId === "city" ? "新都" : option.locationId}`,
    })),
    min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {},
  });
};

export const isJeanneAlterDragonWitchLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && ability?.id === JEANNE_ALTER_DRAGON_WITCH_ABILITY && state.phase === "action" && state.activePlayerId === playerId
    && activeJeanneAlterDragonWitch(state, player) && jeanneAlterMarchOptions(state, player, definitions).length > 0);
};


export const useJeanneAlterOblivionCorrection: SkillHandler = ({ state, player, payload, definitions, randomInt }) => {
  if (!definitions || !isRecord(payload) || payload.eventType !== "card.entered-attack" || !isRecord(payload.event)) return;
  const event = payload.event;
  if (event.face !== "up" || typeof event.instanceId !== "string") return;
  const entered = state.cards[event.instanceId];
  const enteredDefinition = entered ? definitions[entered.definitionId] : undefined;
  if (!entered || !enteredDefinition || !isLuckCardInstance(state, entered, enteredDefinition, definitions)) return;
  if (Number(player.flags.jeanneAlterOblivionRevision ?? -1) === state.revision) return;
  player.flags.jeanneAlterOblivionRevision = state.revision;
  const discarded = [...player.hand];
  const avengerIds = discarded.filter((instanceId) => state.cards[instanceId]?.definitionId === "card.card-avenger");
  for (const instanceId of discarded) movePlayerCard(state, player.id, instanceId, "discard");
  const drawn = drawCards(state, player.id, 3, randomInt ?? ((max) => new StateRandom().integer(state, max)), definitions);
  const joined: string[] = [];
  for (const instanceId of avengerIds) {
    const card = state.cards[instanceId];
    if (!card || card.ownerPlayerId !== player.id || card.zone === "attack" || card.zone === "removed") continue;
    joinOwnedCardToAttack(state, player.id, instanceId, definitions, { manaCost: 0, allowedSourceZones: [card.zone] });
    joined.push(instanceId);
  }
  return { discardedInstanceIds: discarded, drawnInstanceIds: drawn, joinedAvengerInstanceIds: joined };
};

const EMIYA_ALT_ATTRIBUTES = ["力量", "迅捷", "魔术", "特殊", "宝具"] as const;

function activeEmiyaAltUbw(state: GameState, player: PlayerState): GameState["cards"][string] | undefined {
  const instanceId = findActiveOwnedSkillAttack(state, player.id, EMIYA_ALT_UBW_ID);
  return instanceId ? state.cards[instanceId] : undefined;
}

function emiyaAltCombatPlayerIds(state: GameState, player: PlayerState): string[] {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") return [];
  return (state.board.locations[locationId] ?? []).filter((playerId) => !state.players[playerId]?.eliminated);
}

function emiyaAltUbwOptions(state: GameState, player: PlayerState): Array<{ id: string; playerId: string; attribute: string }> {
  return emiyaAltCombatPlayerIds(state, player).flatMap((targetPlayerId) => EMIYA_ALT_ATTRIBUTES.map((attribute) => ({
    id: `${targetPlayerId}::${attribute}`,
    playerId: targetPlayerId,
    attribute,
  })));
}

const resolveEmiyaAltUnlimitedBladeWorks: SkillHandler = ({ state, player, payload, definitions, randomInt, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("EMIYA_ALT_UBW_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selection = Array.isArray(decision.selections) ? decision.selections[0] : undefined;
  if (previous.stage !== "iron-heart" || decision.status !== "resolved" || typeof selection !== "string" || !candidates.includes(selection)) throw new Error("EMIYA_ALT_UBW_DECISION_INVALID");
  if (state.phase !== "combat" || state.activePlayerId !== player.id || !activeEmiyaAltUbw(state, player)) throw new Error("EMIYA_ALT_UBW_SOURCE_INVALID");
  const option = emiyaAltUbwOptions(state, player).find((candidate) => candidate.id === selection);
  if (!option) throw new Error("EMIYA_ALT_UBW_TARGET_INVALID");
  const target = state.players[option.playerId];
  const returned = [...target.discard].filter((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(card && definition && getCardInstanceAttributes(card, definition, state, definitions).includes(option.attribute));
  });
  for (const instanceId of returned) movePlayerCard(state, target.id, instanceId, "deck");
  if (returned.length > 0) {
    const random = new StateRandom();
    shufflePlayerDeck(state, target.id, randomInt ?? ((maxExclusive: number) => random.integer(state, maxExclusive)));
    player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + returned.length * 2;
  }
  if (returned.length >= 4) defeatPlayerByEffect(state, target.id, player.id, definitions, emitEvent, { reason: "effect", sourceSkillId: EMIYA_ALT_UBW_ID });
  return { targetPlayerId: target.id, attribute: option.attribute, returnedInstanceIds: returned, powerBonus: returned.length * 2 };
};


export const useEmiyaAltUnlimitedBladeWorks: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions || readSkillAbilityId(payload) !== EMIYA_ALT_UBW_ABILITY || state.phase !== "combat" || state.activePlayerId !== player.id || !activeEmiyaAltUbw(state, player)) {
    throw new Error("EMIYA_ALT_UBW_WINDOW_INVALID");
  }
  const options = emiyaAltUbwOptions(state, player);
  if (options.length === 0) throw new Error("EMIYA_ALT_UBW_NO_TARGET");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:iron-heart`;
  state.effectQueue.unshift({ effectId, handlerId: EMIYA_ALT_UBW_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "iron-heart", candidates: options.map((option) => option.id) }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "emiya-alt-unlimited-blade-works",
    options: options.map((option) => ({ id: option.id, label: `${state.players[option.playerId]?.name ?? option.playerId} · ${option.attribute}` })),
    min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {},
  });
};

export const isEmiyaAltUnlimitedBladeWorksLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === EMIYA_ALT_UBW_ABILITY && state.phase === "combat" && state.activePlayerId === playerId
    && activeEmiyaAltUbw(state, player) && emiyaAltCombatPlayerIds(state, player).length > 0);
};


export const useEmiyaAltKanshouBakuya: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || payload.eventType !== "card.played" || !isRecord(payload.event)) return;
  const event = payload.event;
  if (event.playerId !== player.id || event.face !== "up" || event.definitionId !== EMIYA_ALT_KANSHOU_ID || typeof event.instanceId !== "string") return;
  const source = state.cards[event.instanceId];
  if (!source || source.ownerPlayerId !== player.id || source.zone !== "attack" || !source.active) throw new Error("EMIYA_ALT_KANSHOU_SOURCE_INVALID");
  const data = isRecord(event.data) ? event.data : undefined;
  const selected = data && Array.isArray(data.removedDiscardInstanceIds)
    ? data.removedDiscardInstanceIds.filter((id): id is string => typeof id === "string")
    : [];
  if (selected.length !== 2 || new Set(selected).size !== 2) throw new Error("EMIYA_ALT_KANSHOU_TWO_DISCARD_REQUIRED");
  const gained = new Set<string>();
  for (const instanceId of selected) {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    if (!card || !definition || card.ownerPlayerId !== player.id || card.zone !== "discard") throw new Error("EMIYA_ALT_KANSHOU_DISCARD_INVALID");
    for (const attribute of getCardInstanceAttributes(card, definition, state, definitions)) gained.add(attribute);
  }
  for (const instanceId of selected) movePlayerCard(state, player.id, instanceId, "removed");
  const sourceDefinition = definitions[source.definitionId];
  source.attributeOverrides = normalizeCardAttributes([...getCardAttributes(sourceDefinition), ...gained]);
  const prefix = "attribute-overrides-until-round-end:";
  source.modifiers = [
    ...(source.modifiers ?? []).filter((marker) => !marker.startsWith(prefix)),
    `${prefix}${state.round}:${EMIYA_ALT_KANSHOU_ID}:bulletproof`,
  ];
  return { removedInstanceIds: selected, gainedAttributes: [...gained] };
};

function merlinFlowerSeaSource(state: GameState, playerId: string): GameState["cards"][string] | undefined {
  const instanceId = findActiveOwnedSkillAttack(state, playerId, MERLIN_FLOWER_SEA_ID);
  return instanceId ? state.cards[instanceId] : undefined;
}


export const useMerlinFlowerSea: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions || readSkillAbilityId(payload) !== MERLIN_FLOWER_SEA_ABILITY || state.phase !== "combat" || state.activePlayerId !== player.id) {
    throw new Error("MERLIN_FLOWER_SEA_WINDOW_INVALID");
  }
  const source = merlinFlowerSeaSource(state, player.id);
  if (!source) throw new Error("MERLIN_FLOWER_SEA_SOURCE_NOT_ACTIVE");
  if (player.locationId !== "mountain" && player.locationId !== "city") throw new Error("MERLIN_FLOWER_SEA_BATTLEFIELD_REQUIRED");
  const data = isRecord(payload) && isRecord(payload.data) ? payload.data : payload;
  const x = isRecord(data) ? Number(data.x) : Number.NaN;
  if (!Number.isInteger(x) || x < 0) throw new Error("MERLIN_FLOWER_SEA_X_INVALID");
  const manaLost = x === 0 ? loseMana(player, 5) : 0;
  const affected: string[] = [];
  for (const targetPlayerId of state.board.locations[player.locationId] ?? []) {
    const target = state.players[targetPlayerId];
    if (!target || target.eliminated) continue;
    for (const instanceId of target.attack) {
      if (instanceId === source.instanceId) continue;
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      if (!card || !definition || !card.active || card.face !== "up") continue;
      if (getCardPlayCost(state, definition, target, card, definitions) !== x) continue;
      const modifierId = `${skill.id}:${MERLIN_FLOWER_SEA_ABILITY}:${state.round}:${instanceId}`;
      card.powerModifiers = [
        ...(card.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
        { id: modifierId, sourceId: skill.id, kind: "set", value: 0, duration: "round" },
      ];
      affected.push(instanceId);
    }
  }
  return { x, manaLost, affectedInstanceIds: affected };
};

export const isMerlinFlowerSeaLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === MERLIN_FLOWER_SEA_ABILITY && state.phase === "combat" && state.activePlayerId === playerId
    && (player.locationId === "mountain" || player.locationId === "city") && merlinFlowerSeaSource(state, playerId));
};

function valkyrieCommanderInstanceIds(state: GameState, player: PlayerState): Map<string, string> {
  const found = new Map<string, string>();
  for (const card of Object.values(state.cards)) {
    if (card.ownerPlayerId !== player.id || !VALKYRIE_COMMANDER_IDS.includes(card.definitionId as typeof VALKYRIE_COMMANDER_IDS[number])) continue;
    if (found.has(card.definitionId)) throw new Error("VALKYRIE_COMMANDER_DUPLICATE");
    found.set(card.definitionId, card.instanceId);
  }
  return found;
}

const resolveValkyrieMaidenDescent: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("VALKYRIE_DESCENT_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (previous.stage !== "choose-destinations" || decision.status !== "resolved" || selections.length !== 3 || new Set(selections).size !== 3) {
    throw new Error("VALKYRIE_DESCENT_DECISION_INVALID");
  }
  const choices = new Map<string, "hand" | "attack">();
  for (const selection of selections) {
    const [definitionId, destination] = selection.split("::");
    if (!VALKYRIE_COMMANDER_IDS.includes(definitionId as typeof VALKYRIE_COMMANDER_IDS[number]) || (destination !== "hand" && destination !== "attack") || choices.has(definitionId)) {
      throw new Error("VALKYRIE_DESCENT_SELECTION_INVALID");
    }
    choices.set(definitionId, destination);
  }
  if (choices.size !== VALKYRIE_COMMANDER_IDS.length) throw new Error("VALKYRIE_DESCENT_SELECTION_INVALID");
  const commanderIds = valkyrieCommanderInstanceIds(state, player);
  if (commanderIds.size !== VALKYRIE_COMMANDER_IDS.length) throw new Error("VALKYRIE_COMMANDER_MISSING");
  const moved: Array<{ instanceId: string; destination: "hand" | "attack" }> = [];
  for (const definitionId of VALKYRIE_COMMANDER_IDS) {
    const instanceId = commanderIds.get(definitionId)!;
    const destination = choices.get(definitionId)!;
    const card = state.cards[instanceId];
    if (destination === "attack") {
      if (card.zone !== "attack" || !card.active || card.face !== "up") {
        joinOwnedCardToAttack(state, player.id, instanceId, definitions, {
          manaCost: 0,
          allowedSourceZones: ["hand", "deck", "discard", "removed", "attack"],
        });
      }
    } else {
      if (card.zone !== "hand") movePlayerCard(state, player.id, instanceId, "hand");
      card.face = "down";
      card.active = false;
      card.residual = false;
      card.paidCost = undefined;
    }
    moved.push({ instanceId, destination });
  }
  return { moved };
};


export const useValkyrieMaidenDescent: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions || readSkillAbilityId(payload) !== "maiden-descent" || state.phase !== "outpost" || state.activePlayerId !== player.id) {
    throw new Error("VALKYRIE_DESCENT_WINDOW_INVALID");
  }
  const commanderIds = valkyrieCommanderInstanceIds(state, player);
  if (commanderIds.size !== VALKYRIE_COMMANDER_IDS.length) throw new Error("VALKYRIE_COMMANDER_MISSING");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:descent`;
  const options = VALKYRIE_COMMANDER_IDS.flatMap((definitionId) => ([
    { id: `${definitionId}::hand`, label: `${definitions[definitionId]?.name ?? definitionId} → 手牌` },
    { id: `${definitionId}::attack`, label: `${definitions[definitionId]?.name ?? definitionId} → 攻击区` },
  ]));
  state.effectQueue.unshift({ effectId, handlerId: VALKYRIE_DESCENT_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "choose-destinations" }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "valkyrie-maiden-descent",
    options, min: 3, max: 3, allowCancel: false, continuationEffectId: effectId, submissions: {},
  });
};

export const isValkyrieMaidenDescentLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "maiden-descent" && state.phase === "outpost" && state.activePlayerId === playerId
    && valkyrieCommanderInstanceIds(state, player).size === VALKYRIE_COMMANDER_IDS.length);
};

function valkyrieNextLocation(player: PlayerState): typeof forwardLocationOrder[number] | undefined {
  if (!player.locationId) return undefined;
  const index = forwardLocationOrder.indexOf(player.locationId as typeof forwardLocationOrder[number]);
  return index >= 0 ? forwardLocationOrder[index + 1] : undefined;
}

function restingValkyrieSwan(state: GameState, player: PlayerState): GameState["cards"][string] | undefined {
  const instanceId = player.servantSkills.find((id) => {
    const card = state.cards[id];
    return card?.ownerPlayerId === player.id && card.definitionId === VALKYRIE_SWAN_ID && card.zone === "servant-skills";
  });
  return instanceId ? state.cards[instanceId] : undefined;
}

function activeValkyrieCommanderIds(state: GameState, player: PlayerState): string[] {
  return player.attack.filter((instanceId) => {
    const card = state.cards[instanceId];
    return Boolean(card?.active && card.face === "up" && VALKYRIE_COMMANDER_IDS.includes(card.definitionId as typeof VALKYRIE_COMMANDER_IDS[number]));
  });
}


export const useValkyrieSwanDress: SkillHandler = ({ state, player, skill, payload, definitions, emitEvent }) => {
  if (!definitions) throw new Error("VALKYRIE_SWAN_DEFINITIONS_REQUIRED");
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === "swan-move-action" || abilityId === "swan-move-combat") {
    const expectedPhase = abilityId === "swan-move-action" ? "action" : "combat";
    if (state.phase !== expectedPhase || state.activePlayerId !== player.id || !findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("VALKYRIE_SWAN_MOVE_WINDOW_INVALID");
    const destination = valkyrieNextLocation(player);
    if (!destination) throw new Error("VALKYRIE_SWAN_NO_FORWARD_LOCATION");
    const movement = movePlayerByEffect(state, player.id, destination, definitions);
    emitEvent?.("player.moved", { playerId: player.id, ...movement, method: "effect", sourceId: skill.id });
    emitEvent?.("player.entered-location", { playerId: player.id, ...movement, method: "effect", sourceId: skill.id });
    return movement;
  }
  if (abilityId === "steel-shield") {
    if (state.phase !== "combat" || state.activePlayerId !== player.id) throw new Error("VALKYRIE_STEEL_SHIELD_WINDOW_INVALID");
    const source = restingValkyrieSwan(state, player);
    if (!source) throw new Error("VALKYRIE_STEEL_SHIELD_SOURCE_UNAVAILABLE");
    const commanderIds = activeValkyrieCommanderIds(state, player);
    const data = isRecord(payload) && isRecord(payload.data) ? payload.data : payload;
    const commanderId = isRecord(data) && typeof data.commanderInstanceId === "string" ? data.commanderInstanceId : undefined;
    if (!commanderId || !commanderIds.includes(commanderId)) throw new Error("VALKYRIE_STEEL_SHIELD_COMMANDER_INVALID");
    const sourceDefinition = definitions[source.definitionId];
    const cost = getCardPlayCost(state, sourceDefinition, player, source, definitions);
    payManaCost(state, player, cost, definitions);
    if (cost > 0) player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + cost;
    const commander = state.cards[commanderId];
    movePlayerCard(state, player.id, commanderId, "hand");
    commander.face = "down";
    commander.active = false;
    commander.residual = false;
    commander.paidCost = undefined;
    joinOwnedCardToAttack(state, player.id, source.instanceId, definitions, { manaCost: 0, allowedSourceZones: ["servant-skills"] });
    return { commanderInstanceId: commanderId, sourceInstanceId: source.instanceId, paidMana: cost };
  }
  throw new Error("VALKYRIE_SWAN_ABILITY_INVALID");
};

export const isValkyrieSwanDressLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || !definitions || state.activePlayerId !== playerId) return false;
  if (ability.id === "swan-move-action" || ability.id === "swan-move-combat") {
    const expectedPhase = ability.id === "swan-move-action" ? "action" : "combat";
    if (state.phase !== expectedPhase || !findActiveOwnedSkillAttack(state, player.id, skill.id)) return false;
    const destination = valkyrieNextLocation(player);
    if (!destination) return false;
    const draft = structuredClone(state);
    try { movePlayerByEffect(draft, player.id, destination, definitions); return true; } catch { return false; }
  }
  if (ability.id === "steel-shield") {
    const source = restingValkyrieSwan(state, player);
    if (!source || state.phase !== "combat" || activeValkyrieCommanderIds(state, player).length === 0) return false;
    return player.flags.infiniteMana === true || player.mana >= getCardPlayCost(state, definitions[source.definitionId], player, source, definitions);
  }
  return false;
};

function initializeSanzangTeachingsResidual(state: GameState, player: PlayerState, sourceInstanceId: string): void {
  const source = state.cards[sourceInstanceId];
  if (!source || source.ownerPlayerId !== player.id || source.definitionId !== SANZANG_TEACHINGS_ID || source.zone !== "attack" || !source.active || source.face !== "up") {
    throw new Error("SANZANG_TEACHINGS_SOURCE_NOT_ACTIVE");
  }
  source.residual = true;
  source.residualUntilRound = Math.max(Number(source.residualUntilRound ?? state.round + 1), state.round + 1);
}

function openSanzangTeachingsXDecision(
  state: GameState,
  player: PlayerState,
  sourceInstanceId: string,
  openDecision: SkillContext["openDecision"],
): void {
  const availableCardCount = player.hand.length + player.deck.length + player.discard.length;
  const maxByMana = player.flags.infiniteMana === true ? availableCardCount : Math.floor(player.mana / 3);
  const maxX = Math.max(0, Math.min(maxByMana, availableCardCount));
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${SANZANG_TEACHINGS_ID}:x`;
  state.effectQueue.unshift({
    effectId,
    handlerId: SANZANG_TEACHINGS_RESOLVE,
    sourceId: SANZANG_TEACHINGS_ID,
    controllerPlayerId: player.id,
    payload: { stage: "choose-x", sourceInstanceId, maxX },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "sanzang-teachings-x",
    options: Array.from({ length: maxX + 1 }, (_, x) => ({ id: String(x), label: `X=${x}` })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
}

const resolveSanzangTeachings: SkillHandler = ({ state, player, payload, definitions, openDecision, randomInt }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) {
    throw new Error("SANZANG_TEACHINGS_DECISION_INVALID");
  }
  const previous = payload.previous;
  const decision = payload.decision;
  const sourceInstanceId = typeof previous.sourceInstanceId === "string" ? previous.sourceInstanceId : undefined;
  if (!sourceInstanceId) throw new Error("SANZANG_TEACHINGS_SOURCE_INVALID");
  initializeSanzangTeachingsResidual(state, player, sourceInstanceId);
  if (decision.status !== "resolved" || !Array.isArray(decision.selections)) throw new Error("SANZANG_TEACHINGS_DECISION_INVALID");

  if (previous.stage === "choose-x") {
    if (decision.selections.length !== 1 || typeof decision.selections[0] !== "string") throw new Error("SANZANG_TEACHINGS_X_INVALID");
    const x = Number(decision.selections[0]);
    const maxX = Number(previous.maxX);
    if (!Number.isInteger(x) || x < 0 || !Number.isInteger(maxX) || x > maxX) throw new Error("SANZANG_TEACHINGS_X_INVALID");
    payManaCost(state, player, x * 3, definitions, "SANZANG_TEACHINGS_INSUFFICIENT_MANA");
    if (x > 0) player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + x * 3;
    const random = new StateRandom();
    drawCards(state, player.id, x, randomInt ?? ((maxExclusive) => random.integer(state, maxExclusive)), definitions);
    if (x === 0) {
      installInstanceCardPowerBonus(state, player, sourceInstanceId, SANZANG_TEACHINGS_ID, "sanzang-teachings-luck", 0);
      return;
    }
    if (player.hand.length < x) throw new Error("SANZANG_TEACHINGS_EXILE_COUNT_UNAVAILABLE");
    const candidates = [...player.hand];
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${SANZANG_TEACHINGS_ID}:remove`;
    state.effectQueue.unshift({
      effectId,
      handlerId: SANZANG_TEACHINGS_RESOLVE,
      sourceId: SANZANG_TEACHINGS_ID,
      controllerPlayerId: player.id,
      payload: { stage: "remove", sourceInstanceId, x, candidates },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "sanzang-teachings-remove",
      options: candidates.map((id) => ({ id, label: definitions[state.cards[id]?.definitionId ?? ""]?.name ?? id })),
      min: x,
      max: x,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }

  if (previous.stage === "remove") {
    const x = Number(previous.x);
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const selections = decision.selections.filter((id): id is string => typeof id === "string");
    if (!Number.isInteger(x) || x < 0 || selections.length !== x || new Set(selections).size !== selections.length
      || selections.some((id) => !candidates.includes(id) || !player.hand.includes(id))) throw new Error("SANZANG_TEACHINGS_EXILE_SELECTION_INVALID");
    let luckCount = 0;
    for (const instanceId of selections) {
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      if (!card || !definition) throw new Error("SANZANG_TEACHINGS_CARD_INVALID");
      if (isLuckCardInstance(state, card, definition, definitions)) luckCount += 1;
    }
    for (const instanceId of selections) movePlayerCard(state, player.id, instanceId, "removed");
    installInstanceCardPowerBonus(state, player, sourceInstanceId, SANZANG_TEACHINGS_ID, "sanzang-teachings-luck", luckCount * 4);
    return;
  }
  throw new Error("SANZANG_TEACHINGS_STAGE_INVALID");
};


export const useSanzangTeachings: SkillHandler = ({ state, player, payload, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType !== "card.played" || !event) return;
  const sourceInstanceId = typeof event.instanceId === "string" ? event.instanceId : undefined;
  if (!sourceInstanceId || event.playerId !== player.id || state.cards[sourceInstanceId]?.definitionId !== SANZANG_TEACHINGS_ID) return;
  initializeSanzangTeachingsResidual(state, player, sourceInstanceId);
  openSanzangTeachingsXDecision(state, player, sourceInstanceId, openDecision);
};

function sanzangPalmHiddenCandidates(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return player.hand.filter((instanceId) => {
    try {
      assertCardCanEnterAttack({ state, playerId: player.id, instanceId, definitions, faceDown: true });
      return true;
    } catch {
      return false;
    }
  });
}


export const useSanzangPalm: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("SANZANG_PALM_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "phase.transitioned") {
    if (!event || event.previousPhase !== "action" || event.transition !== "next-phase" || state.phase !== "combat") return;
    const hiddenInstanceId = typeof player.flags.sanzangPalmHiddenInstanceId === "string" ? player.flags.sanzangPalmHiddenInstanceId : undefined;
    const sourceInstanceId = typeof player.flags.sanzangPalmSourceInstanceId === "string" ? player.flags.sanzangPalmSourceInstanceId : undefined;
    if (!hiddenInstanceId || !sourceInstanceId) return;
    const hidden = state.cards[hiddenInstanceId];
    const hiddenDefinition = hidden ? definitions[hidden.definitionId] : undefined;
    if (hidden && hiddenDefinition && hidden.ownerPlayerId === player.id && hidden.zone === "attack" && hidden.face === "down") {
      hidden.face = "up";
      const lucky = isLuckCardInstance(state, hidden, hiddenDefinition, definitions);
      movePlayerCard(state, player.id, hiddenInstanceId, "discard");
      hidden.face = "down";
      hidden.active = false;
      hidden.residual = false;
      if (lucky) installInstanceCardPowerBonus(state, player, sourceInstanceId, skill.id, "sanzang-palm-luck", 5);
    }
    delete player.flags.sanzangPalmHiddenInstanceId;
    delete player.flags.sanzangPalmSourceInstanceId;
    return;
  }
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== SANZANG_PALM_ABILITY) throw new Error("SANZANG_PALM_ABILITY_INVALID");
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("SANZANG_PALM_SOURCE_NOT_ACTIVE");
  if (player.flags.sanzangPalmHiddenInstanceId) throw new Error("SANZANG_PALM_HIDDEN_ALREADY_SET");
  const candidates = sanzangPalmHiddenCandidates(state, player, definitions);
  if (candidates.length === 0) throw new Error("SANZANG_PALM_NO_HIDDEN_ATTACK");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:hide`;
  state.effectQueue.unshift({
    effectId,
    handlerId: SANZANG_PALM_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { sourceInstanceId, candidates },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "sanzang-palm-hidden-attack",
    options: candidates.map((id) => ({ id, label: definitions[state.cards[id]?.definitionId ?? ""]?.name ?? id })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isSanzangPalmLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && ability?.id === SANZANG_PALM_ABILITY && state.phase === "action" && state.activePlayerId === playerId
    && !player.flags.sanzangPalmHiddenInstanceId && findActiveOwnedSkillAttack(state, playerId, skill.id)
    && sanzangPalmHiddenCandidates(state, player, definitions).length > 0);
};

const resolveSanzangPalm: SkillHandler = ({ state, player, skill, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("SANZANG_PALM_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) throw new Error("SANZANG_PALM_DECISION_INVALID");
  const sourceInstanceId = typeof previous.sourceInstanceId === "string" ? previous.sourceInstanceId : undefined;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const instanceId = decision.selections[0];
  if (!sourceInstanceId || typeof instanceId !== "string" || !candidates.includes(instanceId)
    || !sanzangPalmHiddenCandidates(state, player, definitions).includes(instanceId)) throw new Error("SANZANG_PALM_TARGET_INVALID");
  if (!findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("SANZANG_PALM_SOURCE_NOT_ACTIVE");
  const card = state.cards[instanceId];
  movePlayerCard(state, player.id, instanceId, "attack");
  card.face = "down";
  card.active = false;
  card.residual = false;
  card.paidCost = 0;
  card.playedRound = state.round;
  player.flags.sanzangPalmHiddenInstanceId = instanceId;
  player.flags.sanzangPalmSourceInstanceId = sourceInstanceId;
  emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: null, face: "down", paidMana: 0, attributes: [] });
};


export const useAngraBites: SkillHandler = ({ state, player, skill, randomInt, definitions }) => {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("ANGRA_BITES_NOT_IN_BATTLEFIELD");
  const opponents = (state.board.locations[locationId] ?? []).filter((id) => id !== player.id && !state.players[id]?.eliminated);
  if (opponents.length > 0) {
    const count = Number(skill.drawCount ?? 0);
    if (!Number.isInteger(count) || count <= 0) throw new Error("ANGRA_BITES_DRAW_INVALID");
    drawCards(state, player.id, count, randomInt ?? (() => 0), definitions);
    return;
  }
  const amount = Number(skill.manaGain ?? 0);
  if (!Number.isInteger(amount) || amount <= 0) throw new Error("ANGRA_BITES_MANA_INVALID");
  gainMana(player, amount);
};

export const isAngraBitesLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  return Boolean(player && (player.locationId === "mountain" || player.locationId === "city"));
};

export const useCombatPowerFromBattlefieldPlayedCosts: SkillHandler = ({ state, player, skill }) => {
  if (skill.combatPowerBonusFromBattlefieldPlayedCosts !== true) throw new Error("BATTLEFIELD_PLAYED_COST_RULE_INVALID");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("BATTLEFIELD_PLAYED_COST_NOT_IN_BATTLE");
  let amount = 0;
  for (const participantId of state.board.locations[locationId] ?? []) {
    const participant = state.players[participantId];
    if (!participant || participant.eliminated) continue;
    for (const instanceId of participant.attack) {
      const card = state.cards[instanceId];
      if (!card || card.playedRound !== state.round) continue;
      const paidCost = Number(card.paidCost ?? 0);
      if (Number.isInteger(paidCost) && paidCost > 0) amount += paidCost;
    }
  }
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + amount;
};

export const isCombatPowerFromBattlefieldPlayedCostsLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  return Boolean(skill.combatPowerBonusFromBattlefieldPlayedCosts === true
    && player
    && (player.locationId === "mountain" || player.locationId === "city"));
};


export const useCombatPowerFromCommandSealUsers: SkillHandler = ({ state, player, skill }) => {
  const rule = skill.combatPowerBonusPerCommandSealUser;
  if (!rule || !Number.isInteger(rule.base) || !Number.isInteger(rule.ownCommandSealMultiplier)) {
    throw new Error("COMMAND_SEAL_POWER_RULE_INVALID");
  }
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("COMMAND_SEAL_POWER_NOT_IN_BATTLE");
  const count = countCommandSealUsingOpponents(state, player.id, locationId, rule.includeRulerCommandSeals === true);
  if (count <= 0) throw new Error("COMMAND_SEAL_POWER_NO_TARGET");
  const amount = count * (rule.base + rule.ownCommandSealMultiplier * player.commandSeals);
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + amount;
};

export const isCombatPowerFromCommandSealUsersLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  const rule = skill.combatPowerBonusPerCommandSealUser;
  return Boolean(rule
    && player
    && (player.locationId === "mountain" || player.locationId === "city")
    && countCommandSealUsingOpponents(state, player.id, player.locationId, rule.includeRulerCommandSeals === true) > 0);
};

function countCommandSealUsingOpponents(state: GameState, playerId: string, locationId: string, includeRulerCommandSeals: boolean): number {
  return (state.board.locations[locationId] ?? []).filter((id) => {
    const candidate = state.players[id];
    if (!candidate || id === playerId || candidate.eliminated) return false;
    const usedCommandSeal = Number(candidate.flags.commandSealUsedRound ?? 0) === state.round;
    const usedRulerCommandSeal = includeRulerCommandSeals && Number(candidate.flags.rulerCommandSealUsedRound ?? 0) === state.round;
    return usedCommandSeal || usedRulerCommandSeal;
  }).length;
}

const SANSON_JUDGMENT_ID = "servant.sanson.skill.sc-sanson-1";
const SANSON_JUDGMENT_HANDLER = "core.sanson-judgment-day";
const SANSON_JUDGMENT_RESOLVE = "core.sanson-judgment-day-resolve";
const SANSON_HOPE_ID = "servant.sanson.skill.sc-sanson-2";
const SANSON_HOPE_HANDLER = "core.sanson-death-hope";
const SANSON_HOPE_RESOLVE = "core.sanson-death-hope-resolve";

function sansonAccusationFlag(controllerPlayerId: string): string {
  return `sansonAccusedBy:${controllerPlayerId}`;
}

function syncSansonAccusedStatus(player: PlayerState): void {
  const accused = Object.keys(player.flags).some((key) => key.startsWith("sansonAccusedBy:"));
  if (accused) {
    if (!player.statuses.includes("控诉")) player.statuses.push("控诉");
  } else {
    player.statuses = player.statuses.filter((status) => status !== "控诉");
  }
}

function isAccusedBySanson(player: PlayerState | undefined, controllerPlayerId: string): boolean {
  return Boolean(player && player.flags[sansonAccusationFlag(controllerPlayerId)] !== undefined);
}

function clearSansonAccusation(state: GameState, controllerPlayerId: string, targetPlayerId: string): void {
  const target = state.players[targetPlayerId];
  if (!target) return;
  delete target.flags[sansonAccusationFlag(controllerPlayerId)];
  syncSansonAccusedStatus(target);
}

function clearSansonAccusations(state: GameState, controllerPlayerId: string, roundOnly?: number): void {
  const key = sansonAccusationFlag(controllerPlayerId);
  for (const target of Object.values(state.players)) {
    const value = target.flags[key];
    if (value === undefined) continue;
    if (roundOnly !== undefined && value !== `round:${roundOnly}`) continue;
    delete target.flags[key];
    syncSansonAccusedStatus(target);
  }
}

function accuseBySanson(state: GameState, controllerPlayerId: string, targetPlayerId: string, duration: "persistent" | "round"): void {
  const target = state.players[targetPlayerId];
  if (!target || target.eliminated || targetPlayerId === controllerPlayerId) return;
  target.flags[sansonAccusationFlag(controllerPlayerId)] = duration === "persistent" ? "persistent" : `round:${state.round}`;
  syncSansonAccusedStatus(target);
}

const resolveSansonJudgmentDay: SkillHandler = ({ state, player, payload }) => {
  if (!isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("SANSON_JUDGMENT_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (previous.stage !== "vote" || decision.status !== "resolved" || !isRecord(decision.submissions)) throw new Error("SANSON_JUDGMENT_DECISION_INVALID");
  const chooserIds = Array.isArray(previous.chooserPlayerIds) ? previous.chooserPlayerIds.filter((id): id is string => typeof id === "string") : [];
  const eligibleTargetIds = Array.isArray(previous.eligibleTargetIds) ? previous.eligibleTargetIds.filter((id): id is string => typeof id === "string") : [];
  if (chooserIds.length === 0 || eligibleTargetIds.length === 0) throw new Error("SANSON_JUDGMENT_DECISION_INVALID");

  const counts = new Map<string, number>();
  const nonAbstainingOpponents: string[] = [];
  for (const chooserId of chooserIds) {
    const submission = decision.submissions[chooserId];
    if (!Array.isArray(submission) || submission.length !== 1 || typeof submission[0] !== "string") throw new Error("SANSON_JUDGMENT_DECISION_INVALID");
    const vote = submission[0];
    if (vote === "abstain") continue;
    if (!eligibleTargetIds.includes(vote)) throw new Error("SANSON_JUDGMENT_TARGET_INVALID");
    counts.set(vote, (counts.get(vote) ?? 0) + 1);
    if (chooserId !== player.id) nonAbstainingOpponents.push(chooserId);
  }

  if (counts.size === 0) return { accusedPlayerIds: [], tied: true };
  const highest = Math.max(...counts.values());
  const leaders = [...counts.entries()].filter(([, count]) => count === highest).map(([id]) => id);
  if (leaders.length === 1) {
    accuseBySanson(state, player.id, leaders[0], "persistent");
    return { accusedPlayerIds: leaders, tied: false };
  }
  const accused = [...new Set(nonAbstainingOpponents)];
  for (const targetId of accused) accuseBySanson(state, player.id, targetId, "round");
  return { accusedPlayerIds: accused, tied: true };
};

/** Judgment Day: simultaneous secret-choice semantics are represented by one multi-chooser decision. */
export const useSansonJudgmentDay: SkillHandler = ({ state, player, skill, payload, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "round.ending") {
    clearSansonAccusations(state, player.id, state.round);
    return;
  }
  if (readSkillAbilityId(payload) !== "judgment-day" || state.phase !== "outpost" || state.activePlayerId !== player.id) {
    throw new Error("SANSON_JUDGMENT_WINDOW_INVALID");
  }
  const chooserPlayerIds = Object.values(state.players).filter((candidate) => !candidate.eliminated).map((candidate) => candidate.id);
  const eligibleTargetIds = chooserPlayerIds.filter((id) => id !== player.id);
  if (eligibleTargetIds.length === 0) throw new Error("SANSON_JUDGMENT_NO_TARGET");

  // The prior persistent accusation lasts exactly until Sanson uses Judgment Day again.
  clearSansonAccusations(state, player.id);
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:vote`;
  state.effectQueue.unshift({
    effectId,
    handlerId: SANSON_JUDGMENT_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { stage: "vote", chooserPlayerIds, eligibleTargetIds },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds,
    kind: "sanson-judgment-day-vote",
    options: [
      ...eligibleTargetIds.map((id) => ({ id, label: state.players[id]?.name ?? id })),
      { id: "abstain", label: "弃票" },
    ],
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isSansonJudgmentDayLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "judgment-day" && state.phase === "outpost" && state.activePlayerId === playerId
    && Object.values(state.players).some((candidate) => candidate.id !== playerId && !candidate.eliminated));
};

function sansonHopeCandidates(state: GameState, playerId: string): string[] {
  const player = state.players[playerId];
  const locationId = player?.locationId;
  if (!player || (locationId !== "mountain" && locationId !== "city")) return [];
  return (state.board.locations[locationId] ?? []).filter((targetId) => {
    const target = state.players[targetId];
    return targetId !== playerId && Boolean(target && !target.eliminated && isAccusedBySanson(target, playerId));
  });
}

const resolveSansonDeathHope: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("SANSON_HOPE_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  const candidates = Array.isArray(previous.candidatePlayerIds) ? previous.candidatePlayerIds.filter((id): id is string => typeof id === "string") : [];
  if (previous.stage !== "target" || decision.status !== "resolved" || selections.length !== 1 || !candidates.includes(selections[0])) {
    throw new Error("SANSON_HOPE_DECISION_INVALID");
  }
  const targetPlayerId = selections[0];
  if (!sansonHopeCandidates(state, player.id).includes(targetPlayerId)) throw new Error("SANSON_HOPE_TARGET_INVALID");
  player.flags.sansonHopeTargetPlayerId = targetPlayerId;
  player.flags.sansonHopeTargetRound = state.round;
  defeatPlayerByEffect(state, targetPlayerId, player.id, definitions, emitEvent, { sourceId: SANSON_HOPE_ID, reason: "sanson-death-hope" });
  clearSansonAccusation(state, player.id, targetPlayerId);
  return { targetPlayerId };
};

/** Death Will Be Tomorrow's Hope: defeat one accused combat opponent and reward Sanson if that target is defeated this combat phase. */
export const useSansonDeathHope: SkillHandler = ({ state, player, skill, payload, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "player.defeated") {
    const targetPlayerId = typeof player.flags.sansonHopeTargetPlayerId === "string" ? player.flags.sansonHopeTargetPlayerId : undefined;
    if (player.flags.sansonHopeTargetRound === state.round && targetPlayerId && event?.playerId === targetPlayerId) {
      gainVictoryPoints(player, 4);
      delete player.flags.sansonHopeTargetPlayerId;
      delete player.flags.sansonHopeTargetRound;
    }
    return;
  }
  if (eventType === "combat.ending") {
    const targetPlayerId = typeof player.flags.sansonHopeTargetPlayerId === "string" ? player.flags.sansonHopeTargetPlayerId : undefined;
    if (player.flags.sansonHopeTargetRound === state.round && targetPlayerId && state.players[targetPlayerId]?.defeated) gainVictoryPoints(player, 4);
    delete player.flags.sansonHopeTargetPlayerId;
    delete player.flags.sansonHopeTargetRound;
    return;
  }
  if (readSkillAbilityId(payload) !== "execute-accused" || state.phase !== "combat" || state.activePlayerId !== player.id
    || !findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("SANSON_HOPE_WINDOW_INVALID");
  const candidatePlayerIds = sansonHopeCandidates(state, player.id);
  if (candidatePlayerIds.length === 0) throw new Error("SANSON_HOPE_NO_TARGET");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:target`;
  state.effectQueue.unshift({
    effectId,
    handlerId: SANSON_HOPE_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { stage: "target", candidatePlayerIds },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "sanson-death-hope-target",
    options: candidatePlayerIds.map((id) => ({ id, label: state.players[id]?.name ?? id })), min: 1, max: 1, allowCancel: false,
    continuationEffectId: effectId, submissions: {},
  });
};

export const isSansonDeathHopeLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "execute-accused" && state.phase === "combat" && state.activePlayerId === playerId
    && findActiveOwnedSkillAttack(state, playerId, skill.id) && sansonHopeCandidates(state, playerId).length > 0);
};

const HASSAN_HF_FACES_ID = "servant.hassanhf.skill.sc-hassanhf-1";
const HASSAN_HF_FACES_HANDLER = "core.hundred-faced-hassan-tracking";
const HASSAN_HF_ILLUSION_ID = "servant.hassanhf.skill.sc-hassanhf-2";
const HASSAN_HF_ILLUSION_HANDLER = "core.hundred-faced-hassan-illusion";
const HASSAN_HF_ILLUSION_RESOLVE = "core.hundred-faced-hassan-illusion-resolve";

function hassanHfTrackingFlag(controllerPlayerId: string): string {
  return `hundredFacesTrackedBy:${controllerPlayerId}`;
}

function hassanHfSkillUseCountKey(controllerPlayerId: string, round: number): string {
  return `hundredFacesSkillPlays:${controllerPlayerId}:${round}`;
}

function syncHassanHfTrackedStatus(player: PlayerState): void {
  const tracked = Object.keys(player.flags).some((key) => key.startsWith("hundredFacesTrackedBy:"));
  if (tracked) {
    if (!player.statuses.includes("跟踪")) player.statuses.push("跟踪");
  } else {
    player.statuses = player.statuses.filter((status) => status !== "跟踪");
  }
}

function isTrackedByHassanHf(player: PlayerState | undefined, controllerPlayerId: string): boolean {
  return Boolean(player && player.flags[hassanHfTrackingFlag(controllerPlayerId)] === true);
}

function trackByHassanHf(player: PlayerState, controllerPlayerId: string): void {
  player.flags[hassanHfTrackingFlag(controllerPlayerId)] = true;
  syncHassanHfTrackedStatus(player);
}

function clearHassanHfTracking(player: PlayerState, controllerPlayerId: string): void {
  delete player.flags[hassanHfTrackingFlag(controllerPlayerId)];
  syncHassanHfTrackedStatus(player);
}

/** Hundred Faces: source-specific tracking, skill-card accounting, combat reward and cleanup. */
export const useHassanHfHundredFaces: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType === "card.played") {
    const targetPlayerId = typeof event.playerId === "string" ? event.playerId : undefined;
    const definitionId = typeof event.definitionId === "string" ? event.definitionId : undefined;
    const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
    const definition = definitionId && definitions ? definitions[definitionId] : undefined;
    if (!target || !definition?.isSkill || !isTrackedByHassanHf(target, player.id)) return;
    const key = hassanHfSkillUseCountKey(player.id, state.round);
    target.flags[key] = Number(target.flags[key] ?? 0) + 1;
    return;
  }
  if (eventType === "combat.resolved") {
    const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds.filter((id): id is string => typeof id === "string") : [];
    const powers = isRecord(event.powers) ? event.powers : {};
    if (!winnerIds.includes(player.id) || !Object.prototype.hasOwnProperty.call(powers, player.id)) return;
    const defeatedTrackedOpponent = Object.keys(powers).some((targetPlayerId) => targetPlayerId !== player.id
      && !winnerIds.includes(targetPlayerId) && isTrackedByHassanHf(state.players[targetPlayerId], player.id));
    if (defeatedTrackedOpponent) gainVictoryPoints(player, 2);
    return;
  }
  if (eventType === "combat.ending") {
    const previousLocations = isRecord(event.previousLocations) ? event.previousLocations : {};
    const locationId = previousLocations[player.id];
    if (locationId !== "mountain" && locationId !== "city") return;
    for (const target of Object.values(state.players)) {
      if (target.id === player.id || previousLocations[target.id] !== locationId || !isTrackedByHassanHf(target, player.id)) continue;
      clearHassanHfTracking(target, player.id);
    }
    return;
  }
  if (eventType === "round.ending") {
    const key = hassanHfSkillUseCountKey(player.id, state.round);
    for (const target of Object.values(state.players)) {
      if (!isTrackedByHassanHf(target, player.id)) {
        delete target.flags[key];
        continue;
      }
      const skillPlays = Number(target.flags[key] ?? 0);
      if (!Number.isInteger(skillPlays) || skillPlays < 0) throw new Error("HASSAN_HF_TRACKING_COUNT_INVALID");
      adjustVictoryPoints(target, -(1 + skillPlays));
      delete target.flags[key];
    }
    return;
  }
  if (readSkillAbilityId(payload) !== "track-location" || state.phase !== "action" || state.activePlayerId !== player.id
    || !findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("HASSAN_HF_TRACKING_WINDOW_INVALID");
  if (!player.locationId) throw new Error("HASSAN_HF_TRACKING_LOCATION_REQUIRED");
  for (const targetPlayerId of state.board.locations[player.locationId] ?? []) {
    if (targetPlayerId === player.id) continue;
    const target = state.players[targetPlayerId];
    if (target && !target.eliminated) trackByHassanHf(target, player.id);
  }
};

export const isHassanHfHundredFacesLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "track-location" && state.phase === "action" && state.activePlayerId === playerId
    && findActiveOwnedSkillAttack(state, playerId, skill.id) && player.locationId
    && (state.board.locations[player.locationId] ?? []).some((id) => id !== playerId && !state.players[id]?.eliminated));
};

function hassanHfHiddenAttackIds(state: GameState, player: PlayerState): string[] {
  return player.attack.filter((instanceId) => {
    const card = state.cards[instanceId];
    return Boolean(card && card.controllerPlayerId === player.id && card.zone === "attack" && card.face === "down" && !card.active);
  });
}

function hassanHfCanActivateTwo(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): boolean {
  const hidden = hassanHfHiddenAttackIds(state, player);
  if (hidden.length < 2) return false;
  for (let i = 0; i < hidden.length; i += 1) {
    for (let j = i + 1; j < hidden.length; j += 1) {
      const total = [hidden[i], hidden[j]].reduce((sum, instanceId) => {
        const instance = state.cards[instanceId];
        return sum + getCardPlayCost(state, definitions[instance.definitionId], player, instance, definitions);
      }, 0);
      if (player.flags.infiniteMana === true || player.mana >= total) return true;
    }
  }
  return false;
}

function openHassanHfHiddenDecision(state: GameState, player: PlayerState, skill: SkillContext["skill"], definitions: Record<string, CardDefinition>, openDecision: SkillContext["openDecision"]): void {
  const candidates = hassanHfHiddenAttackIds(state, player);
  if (candidates.length < 2) throw new Error("HASSAN_HF_ILLUSION_HIDDEN_CARDS_REQUIRED");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:hidden`;
  state.effectQueue.unshift({ effectId, handlerId: HASSAN_HF_ILLUSION_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id,
    payload: { stage: "hidden", candidates }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "hundred-faced-hassan-hidden-attacks",
    options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId].definitionId]?.name ?? instanceId })),
    min: 2, max: 2, allowCancel: false, continuationEffectId: effectId, submissions: {},
  });
}

const resolveHassanHfIllusion: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("HASSAN_HF_ILLUSION_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved") throw new Error("HASSAN_HF_ILLUSION_DECISION_INVALID");
  if (previous.stage === "mode") {
    if (selections.length !== 1) throw new Error("HASSAN_HF_ILLUSION_DECISION_INVALID");
    if (selections[0] === "scouting") {
      if (!canMovePlayerByEffect(state, player.id, "scouting", definitions)) throw new Error("HASSAN_HF_ILLUSION_SCOUTING_UNAVAILABLE");
      const movement = movePlayerByEffect(state, player.id, "scouting", definitions);
      gainMana(player, 2);
      emitEvent?.("player.moved", { playerId: player.id, ...movement, method: "effect", sourceId: skill.id });
      emitEvent?.("player.entered-location", { playerId: player.id, ...movement, method: "effect", sourceId: skill.id });
      return;
    }
    if (selections[0] !== "activate-two") throw new Error("HASSAN_HF_ILLUSION_MODE_INVALID");
    openHassanHfHiddenDecision(state, player, skill, definitions, openDecision);
    return;
  }
  if (previous.stage !== "hidden" || selections.length !== 2 || new Set(selections).size !== 2) throw new Error("HASSAN_HF_ILLUSION_DECISION_INVALID");
  const originalCandidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const currentCandidates = new Set(hassanHfHiddenAttackIds(state, player));
  if (selections.some((id) => !originalCandidates.includes(id) || !currentCandidates.has(id))) throw new Error("HASSAN_HF_ILLUSION_HIDDEN_TARGET_INVALID");
  const totalCost = selections.reduce((sum, instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance.definitionId];
    if (!definition) throw new Error("CARD_DEFINITION_NOT_FOUND");
    return sum + getCardPlayCost(state, definition, player, instance, definitions);
  }, 0);
  payManaCost(state, player, totalCost, definitions);
  if (totalCost > 0) player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + totalCost;
  for (const instanceId of selections) {
    const instance = state.cards[instanceId];
    const definition = definitions[instance.definitionId];
    instance.face = "up";
    instance.active = true;
    instance.residual = definition.residual === true;
    const modifierId = `${skill.id}:action-in-combat:${instanceId}:${state.round}`;
    if (!(player.cardRuleModifiers ?? []).some((modifier) => modifier.id === modifierId)) {
      addCardRuleModifier(player, { id: modifierId, sourceId: skill.id, targetDefinitionIds: [definition.id], targetInstanceIds: [instanceId],
        allowActionAbilityInCombat: true, duration: "round" });
    }
  }
  return { activatedInstanceIds: selections, paidMana: totalCost };
};

/** Delusional Illusion: add two drawn cards face-down, or in combat retreat / activate exactly two hidden attacks. */
export const useHassanHfIllusion: SkillHandler = ({ state, player, skill, payload, definitions, randomInt, openDecision }) => {
  if (!definitions || !findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("HASSAN_HF_ILLUSION_SOURCE_INACTIVE");
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === "illusion-draw-hidden") {
    if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("HASSAN_HF_ILLUSION_WINDOW_INVALID");
    const drawn = drawCards(state, player.id, 2, randomInt ?? ((max) => new StateRandom().integer(state, max)), definitions);
    for (const instanceId of drawn) {
      movePlayerCard(state, player.id, instanceId, "attack");
      const instance = state.cards[instanceId];
      instance.face = "down";
      instance.active = false;
      instance.residual = false;
      instance.paidCost = 0;
      instance.playedRound = state.round;
    }
    return { hiddenInstanceIds: drawn };
  }
  if (abilityId !== "illusion-combat" || state.phase !== "combat" || state.activePlayerId !== player.id) throw new Error("HASSAN_HF_ILLUSION_WINDOW_INVALID");
  const options: Array<{ id: string; label: string }> = [];
  if (canMovePlayerByEffect(state, player.id, "scouting", definitions)) options.push({ id: "scouting", label: "移动至侦察" });
  if (hassanHfCanActivateTwo(state, player, definitions)) options.push({ id: "activate-two", label: "激活两张暗置牌" });
  if (options.length === 0) throw new Error("HASSAN_HF_ILLUSION_NO_OPTION");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:mode`;
  state.effectQueue.unshift({ effectId, handlerId: HASSAN_HF_ILLUSION_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id,
    payload: { stage: "mode" }, createdAtRevision: state.revision });
  openDecision({ decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "hundred-faced-hassan-illusion-mode",
    options, min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {} });
};

export const isHassanHfIllusionLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || !definitions || !findActiveOwnedSkillAttack(state, playerId, skill.id) || state.activePlayerId !== playerId) return false;
  if (ability.id === "illusion-draw-hidden") return state.phase === "action" && player.deck.length + player.discard.length > 0;
  if (ability.id === "illusion-combat") return state.phase === "combat"
    && (canMovePlayerByEffect(state, playerId, "scouting", definitions) || hassanHfCanActivateTwo(state, player, definitions));
  return false;
};

const DOUMAN_EVIL_MINISTER_ID = "servant.douman.skill.sc-douman-1";
const DOUMAN_EVIL_MINISTER_HANDLER = "core.douman-evil-minister";
const DOUMAN_RIDICULE_ID = "servant.douman.skill.sc-douman-2";
const DOUMAN_RIDICULE_HANDLER = "core.douman-ridicule-cat";

function doumanCurseFlag(controllerPlayerId: string): string {
  return `doumanCursedBy:${controllerPlayerId}`;
}

function syncDoumanCurseStatus(player: PlayerState): void {
  const cursed = Object.keys(player.flags).some((key) => key.startsWith("doumanCursedBy:"));
  if (cursed) {
    if (!player.statuses.includes("诅咒")) player.statuses.push("诅咒");
  } else {
    player.statuses = player.statuses.filter((status) => status !== "诅咒");
  }
}

function curseByDouman(player: PlayerState, controllerPlayerId: string): void {
  player.flags[doumanCurseFlag(controllerPlayerId)] = true;
  syncDoumanCurseStatus(player);
}

function clearDoumanCurse(player: PlayerState, controllerPlayerId: string, round: number): boolean {
  if (player.flags.curseLossPreventedRound === round) return false;
  delete player.flags[doumanCurseFlag(controllerPlayerId)];
  syncDoumanCurseStatus(player);
  return true;
}

function activeDoumanSource(state: GameState, player: PlayerState, definitionId: string): GameState["cards"][string] | undefined {
  const instanceId = findActiveOwnedSkillAttack(state, player.id, definitionId);
  return instanceId ? state.cards[instanceId] : undefined;
}

/** Evil Minister: curse co-located opponents; a curse normally ends when that player wins a contest. */
export const useDoumanEvilMinister: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "combat.resolved") {
    if (!event || !Array.isArray(event.winnerIds) || !isRecord(event.powers)) return;
    for (const winnerId of event.winnerIds) {
      if (typeof winnerId !== "string" || !Object.prototype.hasOwnProperty.call(event.powers, winnerId)) continue;
      const winner = state.players[winnerId];
      if (winner?.flags[doumanCurseFlag(player.id)] === true) clearDoumanCurse(winner, player.id, state.round);
    }
    return;
  }
  const source = activeDoumanSource(state, player, skill.id);
  if (readSkillAbilityId(payload) !== "evil-minister-curse" || state.phase !== "action" || state.activePlayerId !== player.id
    || !source || source.reversed === true || !player.locationId) throw new Error("DOUMAN_CURSE_WINDOW_INVALID");
  const affected: string[] = [];
  for (const targetPlayerId of state.board.locations[player.locationId] ?? []) {
    if (targetPlayerId === player.id) continue;
    const target = state.players[targetPlayerId];
    if (!target || target.eliminated) continue;
    curseByDouman(target, player.id);
    affected.push(targetPlayerId);
  }
  if (affected.length === 0) throw new Error("DOUMAN_CURSE_NO_TARGET");
  return { cursedPlayerIds: affected };
};

export const isDoumanEvilMinisterLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  const source = player ? activeDoumanSource(state, player, skill.id) : undefined;
  return Boolean(player && source && source.reversed !== true && ability?.id === "evil-minister-curse"
    && state.phase === "action" && state.activePlayerId === playerId && player.locationId
    && (state.board.locations[player.locationId] ?? []).some((id) => id !== playerId && !state.players[id]?.eliminated));
};

function doumanRidiculeArmed(player: PlayerState, round: number): boolean {
  return player.flags.doumanRidiculeArmedRound === round;
}

/** Ridicule Cat: arm defeat rewards/curse absentee penalty, or on reverse preserve all Curse statuses for the round. */
export const useDoumanRidiculeCat: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "player.defeated") {
    if (!doumanRidiculeArmed(player, state.round) || !event || typeof event.playerId !== "string" || event.playerId === player.id) return;
    if (state.players[event.playerId] && !state.players[event.playerId].eliminated) gainVictoryPoints(player, 1);
    return;
  }
  if (eventType === "combat.resolved") {
    if (!doumanRidiculeArmed(player, state.round) || !event || !isRecord(event.powers)) return;
    for (const participantId of Object.keys(event.powers)) {
      const participant = state.players[participantId];
      if (participant) participant.flags[`doumanRidiculeFought:${player.id}`] = state.round;
    }
    return;
  }
  if (eventType === "round.ending") {
    if (!doumanRidiculeArmed(player, state.round)) return;
    const foughtKey = `doumanRidiculeFought:${player.id}`;
    for (const target of Object.values(state.players)) {
      if (target.eliminated) continue;
      if (target.statuses.includes("诅咒") && target.flags[foughtKey] !== state.round) adjustVictoryPoints(target, -3);
      delete target.flags[foughtKey];
    }
    delete player.flags.doumanRidiculeArmedRound;
    return;
  }

  const source = activeDoumanSource(state, player, skill.id);
  const abilityId = readSkillAbilityId(payload);
  if (!source || state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("DOUMAN_RIDICULE_WINDOW_INVALID");
  if (abilityId === "ridicule-cat-normal") {
    if (source.reversed === true) throw new Error("DOUMAN_RIDICULE_FACE_INVALID");
    player.flags.doumanRidiculeArmedRound = state.round;
    return;
  }
  if (abilityId === "ridicule-cat-reverse") {
    if (source.reversed !== true) throw new Error("DOUMAN_RIDICULE_FACE_INVALID");
    for (const target of Object.values(state.players)) {
      if (!target.eliminated) target.flags.curseLossPreventedRound = state.round;
    }
    return;
  }
  throw new Error("DOUMAN_RIDICULE_ABILITY_INVALID");
};

export const isDoumanRidiculeCatLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  const source = player ? activeDoumanSource(state, player, skill.id) : undefined;
  if (!player || !source || !ability || state.phase !== "action" || state.activePlayerId !== playerId) return false;
  if (ability.id === "ridicule-cat-normal") return source.reversed !== true;
  if (ability.id === "ridicule-cat-reverse") return source.reversed === true;
  return false;
};

const KAGEKIYO_AZAMARU_ID = "servant.kagekiyo.skill.sc-kagekiyo-1";
const KAGEKIYO_AZAMARU_HANDLER = "core.kagekiyo-azamaru";
const KAGEKIYO_NEVER_DIES_ID = "servant.kagekiyo.skill.sc-kagekiyo-3";
const KAGEKIYO_NEVER_DIES_HANDLER = "core.kagekiyo-never-dies";

function kagekiyoHiddenAttackIds(state: GameState, player: PlayerState): string[] {
  return player.attack.filter((instanceId) => {
    const instance = state.cards[instanceId];
    return Boolean(instance && instance.zone === "attack" && instance.face === "down" && !instance.active);
  });
}

/** Azamaru: activate every face-down attack atomically and require each printed Action it exposes. */
export const useKagekiyoAzamaru: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions || readSkillAbilityId(payload) !== "azamaru-activate-hidden" || state.phase !== "combat"
    || state.activePlayerId !== player.id || !findActiveOwnedSkillAttack(state, player.id, skill.id)) {
    throw new Error("KAGEKIYO_AZAMARU_WINDOW_INVALID");
  }
  const hidden = kagekiyoHiddenAttackIds(state, player);
  if (hidden.length === 0) throw new Error("KAGEKIYO_AZAMARU_NO_HIDDEN_ATTACK");
  const costs = hidden.map((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance.definitionId];
    if (!definition) throw new Error("KAGEKIYO_AZAMARU_DEFINITION_MISSING");
    return { instanceId, instance, definition, cost: getCardPlayCost(state, definition, player, instance, definitions) };
  });
  const totalCost = costs.reduce((sum, item) => sum + item.cost, 0);
  if (player.flags.infiniteMana !== true && player.mana < totalCost) throw new Error("KAGEKIYO_AZAMARU_MANA_INSUFFICIENT");
  payManaCost(state, player, totalCost, definitions);
  if (totalCost > 0) player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + totalCost;
  for (const { instanceId, instance, definition, cost } of costs) {
    instance.face = "up";
    instance.active = true;
    instance.residual = definition.residual === true;
    instance.paidCost = cost;
    const actionAbilityIds = definition.phases?.includes("action") ? [...(definition.cardAbilityIds ?? [])] : [];
    if (actionAbilityIds.length > 0) {
      addCardRuleModifier(player, {
        id: `${skill.id}:action-in-combat:${instanceId}:${state.round}:${state.revision}`,
        sourceId: skill.id,
        sourceInstanceId: findActiveOwnedSkillAttack(state, player.id, skill.id),
        targetDefinitionIds: [definition.id],
        targetInstanceIds: [instanceId],
        allowActionAbilityInCombat: true,
        mandatoryActionAbilityInCombatIds: actionAbilityIds,
        duration: "round",
      });
    }
  }
  return { activatedInstanceIds: hidden, paidMana: totalCost };
};

export const isKagekiyoAzamaruLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !definitions || ability?.id !== "azamaru-activate-hidden" || state.phase !== "combat"
    || state.activePlayerId !== playerId || !findActiveOwnedSkillAttack(state, playerId, skill.id)) return false;
  const hidden = kagekiyoHiddenAttackIds(state, player);
  if (hidden.length === 0) return false;
  const total = hidden.reduce((sum, instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance.definitionId];
    return sum + (definition ? getCardPlayCost(state, definition, player, instance, definitions) : Number.POSITIVE_INFINITY);
  }, 0);
  return player.flags.infiniteMana === true || player.mana >= total;
};

/** Kagekiyo Never Dies outpost action: pay the authored ability cost, draw up to two, then play them face-down for free. */
export const useKagekiyoNeverDies: SkillHandler = ({ state, player, skill, payload, definitions, randomInt, emitEvent, openDecision }) => {
  const wrapped = isRecord(payload) ? payload : {};
  if (isRecord(wrapped.previous) && isRecord(wrapped.decision)) {
    if (!definitions) throw new Error("KAGEKIYO_NEVER_DIES_DEFINITIONS_REQUIRED");
    const previous = wrapped.previous;
    const decision = wrapped.decision;
    if (previous.stage !== "round-end-close") throw new Error("KAGEKIYO_NEVER_DIES_DECISION_INVALID");
    if (decision.status === "cancelled") return;
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
    if (decision.status !== "resolved" || selections.some((id) => !candidates.includes(id))) throw new Error("KAGEKIYO_NEVER_DIES_DECISION_INVALID");
    for (const instanceId of selections) {
      if (!kagekiyoHiddenAttackIds(state, player).includes(instanceId)) throw new Error("KAGEKIYO_NEVER_DIES_CLOSE_TARGET_INVALID");
      closePlayerCard(state, player.id, instanceId, definitions);
    }
    return { closedInstanceIds: selections };
  }
  if (wrapped.eventType === "round.ending") {
    if (!definitions) throw new Error("KAGEKIYO_NEVER_DIES_DEFINITIONS_REQUIRED");
    const candidates = kagekiyoHiddenAttackIds(state, player);
    if (candidates.length === 0) return;
    const sourceId = findOwnedPhysicalSkill(state, player.id, skill.id);
    if (sourceId && state.cards[sourceId]?.face === "down") state.cards[sourceId].face = "up";
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:round-end-close`;
    state.effectQueue.unshift({
      effectId,
      handlerId: KAGEKIYO_NEVER_DIES_HANDLER,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "round-end-close", candidates: [...candidates] },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "kagekiyo-never-dies-round-end-close",
      options: candidates.map((id) => ({ id, label: definitions[state.cards[id]?.definitionId ?? ""]?.name ?? id })),
      min: 0,
      max: candidates.length,
      allowCancel: true,
      continuationEffectId: effectId,
      submissions: {},
    });
    return { pendingCloseDecision: true, effectId };
  }
  if (!definitions || readSkillAbilityId(payload) !== "vengeful-grudge-facedown" || state.phase !== "outpost"
    || state.activePlayerId !== player.id || kagekiyoHiddenAttackIds(state, player).length > 0) {
    throw new Error("KAGEKIYO_NEVER_DIES_WINDOW_INVALID");
  }
  const drawn = drawCards(state, player.id, 2, randomInt ?? (() => 0), definitions);
  const played: string[] = [];
  for (const instanceId of drawn) {
    const instance = state.cards[instanceId];
    if (!instance || instance.zone !== "hand" || instance.ownerPlayerId !== player.id) continue;
    movePlayerCard(state, player.id, instanceId, "attack");
    instance.face = "down";
    instance.active = false;
    instance.residual = false;
    instance.paidCost = 0;
    instance.playedRound = state.round;
    instance.playCount = Number(instance.playCount ?? 0) + 1;
    played.push(instanceId);
    emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: null, face: "down", paidMana: 0, attributes: [], method: "kagekiyo-never-dies" });
  }
  if (played.length > 0) {
    player.flags.cardsPlayedThisRound = Number(player.flags.cardsPlayedThisRound ?? 0) + played.length;
    player.flags.illyaRoundAttackCommitted = true;
  }
  return { playedInstanceIds: played };
};

export const isKagekiyoNeverDiesLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "vengeful-grudge-facedown" && state.phase === "outpost"
    && state.activePlayerId === playerId && player.mana >= 3 && kagekiyoHiddenAttackIds(state, player).length === 0);
};

const VLAD_PROTECTOR_ID = "servant.vlad.skill.sc-vlad-1";
const VLAD_PROTECTOR_HANDLER = "core.vlad-protector-of-nation";
const VLAD_KAZIKLI_ID = "servant.vlad.skill.sc-vlad-2";
const VLAD_KAZIKLI_HANDLER = "core.vlad-kazikli-bey";

/** Protector of the Nation: terrain doubling, moved-in penalty, and next-round Fortify deployment. */
export const useVladProtectorOfNation: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("VLAD_PROTECTOR_DEFINITIONS_REQUIRED");
  const wrapped = isRecord(payload) ? payload : {};
  if (wrapped.eventType === "combat.resolved") {
    const event = isRecord(wrapped.event) ? wrapped.event : {};
    const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds : [];
    const locationId = typeof event.locationId === "string" ? event.locationId : player.locationId;
    if (player.flags.vladFortifyArmedRound !== state.round || player.flags.vladFortifyLocationId !== locationId || !winnerIds.includes(player.id)) return;
    if (locationId !== "mountain" && locationId !== "city") return;
    player.flags.forcedDeploymentRound = state.round + 1;
    player.flags.forcedDeploymentLocationId = locationId;
    player.flags.chooseTerrainAdvantageRound = state.round + 1;
    delete player.flags.vladFortifyArmedRound;
    delete player.flags.vladFortifyLocationId;
    return { scheduledRound: state.round + 1, locationId };
  }
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === "protector-double-terrain") {
    if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("VLAD_PROTECTOR_ACTION_WINDOW_INVALID");
    const terrain = calculateTerrainAdvantage(state, player, definitions);
    if (terrain <= 0) throw new Error("VLAD_PROTECTOR_TERRAIN_REQUIRED");
    const multiplier = player.flags.deploymentAdvantageMultiplierRound === state.round
      ? Number(player.flags.deploymentAdvantageMultiplier ?? 1)
      : 1;
    if (!Number.isFinite(multiplier) || multiplier < 0) throw new Error("VLAD_PROTECTOR_TERRAIN_MULTIPLIER_INVALID");
    player.flags.deploymentAdvantageMultiplierRound = state.round;
    player.flags.deploymentAdvantageMultiplier = multiplier * 2;
    return { terrainAdvantage: calculateTerrainAdvantage(state, player, definitions) };
  }
  if (abilityId === "protector-fortify") {
    const locationId = player.locationId;
    if (state.phase !== "combat" || state.activePlayerId !== player.id || (locationId !== "mountain" && locationId !== "city")) {
      throw new Error("VLAD_PROTECTOR_COMBAT_WINDOW_INVALID");
    }
    const affected: string[] = [];
    for (const targetId of state.board.locations[locationId] ?? []) {
      const target = state.players[targetId];
      if (!target || target.eliminated || !(target.locationsPassedThisRound ?? []).includes(locationId)) continue;
      target.flags.roundPowerBonus = Number(target.flags.roundPowerBonus ?? 0) - 4;
      affected.push(targetId);
    }
    player.flags.vladFortifyArmedRound = state.round;
    player.flags.vladFortifyLocationId = locationId;
    return { affectedPlayerIds: affected };
  }
  throw new Error("VLAD_PROTECTOR_ABILITY_INVALID");
};

export const isVladProtectorOfNationLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || !definitions || player.mana < 1 || state.activePlayerId !== playerId) return false;
  if (ability.id === "protector-double-terrain") return state.phase === "action" && calculateTerrainAdvantage(state, player, definitions) > 0;
  if (ability.id === "protector-fortify") return state.phase === "combat" && (player.locationId === "mountain" || player.locationId === "city");
  return false;
};

/** Kazikli Bey: use the active NP to play one hand card, or two with terrain and an extra two mana. */
export const useVladKazikliBey: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions || state.phase !== "action" || state.activePlayerId !== player.id || !findActiveOwnedSkillAttack(state, player.id, skill.id)) {
    throw new Error("VLAD_KAZIKLI_WINDOW_INVALID");
  }
  const instanceIds = isRecord(payload) && Array.isArray(payload.instanceIds)
    ? payload.instanceIds.filter((id): id is string => typeof id === "string")
    : [];
  if (instanceIds.length < 1 || instanceIds.length > 2 || new Set(instanceIds).size !== instanceIds.length) throw new Error("VLAD_KAZIKLI_CARD_LIST_INVALID");
  if (instanceIds.length === 2 && calculateTerrainAdvantage(state, player, definitions) <= 0) throw new Error("VLAD_KAZIKLI_TERRAIN_REQUIRED");
  const cards: Array<{ instanceId: string; definitionId: string; paidMana: number; revealsTrueName?: boolean }> = [];
  for (let index = 0; index < instanceIds.length; index += 1) {
    if (index === 1) payManaCost(state, player, 2, definitions, "VLAD_KAZIKLI_EXTRA_MANA_REQUIRED");
    const instanceId = instanceIds[index];
    const instance = state.cards[instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    if (!instance || !definition || instance.ownerPlayerId !== player.id || !player.hand.includes(instanceId)) throw new Error("VLAD_KAZIKLI_HAND_CARD_INVALID");
    const result = addCardToAttack(state, player.id, instanceId, definitions, {
      payCost: true,
      allowedSourceZones: ["hand"],
      bypassTiming: true,
      bypassFaceUpPlayLimit: true,
    });
    cards.push({ instanceId, definitionId: definition.id, paidMana: result.paidMana, revealsTrueName: definition.revealsTrueNameOnPlay === true });
  }
  return { cards };
};

export const isVladKazikliBeyLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "kazikli-play-hand" && state.phase === "action" && state.activePlayerId === playerId
    && findActiveOwnedSkillAttack(state, playerId, skill.id) && player.hand.length > 0);
};

const RULER_CLASS_HANDLER = "core.ruler-class";
const RULER_CLASS_RESOLVE = "core.ruler-class-resolve";

function rulerJudgmentUsesKey(skillId: string): string {
  return `rulerDivineJudgmentUses:${skillId}`;
}

function clearRepeatableRulerSealUsage(player: PlayerState, skillId: string): void {
  delete player.usage[`${skillId}:ruler-seal-command`];
}

function rulerSecondTargetsAfterFirst(state: GameState, controllerPlayerId: string, firstPlayerId: string): string[] {
  const opponents = Object.values(state.players).filter((candidate) => candidate.id !== controllerPlayerId && !candidate.eliminated);
  if (!opponents.some((candidate) => candidate.id === firstPlayerId)) return [];
  const simulatedCounts = new Map(opponents.map((candidate) => [
    candidate.id,
    getRulerBindCount(state, controllerPlayerId, candidate.id) + (candidate.id === firstPlayerId ? 1 : 0),
  ]));
  const minimum = Math.min(...simulatedCounts.values());
  return opponents
    .filter((candidate) => candidate.id !== firstPlayerId && simulatedCounts.get(candidate.id) === minimum)
    .map((candidate) => candidate.id);
}

function rulerFirstJudgmentTargets(state: GameState, controllerPlayerId: string): string[] {
  return getLeastBoundOpponentIds(state, controllerPlayerId)
    .filter((candidateId) => rulerSecondTargetsAfterFirst(state, controllerPlayerId, candidateId).length > 0);
}

function openRulerSealModeDecision(
  state: GameState,
  player: PlayerState,
  skillId: string,
  sealId: string,
  boundPlayerId: string,
  openDecision: SkillContext["openDecision"],
): void {
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skillId}:ruler-seal-mode:${sealId}`;
  state.effectQueue.unshift({
    effectId,
    handlerId: RULER_CLASS_RESOLVE,
    sourceId: skillId,
    controllerPlayerId: player.id,
    payload: { stage: "ruler-seal-mode", sealId, boundPlayerId, skillId },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "ruler-seal-command-mode",
    options: [
      { id: "move", label: "Move to a battlefield" },
      { id: "lock", label: "Cannot move this round" },
      { id: "free-play", label: "Free play one hand card" },
    ],
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
}

const resolveRulerClass: SkillHandler = ({ state, player, payload, definitions, openDecision, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("RULER_CLASS_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || selections.length !== decision.selections.length) throw new Error("RULER_CLASS_DECISION_INVALID");
  const skillId = typeof previous.skillId === "string" ? previous.skillId : undefined;
  if (!skillId) throw new Error("RULER_CLASS_SKILL_ID_REQUIRED");

  if (previous.stage === "divine-judgment-first") {
    const eligible = Array.isArray(previous.eligiblePlayerIds) ? previous.eligiblePlayerIds.filter((id): id is string => typeof id === "string") : [];
    if (selections.length !== 1 || !eligible.includes(selections[0])) throw new Error("RULER_JUDGMENT_TARGET_INVALID");
    const useKey = rulerJudgmentUsesKey(skillId);
    const uses = Number(player.flags[useKey] ?? 0);
    if (!Number.isInteger(uses) || uses < 0 || uses >= 3) throw new Error("RULER_JUDGMENT_LIMIT_REACHED");
    const firstPlayerId = selections[0];
    grantRulerSeal(state, player.id, firstPlayerId, skillId);
    const secondPlayerIds = getLeastBoundOpponentIds(state, player.id).filter((id) => id !== firstPlayerId);
    if (secondPlayerIds.length === 0) throw new Error("RULER_JUDGMENT_SECOND_TARGET_UNAVAILABLE");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skillId}:divine-judgment-second`;
    state.effectQueue.unshift({
      effectId,
      handlerId: RULER_CLASS_RESOLVE,
      sourceId: skillId,
      controllerPlayerId: player.id,
      payload: { stage: "divine-judgment-second", firstPlayerId, eligiblePlayerIds: secondPlayerIds, skillId },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "ruler-divine-judgment-second-target",
      options: secondPlayerIds.map((id) => ({ id, label: state.players[id]?.name ?? id })),
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }

  if (previous.stage === "divine-judgment-second") {
    const firstPlayerId = typeof previous.firstPlayerId === "string" ? previous.firstPlayerId : undefined;
    const eligible = Array.isArray(previous.eligiblePlayerIds) ? previous.eligiblePlayerIds.filter((id): id is string => typeof id === "string") : [];
    if (!firstPlayerId || selections.length !== 1 || selections[0] === firstPlayerId || !eligible.includes(selections[0])) throw new Error("RULER_JUDGMENT_TARGET_INVALID");
    const useKey = rulerJudgmentUsesKey(skillId);
    const uses = Number(player.flags[useKey] ?? 0);
    if (!Number.isInteger(uses) || uses < 0 || uses >= 3) throw new Error("RULER_JUDGMENT_LIMIT_REACHED");
    grantRulerSeal(state, player.id, selections[0], skillId);
    player.flags[useKey] = uses + 1;
    return { boundPlayerIds: [firstPlayerId, selections[0]] };
  }

  if (previous.stage === "select-seal") {
    const sealIds = Array.isArray(previous.sealIds) ? previous.sealIds.filter((id): id is string => typeof id === "string") : [];
    if (selections.length !== 1 || !sealIds.includes(selections[0])) throw new Error("RULER_SEAL_SELECTION_INVALID");
    const seal = listRulerSealsControlledBy(state, player.id).find((candidate) => candidate.sealId === selections[0]);
    if (!seal) throw new Error("RULER_SEAL_NOT_AVAILABLE");
    openRulerSealModeDecision(state, player, skillId, seal.sealId, seal.boundPlayerId, openDecision);
    return;
  }

  if (previous.stage === "ruler-seal-mode") {
    const sealId = typeof previous.sealId === "string" ? previous.sealId : undefined;
    const boundPlayerId = typeof previous.boundPlayerId === "string" ? previous.boundPlayerId : undefined;
    if (!sealId || !boundPlayerId || selections.length !== 1 || !["move", "lock", "free-play"].includes(selections[0])) throw new Error("RULER_SEAL_MODE_INVALID");
    const seal = listRulerSealsControlledBy(state, player.id).find((candidate) => candidate.sealId === sealId && candidate.boundPlayerId === boundPlayerId);
    if (!seal) throw new Error("RULER_SEAL_NOT_AVAILABLE");
    spendRulerCommandSeal(state, player.id, sealId);
    const mode = selections[0];
    if (mode === "lock") {
      state.players[boundPlayerId].flags.movementBlockedRound = state.round;
      return { mode, boundPlayerId };
    }
    if (mode === "move") {
      const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skillId}:ruler-seal-move:${boundPlayerId}`;
      state.effectQueue.unshift({
        effectId,
        handlerId: RULER_CLASS_RESOLVE,
        sourceId: skillId,
        controllerPlayerId: player.id,
        payload: { stage: "ruler-seal-move", boundPlayerId, skillId },
        createdAtRevision: state.revision,
      });
      openDecision({
        decisionId: `${effectId}:decision`,
        ownerPlayerId: player.id,
        chooserPlayerIds: [player.id],
        kind: "ruler-seal-move-location",
        options: [{ id: "mountain", label: "Miyama" }, { id: "city", label: "Shinto" }],
        min: 1,
        max: 1,
        allowCancel: false,
        continuationEffectId: effectId,
        submissions: {},
      });
      return;
    }
    armRulerSealWinReward(state, player.id, boundPlayerId, skillId, 2);
    const target = state.players[boundPlayerId];
    const candidates = [...target.hand];
    if (candidates.length === 0) return { mode, boundPlayerId, playedInstanceId: null };
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skillId}:ruler-seal-free-play:${boundPlayerId}`;
    state.effectQueue.unshift({
      effectId,
      handlerId: RULER_CLASS_RESOLVE,
      sourceId: skillId,
      controllerPlayerId: player.id,
      payload: { stage: "ruler-seal-free-play", boundPlayerId, candidates, skillId },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: boundPlayerId,
      chooserPlayerIds: [boundPlayerId],
      kind: "ruler-seal-free-play-card",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
      min: 0,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }

  if (previous.stage === "ruler-seal-move") {
    const boundPlayerId = typeof previous.boundPlayerId === "string" ? previous.boundPlayerId : undefined;
    if (!boundPlayerId || selections.length !== 1 || (selections[0] !== "mountain" && selections[0] !== "city")) throw new Error("RULER_SEAL_MOVE_INVALID");
    const movement = movePlayerByEffect(state, boundPlayerId, selections[0], definitions);
    emitEvent?.("player.moved", { playerId: boundPlayerId, ...movement, sourceId: skillId });
    emitEvent?.("player.entered-location", { playerId: boundPlayerId, ...movement, method: "effect", sourceId: skillId });
    return { boundPlayerId, ...movement };
  }

  if (previous.stage === "ruler-seal-free-play") {
    const boundPlayerId = typeof previous.boundPlayerId === "string" ? previous.boundPlayerId : undefined;
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    if (!boundPlayerId || selections.length > 1 || selections.some((id) => !candidates.includes(id) || !state.players[boundPlayerId]?.hand.includes(id))) {
      throw new Error("RULER_SEAL_FREE_PLAY_INVALID");
    }
    if (selections.length === 0) return { boundPlayerId, playedInstanceId: null };
    const instanceId = selections[0];
    const result = addCardToAttack(state, boundPlayerId, instanceId, definitions, {
      payCost: false,
      allowedSourceZones: ["hand"],
      bypassFaceUpPlayLimit: true,
      bypassTiming: true,
    });
    const definition = definitions[state.cards[instanceId].definitionId];
    emitEvent?.("card.played", { playerId: boundPlayerId, instanceId, definitionId: definition.id, face: "up", paidMana: 0, attributes: getCardAttributes(definition), method: "ruler-seal" });
    emitEvent?.("card.used", { playerId: boundPlayerId, instanceId, definitionId: definition.id, locationId: state.players[boundPlayerId].locationId, attributes: getCardAttributes(definition), method: "ruler-seal" });
    return { boundPlayerId, playedInstanceId: instanceId, paidMana: result.paidMana };
  }

  throw new Error("RULER_CLASS_STAGE_INVALID");
};

export const useRulerClass: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "combat.resolved" || eventType === "round.ending") {
    if (!definitions) throw new Error("RULER_CLASS_DEFINITIONS_REQUIRED");
    return resolveRulerSealCommandEvent(state, player, payload, definitions);
  }
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === "divine-judgment") {
    const uses = Number(player.flags[rulerJudgmentUsesKey(skill.id)] ?? 0);
    if (!Number.isInteger(uses) || uses < 0 || uses >= 3) throw new Error("RULER_JUDGMENT_LIMIT_REACHED");
    const eligible = rulerFirstJudgmentTargets(state, player.id);
    if (eligible.length === 0) throw new Error("RULER_JUDGMENT_TARGETS_UNAVAILABLE");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:divine-judgment`;
    state.effectQueue.unshift({ effectId, handlerId: RULER_CLASS_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "divine-judgment-first", eligiblePlayerIds: eligible, skillId: skill.id }, createdAtRevision: state.revision });
    openDecision({
      decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "ruler-divine-judgment-first-target",
      options: eligible.map((id) => ({ id, label: state.players[id]?.name ?? id })), min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {},
    });
    return;
  }
  if (abilityId === "ruler-seal-command") {
    return openRulerSealCommand(state, player, skill.id, openDecision, abilityId, definitions);
  }
  throw new Error("RULER_CLASS_ABILITY_INVALID");
};

export const isRulerClassLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player || !ability || state.phase !== "action" || state.step !== "player-window" || state.activePlayerId !== playerId) return false;
  if (ability.id === "divine-judgment") {
    const uses = Number(player.flags[rulerJudgmentUsesKey(skill.id)] ?? 0);
    return Number.isInteger(uses) && uses < 3 && rulerFirstJudgmentTargets(state, playerId).length > 0;
  }
  if (ability.id === "ruler-seal-command") return canUseRulerSealCommand(state, playerId);
  return false;
};

const AMAKUSA_MAGICIAN_ID = "servant.amakusa.skill.sc-amakusa-2";
const AMAKUSA_MAGICIAN_HANDLER = "core.amakusa-magician";
const AMAKUSA_MAGICIAN_RESOLVE = "core.amakusa-magician-resolve";

function amakusaBorrowMarker(skillId: string, round: number): string {
  return `effect-until-close:borrowed-after-combat:${skillId}:${round}`;
}

function amakusaBorrowableOpponentIds(state: GameState, playerId: string): string[] {
  return state.turnOrder.filter((targetPlayerId) => targetPlayerId !== playerId
    && Boolean(state.players[targetPlayerId])
    && !state.players[targetPlayerId].eliminated
    && state.players[targetPlayerId].deck.length > 0);
}

function findOwnedAmakusaMagicianInstance(state: GameState, player: PlayerState): GameState["cards"][string] | undefined {
  return [...player.attack, ...player.servantSkills]
    .map((instanceId) => state.cards[instanceId])
    .find((card) => card?.definitionId === AMAKUSA_MAGICIAN_ID && card.ownerPlayerId === player.id);
}

const resolveAmakusaMagician: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) {
    throw new Error("AMAKUSA_MAGICIAN_DECISION_INVALID");
  }
  const previous = payload.previous;
  const decision = payload.decision;
  const candidates = Array.isArray(previous.candidatePlayerIds)
    ? previous.candidatePlayerIds.filter((id): id is string => typeof id === "string")
    : [];
  const selections = Array.isArray(decision.selections)
    ? decision.selections.filter((id): id is string => typeof id === "string")
    : [];
  if (decision.status !== "resolved" || selections.length !== 1 || !candidates.includes(selections[0])) {
    throw new Error("AMAKUSA_MAGICIAN_TARGET_INVALID");
  }
  const ownerPlayerId = selections[0];
  if (!amakusaBorrowableOpponentIds(state, player.id).includes(ownerPlayerId)) throw new Error("AMAKUSA_MAGICIAN_TARGET_INVALID");
  const { instanceId, definitionId } = borrowTopDeckCardToAttack(state, player.id, ownerPlayerId, definitions);
  const borrowed = state.cards[instanceId];
  const definition = definitions[definitionId];
  const marker = amakusaBorrowMarker(AMAKUSA_MAGICIAN_ID, state.round);
  borrowed.modifiers = [...(borrowed.modifiers ?? []).filter((item) => item !== marker), marker];
  const modifierId = `${AMAKUSA_MAGICIAN_ID}:action-window:${instanceId}:${state.round}`;
  player.cardRuleModifiers = (player.cardRuleModifiers ?? []).filter((modifier) => modifier.id !== modifierId);
  addCardRuleModifier(player, {
    id: modifierId,
    sourceId: AMAKUSA_MAGICIAN_ID,
    targetDefinitionIds: [definitionId],
    targetInstanceIds: [instanceId],
    allowActionAbilityInCombat: true,
    duration: "round",
  });
  const magician = findOwnedAmakusaMagicianInstance(state, player);
  if (magician) {
    const attributes = getCardInstanceAttributes(borrowed, definition, state, definitions);
    magician.attributeOverrides = [...new Set([...(magician.attributeOverrides ?? getCardAttributes(definitions[AMAKUSA_MAGICIAN_ID] ?? definition)), ...attributes])];
    if (!magician.modifiers.includes(`attribute-overrides-until-close:${AMAKUSA_MAGICIAN_ID}`)) {
      magician.modifiers.push(`attribute-overrides-until-close:${AMAKUSA_MAGICIAN_ID}`);
    }
  }
  return { ownerPlayerId, instanceId, definitionId };
};

export const useAmakusaMagician: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("AMAKUSA_MAGICIAN_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "combat.ending") {
    const marker = amakusaBorrowMarker(skill.id, state.round);
    const borrowedIds = [...player.attack].filter((instanceId) => {
      const card = state.cards[instanceId];
      return Boolean(card && card.controllerPlayerId === player.id && card.ownerPlayerId !== player.id && card.modifiers.includes(marker));
    });
    for (const instanceId of borrowedIds) closePlayerCard(state, player.id, instanceId, definitions);
    return { returnedInstanceIds: borrowedIds };
  }
  const abilityId = readSkillAbilityId(payload);
  if (abilityId !== "magician-borrow" || state.phase !== "combat" || state.activePlayerId !== player.id) {
    throw new Error("AMAKUSA_MAGICIAN_FORBIDDEN");
  }
  const candidatePlayerIds = amakusaBorrowableOpponentIds(state, player.id);
  if (candidatePlayerIds.length === 0) throw new Error("AMAKUSA_MAGICIAN_NO_TARGET");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:borrow`;
  state.effectQueue.unshift({
    effectId,
    handlerId: AMAKUSA_MAGICIAN_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { candidatePlayerIds },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "amakusa-magician-opponent",
    options: candidatePlayerIds.map((id) => ({ id, label: state.players[id]?.name ?? id })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isAmakusaMagicianLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  return Boolean(ability?.id === "magician-borrow"
    && state.phase === "combat"
    && state.activePlayerId === playerId
    && amakusaBorrowableOpponentIds(state, playerId).length > 0);
};

const SPARTACUS_FREE_SPIRIT_ID = "servant.spartacus.skill.sc-spartacus-3";
const SPARTACUS_FREE_SPIRIT_HANDLER = "core.spartacus-free-spirit";
const SPARTACUS_FREE_SPIRIT_RULER_RESOLVE = "core.spartacus-free-spirit-ruler-resolve";

function applySpartacusFreeSpiritSealPower(player: PlayerState): void {
  player.flags.commandSealRoundPowerBonus = Number(player.flags.commandSealRoundPowerBonus ?? 0) + 4;
}

function clearRepeatableFreeSpiritSealUsage(player: PlayerState, abilityId: string): void {
  // The printed replacement belongs to each physical once-per-game seal, not
  // to Free Spirit itself.  Clearing this registry marker lets another seal be
  // used in the same round while the finite seal inventory remains the limit.
  delete player.usage[`${SPARTACUS_FREE_SPIRIT_ID}:${abilityId}`];
}


export const useSpartacusFreeSpirit: SkillHandler = ({ state, player, skill, payload, openDecision }) => {
  if (skill.id !== SPARTACUS_FREE_SPIRIT_ID) throw new Error("SPARTACUS_FREE_SPIRIT_SKILL_INVALID");
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === "free-spirit-unused-seal-aura") {
    player.flags.engagedOpponentUnusedSealPowerRound = state.round;
    player.flags.engagedOpponentUnusedSealPowerPerSeal = 1;
    return;
  }
  if (abilityId === "free-spirit-use-command-seal") {
    spendNormalCommandSeal(state, player.id);
    applySpartacusFreeSpiritSealPower(player);
    clearRepeatableFreeSpiritSealUsage(player, abilityId);
    return;
  }
  if (abilityId === "free-spirit-use-ruler-seal") {
    const seals = listRulerSealsControlledBy(state, player.id);
    if (seals.length === 0) throw new Error("SPARTACUS_RULER_SEAL_NOT_AVAILABLE");
    if (seals.length === 1) {
      spendRulerCommandSeal(state, player.id, seals[0].sealId);
      applySpartacusFreeSpiritSealPower(player);
      clearRepeatableFreeSpiritSealUsage(player, abilityId);
      return;
    }
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:ruler-seal`;
    state.effectQueue.unshift({
      effectId,
      handlerId: SPARTACUS_FREE_SPIRIT_RULER_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { sealIds: seals.map((seal) => seal.sealId) },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "spartacus-free-spirit-ruler-seal",
      options: seals.map((seal) => ({ id: seal.sealId, label: `裁决者令咒（${state.players[seal.boundPlayerId]?.name ?? seal.boundPlayerId}）` })),
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  throw new Error("SPARTACUS_FREE_SPIRIT_ABILITY_INVALID");
};

const resolveSpartacusFreeSpiritRulerSeal: SkillHandler = ({ state, player, payload }) => {
  if (!isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("SPARTACUS_RULER_SEAL_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const allowed = Array.isArray(previous.sealIds) ? previous.sealIds.filter((id): id is string => typeof id === "string") : [];
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || selections.length !== 1 || !allowed.includes(selections[0])) throw new Error("SPARTACUS_RULER_SEAL_DECISION_INVALID");
  spendRulerCommandSeal(state, player.id, selections[0]);
  applySpartacusFreeSpiritSealPower(player);
  clearRepeatableFreeSpiritSealUsage(player, "free-spirit-use-ruler-seal");
};

export const isSpartacusFreeSpiritLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  if (skill.id !== SPARTACUS_FREE_SPIRIT_ID || !ability) return false;
  const player = state.players[playerId];
  if (!player || state.phase !== "action" || state.step !== "player-window" || state.activePlayerId !== playerId) return false;
  if (ability.id === "free-spirit-unused-seal-aura") return player.flags.engagedOpponentUnusedSealPowerRound !== state.round;
  if (ability.id === "free-spirit-use-command-seal") return player.commandSeals > 0;
  if (ability.id === "free-spirit-use-ruler-seal") return listRulerSealsControlledBy(state, playerId).length > 0;
  return false;
};

const STHENO_DIVINE_CORE_ID = "servant.stheno.skill.sc-stheno-3";
const STHENO_DIVINE_CORE_HANDLER = "core.stheno-divine-core";
const STHENO_DIVINE_CORE_RESOLVE = "core.stheno-divine-core-resolve";

type SthenoDrawReward = { playerId: string; instanceId: string };

function sthenoEngagedOpponentIds(state: GameState, player: PlayerState): string[] {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") return [];
  const here = new Set((state.board.locations[locationId] ?? []).filter((id) => id !== player.id));
  return state.turnOrder.filter((id) => here.has(id) && Boolean(state.players[id]) && !state.players[id].eliminated && !state.players[id].defeated);
}

function sthenoLuckyHandIds(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return player.hand.filter((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    return Boolean(instance && definition && isLuckCard(definition));
  });
}

function sthenoClosableAttackIds(state: GameState, opponent: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return opponent.attack.filter((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = definitions[instance?.definitionId ?? ""];
    return Boolean(instance?.active && instance.face === "up" && definition && definition.limit !== "once-per-game");
  });
}

function parseSthenoRewards(value: unknown): SthenoDrawReward[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((entry) => isRecord(entry) && typeof entry.playerId === "string" && typeof entry.instanceId === "string"
    ? [{ playerId: entry.playerId, instanceId: entry.instanceId }]
    : []);
}

function canSthenoEffectPlayDrawnCard(state: GameState, reward: SthenoDrawReward, definitions: Record<string, CardDefinition>): boolean {
  const target = state.players[reward.playerId];
  const instance = state.cards[reward.instanceId];
  const definition = definitions[instance?.definitionId ?? ""];
  if (!target || target.eliminated || target.defeated || !instance || !definition || !target.hand.includes(reward.instanceId)) return false;
  try {
    assertCardCanEnterAttack({
      state,
      playerId: target.id,
      instanceId: reward.instanceId,
      definitions,
      faceDown: false,
      allowedSourceZones: ["hand"],
      bypassTiming: true,
    });
    const cost = getCardPlayCost(state, definition, target, instance, definitions);
    return target.flags.infiniteMana === true || target.mana >= cost;
  } catch {
    return false;
  }
}

function openSthenoPlayDecision(
  state: GameState,
  player: PlayerState,
  rewards: SthenoDrawReward[],
  index: number,
  definitions: Record<string, CardDefinition>,
  openDecision: SkillContext["openDecision"],
): void {
  for (let cursor = index; cursor < rewards.length; cursor += 1) {
    const reward = rewards[cursor];
    if (!canSthenoEffectPlayDrawnCard(state, reward, definitions)) continue;
    const target = state.players[reward.playerId];
    const instance = state.cards[reward.instanceId];
    const definition = definitions[instance.definitionId];
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${STHENO_DIVINE_CORE_ID}:play:${cursor}`;
    state.effectQueue.unshift({
      effectId,
      handlerId: STHENO_DIVINE_CORE_RESOLVE,
      sourceId: STHENO_DIVINE_CORE_ID,
      controllerPlayerId: player.id,
      payload: { stage: "play", rewards: rewards.map((item) => ({ ...item })), index: cursor },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [target.id],
      kind: "stheno-divine-core-play-drawn",
      options: [
        { id: "play", label: `打出 ${definition.name}` },
        { id: "skip", label: "跳过" },
      ],
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
}

function openSthenoCloseDecision(
  state: GameState,
  player: PlayerState,
  opponentIds: string[],
  index: number,
  rewards: SthenoDrawReward[],
  definitions: Record<string, CardDefinition>,
  openDecision: SkillContext["openDecision"],
): void {
  for (let cursor = index; cursor < opponentIds.length; cursor += 1) {
    const opponent = state.players[opponentIds[cursor]];
    if (!opponent || opponent.eliminated || opponent.defeated) continue;
    const candidates = sthenoClosableAttackIds(state, opponent, definitions);
    if (candidates.length === 0) continue;
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${STHENO_DIVINE_CORE_ID}:close:${cursor}`;
    state.effectQueue.unshift({
      effectId,
      handlerId: STHENO_DIVINE_CORE_RESOLVE,
      sourceId: STHENO_DIVINE_CORE_ID,
      controllerPlayerId: player.id,
      payload: {
        stage: "close",
        opponentIds: [...opponentIds],
        index: cursor,
        candidates: [...candidates],
        rewards: rewards.map((item) => ({ ...item })),
      },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "stheno-divine-core-close-attack",
      options: [
        ...candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId].definitionId]?.name ?? instanceId })),
        { id: "skip", label: "跳过" },
      ],
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  openSthenoPlayDecision(state, player, rewards, 0, definitions, openDecision);
}

function discardSthenoLuckyAndContinue(
  state: GameState,
  player: PlayerState,
  instanceId: string,
  opponentIds: string[],
  definitions: Record<string, CardDefinition>,
  openDecision: SkillContext["openDecision"],
): void {
  if (!sthenoLuckyHandIds(state, player, definitions).includes(instanceId)) throw new Error("STHENO_DIVINE_CORE_LUCK_INVALID");
  movePlayerCard(state, player.id, instanceId, "discard");
  state.cards[instanceId].face = "up";
  state.cards[instanceId].active = false;
  openSthenoCloseDecision(state, player, opponentIds, 0, [], definitions, openDecision);
}

export const useSthenoDivineCore: SkillHandler = ({ state, player, definitions, openDecision }) => {
  if (!definitions) throw new Error("STHENO_DIVINE_CORE_DEFINITIONS_REQUIRED");
  if (state.phase !== "combat") throw new Error("STHENO_DIVINE_CORE_WINDOW_INVALID");
  const opponentIds = sthenoEngagedOpponentIds(state, player);
  if (opponentIds.length === 0) throw new Error("STHENO_DIVINE_CORE_NO_OPPONENT");
  const luckyIds = sthenoLuckyHandIds(state, player, definitions);
  if (luckyIds.length === 0) throw new Error("STHENO_DIVINE_CORE_LUCK_REQUIRED");
  if (luckyIds.length === 1) {
    discardSthenoLuckyAndContinue(state, player, luckyIds[0], opponentIds, definitions, openDecision);
    return;
  }
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${STHENO_DIVINE_CORE_ID}:discard`;
  state.effectQueue.unshift({
    effectId,
    handlerId: STHENO_DIVINE_CORE_RESOLVE,
    sourceId: STHENO_DIVINE_CORE_ID,
    controllerPlayerId: player.id,
    payload: { stage: "discard", opponentIds: [...opponentIds], luckyIds: [...luckyIds] },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "stheno-divine-core-discard-luck",
    options: luckyIds.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId].definitionId]?.name ?? instanceId })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isSthenoDivineCoreLegal: SkillLegalityPredicate = (state, playerId, _skill, _ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && state.phase === "combat"
    && sthenoEngagedOpponentIds(state, player).length > 0
    && sthenoLuckyHandIds(state, player, definitions).length > 0);
};

const resolveSthenoDivineCore: SkillHandler = ({ state, player, payload, definitions, openDecision, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("STHENO_DIVINE_CORE_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || selections.length !== 1) throw new Error("STHENO_DIVINE_CORE_DECISION_INVALID");

  if (previous.stage === "discard") {
    const opponentIds = Array.isArray(previous.opponentIds) ? previous.opponentIds.filter((id): id is string => typeof id === "string") : [];
    const luckyIds = Array.isArray(previous.luckyIds) ? previous.luckyIds.filter((id): id is string => typeof id === "string") : [];
    if (!luckyIds.includes(selections[0])) throw new Error("STHENO_DIVINE_CORE_LUCK_INVALID");
    discardSthenoLuckyAndContinue(state, player, selections[0], opponentIds, definitions, openDecision);
    return;
  }

  if (previous.stage === "close") {
    const opponentIds = Array.isArray(previous.opponentIds) ? previous.opponentIds.filter((id): id is string => typeof id === "string") : [];
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const rewards = parseSthenoRewards(previous.rewards);
    const index = Number(previous.index);
    if (!Number.isInteger(index) || index < 0 || index >= opponentIds.length) throw new Error("STHENO_DIVINE_CORE_DECISION_INVALID");
    const opponent = state.players[opponentIds[index]];
    if (!opponent) throw new Error("STHENO_DIVINE_CORE_OPPONENT_INVALID");
    const selected = selections[0];
    if (selected !== "skip") {
      if (!candidates.includes(selected) || !sthenoClosableAttackIds(state, opponent, definitions).includes(selected)) throw new Error("STHENO_DIVINE_CORE_ATTACK_INVALID");
      const card = state.cards[selected];
      const definition = definitions[card.definitionId];
      const manaGain = getCardPlayCost(state, definition, opponent, card, definitions);
      closePlayerCard(state, opponent.id, selected, definitions, { closedByPlayerId: player.id });
      gainMana(opponent, manaGain);
      const random = new StateRandom();
      const drawn = drawCards(state, opponent.id, 1, (maxExclusive) => random.integer(state, maxExclusive), definitions)[0];
      if (drawn) rewards.push({ playerId: opponent.id, instanceId: drawn });
    }
    openSthenoCloseDecision(state, player, opponentIds, index + 1, rewards, definitions, openDecision);
    return;
  }

  if (previous.stage === "play") {
    const rewards = parseSthenoRewards(previous.rewards);
    const index = Number(previous.index);
    if (!Number.isInteger(index) || index < 0 || index >= rewards.length) throw new Error("STHENO_DIVINE_CORE_DECISION_INVALID");
    const reward = rewards[index];
    const selected = selections[0];
    if (selected !== "play" && selected !== "skip") throw new Error("STHENO_DIVINE_CORE_PLAY_CHOICE_INVALID");
    if (selected === "play") {
      if (!canSthenoEffectPlayDrawnCard(state, reward, definitions)) throw new Error("STHENO_DIVINE_CORE_DRAWN_CARD_NOT_PLAYABLE");
      const target = state.players[reward.playerId];
      const instance = state.cards[reward.instanceId];
      const definition = definitions[instance.definitionId];
      const { paidMana } = addCardToAttack(state, target.id, reward.instanceId, definitions, {
        payCost: true,
        allowedSourceZones: ["hand"],
        bypassFaceUpPlayLimit: true,
        bypassTiming: true,
      });
      addCardRuleModifier(target, {
        id: `${STHENO_DIVINE_CORE_ID}:ability-window:${reward.instanceId}:${state.round}`,
        sourceId: STHENO_DIVINE_CORE_ID,
        targetDefinitionIds: [instance.definitionId],
        targetInstanceIds: [reward.instanceId],
        allowActionAbilityInCombat: true,
        duration: "round",
      });
      emitEvent?.("card.played", { playerId: target.id, instanceId: reward.instanceId, definitionId: definition.id, face: "up", paidMana, attributes: getCardAttributes(definition), method: "stheno-divine-core" });
      emitEvent?.("card.used", { playerId: target.id, instanceId: reward.instanceId, definitionId: definition.id, locationId: target.locationId, attributes: getCardAttributes(definition), method: "stheno-divine-core" });
    }
    openSthenoPlayDecision(state, player, rewards, index + 1, definitions, openDecision);
    return;
  }

  throw new Error("STHENO_DIVINE_CORE_STAGE_INVALID");
};

function getElizabethVolume(player: PlayerState): number {
  const value = Number(player.flags.elizabethVolumeMarkers ?? 0);
  if (!Number.isInteger(value) || value < 0) throw new Error("ELIZABETH_VOLUME_INVALID");
  return value;
}

function setElizabethVolume(player: PlayerState, value: number): void {
  if (!Number.isInteger(value) || value < 0) throw new Error("ELIZABETH_VOLUME_INVALID");
  if (value === 0) delete player.flags.elizabethVolumeMarkers;
  else player.flags.elizabethVolumeMarkers = value;
}

function adjustElizabethVolume(player: PlayerState, delta: number): number {
  if (!Number.isInteger(delta)) throw new Error("ELIZABETH_VOLUME_DELTA_INVALID");
  const next = Math.max(0, getElizabethVolume(player) + delta);
  setElizabethVolume(player, next);
  return next;
}

function readCombatResultPayload(payload: unknown): unknown {
  return isRecord(payload) && isRecord(payload.event) ? payload.event : payload;
}

function isCombatResultParticipant(payload: unknown, playerId: string): boolean {
  const result = readCombatResultPayload(payload);
  if (!isRecord(result) || !isRecord(result.powers)) return false;
  return Object.prototype.hasOwnProperty.call(result.powers, playerId);
}

function isCombatResultWinner(payload: unknown, playerId: string): boolean {
  const result = readCombatResultPayload(payload);
  if (!isRecord(result) || !Array.isArray(result.winnerIds)) return false;
  return result.winnerIds.includes(playerId);
}

function combatResultParticipantIds(payload: unknown): string[] {
  const result = readCombatResultPayload(payload);
  if (!isRecord(result) || !isRecord(result.powers)) return [];
  return Object.keys(result.powers);
}

function findActiveSkillCardInstanceId(state: GameState, player: PlayerState, skillId: string, definitions?: Record<string, CardDefinition>): string | undefined {
  return player.attack.find((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = instance ? definitions?.[instance.definitionId] : undefined;
    return Boolean(instance?.active && instance.face === "up" && (instance.definitionId === skillId || definition?.linkedSkillId === skillId));
  });
}

export const useElizabethVolumePower: SkillHandler = ({ player, skill }) => {
  const rule = skill.elizabethVolumePower;
  if (!rule || !Number.isInteger(rule.perMarker) || !Number.isInteger(rule.max)) throw new Error("ELIZABETH_VOLUME_POWER_RULE_INVALID");
  const amount = Math.min(rule.max, getElizabethVolume(player) * rule.perMarker);
  if (amount <= 0) throw new Error("ELIZABETH_VOLUME_POWER_NO_MARKERS");
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + amount;
};

export const isElizabethVolumePowerLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  const rule = skill.elizabethVolumePower;
  return Boolean(player && rule && getElizabethVolume(player) > 0 && (player.locationId === "mountain" || player.locationId === "city"));
};

export const useElizabethVocalPerformance: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const rule = skill.elizabethVocalPerformance;
  if (!rule || !Number.isInteger(rule.markersPerOpponent) || !Number.isInteger(rule.loseIfNoCombatThisRound)) throw new Error("ELIZABETH_VOCAL_RULE_INVALID");
  if (isRecord(payload) && payload.eventType === "combat.ending") {
    if (!findActiveSkillCardInstanceId(state, player, skill.id, definitions)) return;
    if (Number(player.flags.combatWinRound ?? 0) === state.round || Number(player.flags.combatLossRound ?? 0) === state.round) return;
    adjustElizabethVolume(player, -rule.loseIfNoCombatThisRound);
    return;
  }
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("ELIZABETH_VOCAL_NOT_IN_BATTLE");
  const opponentCount = (state.board.locations[locationId] ?? [])
    .filter((id) => id !== player.id && !state.players[id]?.eliminated).length;
  if (opponentCount <= 0) throw new Error("ELIZABETH_VOCAL_NO_OPPONENT");
  const volume = adjustElizabethVolume(player, opponentCount * rule.markersPerOpponent);
  const sourceInstanceId = findActiveSkillCardInstanceId(state, player, skill.id, definitions);
  if (!sourceInstanceId) throw new Error("ELIZABETH_VOCAL_CARD_REQUIRED");
  const source = state.cards[sourceInstanceId];
  const modifierId = `${skill.id}:vocal-performance:${state.round}:${state.revision}`;
  source.powerModifiers = [
    ...(source.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
    { id: modifierId, sourceId: skill.id, kind: "add", value: volume, duration: "round" },
  ];
};

export const isElizabethVocalPerformanceLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player || !skill.elizabethVocalPerformance || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return (state.board.locations[player.locationId] ?? []).some((id) => id !== playerId && !state.players[id]?.eliminated);
};

export const useElizabethVolumeLossOnCombatLoss: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const amount = skill.elizabethVolumeLossOnCombatLoss;
  if (!Number.isInteger(amount) || amount <= 0) throw new Error("ELIZABETH_VOLUME_LOSS_RULE_INVALID");
  if (!findActiveSkillCardInstanceId(state, player, skill.id, definitions)) return;
  if (!isCombatResultParticipant(payload, player.id) || isCombatResultWinner(payload, player.id)) return;
  adjustElizabethVolume(player, -amount);
};

export const useElizabethIronMaiden: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const rule = skill.elizabethIronMaiden;
  if (!rule || !Number.isInteger(rule.loserVictoryPointLoss) || !Number.isInteger(rule.controllerVictoryPointGainIfIncludesOverallLowest)) {
    throw new Error("ELIZABETH_IRON_MAIDEN_RULE_INVALID");
  }
  if (!findActiveSkillCardInstanceId(state, player, skill.id, definitions)) return;
  if (!isRecord(payload) || !isCombatResultWinner(payload, player.id)) return;
  const participantIds = combatResultParticipantIds(payload);
  const losers = participantIds
    .filter((id) => id !== player.id && !isCombatResultWinner(payload, id))
    .map((id) => state.players[id])
    .filter((candidate): candidate is PlayerState => Boolean(candidate && !candidate.eliminated));
  if (losers.length === 0) return;
  const lowestLoserScore = Math.min(...losers.map((candidate) => candidate.victoryPoints));
  const affected = losers.filter((candidate) => candidate.victoryPoints === lowestLoserScore);
  const aliveBefore = Object.values(state.players).filter((candidate) => !candidate.eliminated);
  const overallLowestBefore = Math.min(...aliveBefore.map((candidate) => candidate.victoryPoints));
  const includesOverallLowest = affected.some((candidate) => candidate.victoryPoints === overallLowestBefore);
  for (const target of affected) {
    adjustVictoryPoints(target, -rule.loserVictoryPointLoss);
  }
  if (includesOverallLowest) {
    gainVictoryPoints(player, rule.controllerVictoryPointGainIfIncludesOverallLowest);
  }
};

export const isElizabethIronMaidenLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  return Boolean(player && (player.locationId === "mountain" || player.locationId === "city"));
};

export const useHighVictoryCombatPowerRule: SkillHandler = ({ state, player, skill }) => {
  const rule = skill.highVictoryCombatPowerRule;
  if (!rule || !Number.isInteger(rule.penalty) || !Number.isInteger(rule.selfBonusIfTopOpponentEngaged)) {
    throw new Error("HIGH_VICTORY_POWER_RULE_INVALID");
  }
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("HIGH_VICTORY_POWER_NOT_IN_BATTLE");
  const participants = (state.board.locations[locationId] ?? [])
    .map((id) => state.players[id])
    .filter((candidate): candidate is NonNullable<typeof candidate> => Boolean(candidate && !candidate.eliminated));
  if (participants.length < 2) throw new Error("HIGH_VICTORY_POWER_NO_COMBAT");
  const remaining = Object.values(state.players).filter((candidate) => !candidate.eliminated).length;
  const threshold = Math.ceil(remaining / 2);
  for (const participant of participants) {
    if (participant.victoryPoints > threshold) {
      participant.flags.roundPowerBonus = Number(participant.flags.roundPowerBonus ?? 0) + rule.penalty;
    }
  }
  const maxVictoryPoints = Math.max(...Object.values(state.players).filter((candidate) => !candidate.eliminated).map((candidate) => candidate.victoryPoints));
  const topOpponentEngaged = participants.some((participant) => participant.id !== player.id && participant.victoryPoints === maxVictoryPoints);
  if (topOpponentEngaged) {
    player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + rule.selfBonusIfTopOpponentEngaged;
  }
};

export const isHighVictoryCombatPowerRuleLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player || !skill.highVictoryCombatPowerRule || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return (state.board.locations[player.locationId] ?? []).some((id) => id !== playerId && !state.players[id]?.eliminated);
};


export const useOpponentBonusPerCostlyAttack: SkillHandler = ({ state, player, skill, definitions }) => {
  const rule = skill.opponentBonusPerCostlyAttack;
  if (!rule
    || !Number.isInteger(rule.minPaidCost)
    || !Number.isInteger(rule.mana)
    || !Number.isInteger(rule.combatPower)) {
    throw new Error("OPPONENT_COSTLY_ATTACK_RULE_INVALID");
  }
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("OPPONENT_COSTLY_ATTACK_NOT_IN_BATTLE");
  const opponents = (state.board.locations[locationId] ?? [])
    .filter((id) => id !== player.id && !state.players[id]?.eliminated)
    .map((id) => state.players[id])
    .filter((candidate): candidate is NonNullable<typeof candidate> => Boolean(candidate));
  let affected = 0;
  for (const opponent of opponents) {
    const costlyAttacks = opponent.attack.filter((instanceId) => {
      const card = state.cards[instanceId];
      const definition = card && definitions ? definitions[card.definitionId] : undefined;
      return Boolean(card?.active && card.face === "up" && definition
        && getCardPlayCost(state, definition, opponent, card, definitions) >= rule.minPaidCost);
    }).length;
    if (costlyAttacks <= 0) continue;
    affected += costlyAttacks;
    if (rule.mana !== 0) gainMana(opponent, rule.mana * costlyAttacks);
    if (rule.combatPower !== 0) opponent.flags.roundPowerBonus = Number(opponent.flags.roundPowerBonus ?? 0) + rule.combatPower * costlyAttacks;
  }
  if (affected === 0) throw new Error("OPPONENT_COSTLY_ATTACK_NO_TARGET");
};

export const isOpponentBonusPerCostlyAttackLegal: SkillLegalityPredicate = (state, playerId, skill, _ability, definitions) => {
  const player = state.players[playerId];
  const rule = skill.opponentBonusPerCostlyAttack;
  if (!player || !rule || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return (state.board.locations[player.locationId] ?? []).some((id) => {
    const opponent = state.players[id];
    return Boolean(id !== playerId && opponent && !opponent.eliminated && opponent.attack.some((instanceId) => {
      const card = state.cards[instanceId];
      const definition = card && definitions ? definitions[card.definitionId] : undefined;
      return Boolean(card?.active && card.face === "up" && definition
        && getCardPlayCost(state, definition, opponent, card, definitions) >= rule.minPaidCost);
    }));
  });
};


function isOpponentLinkedToOwnerCard(
  state: GameState,
  opponent: PlayerState,
  ownerPlayerId: string,
  definitions: Record<string, CardDefinition>,
): boolean {
  return opponent.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(card?.active && card.face === "up" && card.zone === "attack"
      && card.ownerPlayerId === ownerPlayerId && card.controllerPlayerId === opponent.id
      && definition?.linkedOwnerCombatPowerMaximum === true);
  });
}

export const useOpponentAttackPowerModifier: SkillHandler = ({ state, player, skill, definitions }) => {
  if (!definitions) throw new Error("OPPONENT_ATTACK_POWER_DEFINITIONS_REQUIRED");
  const rule = skill.opponentAttackPowerModifier;
  if (!rule || !Number.isInteger(rule.hiddenTrueNameAmount) || !Number.isInteger(rule.revealedTrueNameAmount)) {
    throw new Error("OPPONENT_ATTACK_POWER_RULE_INVALID");
  }
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("OPPONENT_ATTACK_POWER_NOT_IN_BATTLE");
  const amount = player.trueNameRevealed ? rule.revealedTrueNameAmount : rule.hiddenTrueNameAmount;
  let affected = 0;
  for (const opponentId of state.board.locations[locationId] ?? []) {
    const opponent = state.players[opponentId];
    if (!opponent || opponentId === player.id || opponent.eliminated) continue;
    if (rule.excludeGuardedByOwner === true && isOpponentLinkedToOwnerCard(state, opponent, player.id, definitions)) continue;
    for (const instanceId of opponent.attack) {
      const card = state.cards[instanceId];
      if (!card?.active || card.face !== "up") continue;
      const modifierId = `${skill.id}:opponent-attack:${instanceId}`;
      card.powerModifiers = [
        ...(card.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
        { id: modifierId, sourceId: skill.id, kind: "add", value: amount, duration: "round" },
      ];
      affected += 1;
    }
  }
  if (affected === 0) throw new Error("OPPONENT_ATTACK_POWER_NO_TARGET");
};

export const isOpponentAttackPowerModifierLegal: SkillLegalityPredicate = (state, playerId, skill, _ability, definitions) => {
  const player = state.players[playerId];
  const rule = skill.opponentAttackPowerModifier;
  if (!player || !rule || !definitions || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return (state.board.locations[player.locationId] ?? []).some((opponentId) => {
    const opponent = state.players[opponentId];
    if (!opponent || opponentId === playerId || opponent.eliminated) return false;
    if (rule.excludeGuardedByOwner === true && isOpponentLinkedToOwnerCard(state, opponent, playerId, definitions)) return false;
    return opponent.attack.some((instanceId) => {
      const card = state.cards[instanceId];
      return Boolean(card?.active && card.face === "up");
    });
  });
};

const LEONIDAS_PRIDE_ID = "servant.leonidas.skill.sc-leonidas-3";
const LEONIDAS_WARRIOR_ROAR_ID = "servant.leonidas.skill.sc-leonidas-2";
const LEONIDAS_PRIDE_RESOLVE = "core.leonidas-pride-resolve";
const LEONIDAS_ACTIVATE_HIDDEN_ABILITY = "activate-hidden-attack";
const LEONIDAS_PHALANX_ABILITY = "phalanx";

function ensureLeonidasFaceDownGrant(state: GameState, player: PlayerState): void {
  const sourceInstanceId = findOwnedPhysicalSkill(state, player.id, LEONIDAS_PRIDE_ID);
  if (!sourceInstanceId) return;
  const modifierId = `${LEONIDAS_PRIDE_ID}:face-down-warrior-roar:${sourceInstanceId}`;
  if ((player.cardRuleModifiers ?? []).some((modifier) => modifier.id === modifierId)) return;
  addCardRuleModifier(player, {
    id: modifierId,
    sourceId: LEONIDAS_PRIDE_ID,
    sourceInstanceId,
    targetDefinitionIds: [LEONIDAS_WARRIOR_ROAR_ID],
    allowFaceDownPlay: true,
    duration: "while-source-present",
  });
}

function leonidasHiddenAttackCandidates(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return player.attack.filter((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    return Boolean(instance && definition && instance.face === "down" && !instance.active
      && (instance.controllerPlayerId === player.id || instance.ownerPlayerId === player.id));
  });
}

function leonidasPhalanxTriggeredHere(state: GameState, player: PlayerState): boolean {
  const locationId = player.locationId;
  return Boolean((locationId === "mountain" || locationId === "city")
    && Number(player.flags[`leonidasPhalanxRound:${locationId}`] ?? -1) === state.round);
}


export const useLeonidasPride: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "game.started" || eventType === "card.created" || eventType === "card.zone.changed") {
    ensureLeonidasFaceDownGrant(state, player);
    return;
  }
  if (eventType === "player.entered-location") {
    const movedPlayerId = event && typeof event.playerId === "string" ? event.playerId : undefined;
    const locationId = event && typeof event.locationId === "string" ? event.locationId : undefined;
    const method = event && typeof event.method === "string" ? event.method : undefined;
    if (movedPlayerId && movedPlayerId !== player.id && method !== "deploy"
      && (locationId === "mountain" || locationId === "city") && player.locationId === locationId) {
      player.flags[`leonidasPhalanxRound:${locationId}`] = state.round;
    }
    return;
  }

  const wrapped = isRecord(payload) ? payload : {};
  if (isRecord(wrapped.previous) && isRecord(wrapped.decision)) {
    if (!definitions) throw new Error("LEONIDAS_PRIDE_DEFINITIONS_REQUIRED");
    const previous = wrapped.previous;
    const decision = wrapped.decision;
    if (previous.stage !== "activate-hidden" || decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) {
      throw new Error("LEONIDAS_PRIDE_DECISION_INVALID");
    }
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const instanceId = decision.selections[0];
    if (typeof instanceId !== "string" || !candidates.includes(instanceId) || !leonidasHiddenAttackCandidates(state, player, definitions).includes(instanceId)) {
      throw new Error("LEONIDAS_PRIDE_HIDDEN_TARGET_INVALID");
    }
    const instance = state.cards[instanceId];
    const definition = definitions[instance.definitionId];
    const cost = getCardPlayCost(state, definition, player, instance, definitions) * 3;
    payManaCost(state, player, cost, definitions);
    if (cost > 0) player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + cost;
    instance.face = "up";
    instance.active = true;
    instance.residual = definition.residual === true;
    const modifierId = `${skill.id}:action-in-combat:${instanceId}:${state.round}`;
    if (!(player.cardRuleModifiers ?? []).some((modifier) => modifier.id === modifierId)) {
      addCardRuleModifier(player, {
        id: modifierId,
        sourceId: skill.id,
        targetDefinitionIds: [instance.definitionId],
        targetInstanceIds: [instanceId],
        allowActionAbilityInCombat: true,
        duration: "round",
      });
    }
    return;
  }

  const abilityId = typeof wrapped.abilityId === "string" ? wrapped.abilityId : undefined;
  if (abilityId === LEONIDAS_ACTIVATE_HIDDEN_ABILITY) {
    if (!definitions) throw new Error("LEONIDAS_PRIDE_DEFINITIONS_REQUIRED");
    const candidates = leonidasHiddenAttackCandidates(state, player, definitions);
    if (candidates.length === 0) throw new Error("LEONIDAS_PRIDE_NO_HIDDEN_ATTACK");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:activate-hidden`;
    state.effectQueue.unshift({
      effectId,
      handlerId: LEONIDAS_PRIDE_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "activate-hidden", candidates: [...candidates] },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "leonidas-pride-hidden-attack",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  if (abilityId === LEONIDAS_PHALANX_ABILITY) {
    if (!leonidasPhalanxTriggeredHere(state, player)) throw new Error("LEONIDAS_PHALANX_CONDITION_FALSE");
    player.flags.deploymentLocationId = player.locationId ?? "";
    player.flags.deploymentBonus = 3;
    player.flags.deploymentBonusActive = true;
    return;
  }
  throw new Error("LEONIDAS_PRIDE_ABILITY_INVALID");
};

export const isLeonidasPrideLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || state.phase !== "combat" || state.activePlayerId !== playerId) return false;
  if (ability.id === LEONIDAS_ACTIVATE_HIDDEN_ABILITY) {
    return Boolean(definitions && leonidasHiddenAttackCandidates(state, player, definitions).some((instanceId) => {
      const instance = state.cards[instanceId];
      const definition = definitions[instance.definitionId];
      const cost = getCardPlayCost(state, definition, player, instance, definitions) * 3;
      return player.flags.infiniteMana === true || player.mana >= cost;
    }));
  }
  if (ability.id === LEONIDAS_PHALANX_ABILITY) return leonidasPhalanxTriggeredHere(state, player);
  return false;
};

const resolveLeonidasPride: SkillHandler = (context) => useLeonidasPride(context);

const WAVER_CASE_FILES_ID = "master.waver.skill.ascension";
const WAVER_CASE_FILES_RESOLVE = "core.waver-case-files-resolve";
const WAVER_PREDICT_ABILITY = "case-files-predict";
const WAVER_DISCARD_ABILITY = "case-files-discard";

function waverPredictionOptions(state: GameState): Array<{ id: string; label: string }> {
  const players = Object.values(state.players).filter((candidate) => !candidate.eliminated);
  return (["mountain", "city"] as const).flatMap((locationId) => players.map((candidate) => ({
    id: `${locationId}:${candidate.id}`,
    label: `${locationId === "mountain" ? "深山町" : "新都"} · ${candidate.name}`,
  })));
}

function discardRandomCardsFromHand(state: GameState, playerId: string, count: number): string[] {
  const player = state.players[playerId];
  if (!player || player.eliminated || !Number.isInteger(count) || count < 0) return [];
  const random = new StateRandom();
  const discarded: string[] = [];
  for (let index = 0; index < count && player.hand.length > 0; index += 1) {
    const targetIndex = random.integer(state, player.hand.length);
    const instanceId = player.hand[targetIndex];
    if (!instanceId) break;
    movePlayerCard(state, playerId, instanceId, "discard");
    discarded.push(instanceId);
  }
  return discarded;
}


export const useWaverCaseFiles: SkillHandler = ({ state, player, skill, payload, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "combat.ending") {
    if (!event || Number(player.flags.waverPredictionRound ?? -1) !== state.round) return;
    const winners = isRecord(event.combatWinnerIdsByLocation) ? event.combatWinnerIdsByLocation : {};
    let correct = 0;
    const mountainPrediction = typeof player.flags.waverPredictionMountainPlayerId === "string" ? player.flags.waverPredictionMountainPlayerId : undefined;
    const cityPrediction = typeof player.flags.waverPredictionCityPlayerId === "string" ? player.flags.waverPredictionCityPlayerId : undefined;
    if (mountainPrediction && Array.isArray(winners.mountain) && winners.mountain.includes(mountainPrediction)) correct += 1;
    if (cityPrediction && Array.isArray(winners.city) && winners.city.includes(cityPrediction)) correct += 1;
    gainVictoryPoints(player, correct);
    delete player.flags.waverPredictionRound;
    delete player.flags.waverPredictionMountainPlayerId;
    delete player.flags.waverPredictionCityPlayerId;
    return;
  }
  if (eventType === "phase.transitioned") {
    if (!event || Number(player.flags.waverCaseFilesDiscardRound ?? -1) !== state.round) return;
    if (event.previousPhase !== "outpost" || event.transition !== "next-phase") return;
    const locationId = player.locationId;
    if (locationId && state.board.locations[locationId]) {
      for (const targetPlayerId of [...state.board.locations[locationId]]) discardRandomCardsFromHand(state, targetPlayerId, 2);
    }
    delete player.flags.waverCaseFilesDiscardRound;
    return;
  }

  const wrapped = isRecord(payload) ? payload : {};
  if (isRecord(wrapped.previous) && isRecord(wrapped.decision)) {
    const previous = wrapped.previous;
    const decision = wrapped.decision;
    if (previous.stage !== "predict" || decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 2) {
      throw new Error("WAVER_CASE_FILES_PREDICTION_INVALID");
    }
    const selections = decision.selections.filter((value): value is string => typeof value === "string");
    const allowed = new Set(waverPredictionOptions(state).map((option) => option.id));
    if (selections.length !== 2 || new Set(selections).size !== 2 || selections.some((value) => !allowed.has(value))) {
      throw new Error("WAVER_CASE_FILES_PREDICTION_INVALID");
    }
    const mountain = selections.find((value) => value.startsWith("mountain:"));
    const city = selections.find((value) => value.startsWith("city:"));
    if (!mountain || !city) throw new Error("WAVER_CASE_FILES_PREDICTION_INVALID");
    player.flags.waverPredictionRound = state.round;
    player.flags.waverPredictionMountainPlayerId = mountain.slice("mountain:".length);
    player.flags.waverPredictionCityPlayerId = city.slice("city:".length);
    player.flags.scoutingVictoryPointGainBlockedRound = state.round;
    return;
  }

  const abilityId = typeof wrapped.abilityId === "string" ? wrapped.abilityId : undefined;
  if (abilityId === WAVER_PREDICT_ABILITY) {
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:predict`;
    const options = waverPredictionOptions(state);
    if (options.length < 2) throw new Error("WAVER_CASE_FILES_NO_PREDICTION_TARGET");
    state.effectQueue.unshift({
      effectId,
      handlerId: WAVER_CASE_FILES_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "predict" },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "waver-case-files-predictions",
      options,
      min: 2,
      max: 2,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  if (abilityId === WAVER_DISCARD_ABILITY) {
    player.flags.waverCaseFilesDiscardRound = state.round;
    return;
  }
  throw new Error("WAVER_CASE_FILES_ABILITY_INVALID");
};

export const isWaverCaseFilesLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  if (!player || state.phase !== "outpost" || state.activePlayerId !== playerId || !ability) return false;
  if (ability.id === WAVER_PREDICT_ABILITY) return Object.values(state.players).some((candidate) => !candidate.eliminated);
  if (ability.id === WAVER_DISCARD_ABILITY) return player.mana >= 5;
  return false;
};

const resolveWaverCaseFiles: SkillHandler = (context) => useWaverCaseFiles(context);

const IVAN_BEAST_FORM_ID = "servant.ivan.skill.sc-ivan-2";
const IVAN_BEAST_FORM_RESOLVE = "core.ivan-beast-form-resolve";
const IVAN_BEAST_FORM_MOVE_ABILITY = "beast-form-move";

function ivanBeastFormDisplayed(state: GameState, player: PlayerState): boolean {
  const instanceId = findOwnedPhysicalSkill(state, player.id, IVAN_BEAST_FORM_ID);
  const card = instanceId ? state.cards[instanceId] : undefined;
  return Boolean(card && card.zone !== "removed" && card.face === "up");
}

function ivanBeastFormMoveCandidates(state: GameState, player: PlayerState): string[] {
  if (player.locationId !== "mountain" && player.locationId !== "city") return [];
  if ((state.board.locations.scouting ?? []).some((id) => !state.players[id]?.eliminated)) return [];
  return sameBattlefieldOpponentIds(state, player.id, player.locationId).filter((id) => {
    const target = state.players[id];
    return Boolean(target && !target.eliminated && target.flags.movementBlockedPermanent !== true && target.flags.movementBlockedRound !== state.round);
  });
}


export const useIvanBeastForm: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, emitEvent }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "game.started") {
    player.flags.movementBlockedPermanent = true;
    return;
  }
  if (eventType === "player.victory-points.changed") {
    if (!event || !ivanBeastFormDisplayed(state, player)) return;
    const targetPlayerId = typeof event.playerId === "string" ? event.playerId : undefined;
    const before = Number(event.before);
    const delta = Number(event.delta);
    const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
    if (!target || target.id === player.id || target.eliminated || !Number.isFinite(before) || !Number.isFinite(delta) || delta <= 0) return;
    if (!player.locationId || target.locationId !== player.locationId) return;
    const currentGain = Math.max(0, target.victoryPoints - before);
    if (currentGain <= 0) return;
    target.victoryPoints = before + Math.ceil(currentGain / 2);
    return;
  }

  const wrapped = isRecord(payload) ? payload : {};
  if (isRecord(wrapped.previous) && isRecord(wrapped.decision)) {
    if (!definitions) throw new Error("IVAN_BEAST_FORM_DEFINITIONS_REQUIRED");
    const previous = wrapped.previous;
    const decision = wrapped.decision;
    if (previous.stage !== "move" || decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) {
      throw new Error("IVAN_BEAST_FORM_DECISION_INVALID");
    }
    const candidateIds = Array.isArray(previous.candidateIds) ? previous.candidateIds.filter((id): id is string => typeof id === "string") : [];
    const targetPlayerId = decision.selections[0];
    if (typeof targetPlayerId !== "string" || !candidateIds.includes(targetPlayerId) || !ivanBeastFormMoveCandidates(state, player).includes(targetPlayerId)) {
      throw new Error("IVAN_BEAST_FORM_TARGET_INVALID");
    }
    const moved = movePlayerByEffect(state, targetPlayerId, "scouting", definitions);
    player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + state.round;
    emitEvent?.("player.moved", { playerId: targetPlayerId, ...moved, method: "effect", sourceId: skill.id });
    emitEvent?.("player.entered-location", { playerId: targetPlayerId, previousLocationId: moved.previousLocationId, locationId: moved.locationId, method: "effect", distance: moved.distance, sourceId: skill.id });
    return;
  }

  const abilityId = typeof wrapped.abilityId === "string" ? wrapped.abilityId : undefined;
  if (abilityId !== IVAN_BEAST_FORM_MOVE_ABILITY) throw new Error("IVAN_BEAST_FORM_ABILITY_INVALID");
  if (!definitions) throw new Error("IVAN_BEAST_FORM_DEFINITIONS_REQUIRED");
  const candidateIds = ivanBeastFormMoveCandidates(state, player);
  if (candidateIds.length === 0) throw new Error("IVAN_BEAST_FORM_NO_TARGET");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:move`;
  state.effectQueue.unshift({
    effectId,
    handlerId: IVAN_BEAST_FORM_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { stage: "move", candidateIds: [...candidateIds] },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "ivan-beast-form-move-opponent",
    options: candidateIds.map((id) => ({ id, label: state.players[id]?.name ?? id })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isIvanBeastFormLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === IVAN_BEAST_FORM_MOVE_ABILITY && state.phase === "action" && state.activePlayerId === playerId
    && ivanBeastFormMoveCandidates(state, player).length > 0);
};

const resolveIvanBeastForm: SkillHandler = (context) => useIvanBeastForm(context);

const ARCUEID_MATERIALIZATION_ID = "master.arcueid.skill.s2";
const ARCUEID_MATERIALIZATION_RESOLVE = "core.arcueid-materialization-resolve";

function arcueidMaterializationCandidates(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") return [];
  return (state.board.locations[locationId] ?? []).flatMap((playerId) => {
    const participant = state.players[playerId];
    if (!participant || participant.eliminated) return [];
    return participant.attack.filter((instanceId) => {
      const card = state.cards[instanceId];
      const definition = card ? definitions[card.definitionId] : undefined;
      return Boolean(card?.active && card.face === "up" && definition?.basic === true);
    });
  });
}


export const useArcueidMaterialization: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("ARCUEID_MATERIALIZATION_DEFINITIONS_REQUIRED");
  const wrapped = isRecord(payload) ? payload : {};
  const abilityId = typeof wrapped.abilityId === "string" ? wrapped.abilityId : undefined;
  if (abilityId === "prepare-materialization") {
    if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("ARCUEID_MATERIALIZATION_PREPARE_WINDOW_INVALID");
    player.flags.arcueidMaterializationPreparedRound = state.round;
    return;
  }
  if (abilityId !== "materialize-replace") throw new Error("ARCUEID_MATERIALIZATION_ABILITY_INVALID");
  if (state.phase !== "combat" || state.activePlayerId !== player.id || Number(player.flags.arcueidMaterializationPreparedRound ?? -1) !== state.round) {
    throw new Error("ARCUEID_MATERIALIZATION_COMBAT_WINDOW_INVALID");
  }
  const candidates = arcueidMaterializationCandidates(state, player, definitions);
  if (candidates.length === 0) throw new Error("ARCUEID_MATERIALIZATION_NO_TARGET");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:replace`;
  state.effectQueue.unshift({
    effectId,
    handlerId: ARCUEID_MATERIALIZATION_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { candidates: [...candidates] },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "arcueid-materialization-basic-attack",
    options: candidates.map((instanceId) => ({
      id: instanceId,
      label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId,
    })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isArcueidMaterializationLegal: SkillLegalityPredicate = (state, playerId, _skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || !definitions || state.activePlayerId !== playerId) return false;
  if (ability.id === "prepare-materialization") return state.phase === "action";
  if (ability.id === "materialize-replace") {
    return state.phase === "combat" && Number(player.flags.arcueidMaterializationPreparedRound ?? -1) === state.round
      && arcueidMaterializationCandidates(state, player, definitions).length > 0;
  }
  return false;
};

const resolveArcueidMaterialization: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("ARCUEID_MATERIALIZATION_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) throw new Error("ARCUEID_MATERIALIZATION_DECISION_INVALID");
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const instanceId = decision.selections[0];
  if (typeof instanceId !== "string" || !candidates.includes(instanceId)
    || !arcueidMaterializationCandidates(state, player, definitions).includes(instanceId)) throw new Error("ARCUEID_MATERIALIZATION_TARGET_INVALID");
  const card = state.cards[instanceId];
  const ownerPlayerId = card.ownerPlayerId;
  const controllerPlayerId = card.controllerPlayerId ?? ownerPlayerId;
  if (!ownerPlayerId || !controllerPlayerId || !state.players[controllerPlayerId]) throw new Error("ARCUEID_MATERIALIZATION_CONTROLLER_INVALID");
  closePlayerCard(state, ownerPlayerId, instanceId, definitions, { closedByPlayerId: player.id });

  const random = new StateRandom();
  const maxDraws = state.players[controllerPlayerId].deck.length + state.players[controllerPlayerId].discard.length;
  for (let index = 0; index < maxDraws; index += 1) {
    const drawn = drawCards(state, controllerPlayerId, 1, (maxExclusive) => random.integer(state, maxExclusive), definitions)[0];
    if (!drawn) break;
    const drawnCard = state.cards[drawn];
    const drawnDefinition = definitions[drawnCard.definitionId];
    if (drawnDefinition?.basic !== true) continue;
    emitEvent?.("card.drawn", { playerId: controllerPlayerId, instanceId: drawn, definitionId: drawnCard.definitionId, sourceId: ARCUEID_MATERIALIZATION_ID });
    movePlayerCard(state, controllerPlayerId, drawn, "attack");
    drawnCard.face = "up";
    drawnCard.active = true;
    drawnCard.residual = drawnDefinition.residual === true;
    drawnCard.paidCost = 0;
    break;
  }
};

const CELENIKE_CURSE_ID = "master.celenike.skill.s1";
const CELENIKE_STAKE_ID = "master.celenike.skill.ascension";
const CELENIKE_STAKE_RESOLVE = "core.celenike-iron-stake-resolve";
const IBARAKI_RASHOMON_RESOLVE = "core.ibaraki-rashomon-resolve";

const MANDRICARDO_OATH_ID = "servant.mandricardo.skill.sc-mandricardo-1";
const MANDRICARDO_WOODEN_SWORD_ID = "servant.mandricardo.skill.sc-mandricardo-2";
const MANDRICARDO_HANDLER_ID = "core.mandricardo-instant-strike";

function mandricardoRoundSetKey(kind: "below" | "overtaken", playerId: string, round: number): string {
  return `mandricardo:${kind}:${playerId}:${round}`;
}

function readMandricardoRoundSet(state: GameState, kind: "below" | "overtaken", playerId: string): Set<string> {
  const value = state.modeState[mandricardoRoundSetKey(kind, playerId, state.round)];
  return new Set(Array.isArray(value) ? value.filter((id): id is string => typeof id === "string") : []);
}

function writeMandricardoRoundSet(state: GameState, kind: "below" | "overtaken", playerId: string, values: Set<string>): void {
  state.modeState[mandricardoRoundSetKey(kind, playerId, state.round)] = [...values];
}

/** Tracks unique opponents whom Mandricardo has gone from below to above in VP this round. */
function updateMandricardoOvertakes(state: GameState, playerId: string, reset = false): void {
  const player = state.players[playerId];
  if (!player) return;
  const below = reset ? new Set<string>() : readMandricardoRoundSet(state, "below", playerId);
  const overtaken = reset ? new Set<string>() : readMandricardoRoundSet(state, "overtaken", playerId);
  for (const opponent of Object.values(state.players)) {
    if (opponent.id === playerId) continue;
    if (player.victoryPoints < opponent.victoryPoints) {
      below.add(opponent.id);
      continue;
    }
    if (player.victoryPoints > opponent.victoryPoints && below.has(opponent.id)) overtaken.add(opponent.id);
  }
  writeMandricardoRoundSet(state, "below", playerId, below);
  writeMandricardoRoundSet(state, "overtaken", playerId, overtaken);
}

function mandricardoArmedSource(state: GameState, player: PlayerState): import("../domain/state/types.ts").CardInstance | undefined {
  if (Number(player.flags.mandricardoInstantStrikeRound ?? -1) !== state.round) return undefined;
  const sourceInstanceId = typeof player.flags.mandricardoInstantStrikeSourceInstanceId === "string"
    ? player.flags.mandricardoInstantStrikeSourceInstanceId
    : undefined;
  return sourceInstanceId ? state.cards[sourceInstanceId] : undefined;
}

function armMandricardoInstantStrike(state: GameState, player: PlayerState, sourceInstanceId: string): void {
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + 5;
  player.flags.mandricardoInstantStrikeRound = state.round;
  player.flags.mandricardoInstantStrikeSourceInstanceId = sourceInstanceId;
}

/** Mandricardo's Instant Strike and the complete copy later granted to Wooden Sword. */
export const useMandricardoInstantStrike: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "round.started") {
    updateMandricardoOvertakes(state, player.id, true);
    return;
  }
  if (eventType === "player.victory-points.changed") {
    updateMandricardoOvertakes(state, player.id);
    return;
  }
  if (eventType === "combat.ending") {
    const source = mandricardoArmedSource(state, player);
    if (!source) return;
    const overtaken = readMandricardoRoundSet(state, "overtaken", player.id);
    if (overtaken.size > 0) gainVictoryPoints(player, overtaken.size);
    const removedByThisEffect = source.ownerPlayerId === player.id && source.zone !== "removed";
    if (removedByThisEffect) {
      movePlayerCard(state, player.id, source.instanceId, "removed");
      source.active = false;
      source.residual = false;
      if (source.definitionId === MANDRICARDO_OATH_ID) player.flags.mandricardoWoodenSwordInstantStrikeGranted = true;
    }
    delete player.flags.mandricardoInstantStrikeRound;
    delete player.flags.mandricardoInstantStrikeSourceInstanceId;
    return;
  }

  const abilityId = readSkillAbilityId(payload);
  if (skill.id === MANDRICARDO_OATH_ID && abilityId === "oath-instant-strike") {
    if (state.phase !== "action" || state.step !== "player-window" || state.activePlayerId !== player.id) throw new Error("MANDRICARDO_OATH_WINDOW_INVALID");
    const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, MANDRICARDO_OATH_ID);
    if (!sourceInstanceId) throw new Error("MANDRICARDO_OATH_SOURCE_NOT_ACTIVE");
    armMandricardoInstantStrike(state, player, sourceInstanceId);
    return;
  }
  if (skill.id === MANDRICARDO_WOODEN_SWORD_ID && abilityId === "wooden-sword-instant-strike") {
    if (player.flags.mandricardoWoodenSwordInstantStrikeGranted !== true) throw new Error("MANDRICARDO_WOODEN_SWORD_NOT_GRANTED");
    if (state.phase !== "combat" || state.step !== "player-window" || state.activePlayerId !== player.id) throw new Error("MANDRICARDO_WOODEN_SWORD_WINDOW_INVALID");
    const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, MANDRICARDO_WOODEN_SWORD_ID);
    if (!sourceInstanceId) throw new Error("MANDRICARDO_WOODEN_SWORD_SOURCE_NOT_ACTIVE");
    armMandricardoInstantStrike(state, player, sourceInstanceId);
    return;
  }
  throw new Error("MANDRICARDO_INSTANT_STRIKE_ABILITY_INVALID");
};

export const isMandricardoInstantStrikeLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player || !ability || Number(player.flags.mandricardoInstantStrikeRound ?? -1) === state.round) return false;
  if (skill.id === MANDRICARDO_OATH_ID && ability.id === "oath-instant-strike") {
    return state.phase === "action" && state.step === "player-window" && state.activePlayerId === playerId
      && Boolean(findActiveOwnedSkillAttack(state, playerId, MANDRICARDO_OATH_ID));
  }
  if (skill.id === MANDRICARDO_WOODEN_SWORD_ID && ability.id === "wooden-sword-instant-strike") {
    return player.flags.mandricardoWoodenSwordInstantStrikeGranted === true
      && state.phase === "combat" && state.step === "player-window" && state.activePlayerId === playerId
      && Boolean(findActiveOwnedSkillAttack(state, playerId, MANDRICARDO_WOODEN_SWORD_ID));
  }
  return false;
};

const KAYNETH_ALCHEMIST_ID = "master.kayneth.skill.s2";
const KAYNETH_FLUID_DYNAMICS_ID = "master.kayneth.skill.ascension";
const KAYNETH_ALCHEMIST_HANDLER = "core.kayneth-alchemist";
const KAYNETH_FLUID_HANDLER = "core.kayneth-fluid-dynamics";
const KAYNETH_FLUID_REVEAL_RESOLVE = "core.kayneth-fluid-reveal-resolve";
const KAYNETH_VOLUMEN_SCALP = "card.card-volumen-slash";
const KAYNETH_VOLUMEN_IRE = "card.card-volumen-track";
const KAYNETH_VOLUMEN_FERVOR = "card.card-volumen-boil";
const KAYNETH_VOLUMEN_IDS = new Set([KAYNETH_VOLUMEN_SCALP, KAYNETH_VOLUMEN_IRE, KAYNETH_VOLUMEN_FERVOR]);

function kaynethVolumenDeckKey(playerId: string): string {
  return `kaynethVolumenDeck:${playerId}`;
}

function kaynethVolumenDrawCountKey(playerId: string): string {
  return `kaynethVolumenDrawCount:${playerId}`;
}

function shuffleDefinitionIds(state: GameState, definitionIds: string[]): string[] {
  const result = [...definitionIds];
  const random = new StateRandom();
  for (let index = result.length - 1; index > 0; index -= 1) {
    const swapIndex = random.integer(state, index + 1);
    [result[index], result[swapIndex]] = [result[swapIndex], result[index]];
  }
  return result;
}


export const useKaynethAlchemist: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "game.started") {
    state.modeState[kaynethVolumenDeckKey(player.id)] = shuffleDefinitionIds(state, [
      KAYNETH_VOLUMEN_SCALP, KAYNETH_VOLUMEN_SCALP, KAYNETH_VOLUMEN_SCALP,
      KAYNETH_VOLUMEN_IRE, KAYNETH_VOLUMEN_IRE,
      KAYNETH_VOLUMEN_FERVOR,
    ]);
    state.modeState[kaynethVolumenDrawCountKey(player.id)] = 0;
    return;
  }
  const abilityId = readSkillAbilityId(payload);
  if (skill.id !== KAYNETH_ALCHEMIST_ID || abilityId !== "alchemist-draw") throw new Error("KAYNETH_ALCHEMIST_ABILITY_INVALID");
  if (state.phase !== "action" || state.step !== "player-window" || state.activePlayerId !== player.id || !definitions) {
    throw new Error("KAYNETH_ALCHEMIST_WINDOW_INVALID");
  }
  const key = kaynethVolumenDeckKey(player.id);
  const deck = Array.isArray(state.modeState[key]) ? (state.modeState[key] as unknown[]).filter((id): id is string => typeof id === "string") : [];
  const definitionId = deck.shift();
  if (!definitionId || !KAYNETH_VOLUMEN_IDS.has(definitionId) || !definitions[definitionId]) throw new Error("KAYNETH_VOLUMEN_DECK_EMPTY");
  state.modeState[key] = deck;
  const countKey = kaynethVolumenDrawCountKey(player.id);
  const drawCount = Number(state.modeState[countKey] ?? 0) + 1;
  state.modeState[countKey] = drawCount;
  const instanceId = `${player.id}:volumen:${drawCount}:${definitionId}`;
  createOwnedCardInstance(state, player.id, {
    instanceId,
    definitionId,
    zone: "hand",
    face: "down",
    active: false,
  });
  return { instanceId, definitionId, remaining: deck.length };
};

export const isKaynethAlchemistLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  if (skill.id !== KAYNETH_ALCHEMIST_ID || ability?.id !== "alchemist-draw") return false;
  const deck = state.modeState[kaynethVolumenDeckKey(playerId)];
  return state.phase === "action" && state.step === "player-window" && state.activePlayerId === playerId
    && Array.isArray(deck) && deck.length > 0;
};

function installKaynethFluidDynamics(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): void {
  const modifierId = `${KAYNETH_FLUID_DYNAMICS_ID}:two-round-residual`;
  if (!(player.cardRuleModifiers ?? []).some((modifier) => modifier.id === modifierId)) {
    const targetDefinitionIds = Object.values(definitions)
      .filter((definition) => definition.isSkill !== true && definition.id.startsWith("card."))
      .map((definition) => definition.id);
    addCardRuleModifier(player, {
      id: modifierId,
      sourceId: KAYNETH_FLUID_DYNAMICS_ID,
      targetDefinitionIds,
      grantResidual: true,
      residualUntilRoundOffset: 1,
      duration: "game",
    });
  }
  for (const instanceId of player.attack) {
    const instance = state.cards[instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    if (!instance?.active || instance.face !== "up" || !definition || definition.isSkill === true) continue;
    instance.residual = true;
    instance.residualUntilRound = Math.max(Number(instance.residualUntilRound ?? state.round + 1), state.round + 1);
  }
}


export const useKaynethFluidDynamics: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("KAYNETH_FLUID_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType === "game.started" || eventType === "skill.unlocked") {
    if (eventType === "skill.unlocked" && (event.playerId !== player.id || event.skillId !== skill.id)) return;
    installKaynethFluidDynamics(state, player, definitions);
    return;
  }
  if (eventType === "card.entered-attack") {
    if (event.ownerPlayerId !== player.id || typeof event.instanceId !== "string") return;
    const instance = state.cards[event.instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    if (!instance?.active || !definition || definition.isSkill === true) return;
    instance.residual = true;
    instance.residualUntilRound = Math.max(Number(instance.residualUntilRound ?? state.round + 1), state.round + 1);
    return;
  }
  if (eventType !== "card.drawn") return;
  const definitionId = typeof event.definitionId === "string" ? event.definitionId : undefined;
  const instanceId = typeof event.instanceId === "string" ? event.instanceId : undefined;
  if (event.ownerPlayerId !== player.id || event.fromZone !== "deck" || !definitionId || !instanceId || !KAYNETH_VOLUMEN_IDS.has(definitionId)) return;
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:reveal:${instanceId}`;
  state.effectQueue.unshift({
    effectId,
    handlerId: KAYNETH_FLUID_REVEAL_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { instanceId, definitionId },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "kayneth-fluid-reveal-draw",
    options: [
      { id: "reveal-draw", label: "展示此牌并额外抽1张牌" },
      { id: "decline", label: "不发动" },
    ],
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

const resolveKaynethFluidReveal: SkillHandler = ({ state, player, payload, definitions, randomInt, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("KAYNETH_FLUID_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || selections.length !== 1) throw new Error("KAYNETH_FLUID_DECISION_INVALID");
  if (selections[0] === "decline") return;
  if (selections[0] !== "reveal-draw") throw new Error("KAYNETH_FLUID_DECISION_INVALID");
  const instanceId = typeof previous.instanceId === "string" ? previous.instanceId : undefined;
  const card = instanceId ? state.cards[instanceId] : undefined;
  if (!card || card.ownerPlayerId !== player.id || !KAYNETH_VOLUMEN_IDS.has(card.definitionId) || !player.hand.includes(card.instanceId)) {
    throw new Error("KAYNETH_FLUID_REVEAL_CARD_INVALID");
  }
  emitEvent?.("card.revealed", { playerId: player.id, instanceId: card.instanceId, definitionId: card.definitionId, sourceId: KAYNETH_FLUID_DYNAMICS_ID });
  drawCards(state, player.id, 1, randomInt ?? ((max) => new StateRandom().integer(state, max)), definitions);
};

const KOHAKU_BURNED_WORKSHOP_HANDLER = "core.kohaku-burned-workshop";
const KOHAKU_MECH_HISUI_ID = "master.kohaku.skill.ascension";
const KOHAKU_MECH_HISUI_HANDLER = "core.kohaku-mech-hisui";
const KOHAKU_MECH_HISUI_RESOLVE = "core.kohaku-mech-hisui-resolve";


export const useKohakuBurnedWorkshop: SkillHandler = ({ state, player, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType !== "round.ending") return;
  const previousLocations = isRecord(event.previousLocations) ? event.previousLocations : {};
  if (previousLocations[player.id] !== "mountain") return;
  const copies = [...new Set([...player.masterSkills, ...player.servantSkills, ...player.hand, ...player.attack])]
    .filter((instanceId) => state.cards[instanceId]?.definitionId === KOHAKU_BURNED_WORKSHOP_ID && state.cards[instanceId]?.zone !== "removed");
  for (const instanceId of copies) movePlayerCard(state, player.id, instanceId, "removed");
};

function kohakuOnslaughtHandCards(state: GameState, player: PlayerState): string[] {
  return player.hand.filter((instanceId) => state.cards[instanceId]?.definitionId === KOHAKU_MAGICAL_ONSLAUGHT_ID);
}


export const useKohakuMechHisui: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("KOHAKU_MECH_HISUI_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "combat.resolved") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
    const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds.filter((id): id is string => typeof id === "string") : [];
    if (player.flags.kohakuMechHisuiCombatRound !== state.round || player.flags.kohakuMechHisuiCombatLocationId !== event.locationId || !winnerIds.includes(player.id)) return;
    const burned: string[] = [];
    for (const targetId of state.board.locations.workshop ?? []) {
      const target = state.players[targetId];
      if (!target || target.eliminated) continue;
      burned.push(grantBurnedWorkshop(state, targetId, definitions));
    }
    return { burned };
  }

  const abilityId = readSkillAbilityId(payload);
  if (abilityId === "mech-hisui-onslaught") {
    if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("KOHAKU_MECH_HISUI_ACTION_WINDOW_INVALID");
    const candidates = kohakuOnslaughtHandCards(state, player);
    if (candidates.length === 0) throw new Error("KOHAKU_MECH_HISUI_NO_ONSLAUGHT");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:onslaught`;
    state.effectQueue.unshift({
      effectId,
      handlerId: KOHAKU_MECH_HISUI_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { candidates: [...candidates] },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "kohaku-mech-hisui-onslaught",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
      min: 1,
      max: Math.min(2, candidates.length),
      allowCancel: true,
      continuationEffectId: effectId,
      fallbackEffectId: effectId,
      submissions: {},
    });
    return;
  }

  if (abilityId === "mech-hisui-combat") {
    if (state.phase !== "combat" || state.step !== "player-window" || state.activePlayerId !== player.id) throw new Error("KOHAKU_MECH_HISUI_COMBAT_WINDOW_INVALID");
    const locationId = player.locationId;
    if (locationId !== "mountain" && locationId !== "city") throw new Error("KOHAKU_MECH_HISUI_NOT_IN_BATTLE");
    const ownTerrain = calculateTerrainAdvantage(state, player, definitions, locationId);
    const penalized: string[] = [];
    for (const opponentId of state.board.locations[locationId] ?? []) {
      if (opponentId === player.id) continue;
      const opponent = state.players[opponentId];
      if (!opponent || opponent.eliminated) continue;
      const opponentTerrain = calculateTerrainAdvantage(state, opponent, definitions, locationId);
      if (opponentTerrain >= ownTerrain) continue;
      opponent.flags.roundPowerBonus = Number(opponent.flags.roundPowerBonus ?? 0) - 4;
      penalized.push(opponentId);
    }
    player.flags.kohakuMechHisuiCombatRound = state.round;
    player.flags.kohakuMechHisuiCombatLocationId = locationId;
    return { ownTerrain, penalized };
  }
  throw new Error("KOHAKU_MECH_HISUI_ABILITY_INVALID");
};

const resolveKohakuMechHisuiOnslaught: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("KOHAKU_MECH_HISUI_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status === "cancelled") return;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved" || selections.length < 1 || selections.length > 2 || selections.some((id) => !candidates.includes(id))) {
    throw new Error("KOHAKU_MECH_HISUI_DECISION_INVALID");
  }
  const played: string[] = [];
  for (const instanceId of selections) {
    const instance = state.cards[instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    if (!instance || instance.ownerPlayerId !== player.id || instance.zone !== "hand" || definition?.id !== KOHAKU_MAGICAL_ONSLAUGHT_ID) {
      throw new Error("KOHAKU_MECH_HISUI_ONSLAUGHT_INVALID");
    }
    const { paidMana } = addCardToAttack(state, player.id, instanceId, definitions, {
      payCost: true,
      allowedSourceZones: ["hand"],
      bypassFaceUpPlayLimit: true,
      bypassTiming: true,
    });
    emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: definition.id, face: "up", paidMana, attributes: getCardAttributes(definition), method: "mech-hisui" });
    emitEvent?.("card.used", { playerId: player.id, instanceId, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "mech-hisui" });
    played.push(instanceId);
  }
  return { played };
};

export const isKohakuMechHisuiLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  if (skill.id !== KOHAKU_MECH_HISUI_ID || !ability) return false;
  const player = state.players[playerId];
  if (!player) return false;
  if (ability.id === "mech-hisui-onslaught") return state.phase === "action" && state.activePlayerId === playerId && kohakuOnslaughtHandCards(state, player).length > 0;
  if (ability.id === "mech-hisui-combat") return state.phase === "combat" && state.step === "player-window" && state.activePlayerId === playerId
    && (player.locationId === "mountain" || player.locationId === "city");
  return false;
};

function celenikeWitherKey(sourcePlayerId: string): string {
  return `celenikeWitheredBy:${sourcePlayerId}`;
}

function isCelenikeWithered(player: PlayerState): boolean {
  return Object.entries(player.flags).some(([key, value]) => key.startsWith("celenikeWitheredBy:") && value === true);
}

function clearCelenikeWitherFromSource(state: GameState, sourcePlayerId: string): void {
  const key = celenikeWitherKey(sourcePlayerId);
  for (const candidate of Object.values(state.players)) delete candidate.flags[key];
}


export const useCelenikeCurse: SkillHandler = ({ state, player, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "player.victory-points.changed") {
    if (!event || event.playerId !== player.id || Number(event.delta) <= 0) return;
    if (Number(player.flags.roundVictoryPointsGained ?? 0) >= 4) clearCelenikeWitherFromSource(state, player.id);
    return;
  }
  if (eventType !== "combat.resolved" || !event || !isRecord(event.powers) || !Array.isArray(event.winnerIds)) return;
  const participantIds = Object.keys(event.powers).filter((id) => Boolean(state.players[id]));
  if (!participantIds.includes(player.id)) return;
  const winnerIds = event.winnerIds.filter((id): id is string => typeof id === "string" && Boolean(state.players[id]));
  if (winnerIds.includes(player.id)) {
    for (const targetPlayerId of participantIds) {
      if (targetPlayerId === player.id || !isCelenikeWithered(state.players[targetPlayerId])) continue;
      const target = state.players[targetPlayerId];
      const amount = Math.min(2, Math.max(0, target.victoryPoints));
      target.victoryPoints -= amount;
      gainVictoryPoints(player, amount);
    }
    return;
  }
  const defeatedPlayerIds = Array.isArray(event.defeatedPlayerIds)
    ? event.defeatedPlayerIds.filter((id): id is string => typeof id === "string")
    : [];
  if (!defeatedPlayerIds.includes(player.id)) return;
  const key = celenikeWitherKey(player.id);
  for (const winnerId of winnerIds) state.players[winnerId].flags[key] = true;
};

function celenikeStakeTargets(state: GameState): string[] {
  return state.turnOrder.filter((playerId) => {
    const target = state.players[playerId];
    return Boolean(target && !target.eliminated && isCelenikeWithered(target));
  });
}

function openCelenikeStakeDecision(
  state: GameState,
  player: PlayerState,
  targetIds: string[],
  startIndex: number,
  openDecision: SkillContext["openDecision"],
): void {
  for (let index = startIndex; index < targetIds.length; index += 1) {
    const target = state.players[targetIds[index]];
    if (!target || target.eliminated || !isCelenikeWithered(target)) continue;
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${CELENIKE_STAKE_ID}:${index}`;
    state.effectQueue.unshift({
      effectId,
      handlerId: CELENIKE_STAKE_RESOLVE,
      sourceId: CELENIKE_STAKE_ID,
      controllerPlayerId: player.id,
      payload: { targetIds: [...targetIds], index },
      createdAtRevision: state.revision,
    });
    const options = [{ id: "discard-all", label: "弃置所有手牌" }];
    if (target.mana >= 2) options.unshift({ id: "pay-mana", label: "支付2点魔力" });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [target.id],
      kind: "celenike-pain-stake",
      options,
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
}


export const useCelenikeIronStake: SkillHandler = ({ state, player, payload, openDecision }) => {
  const wrapped = isRecord(payload) ? payload : {};
  const abilityId = typeof wrapped.abilityId === "string" ? wrapped.abilityId : undefined;
  if (abilityId !== "pain-stake") throw new Error("CELENIKE_STAKE_ABILITY_INVALID");
  if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("CELENIKE_STAKE_WINDOW_INVALID");
  const targetIds = celenikeStakeTargets(state);
  if (targetIds.length === 0) throw new Error("CELENIKE_STAKE_NO_TARGET");
  openCelenikeStakeDecision(state, player, targetIds, 0, openDecision);
};

export const isCelenikeIronStakeLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  return Boolean(state.players[playerId] && ability?.id === "pain-stake" && state.phase === "action"
    && state.activePlayerId === playerId && celenikeStakeTargets(state).length > 0);
};

const resolveCelenikeIronStake: SkillHandler = ({ state, player, payload, openDecision }) => {
  if (!isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("CELENIKE_STAKE_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) throw new Error("CELENIKE_STAKE_DECISION_INVALID");
  const targetIds = Array.isArray(previous.targetIds) ? previous.targetIds.filter((id): id is string => typeof id === "string") : [];
  const index = Number(previous.index);
  if (!Number.isInteger(index) || index < 0 || index >= targetIds.length) throw new Error("CELENIKE_STAKE_DECISION_INVALID");
  const target = state.players[targetIds[index]];
  if (!target || target.eliminated || !isCelenikeWithered(target)) throw new Error("CELENIKE_STAKE_TARGET_INVALID");
  const selected = decision.selections[0];
  if (selected === "pay-mana") {
    if (target.mana < 2) throw new Error("INSUFFICIENT_MANA");
    target.mana -= 2;
  } else if (selected === "discard-all") {
    for (const instanceId of [...target.hand]) {
      movePlayerCard(state, target.id, instanceId, "discard");
      state.cards[instanceId].face = "up";
      state.cards[instanceId].active = false;
      state.cards[instanceId].residual = false;
    }
  } else {
    throw new Error("CELENIKE_STAKE_SELECTION_INVALID");
  }
  openCelenikeStakeDecision(state, player, targetIds, index + 1, openDecision);
};

export const useIvanBlackDog: SkillHandler = ({ state, player, skill, payload }) => {
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId === "tsar-eye") {
    gainVictoryPoints(player, 2);
    return;
  }
  if (abilityId === "tsar-law") {
    const targetPlayerId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
    const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
    if (!target || target.id === player.id || target.eliminated || target.mana < 1) throw new Error("IVAN_BLACK_DOG_TARGET_INVALID");
    target.mana -= 1;
    gainMana(player, 1);
    return;
  }
  if (abilityId === "tsar-wrath") {
    const activeAttacks = player.attack
      .map((instanceId) => state.cards[instanceId])
      .filter((card): card is NonNullable<typeof card> => Boolean(card?.active && card.face === "up"));
    if (activeAttacks.length === 0) throw new Error("IVAN_BLACK_DOG_NO_ATTACK");
    for (const card of activeAttacks) {
      const modifierId = `${skill.id}:tsar-wrath:${card.instanceId}`;
      card.powerModifiers = [
        ...(card.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
        { id: modifierId, sourceId: skill.id, kind: "add", value: 1, duration: "round" },
      ];
    }
    return;
  }
  throw new Error("IVAN_BLACK_DOG_ABILITY_INVALID");
};

export const isIvanBlackDogLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  if (!player) return false;
  if (ability?.id === "tsar-eye") return true;
  if (ability?.id === "tsar-law") return Object.values(state.players).some((target) => target.id !== playerId && !target.eliminated && target.mana > 0);
  if (ability?.id === "tsar-wrath") return player.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    return Boolean(card?.active && card.face === "up");
  });
  return false;
};


export const useMhxAntiSaberWeapon: SkillHandler = ({ state, player, skill, payload, emitEvent, definitions }) => {
  const locationId = player.locationId;
  if (state.phase !== "combat" || state.step !== "player-window" || state.activePlayerId !== player.id
    || (locationId !== "mountain" && locationId !== "city")) throw new Error("MHX_ANTI_SABER_WINDOW_INVALID");
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("MHX_ANTI_SABER_SOURCE_MISSING");
  const targetPlayerId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
  if (!target || target.id === player.id || target.eliminated || target.defeated || target.locationId !== locationId) {
    throw new Error("MHX_ANTI_SABER_TARGET_INVALID");
  }
  // If the target is ignoring other-player ability effects, the defeat and the
  // conditional theft are both ignored; consuming the once-per-game use is still legal.
  if (isOtherPlayerAbilityEffectIgnored(state, player.id, target.id)) return;
  if (!definitions) throw new Error("MHX_ANTI_SABER_DEFINITIONS_REQUIRED");
  defeatPlayerByEffect(state, target.id, player.id, definitions, emitEvent, { sourceId: skill.id });
  if (!target.defeated) return;
  const traitCount = Number(isBlondServant(target.servantId)) + Number(isSaberServant(target.servantId));
  const requested = 2 + 2 * traitCount;
  const stolen = Math.min(requested, target.victoryPoints);
  target.victoryPoints -= stolen;
  gainVictoryPoints(player, stolen);
  return { targetPlayerId: target.id, requested, stolen, blond: traitCount > 0 && isBlondServant(target.servantId), saber: isSaberServant(target.servantId) };
};

export const isMhxAntiSaberWeaponLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  const locationId = player?.locationId;
  return Boolean(player && state.phase === "combat" && state.step === "player-window" && state.activePlayerId === playerId
    && (locationId === "mountain" || locationId === "city")
    && findActiveOwnedSkillAttack(state, playerId, skill.id)
    && (state.board.locations[locationId] ?? []).some((id) => id !== playerId && !state.players[id]?.eliminated && !state.players[id]?.defeated));
};

const ARTOIRA_CHARGE_ID = "master.artoira.skill.s1";
const ARTOIRA_WOODEN_SWORD_ID = "master.artoira.skill.ascension";
const ARTOIRA_CHARGE_RESOLVE = "core.artoira-charge-resolve";

function artoiraChargeCandidates(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return [...player.servantSkills, ...player.masterSkills].filter((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    if (!card || !definition || card.face !== "up" || card.active || !definition.isSkill || getCardAttributes(definition).length === 0) return false;
    const linkedSkillId = definition.linkedSkillId ?? definition.id;
    const servantSkillAttack = card.zone === "servant-skills" && definition.skillOwnerType === "servant"
      && typeof player.servantId === "string" && definition.ownerDefinitionId === player.servantId;
    const woodenSword = card.zone === "master-skills" && linkedSkillId === ARTOIRA_WOODEN_SWORD_ID;
    if (!servantSkillAttack && !woodenSword) return false;
    const position = Number(definition.cost) + 1;
    return Number.isInteger(position) && position > 0 && player.deck.length >= position;
  });
}


export const useArtoiraCharge: SkillHandler = ({ state, player, skill, openDecision, definitions }) => {
  if (!definitions || state.phase !== "outpost" || state.step !== "player-window" || state.activePlayerId !== player.id) {
    throw new Error("ARTOIRA_CHARGE_WINDOW_INVALID");
  }
  const candidates = artoiraChargeCandidates(state, player, definitions);
  if (candidates.length === 0) throw new Error("ARTOIRA_CHARGE_NO_TARGET");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:charge`;
  state.effectQueue.unshift({
    effectId,
    handlerId: ARTOIRA_CHARGE_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { candidates: [...candidates] },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "artoira-charge-skill-attack",
    options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isArtoiraChargeLegal: SkillLegalityPredicate = (state, playerId, _skill, _ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && state.phase === "outpost" && state.step === "player-window" && state.activePlayerId === playerId
    && artoiraChargeCandidates(state, player, definitions).length > 0);
};

const resolveArtoiraCharge: SkillHandler = ({ state, player, payload, definitions }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("ARTOIRA_CHARGE_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) throw new Error("ARTOIRA_CHARGE_DECISION_INVALID");
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const instanceId = decision.selections[0];
  if (typeof instanceId !== "string" || !candidates.includes(instanceId) || !artoiraChargeCandidates(state, player, definitions).includes(instanceId)) {
    throw new Error("ARTOIRA_CHARGE_TARGET_INVALID");
  }
  return { instanceId, ...chargeOwnedSkillAttack(state, player.id, instanceId, definitions, ARTOIRA_CHARGE_ID) };
};


export const useArtoiraWoodenSword: SkillHandler = ({ state, player, skill, emitEvent }) => {
  const source = player.attack.map((instanceId) => state.cards[instanceId]).find((card) => card
    && (card.definitionId === skill.id)
    && card.active && card.face === "up" && card.chargedAttackEnteredRound === state.round);
  if (!source) return;
  state.modeState.instantVictoryIds = [player.id];
  state.modeState.instantVictoryReason = skill.id;
  state.status = "finished";
  state.phase = "combat";
  state.step = "settlement";
  state.activePlayerId = null;
  emitEvent?.("game.finished", { round: state.round, winnerIds: [player.id], reason: skill.id, sourceSkillId: skill.id });
};


export const useMhxNamelessVictorySword: SkillHandler = ({ state, player, skill, payload }) => {
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("MHX_NAMELESS_SOURCE_MISSING");
  const source = state.cards[sourceInstanceId];
  if (abilityId === "galaxy-meteor-sword") {
    const modifierId = `${skill.id}:galaxy-meteor:${sourceInstanceId}`;
    source.powerModifiers = [
      ...(source.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
      { id: modifierId, sourceId: skill.id, kind: "add", value: 4, duration: "game" },
    ];
    return;
  }
  if (abilityId === "cosmic-reactor") {
    const rule = skill.eventCardPowerBonus;
    if (!rule || !Number.isInteger(rule.perEvent)) throw new Error("MHX_NAMELESS_RULE_INVALID");
    const eventCount = countCurrentEventCards(state);
    if (eventCount <= 0) throw new Error("MHX_NAMELESS_NO_EVENTS");
    const modifierId = `${skill.id}:cosmic-reactor:${sourceInstanceId}:${state.round}`;
    source.powerModifiers = [
      ...(source.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
      { id: modifierId, sourceId: skill.id, kind: "add", value: eventCount * rule.perEvent, duration: "round" },
    ];
    return;
  }
  throw new Error("MHX_NAMELESS_ABILITY_INVALID");
};

export const isMhxNamelessVictorySwordLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  if (!findActiveOwnedSkillAttack(state, playerId, skill.id)) return false;
  if (ability?.id === "galaxy-meteor-sword") return true;
  if (ability?.id === "cosmic-reactor") return countCurrentEventCards(state) > 0;
  return false;
};

function findActiveOwnedSkillAttack(state: GameState, playerId: string, skillId: string): string | undefined {
  const player = state.players[playerId];
  if (!player) return undefined;
  return player.attack.find((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === skillId && card.ownerPlayerId === playerId && card.active && card.face === "up";
  });
}

function countCurrentEventCards(state: GameState): number {
  return Object.values(state.board.currentEvents).reduce((total, eventIds) => total + eventIds.length, 0);
}


export const useAndersenInnocentMonster: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "round.ended") {
    clearAndersenInnocentMonsterMark(player);
    return;
  }
  if (eventType === "combat.resolved") {
    const targetId = typeof player.flags.andersenInnocentMonsterTargetPlayerId === "string"
      ? player.flags.andersenInnocentMonsterTargetPlayerId
      : undefined;
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
    const powers = isRecord(event.powers) ? event.powers : {};
    const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds : [];
    if (targetId && Object.prototype.hasOwnProperty.call(powers, targetId) && !winnerIds.includes(targetId)) {
      gainVictoryPoints(player, Number(skill.markedDefeatVictoryPointReward ?? 2));
      clearAndersenInnocentMonsterMark(player);
    }
    return;
  }

  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId === "innocent-mark") {
    const targetPlayerId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
    const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
    if (!target || target.id === player.id || target.eliminated) throw new Error("ANDERSEN_INNOCENT_TARGET_INVALID");
    player.flags.andersenInnocentMonsterTargetPlayerId = target.id;
    player.flags.andersenInnocentMonsterRound = state.round;
    return;
  }
  if (abilityId === "monster-power") {
    const amount = isRecord(payload) && Number.isInteger(payload.amount) ? Number(payload.amount) : NaN;
    const max = Number(skill.variableManaPowerBonusMax ?? 12);
    const targetPlayerId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
    const target = targetPlayerId ? state.players[targetPlayerId] : undefined;
    if (!Number.isInteger(amount) || amount < 0 || amount > max) throw new Error("ANDERSEN_POWER_AMOUNT_INVALID");
    if (!target || target.eliminated) throw new Error("ANDERSEN_POWER_TARGET_INVALID");
    payManaCost(state, player, amount, definitions);
    target.flags.roundPowerBonus = Number(target.flags.roundPowerBonus ?? 0) + amount;
    return;
  }
  throw new Error("ANDERSEN_INNOCENT_ABILITY_INVALID");
};

export const isAndersenInnocentMonsterLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player || !findActiveOwnedSkillAttack(state, playerId, skill.id)) return false;
  if (ability?.id === "innocent-mark") return player.mana >= Number(ability.abilityCost ?? 0)
    && Object.values(state.players).some((target) => target.id !== playerId && !target.eliminated);
  if (ability?.id === "monster-power") return Object.values(state.players).some((target) => !target.eliminated);
  return false;
};

function clearAndersenInnocentMonsterMark(player: GameState["players"][string]): void {
  delete player.flags.andersenInnocentMonsterTargetPlayerId;
  delete player.flags.andersenInnocentMonsterRound;
}


export const useOkitaHaori: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "phase.transitioned") {
    const count = Number(skill.combatStartDrawCount ?? 1);
    if (Number.isInteger(count) && count > 0) {
      const random = new StateRandom();
      drawCards(state, player.id, count, (maxExclusive) => random.integer(state, maxExclusive), definitions);
    }
    delete player.flags.okitaHaoriCombatDrawPending;
    return;
  }
  if (eventType === "round.ended") {
    clearOkitaHaoriFlags(player);
    return;
  }
  if (skill.revealHandUntilRoundEnd !== true) throw new Error("OKITA_HAORI_RULE_INVALID");
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + Number(skill.combatPowerBonus ?? 3);
  player.flags.handRevealedUntilRound = state.round;
  player.flags.okitaHaoriRound = state.round;
  player.flags.okitaHaoriCombatDrawPending = true;
};

export const isOkitaHaoriLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  return Boolean(player && player.flags.okitaHaoriRound !== state.round);
};

function clearOkitaHaoriFlags(player: GameState["players"][string]): void {
  delete player.flags.handRevealedUntilRound;
  delete player.flags.okitaHaoriRound;
  delete player.flags.okitaHaoriCombatDrawPending;
}


export const useRevealHandPowerBonus: SkillHandler = ({ state, player, skill, definitions }) => {
  if (!definitions) throw new Error("REVEAL_HAND_POWER_CONTEXT_REQUIRED");
  const rule = skill.revealHandPowerBonus;
  if (!rule || !Number.isInteger(rule.minBasePower) || !Number.isInteger(rule.perCard) || !Number.isInteger(rule.max)) {
    throw new Error("REVEAL_HAND_POWER_RULE_INVALID");
  }
  player.flags.handRevealedRevision = state.revision;
  const matching = player.hand.filter((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(definition && definition.basePower >= rule.minBasePower);
  }).length;
  const bonus = Math.min(rule.max, matching * rule.perCard);
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + bonus;
};

export const isRevealHandPowerBonusLegal: SkillLegalityPredicate = (state, playerId, skill) => Boolean(findActiveOwnedSkillAttack(state, playerId, skill.id));


export const useGawainGalatine: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "card.played") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
    if (event.playerId === player.id && event.definitionId === skill.id) player.flags.gawainGalatinePlayed = true;
    return;
  }
  if (eventType === "round.ended") {
    if (skill.roundEndLoseAllManaUnlessPlayedSelf !== false && player.flags.gawainGalatinePlayed !== true) {
      setMana(player, 0);
    }
    delete player.flags.gawainGalatineRound;
    delete player.flags.gawainGalatinePlayed;
    return;
  }
  if (skill.requiresBattlefieldLocation === true && player.locationId !== "mountain" && player.locationId !== "city") {
    throw new Error("GAWAIN_GALATINE_LOCATION_INVALID");
  }
  gainMana(player, Number(skill.manaGain ?? 3));
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + Number(skill.combatPowerBonus ?? 3);
  player.flags.gawainGalatineRound = state.round;
  player.flags.gawainGalatinePlayed = false;
};

export const isGawainGalatineLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player) return false;
  if (skill.requiresBattlefieldLocation === true && player.locationId !== "mountain" && player.locationId !== "city") return false;
  return player.flags.gawainGalatineRound !== state.round;
};

function getGawainChallengeAttributes(state: GameState, definitions: Record<string, CardDefinition> | undefined, eventId: string): string[] {
  const definition = definitions?.[eventId] as (CardDefinition & { mentionedAttributes?: string[] }) | undefined;
  const printed = Array.isArray(definition?.mentionedAttributes) ? definition.mentionedAttributes : [];
  return replaceNamedAttributesForColor(state, eventId, printed);
}

function getGawainChallengeHandCandidates(
  state: GameState,
  playerId: string,
  eventId: string,
  definitions: Record<string, CardDefinition> | undefined,
): string[] {
  if (!definitions) return [];
  const attributes = new Set(getGawainChallengeAttributes(state, definitions, eventId));
  if (attributes.size === 0) return [];
  const player = state.players[playerId];
  if (!player) return [];
  return player.hand.filter((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    return Boolean(definition && getCardAttributes(definition).some((attribute) => attributes.has(attribute)));
  });
}

function isCurrentVisibleEvent(state: GameState, eventId: string): boolean {
  return state.board.eventVisibility[eventId] === "up"
    && (state.board.currentEvents.mountain.includes(eventId) || state.board.currentEvents.city.includes(eventId));
}

function hasActiveGawainSaintNumberSource(
  state: GameState,
  playerId: string,
  skillId: string,
  definitions: Record<string, CardDefinition> | undefined,
): boolean {
  const player = state.players[playerId];
  if (!player) return false;
  return player.attack.some((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = instance && definitions ? definitions[instance.definitionId] : undefined;
    return Boolean(instance?.active && instance.face === "up"
      && (instance.definitionId === skillId || definition?.linkedSkillId === skillId));
  });
}


export const useGawainSaintNumber: SkillHandler = ({ state, player, skill, payload, openDecision, definitions, emitEvent }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "event.revealed") {
    if (!definitions || !hasActiveGawainSaintNumberSource(state, player.id, skill.id, definitions)) return;
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
    const eventId = typeof event.eventId === "string" ? event.eventId : undefined;
    if (!eventId || !isCurrentVisibleEvent(state, eventId)) return;
    const candidates = getGawainChallengeHandCandidates(state, player.id, eventId, definitions);
    if (candidates.length === 0) return;
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:challenge:${eventId}`;
    state.effectQueue.unshift({
      effectId,
      handlerId: "core.gawain-saint-number-challenge-resolve",
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { eventId },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "gawain-saint-number-challenge",
      options: candidates.map((instanceId) => ({ instanceId, definition: definitions[state.cards[instanceId]?.definitionId ?? ""] }))
        .map(({ instanceId, definition }) => ({ id: instanceId, label: definition?.name ?? instanceId })),
      min: 1,
      max: 1,
      allowCancel: true,
      continuationEffectId: effectId,
      fallbackEffectId: effectId,
      submissions: {},
    });
    return;
  }

  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== "nightless-charm") throw new Error("GAWAIN_SAINT_NUMBER_ABILITY_INVALID");
  if (!definitions) throw new Error("GAWAIN_SAINT_NUMBER_DEFINITIONS_REQUIRED");
  const locationId = player.locationId;
  const challengedHere = (locationId === "mountain" || locationId === "city")
    && state.board.currentEvents[locationId].some((eventId) => Number(state.board.eventVictoryPointBonuses?.[eventId] ?? 0) > 0);
  if (!challengedHere) {
    payManaCost(state, player, 3, definitions);
    player.flags.roundManaSpent = Number(player.flags.roundManaSpent ?? 0) + 3;
  }
  const targets = player.attack.filter((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    return Boolean(instance?.active && instance.face === "up" && definition?.basePower === 3);
  });
  if (targets.length === 0) throw new Error("GAWAIN_SAINT_NUMBER_NO_BASE3_ATTACKS");
  for (const instanceId of targets) {
    const instance = state.cards[instanceId];
    const modifierId = `${skill.id}:nightless-charm:${state.round}:${instanceId}`;
    instance.powerModifiers = [
      ...(instance.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
      { id: modifierId, sourceId: skill.id, kind: "add", value: 6, duration: "round" },
    ];
  }
  emitEvent?.("gawain.nightless-charm.applied", { playerId: player.id, instanceIds: targets, paidMana: challengedHere ? 0 : 3 });
};

export const resolveGawainSaintNumberChallenge: SkillHandler = ({ state, player, skill, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload)) return;
  const previous = isRecord(payload.previous) ? payload.previous : payload;
  const eventId = typeof previous.eventId === "string" ? previous.eventId : undefined;
  const decision = isRecord(payload.decision) ? payload.decision : undefined;
  if (!eventId || !decision || decision.status === "cancelled") return;
  if (!isCurrentVisibleEvent(state, eventId)) return;
  const submissions = isRecord(decision.submissions) ? decision.submissions : {};
  const selected = submissions[player.id];
  const instanceId = Array.isArray(selected) && typeof selected[0] === "string" ? selected[0] : undefined;
  if (!instanceId || !player.hand.includes(instanceId)) throw new Error("GAWAIN_CHALLENGE_SELECTION_INVALID");
  if (!getGawainChallengeHandCandidates(state, player.id, eventId, definitions).includes(instanceId)) {
    throw new Error("GAWAIN_CHALLENGE_SELECTION_INVALID");
  }
  movePlayerCard(state, player.id, instanceId, "discard");
  addEventVictoryPointBonus(state, eventId, 3);
  emitEvent?.("event.challenged", { playerId: player.id, eventId, discardedInstanceId: instanceId, victoryPointBonus: 3, sourceId: skill.id });
};

export const isGawainSaintNumberLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !definitions || ability?.id !== "nightless-charm") return false;
  if (!hasActiveGawainSaintNumberSource(state, playerId, skill.id, definitions)) return false;
  const hasBaseThree = player.attack.some((instanceId) => {
    const instance = state.cards[instanceId];
    const definition = instance ? definitions[instance.definitionId] : undefined;
    return Boolean(instance?.active && instance.face === "up" && definition?.basePower === 3);
  });
  if (!hasBaseThree) return false;
  const locationId = player.locationId;
  const challengedHere = (locationId === "mountain" || locationId === "city")
    && state.board.currentEvents[locationId].some((eventId) => Number(state.board.eventVictoryPointBonuses?.[eventId] ?? 0) > 0);
  if (challengedHere) return true;
  try {
    const draft = structuredClone(state) as GameState;
    payManaCost(draft, draft.players[playerId], 3, definitions);
    return true;
  } catch {
    return false;
  }
};

const ARCUEID_CRIMSON_MOON_ID = "servant.arcueid.skill.sc-arcueid-1";
const ARCUEID_CRIMSON_MOON_HANDLER = "core.arcueid-crimson-moon";
const ARCUEID_MILLENNIUM_CASTLE_ID = "servant.arcueid.skill.sc-arcueid-2";
const ARCUEID_MILLENNIUM_CASTLE_HANDLER = "core.arcueid-millennium-castle";

function isSameBattlefield(state: GameState, leftPlayerId: string, rightPlayerId: string): boolean {
  const left = state.players[leftPlayerId];
  const right = state.players[rightPlayerId];
  return Boolean(left && right
    && left.locationId === right.locationId
    && (left.locationId === "mountain" || left.locationId === "city"));
}

function isPlayerEngagedOnBattlefield(state: GameState, playerId: string): boolean {
  const player = state.players[playerId];
  const locationId = player?.locationId;
  if (!player || player.eliminated || (locationId !== "mountain" && locationId !== "city")) return false;
  return (state.board.locations[locationId] ?? []).some((id) => id !== playerId && Boolean(state.players[id]) && !state.players[id].eliminated);
}

function arcueidUnengagedOpponentIds(state: GameState, player: PlayerState): string[] {
  return state.turnOrder.filter((id) => {
    if (id === player.id) return false;
    const target = state.players[id];
    return Boolean(target && !target.eliminated && target.locationId && !isPlayerEngagedOnBattlefield(state, id));
  });
}

/** Arcueid Crimson Moon: same-batch other face-up card costs 3 less; in combat, unengaged opponents lose 1 VP then move here if legal. */
export const useArcueidCrimsonMoon: SkillHandler = ({ state, player, skill, payload, definitions, emitEvent }) => {
  if (!definitions || readSkillAbilityId(payload) !== "crimson-moon-gather" || state.phase !== "combat" || state.activePlayerId !== player.id) {
    throw new Error("ARCUEID_CRIMSON_MOON_WINDOW_INVALID");
  }
  if (!findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("ARCUEID_CRIMSON_MOON_SOURCE_NOT_ACTIVE");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("ARCUEID_CRIMSON_MOON_BATTLEFIELD_REQUIRED");
  const affected: Array<{ playerId: string; victoryPointsDelta: number; moved: boolean }> = [];
  for (const targetId of arcueidUnengagedOpponentIds(state, player)) {
    const target = state.players[targetId];
    const victoryPointsDelta = adjustVictoryPoints(target, -1);
    let moved = false;
    if (target.locationId && target.locationId !== locationId) {
      const draft = structuredClone(state) as GameState;
      try {
        movePlayerByEffect(draft, targetId, locationId, definitions);
        const movement = movePlayerByEffect(state, targetId, locationId, definitions);
        emitEvent?.("player.moved", { playerId: targetId, ...movement, method: "effect", sourceId: skill.id });
        emitEvent?.("player.entered-location", { playerId: targetId, ...movement, method: "effect", sourceId: skill.id });
        moved = true;
      } catch {
        // Score loss still resolves when another rule blocks the following movement.
      }
    }
    affected.push({ playerId: targetId, victoryPointsDelta, moved });
  }
  return { affected };
};

export const isArcueidCrimsonMoonLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "crimson-moon-gather" && state.phase === "combat" && state.activePlayerId === playerId
    && (player.locationId === "mountain" || player.locationId === "city") && findActiveOwnedSkillAttack(state, playerId, skill.id));
};

/** Arcueid Millennium Castle: engaged opponents lose 3 mana, then Arcueid leaves the board; this physical card stays locked until her next combat win. */
export const useArcueidMillenniumCastle: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (readSkillAbilityId(payload) !== "millennium-castle-exile" || state.phase !== "combat" || state.activePlayerId !== player.id) {
    throw new Error("ARCUEID_MILLENNIUM_CASTLE_WINDOW_INVALID");
  }
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("ARCUEID_MILLENNIUM_CASTLE_SOURCE_NOT_ACTIVE");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("ARCUEID_MILLENNIUM_CASTLE_BATTLEFIELD_REQUIRED");
  const opponents = sameBattlefieldOpponentIds(state, player.id, locationId);
  if (opponents.length === 0) throw new Error("ARCUEID_MILLENNIUM_CASTLE_NO_OPPONENT");
  const manaLostByPlayerId: Record<string, number> = {};
  for (const opponentId of opponents) manaLostByPlayerId[opponentId] = loseMana(state.players[opponentId], 3);
  const source = state.cards[sourceInstanceId];
  source.playBlockedUntilOwnerCombatWin = { sourceId: skill.id };
  const removed = removePlayerFromBoardByEffect(state, player.id, definitions);
  return { manaLostByPlayerId, removedFrom: removed.previousLocationId, sourceInstanceId };
};

export const isArcueidMillenniumCastleLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player || ability?.id !== "millennium-castle-exile" || state.phase !== "combat" || state.activePlayerId !== playerId) return false;
  const locationId = player.locationId;
  return Boolean((locationId === "mountain" || locationId === "city")
    && findActiveOwnedSkillAttack(state, playerId, skill.id)
    && sameBattlefieldOpponentIds(state, playerId, locationId).length > 0);
};

/** Arcueid Marble Phantasm: defeat an opponent with more VP; gain 3 VP if that opponent was not engaged with Arcueid. */
export const useArcueidMarblePhantasm: SkillHandler = ({ state, player, skill, payload, emitEvent, definitions }) => {
  const targetId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetId ? state.players[targetId] : undefined;
  if (!target || target.id === player.id || target.eliminated || target.victoryPoints <= player.victoryPoints) {
    throw new Error("ARCUEID_TARGET_INVALID");
  }
  const engaged = isSameBattlefield(state, player.id, target.id);
  if (!definitions) throw new Error("ARCUEID_MARBLE_DEFINITIONS_REQUIRED");
  defeatPlayerByEffect(state, target.id, player.id, definitions, emitEvent, { reason: "effect", sourceSkillId: skill.id });
  if (!engaged) gainVictoryPoints(player, 3);
};

export const isArcueidMarblePhantasmLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  return Boolean(player && Object.values(state.players).some((target) => target.id !== playerId
    && !target.eliminated
    && target.victoryPoints > player.victoryPoints));
};

export const useSionPresenceConcealmentEx: SkillHandler = ({ state, player, skill, payload }) => {
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (event) {
    const instanceIds = player.attack.filter((instanceId) => {
      const card = state.cards[instanceId];
      return card?.definitionId === skill.id && card.active && card.face === "up";
    });
    for (const instanceId of instanceIds) {
      const card = state.cards[instanceId];
      movePlayerCard(state, player.id, instanceId, "removed");
      card.face = "down";
      card.active = false;
      card.residual = false;
    }
    return;
  }
  const targetId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetId ? state.players[targetId] : undefined;
  if (!target || target.eliminated || !isSameBattlefield(state, player.id, target.id)) throw new Error("SION_PRESENCE_TARGET_INVALID");
  target.defeated = true;
};

export const isSionPresenceConcealmentExLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  if (!player || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return state.board.locations[player.locationId].some((id) => id !== playerId && !state.players[id]?.eliminated);
};

const DANZOU_MECHANICAL_ID = "servant.danzou.skill.sc-danzou-1";
const DANZOU_SYNTHETIC_ID = "servant.danzou.skill.sc-danzou-2";
const DANZOU_MECHANICAL_HANDLER = "core.danzou-mechanical-illusion";
const DANZOU_SYNTHETIC_HANDLER = "core.danzou-synthetic-limbs";
const DANZOU_MECHANICAL_RESOLVE = "core.danzou-mechanical-illusion-resolve";
const DANZOU_SYNTHETIC_RESOLVE = "core.danzou-synthetic-limbs-resolve";

function danzouVacuumEligibleTargetIds(
  state: GameState,
  player: PlayerState,
  definitions: Record<string, CardDefinition>,
): string[] {
  if (Number(player.flags.danzouVacuumRound ?? -1) !== state.round) return [];
  const threshold = Number(player.flags.danzouVacuumBasePowerSum ?? 0);
  const locationId = player.locationId;
  if ((locationId !== "mountain" && locationId !== "city") || !Number.isFinite(threshold) || threshold < 0) return [];
  return (state.board.locations[locationId] ?? []).filter((targetPlayerId) => {
    if (targetPlayerId === player.id) return false;
    const target = state.players[targetPlayerId];
    if (!target || target.eliminated || target.defeated) return false;
    return !target.attack.some((instanceId) => {
      const instance = state.cards[instanceId];
      if (!instance?.active || instance.face !== "up") return false;
      return calculateCombatCardPower(state, target, instanceId, definitions, locationId) > threshold;
    });
  });
}

const resolveDanzouMechanicalIllusion: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) {
    throw new Error("DANZOU_MECHANICAL_DECISION_INVALID");
  }
  const previous = payload.previous;
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections)) throw new Error("DANZOU_MECHANICAL_DECISION_INVALID");
  const selections = decision.selections.filter((id): id is string => typeof id === "string");
  if (selections.length !== decision.selections.length || new Set(selections).size !== selections.length) throw new Error("DANZOU_MECHANICAL_DECISION_INVALID");
  if (previous.stage === "vacuum-discard") {
    const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
    const sourceInstanceId = typeof previous.sourceInstanceId === "string" ? previous.sourceInstanceId : undefined;
    if (Number(previous.round) !== state.round || !sourceInstanceId || !findActiveOwnedSkillAttack(state, player.id, DANZOU_MECHANICAL_ID)
      || selections.length > 5 || selections.some((instanceId) => !candidates.includes(instanceId) || !player.hand.includes(instanceId))) {
      throw new Error("DANZOU_VACUUM_DISCARD_INVALID");
    }
    let basePowerSum = 0;
    for (const instanceId of selections) {
      const instance = state.cards[instanceId];
      const definition = definitions[instance.definitionId];
      if (!definition) throw new Error("DANZOU_VACUUM_CARD_DEFINITION_REQUIRED");
      basePowerSum += getPrintedCardBasePower(state, player, definition);
      movePlayerCard(state, player.id, instanceId, "discard");
      instance.face = "up";
      instance.active = false;
    }
    player.flags.danzouVacuumRound = state.round;
    player.flags.danzouVacuumBasePowerSum = basePowerSum;
    return { discardedInstanceIds: selections, basePowerSum };
  }
  if (previous.stage !== "vacuum-defeat" || selections.length !== 1 || Number(previous.round) !== state.round) {
    throw new Error("DANZOU_VACUUM_DEFEAT_DECISION_INVALID");
  }
  const targetPlayerId = selections[0];
  if (!danzouVacuumEligibleTargetIds(state, player, definitions).includes(targetPlayerId)) throw new Error("DANZOU_VACUUM_TARGET_INVALID");
  const defeated = defeatPlayerByEffect(state, targetPlayerId, player.id, definitions, emitEvent, { sourceId: DANZOU_MECHANICAL_ID, method: "vacuum-blade" });
  return { targetPlayerId, defeated };
};

export const useDanzouMechanicalIllusion: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("DANZOU_MECHANICAL_DEFINITIONS_REQUIRED");
  const abilityId = readSkillAbilityId(payload);
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("DANZOU_MECHANICAL_SOURCE_NOT_ACTIVE");
  if (abilityId === "vacuum-blade-discard") {
    if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("DANZOU_VACUUM_ACTION_WINDOW_INVALID");
    const candidates = [...player.hand];
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:vacuum-discard`;
    state.effectQueue.unshift({
      effectId,
      handlerId: DANZOU_MECHANICAL_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "vacuum-discard", candidates, sourceInstanceId, round: state.round },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "danzou-vacuum-discard",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId]?.definitionId ?? ""]?.name ?? instanceId })),
      min: 0,
      max: Math.min(5, candidates.length),
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  if (abilityId !== "vacuum-blade-defeat" || state.phase !== "combat" || state.activePlayerId !== player.id) {
    throw new Error("DANZOU_VACUUM_COMBAT_WINDOW_INVALID");
  }
  const candidates = danzouVacuumEligibleTargetIds(state, player, definitions);
  if (candidates.length === 0) throw new Error("DANZOU_VACUUM_NO_TARGET");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:vacuum-defeat`;
  state.effectQueue.unshift({
    effectId,
    handlerId: DANZOU_MECHANICAL_RESOLVE,
    sourceId: skill.id,
    controllerPlayerId: player.id,
    payload: { stage: "vacuum-defeat", round: state.round },
    createdAtRevision: state.revision,
  });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "danzou-vacuum-target",
    options: candidates.map((playerId) => ({ id: playerId, label: state.players[playerId]?.name ?? playerId })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isDanzouMechanicalIllusionLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  if (!definitions || !ability) return false;
  const player = state.players[playerId];
  if (!player || !findActiveOwnedSkillAttack(state, playerId, skill.id)) return false;
  if (ability.id === "vacuum-blade-discard") return state.phase === "action" && state.activePlayerId === playerId;
  return ability.id === "vacuum-blade-defeat" && state.phase === "combat" && state.activePlayerId === playerId
    && danzouVacuumEligibleTargetIds(state, player, definitions).length > 0;
};

const resolveDanzouSyntheticLimbs: SkillHandler = ({ state, player, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("DANZOU_SYNTHETIC_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  if (previous.stage !== "overclock-append" || Number(previous.round) !== state.round || decision.status !== "resolved" || !Array.isArray(decision.selections)) {
    throw new Error("DANZOU_OVERCLOCK_DECISION_INVALID");
  }
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selections = decision.selections.filter((id): id is string => typeof id === "string");
  if (selections.length !== decision.selections.length || new Set(selections).size !== selections.length
    || selections.some((instanceId) => !candidates.includes(instanceId) || !player.servantSkills.includes(instanceId))) {
    throw new Error("DANZOU_OVERCLOCK_SELECTION_INVALID");
  }
  let paidMana = 0;
  const played: string[] = [];
  for (const instanceId of selections) {
    const result = addCardToAttack(state, player.id, instanceId, definitions, {
      payCost: true,
      bypassSkillEightMana: true,
      allowedSourceZones: ["servant-skills"],
      bypassFaceUpPlayLimit: true,
      bypassTiming: true,
    });
    paidMana += result.paidMana;
    const definition = definitions[state.cards[instanceId].definitionId];
    emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: definition.id, face: "up", paidMana: result.paidMana, attributes: getCardAttributes(definition), method: "danzou-overclock" });
    emitEvent?.("card.used", { playerId: player.id, instanceId, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "danzou-overclock" });
    played.push(instanceId);
  }
  return { playedInstanceIds: played, paidMana };
};

export const useDanzouSyntheticLimbs: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, randomInt }) => {
  if (!definitions) throw new Error("DANZOU_SYNTHETIC_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType === "combat.resolved") {
    if (Number(player.flags.danzouTacticalReconstructionRound ?? -1) !== state.round) return;
    delete player.flags.danzouTacticalReconstructionRound;
    const winnerIds = Array.isArray(event?.winnerIds) ? event.winnerIds.filter((id): id is string => typeof id === "string") : [];
    if (!winnerIds.includes(player.id)) return { won: false };
    player.trueNameRevealed = false;
    const drawn = drawCards(state, player.id, 4, randomInt ?? ((maxExclusive) => new StateRandom().integer(state, maxExclusive)), definitions);
    return { won: true, drawnInstanceIds: drawn };
  }
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === "overclock") {
    if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("DANZOU_OVERCLOCK_WINDOW_INVALID");
    const originallyHidden = !player.trueNameRevealed;
    if (!originallyHidden) return { originallyHidden: false, playedInstanceIds: [] };
    const candidates = player.servantSkills.filter((instanceId) => {
      const instance = state.cards[instanceId];
      const definition = instance ? definitions[instance.definitionId] : undefined;
      return Boolean(instance && definition && definition.ownerDefinitionId === skill.ownerId && definition.isSkill === true);
    });
    if (candidates.length === 0) return { originallyHidden: true, playedInstanceIds: [] };
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:overclock-append`;
    state.effectQueue.unshift({
      effectId,
      handlerId: DANZOU_SYNTHETIC_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { stage: "overclock-append", candidates, round: state.round },
      createdAtRevision: state.revision,
    });
    openDecision({
      decisionId: `${effectId}:decision`,
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "danzou-overclock-append",
      options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId].definitionId]?.name ?? instanceId })),
      min: 0,
      max: candidates.length,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  if (abilityId !== "tactical-reconstruction" || state.phase !== "combat" || state.activePlayerId !== player.id
    || !findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("DANZOU_TACTICAL_RECONSTRUCTION_FORBIDDEN");
  player.flags.danzouTacticalReconstructionRound = state.round;
  return { armed: true };
};

export const isDanzouSyntheticLimbsLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player || !ability || state.activePlayerId !== playerId) return false;
  if (ability.id === "overclock") return state.phase === "action";
  return ability.id === "tactical-reconstruction" && state.phase === "combat"
    && (player.locationId === "mountain" || player.locationId === "city")
    && Boolean(findActiveOwnedSkillAttack(state, playerId, skill.id));
};

const CU_ALTER_PASSIVE_ID = "servant.cu-alter.skill.sc-cu-alter-1";
const CU_ALTER_PERMANENT_ID = "servant.cu-alter.skill.sc-cu-alter-2";
const CU_ALTER_PASSIVE_HANDLER = "core.cu-alter-curruid-passive";
const CU_ALTER_PERMANENT_HANDLER = "core.cu-alter-curruid-permanent";

/** Curruid passive: after combat, engaged opponents lose VP based on active attacks. */
export const useCuAlterCurruidPassive: SkillHandler = ({ state, player, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType !== "combat.ending" || !event) throw new Error("CU_ALTER_CURRUID_PASSIVE_TRIGGER_INVALID");
  const previousLocations = isRecord(event.previousLocations) ? event.previousLocations : {};
  const locationId = previousLocations[player.id];
  if (locationId !== "mountain" && locationId !== "city") return;
  for (const [targetPlayerId, previousLocationId] of Object.entries(previousLocations)) {
    if (targetPlayerId === player.id || previousLocationId !== locationId) continue;
    const target = state.players[targetPlayerId];
    if (!target || target.eliminated) continue;
    const activeAttackCount = target.attack.filter((instanceId) => {
      const card = state.cards[instanceId];
      return Boolean(card?.zone === "attack" && card.face === "up" && card.active);
    }).length;
    const loss = Math.min(3, Math.max(0, activeAttackCount - 1));
    if (loss > 0) adjustVictoryPoints(target, -loss);
  }
};

function activeCuAlterPermanent(state: GameState, player: PlayerState): GameState["cards"][string] | undefined {
  return player.attack
    .map((instanceId) => state.cards[instanceId])
    .find((card) => card?.definitionId === CU_ALTER_PERMANENT_ID && card.ownerPlayerId === player.id
      && card.zone === "attack" && card.face === "up" && card.active);
}

/** Curruid permanent: action +3 total power; after combat remove every owned Curruid card. */
export const useCuAlterCurruidPermanent: SkillHandler = ({ state, player, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "combat.ending") {
    if (!activeCuAlterPermanent(state, player)) return;
    const curruidDefinitionIds = new Set([CU_ALTER_PASSIVE_ID, CU_ALTER_PERMANENT_ID]);
    for (const instanceId of [...new Set([
      ...player.masterSkills,
      ...player.servantSkills,
      ...player.hand,
      ...player.deck,
      ...player.discard,
      ...player.attack,
    ])]) {
      const card = state.cards[instanceId];
      if (!card || card.ownerPlayerId !== player.id || !curruidDefinitionIds.has(card.definitionId)) continue;
      movePlayerCard(state, player.id, instanceId, "removed");
      card.face = "down";
      card.active = false;
      card.residual = false;
    }
    return;
  }
  const abilityId = readSkillAbilityId(payload);
  if (abilityId !== "curruid-power" || state.phase !== "action" || state.activePlayerId !== player.id || !activeCuAlterPermanent(state, player)) {
    throw new Error("CU_ALTER_CURRUID_PERMANENT_FORBIDDEN");
  }
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + 3;
};

export const isCuAlterCurruidPermanentLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  return Boolean(player && ability?.id === "curruid-power" && state.phase === "action" && state.activePlayerId === playerId
    && activeCuAlterPermanent(state, player));
};


export const useCuAlterGaeBolg: SkillHandler = ({ state, player, payload }) => {
  const targetId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  const target = targetId ? state.players[targetId] : undefined;
  if (!target || target.eliminated || !isSameBattlefield(state, player.id, target.id)) throw new Error("CU_ALTER_GAE_BOLG_TARGET_INVALID");
  target.victoryPoints = Math.max(0, target.victoryPoints - 3);
  if (target.victoryPoints > player.victoryPoints) {
    gainVictoryPoints(player, 2);
    player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + 3;
  }
};

export const isCuAlterGaeBolgLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  if (!player || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return state.board.locations[player.locationId].some((id) => id !== playerId && !state.players[id]?.eliminated);
};


export const useKarnaNextRoundDefeat: SkillHandler = ({ state, player, skill, payload }) => {
  const scheduled = isRecord(payload) && isRecord(payload.scheduled) ? payload.scheduled : undefined;
  if (scheduled) {
    const targetIds = Array.isArray(scheduled.targetPlayerIds) ? scheduled.targetPlayerIds : [];
    for (const targetId of targetIds) {
      if (typeof targetId !== "string") continue;
      const target = state.players[targetId];
      if (target && !target.eliminated) target.defeated = true;
    }
    return;
  }

  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (!event) {
    player.flags.karnaNextRoundDefeatRound = state.round;
    return;
  }

  try {
    const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds.filter((id): id is string => typeof id === "string") : [];
    const powers = isRecord(event.powers) ? event.powers : {};
    if (!winnerIds.includes(player.id)) return;
    const targetPlayerIds = Object.keys(powers).filter((targetId) => targetId !== player.id
      && !winnerIds.includes(targetId)
      && !state.players[targetId]?.eliminated);
    if (targetPlayerIds.length === 0) return;
    scheduleEffect(state, {
      scheduleId: `${skill.id}:next-round-defeat:${state.round}:${player.id}`,
      sourceId: skill.id,
      handlerId: "core.karna-next-round-defeat",
      controllerPlayerId: player.id,
      payload: { targetPlayerIds },
      triggerEventType: "round.started",
      triggerRound: state.round + 1,
      expiresAfterRound: state.round + 1,
      once: true,
    });
  } finally {
    delete player.flags.karnaNextRoundDefeatRound;
  }
};


export const useEmiyaFakeSpiralSword: SkillHandler = ({ state, player, skill, payload }) => {
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (event) {
    try {
      const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds : [];
      if (winnerIds.includes(player.id)) gainVictoryPoints(player, 4);
    } finally {
      delete player.flags.emiyaFakeSpiralRewardRound;
    }
    return;
  }

  if (player.flags.emiyaFakeSpiralSwordUsed === true) throw new Error("EMIYA_FAKE_SPIRAL_ALREADY_USED");
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId === "fake-spiral-triple-advantage") {
    const bonus = Number(player.flags.deploymentBonus ?? 0);
    if (player.flags.deploymentBonusActive !== true || !Number.isInteger(bonus) || bonus <= 0) {
      throw new Error("EMIYA_FAKE_SPIRAL_ADVANTAGE_UNAVAILABLE");
    }
    player.flags.deploymentBonus = bonus * 3;
    player.flags.emiyaFakeSpiralSwordUsed = true;
    return;
  }
  if (abilityId === "fake-spiral-victory-reward") {
    const active = player.attack.some((instanceId) => {
      const card = state.cards[instanceId];
      return card?.definitionId === skill.id && card.active && card.face === "up";
    });
    if (!active) throw new Error("EMIYA_FAKE_SPIRAL_CARD_MISSING");
    player.flags.emiyaFakeSpiralRewardRound = state.round;
    player.flags.emiyaFakeSpiralSwordUsed = true;
    return;
  }
  throw new Error("EMIYA_FAKE_SPIRAL_ABILITY_REQUIRED");
};

export const isEmiyaFakeSpiralSwordLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player || player.flags.emiyaFakeSpiralSwordUsed === true) return false;
  if (ability?.id === "fake-spiral-triple-advantage") {
    return player.flags.deploymentBonusActive === true && Number(player.flags.deploymentBonus ?? 0) > 0;
  }
  if (ability?.id === "fake-spiral-victory-reward") {
    return player.attack.some((instanceId) => {
      const card = state.cards[instanceId];
      return card?.definitionId === skill.id && card.active && card.face === "up";
    });
  }
  return false;
};

function hasActiveSkillSource(state: GameState, player: GameState["players"][string], skillId: string): boolean {
  return player.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    return (card?.definitionId === skillId || card?.definitionId === `card.skill.${skillId}`)
      && card.active
      && card.face === "up";
  });
}


export const useSionIndependentActionEx: SkillHandler = ({ state, player, skill, payload }) => {
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (event) {
    try {
      const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds : [];
      if (winnerIds.includes(player.id)) gainVictoryPoints(player, 2);
      else player.victoryPoints = Math.max(0, player.victoryPoints - 3);
    } finally {
      delete player.flags.sionIndependentActionExRound;
    }
    return;
  }

  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId === "sion-ex-remote-control") {
    const bonus = Number(player.flags.deploymentBonus ?? 0);
    if (player.flags.deploymentBonusActive !== true || !Number.isInteger(bonus) || bonus <= 0) {
      throw new Error("SION_EX_ADVANTAGE_UNAVAILABLE");
    }
    player.flags.deploymentBonus = bonus * 2;
    return;
  }
  if (abilityId === "sion-ex-combat-result") {
    const active = player.attack.some((instanceId) => {
      const card = state.cards[instanceId];
      return card?.definitionId === skill.id && card.active && card.face === "up";
    });
    if (!active) throw new Error("SION_EX_CARD_MISSING");
    player.flags.sionIndependentActionExRound = state.round;
    return;
  }
  throw new Error("SION_EX_ABILITY_REQUIRED");
};

export const isSionIndependentActionExLegal: SkillLegalityPredicate = (state, playerId, skill, ability) => {
  const player = state.players[playerId];
  if (!player) return false;
  if (ability?.id === "sion-ex-remote-control") {
    return player.flags.deploymentBonusActive === true && Number(player.flags.deploymentBonus ?? 0) > 0;
  }
  if (ability?.id === "sion-ex-combat-result") {
    return player.attack.some((instanceId) => {
      const card = state.cards[instanceId];
      return card?.definitionId === skill.id && card.active && card.face === "up";
    });
  }
  return false;
};


export const useSionTerritoryExpansionEx: SkillHandler = ({ state, player, skill, payload }) => {
  if (!hasActiveSkillSource(state, player, skill.id)) return;
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType === "player.deployed") {
    if (event.playerId !== player.id || event.locationId !== "workshop") return;
    const amount = Number(player.flags.sionTerritoryExpansionX ?? 0);
    if (!Number.isInteger(amount) || amount < 0) throw new Error("SION_TERRITORY_EXPANSION_VALUE_INVALID");
    if (amount > 0) {
      gainMana(player, amount);
      gainVictoryPoints(player, amount);
      player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + amount;
    }
    return;
  }
  if (eventType === "combat.resolved") {
    const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds : [];
    if (winnerIds.includes(player.id)) {
      player.flags.sionTerritoryExpansionX = Number(player.flags.sionTerritoryExpansionX ?? 0) + 1;
    }
  }
};


export const useChaosShadowTrap: SkillHandler = ({ state, player, skill, payload }) => {
  if (!hasActiveSkillSource(state, player, skill.id)) return;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  const targetPlayerId = typeof event.playerId === "string" ? event.playerId : undefined;
  const locationId = typeof event.locationId === "string" ? event.locationId : undefined;
  if (!targetPlayerId || targetPlayerId === player.id || locationId !== player.locationId) return;
  const target = state.players[targetPlayerId];
  if (!target || target.eliminated) return;
  target.flags.roundPowerBonus = Number(target.flags.roundPowerBonus ?? 0) - 5;
};


export const useRyuunosukeBlasphemer: SkillHandler = ({ state, player, payload, definitions }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "phase.transitioned") {
    if (player.flags.ryuunosukeBlasphemerRound !== state.round) return;
    const locationId = String(player.flags.ryuunosukeBlasphemerLocationId ?? "");
    const x = Number(player.flags.ryuunosukeBlasphemerX ?? 0);
    if ((locationId !== "mountain" && locationId !== "city") || !Number.isInteger(x) || x <= 0) {
      throw new Error("RYUUNOSUKE_BLASPHEMER_STATE_INVALID");
    }
    for (const targetId of state.board.locations[locationId] ?? []) {
      if (targetId === player.id) continue;
      const target = state.players[targetId];
      if (!target || target.eliminated) continue;
      target.flags.deploymentBonusActive = false;
      target.flags.deploymentBonus = 0;
      target.victoryPoints = Math.max(0, target.victoryPoints - x);
      target.flags.roundPowerBonus = Number(target.flags.roundPowerBonus ?? 0) - (2 * x);
    }
    delete player.flags.ryuunosukeBlasphemerRound;
    delete player.flags.ryuunosukeBlasphemerLocationId;
    delete player.flags.ryuunosukeBlasphemerX;
    return;
  }

  if (!definitions) throw new Error("RYUUNOSUKE_BLASPHEMER_CONTEXT_REQUIRED");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("RYUUNOSUKE_BLASPHEMER_NOT_IN_BATTLEFIELD");
  const x = isRecord(payload) && Number.isInteger(payload.x) ? Number(payload.x) : 0;
  if (x <= 0) throw new Error("RYUUNOSUKE_BLASPHEMER_X_INVALID");
  payManaCost(state, player, 2 * x, definitions);
  const eventId = state.board.currentEvents[locationId]
    .find((candidateId) => definitions[candidateId]?.victoryPoints === x);
  if (!eventId) throw new Error("RYUUNOSUKE_BLASPHEMER_EVENT_NOT_FOUND");
  removeEventFromLocation(state, locationId, eventId);
  player.flags.ryuunosukeBlasphemerRound = state.round;
  player.flags.ryuunosukeBlasphemerLocationId = locationId;
  player.flags.ryuunosukeBlasphemerX = x;
};

export const isRyuunosukeBlasphemerLegal: SkillLegalityPredicate = (state, playerId, _skill, _ability, definitions) => {
  const player = state.players[playerId];
  if (!player || state.phase !== "action" || state.activePlayerId !== playerId) return false;
  if (player.locationId !== "mountain" && player.locationId !== "city") return false;
  if (!definitions) return false;
  return state.board.currentEvents[player.locationId].some((eventId) => Number.isInteger(definitions[eventId]?.victoryPoints)
    && definitions[eventId].victoryPoints > 0
    && player.mana >= definitions[eventId].victoryPoints * 2);
};


export const useLeonardoFinalJudgment: SkillHandler = ({ state, player, payload }) => {
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (!event) {
    player.flags.leonardoFinalJudgmentRound = state.round;
    return;
  }
  try {
    const powers = isRecord(event.powers) ? event.powers : {};
    const ownPower = Number(powers[player.id]);
    if (!Number.isFinite(ownPower) || ownPower < 20) return;
    for (const [targetId, value] of Object.entries(powers)) {
      if (targetId === player.id) continue;
      const target = state.players[targetId];
      const targetPower = Number(value);
      if (!target || target.eliminated || !Number.isFinite(targetPower) || targetPower >= ownPower) continue;
      target.victoryPoints = Math.max(0, target.victoryPoints - 3);
    }
  } finally {
    delete player.flags.leonardoFinalJudgmentRound;
  }
};


export const useRocheGiantGuidance: SkillHandler = ({ state, player, skill, randomInt, definitions }) => {
  const betrayalDefinitionId = "master.roche.skill.s2";
  if (definitions && !definitions[betrayalDefinitionId]) throw new Error("ROCHE_BETRAYAL_DEFINITION_MISSING");
  gainVictoryPoints(player, 1);
  gainMana(player, 1);
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + 2;
  drawCards(state, player.id, 1, randomInt ?? (() => 0), definitions);
  const instanceId = `${player.id}:derived:${skill.id}:betrayal:${state.round}:${state.revision}`;
  const instance = createDerivedCardInstance(state, player.id, {
    instanceId,
    definitionId: betrayalDefinitionId,
    zone: "deck",
    sourceEffectId: `${skill.id}:round-${state.round}`,
  });
  const pushedIndex = player.deck.indexOf(instance.instanceId);
  if (pushedIndex >= 0) player.deck.splice(pushedIndex, 1);
  const insertIndex = randomInt ? randomInt(player.deck.length + 1) : 0;
  player.deck.splice(insertIndex, 0, instance.instanceId);
};

const ROCHE_INNOCENCE_ID = "master.roche.skill.s1";
const ROCHE_GUIDANCE_ID = "master.roche.skill.s1a";
const ROCHE_BETRAYAL_ID = "master.roche.skill.s2";
const ROCHE_ASCENSION_ID = "master.roche.skill.ascension";
const ROCHE_BETRAYAL_HANDLER = "core.roche-betrayal";
const ROCHE_BETRAYAL_RESOLVE = "core.roche-betrayal-resolve";
const ROCHE_INNOCENCE_HANDLER = "core.roche-innocence";
const ROCHE_ASCENSION_HANDLER = "core.roche-noble-sacrifice";
const ROCHE_BETRAYAL_CHAIN_MARKER = `effect-handled-draw:${ROCHE_BETRAYAL_ID}`;

function rocheBetrayalHandIds(state: GameState, player: PlayerState): string[] {
  return player.hand.filter((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === ROCHE_BETRAYAL_ID || card?.definitionId === `card.skill.${ROCHE_BETRAYAL_ID}`;
  });
}

/** Innocence keeps Roche's hand public. Draw timing is handled generically by the tagged physical skill. */
export const useRocheInnocence: SkillHandler = ({ player, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType !== "game.started") return;
  player.flags["public:handRevealed"] = true;
};

function openRocheBetrayalDecision(state: GameState, player: PlayerState, openDecision: SkillContext["openDecision"]): void {
  if (player.flags.rocheBetrayalConflictPending === true || player.flags.rocheNobleSacrificeActive === true) return;
  const betrayalIds = rocheBetrayalHandIds(state, player);
  if (betrayalIds.length < 3) return;
  adjustVictoryPoints(player, -6);
  player.flags.rocheBetrayalConflictPending = true;
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${ROCHE_BETRAYAL_ID}:conflict`;
  state.effectQueue.unshift({
    effectId,
    handlerId: ROCHE_BETRAYAL_RESOLVE,
    sourceId: ROCHE_BETRAYAL_ID,
    controllerPlayerId: player.id,
    payload: { betrayalIds },
    createdAtRevision: state.revision,
  });
  const options = [{ id: "decline", label: "不花费令咒" }];
  if (player.commandSeals > 0 || Number(player.flags.commandSealPaymentCredits ?? 0) > 0) options.unshift({ id: "pay", label: "花费1枚令咒" });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "roche-betrayal-conflict",
    options,
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
}

/** Betrayal: every physical draw draws once more. Chained Betrayals resolve before the unique conflict check. */
export const useRocheBetrayal: SkillHandler = ({ state, player, payload, definitions, randomInt, openDecision }) => {
  if (!definitions) throw new Error("ROCHE_BETRAYAL_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType !== "card.drawn" || event.ownerPlayerId !== player.id) return;
  const instanceId = typeof event.instanceId === "string" ? event.instanceId : undefined;
  const card = instanceId ? state.cards[instanceId] : undefined;
  if (!card || (card.definitionId !== ROCHE_BETRAYAL_ID && card.definitionId !== `card.skill.${ROCHE_BETRAYAL_ID}`)) return;
  if (card.modifiers?.includes(ROCHE_BETRAYAL_CHAIN_MARKER)) {
    card.modifiers = card.modifiers.filter((marker) => marker !== ROCHE_BETRAYAL_CHAIN_MARKER);
    return;
  }
  const random = new StateRandom();
  const choose = randomInt ?? ((maxExclusive: number) => random.integer(state, maxExclusive));
  while (true) {
    const drawnId = drawCards(state, player.id, 1, choose, definitions)[0];
    if (!drawnId) break;
    const drawn = state.cards[drawnId];
    if (drawn.definitionId !== ROCHE_BETRAYAL_ID && drawn.definitionId !== `card.skill.${ROCHE_BETRAYAL_ID}`) break;
    drawn.modifiers = [...new Set([...(drawn.modifiers ?? []), ROCHE_BETRAYAL_CHAIN_MARKER])];
  }
  openRocheBetrayalDecision(state, player, openDecision);
};

export const resolveRocheBetrayal: SkillHandler = ({ state, player, payload, definitions, randomInt, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.decision)) throw new Error("ROCHE_BETRAYAL_DECISION_INVALID");
  const decision = payload.decision;
  const selection = Array.isArray(decision.selections) ? decision.selections[0] : undefined;
  if (decision.status !== "resolved" || (selection !== "pay" && selection !== "decline")) throw new Error("ROCHE_BETRAYAL_DECISION_INVALID");
  const current = rocheBetrayalHandIds(state, player);
  if (selection === "pay") {
    payCommandSealCost(state, player.id, 1);
    for (const instanceId of current) movePlayerCard(state, player.id, instanceId, "deck");
    if (current.length > 0) shufflePlayerDeck(state, player.id, randomInt ?? ((maxExclusive) => new StateRandom().integer(state, maxExclusive)));
  } else {
    player.flags.rocheDefeatedByBetrayal = true;
    defeatPlayer(state, player.id, emitEvent, { sourceId: ROCHE_BETRAYAL_ID, method: "betrayal" });
    for (const instanceId of current) movePlayerCard(state, player.id, instanceId, "discard");
  }
  delete player.flags.rocheBetrayalConflictPending;
  return { choice: selection, betrayalInstanceIds: current };
};

/** Noble Sacrifice removes Roche's earlier package and permanently rewrites every present/future Betrayal. */
export const useRocheNobleSacrifice: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType !== "skill.unlocked" || event.playerId !== player.id || event.skillId !== skill.id) return;
  if (player.flags.rocheDefeatedByBetrayal === true) return { applied: false, reason: "betrayal-defeat" };
  const lostSeals = Math.max(0, Number(player.commandSeals ?? 0));
  player.commandSeals = 0;
  for (const oldSkillId of [ROCHE_INNOCENCE_ID, ROCHE_GUIDANCE_ID]) {
    const instance = [...player.masterSkills, ...player.attack].find((id) => {
      const card = state.cards[id];
      return card?.ownerPlayerId === player.id && card.definitionId === oldSkillId && card.zone !== "removed";
    });
    if (instance) {
      movePlayerCard(state, player.id, instance, "removed");
      state.cards[instance].active = false;
      state.cards[instance].face = "down";
    }
  }
  delete player.flags["public:handRevealed"];
  player.flags.rocheNobleSacrificeActive = true;
  player.cardRuleModifiers = (player.cardRuleModifiers ?? []).filter((modifier) => modifier.sourceId !== skill.id);
  player.cardRuleModifiers.push({
    id: `${skill.id}:betrayal`,
    sourceId: skill.id,
    targetDefinitionIds: [ROCHE_BETRAYAL_ID, `card.skill.${ROCHE_BETRAYAL_ID}`],
    grantAttributes: ["魔术"],
    powerAdd: lostSeals * 3,
    grantStandardAppend: true,
    duration: "game",
  });
  return { lostCommandSeals: lostSeals, betrayalPowerBonus: lostSeals * 3 };
};

export const useDefeatCombatParticipants: SkillHandler = ({ state, player, skill }) => {
  if (skill.defeatScope !== "all-combat-participants") throw new Error("DEFEAT_SCOPE_INVALID");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("DEFEAT_NOT_IN_BATTLE");
  const participants = (state.board.locations[locationId] ?? [])
    .filter((id) => !state.players[id]?.eliminated)
    .map((id) => state.players[id])
    .filter((candidate): candidate is NonNullable<typeof candidate> => Boolean(candidate));
  if (participants.length < 2) throw new Error("DEFEAT_REQUIRES_COMBAT");
  for (const participant of participants) participant.defeated = true;
};


export const useKiritsuguFourfoldSpeed: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions || !skill.closeActiveAndActivateHiddenDefinitionId) throw new Error("FOURFOLD_SPEED_CONTEXT_REQUIRED");
  const closeId = isRecord(payload) && typeof payload.closeInstanceId === "string" ? payload.closeInstanceId : undefined;
  const active = closeId ? state.cards[closeId] : undefined;
  if (!active || active.ownerPlayerId !== player.id || active.zone !== "attack" || !active.active || active.face !== "up") {
    throw new Error("FOURFOLD_SPEED_ACTIVE_TARGET_INVALID");
  }
  const hidden = player.attack
    .map((instanceId) => state.cards[instanceId])
    .find((card) => card?.ownerPlayerId === player.id
      && card.zone === "attack"
      && card.definitionId === skill.closeActiveAndActivateHiddenDefinitionId
      && card.face === "down"
      && !card.active);
  if (!hidden) throw new Error("FOURFOLD_SPEED_ORIGIN_BULLET_MISSING");
  closePlayerCard(state, player.id, active.instanceId, definitions);
  hidden.face = "up";
  hidden.active = true;
};

export const isKiritsuguFourfoldSpeedLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player || state.phase !== "combat" || !skill.closeActiveAndActivateHiddenDefinitionId) return false;
  const hasActive = player.attack.some((instanceId) => state.cards[instanceId]?.active && state.cards[instanceId]?.face === "up");
  const hasHidden = player.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === skill.closeActiveAndActivateHiddenDefinitionId && card.face === "down" && !card.active;
  });
  return hasActive && hasHidden;
};

const TOMOE_INFERNAL_FIRE_ABILITY = "infernal-fire";
const TOMOE_DOUBLE_ADVANTAGE_ABILITY = "double-advantage";


export const useTomoeDemonicNature: SkillHandler = ({ state, player, skill, payload }) => {
  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId === TOMOE_INFERNAL_FIRE_ABILITY) {
    if (state.phase !== "action" || state.activePlayerId !== player.id || (player.locationId !== "mountain" && player.locationId !== "city")) {
      throw new Error("TOMOE_INFERNAL_FIRE_WINDOW_INVALID");
    }
    addDeploymentAdvantageBidRule(state, {
      sourceId: skill.id,
      controllerPlayerId: player.id,
      locationId: player.locationId,
      round: state.round + 1,
      maxPayment: 5,
    });
    return;
  }
  if (abilityId === TOMOE_DOUBLE_ADVANTAGE_ABILITY) {
    if (state.phase !== "combat" || player.flags.deploymentBonusActive !== true) throw new Error("DEPLOYMENT_BONUS_NOT_AVAILABLE");
    const bonus = Number(player.flags.deploymentBonus ?? 0);
    if (!Number.isInteger(bonus) || bonus <= 0) throw new Error("DEPLOYMENT_BONUS_INVALID");
    player.flags.deploymentBonus = bonus * 2;
    return;
  }
  throw new Error("TOMOE_DEMONIC_NATURE_ABILITY_INVALID");
};

export const isTomoeDemonicNatureLegal: SkillLegalityPredicate = (state, playerId, _skill, ability) => {
  const player = state.players[playerId];
  if (!player || !ability) return false;
  if (ability.id === TOMOE_INFERNAL_FIRE_ABILITY) {
    return state.phase === "action" && state.activePlayerId === playerId && (player.locationId === "mountain" || player.locationId === "city");
  }
  if (ability.id === TOMOE_DOUBLE_ADVANTAGE_ABILITY) {
    return state.phase === "combat" && player.flags.deploymentBonusActive === true && Number(player.flags.deploymentBonus ?? 0) > 0;
  }
  return false;
};


const ARASH_CLAIRVOYANCE_ID = "servant.arash.skill.sc-arash-2";
const ARASH_CLAIRVOYANCE_HANDLER = "core.arash-clairvoyance";
const ARASH_CLAIRVOYANCE_RESOLVE = "core.arash-clairvoyance-resolve";
const ARASH_CLAIRVOYANCE_TERRAIN = "clairvoyance-double-terrain";
const ARASH_CLAIRVOYANCE_COMBAT = "clairvoyance-top-card";
const ARASH_STELLA_ID = "servant.arash.skill.sc-arash-3";

function arashClairvoyanceBasicCandidates(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): string[] {
  return player.attack.filter((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(card && card.controllerPlayerId === player.id && card.active && card.face === "up" && definition?.basic === true);
  });
}

const resolveArashClairvoyance: SkillHandler = ({ state, player, payload, definitions, randomInt }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("ARASH_CLAIRVOYANCE_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  const selection = Array.isArray(decision.selections) ? decision.selections[0] : undefined;
  if (decision.status !== "resolved" || typeof selection !== "string" || !candidates.includes(selection)) throw new Error("ARASH_CLAIRVOYANCE_DECISION_INVALID");
  if (state.phase !== "combat" || state.activePlayerId !== player.id || !findActiveOwnedSkillAttack(state, player.id, ARASH_CLAIRVOYANCE_ID)) {
    throw new Error("ARASH_CLAIRVOYANCE_WINDOW_INVALID");
  }
  if (!arashClairvoyanceBasicCandidates(state, player, definitions).includes(selection)) throw new Error("ARASH_CLAIRVOYANCE_TARGET_INVALID");
  if (player.deck.length === 0 && player.discard.length > 0) {
    player.deck = [...player.discard];
    player.discard = [];
    for (const instanceId of player.deck) state.cards[instanceId].zone = "deck";
    const random = new StateRandom();
    shufflePlayerDeck(state, player.id, randomInt ?? ((maxExclusive: number) => random.integer(state, maxExclusive)));
  }
  const topInstanceId = player.deck[0];
  if (!topInstanceId) return { selectedInstanceId: selection, discardedInstanceId: null, matched: false };
  const selectedDefinition = definitions[state.cards[selection]?.definitionId ?? ""];
  const topDefinition = definitions[state.cards[topInstanceId]?.definitionId ?? ""];
  if (!selectedDefinition || !topDefinition) throw new Error("ARASH_CLAIRVOYANCE_DEFINITION_MISSING");
  const selectedBase = getPrintedCardBasePower(state, player, selectedDefinition);
  const discardedBase = getPrintedCardBasePower(state, player, topDefinition);
  movePlayerCard(state, player.id, topInstanceId, "discard");
  const discarded = state.cards[topInstanceId];
  discarded.face = "up";
  discarded.active = false;
  const matched = selectedBase === discardedBase;
  if (matched) player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + 3;
  return { selectedInstanceId: selection, discardedInstanceId: topInstanceId, selectedBasePower: selectedBase, discardedBasePower: discardedBase, matched };
};

/** Arash Clairvoyance: action doubles current terrain; combat reveals the top-card comparison through a serializable target choice. */
export const useArashClairvoyance: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  if (!definitions) throw new Error("ARASH_CLAIRVOYANCE_DEFINITIONS_REQUIRED");
  const abilityId = readSkillAbilityId(payload);
  if (abilityId === ARASH_CLAIRVOYANCE_TERRAIN) {
    if (state.phase !== "action" || state.activePlayerId !== player.id || !findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("ARASH_CLAIRVOYANCE_TERRAIN_FORBIDDEN");
    if (player.flags.deploymentBonusActive !== true || Number(player.flags.deploymentBonus ?? 0) <= 0) throw new Error("DEPLOYMENT_BONUS_NOT_AVAILABLE");
    const bonus = Number(player.flags.deploymentBonus ?? 0);
    if (!Number.isInteger(bonus) || bonus <= 0) throw new Error("DEPLOYMENT_BONUS_INVALID");
    player.flags.deploymentBonus = bonus * 2;
    return { terrainAdvantage: player.flags.deploymentBonus };
  }
  if (abilityId !== ARASH_CLAIRVOYANCE_COMBAT || state.phase !== "combat" || state.activePlayerId !== player.id
    || !findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("ARASH_CLAIRVOYANCE_COMBAT_FORBIDDEN");
  const candidates = arashClairvoyanceBasicCandidates(state, player, definitions);
  if (candidates.length === 0) throw new Error("ARASH_CLAIRVOYANCE_NO_BASIC_ATTACK");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:top-card`;
  state.effectQueue.unshift({ effectId, handlerId: ARASH_CLAIRVOYANCE_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { candidates }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`,
    ownerPlayerId: player.id,
    chooserPlayerIds: [player.id],
    kind: "arash-clairvoyance-basic-attack",
    options: candidates.map((instanceId) => ({ id: instanceId, label: definitions[state.cards[instanceId].definitionId]?.name ?? instanceId })),
    min: 1,
    max: 1,
    allowCancel: false,
    continuationEffectId: effectId,
    submissions: {},
  });
};

export const isArashClairvoyanceLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || !definitions || !findActiveOwnedSkillAttack(state, playerId, skill.id)) return false;
  if (ability.id === ARASH_CLAIRVOYANCE_TERRAIN) return state.phase === "action" && player.flags.deploymentBonusActive === true && Number(player.flags.deploymentBonus ?? 0) > 0;
  if (ability.id === ARASH_CLAIRVOYANCE_COMBAT) return state.phase === "combat" && arashClairvoyanceBasicCandidates(state, player, definitions).length > 0;
  return false;
};

/** Stella resolves after Arash's fight: award the printed victory bonus, then remove Arash while leaving the basic deck intact. */
export const useArashStella: SkillHandler = ({ state, player, skill, payload, definitions }) => {
  if (!definitions) throw new Error("ARASH_STELLA_DEFINITIONS_REQUIRED");
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
  if (eventType !== "combat.resolved" || !event) return;
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) return;
  const powers = isRecord(event.powers) ? event.powers : {};
  if (!Object.prototype.hasOwnProperty.call(powers, player.id)) return;
  const winnerIds = Array.isArray(event.winnerIds) ? event.winnerIds.filter((id): id is string => typeof id === "string") : [];
  if (winnerIds.includes(player.id)) gainVictoryPoints(player, 6);

  const retainedSkillId = "servant.arash.skill.sc-arash-1";
  const removedSkillInstanceIds: string[] = [];
  for (const instanceId of [...player.servantSkills, ...player.attack]) {
    const card = state.cards[instanceId];
    if (!card || card.ownerPlayerId !== player.id) continue;
    const definition = definitions[card.definitionId];
    const linkedSkillId = definition?.linkedSkillId ?? card.definitionId;
    if (!linkedSkillId.startsWith("servant.arash.skill.") || linkedSkillId === retainedSkillId) continue;
    movePlayerCard(state, player.id, instanceId, "removed");
    card.face = "up";
    card.active = false;
    card.residual = false;
    removedSkillInstanceIds.push(instanceId);
  }
  player.servantId = null;
  player.flags.arashDiedRound = state.round;
  return { won: winnerIds.includes(player.id), removedSkillInstanceIds };
};

const QUETZAL_FLAME_ID = "servant.quetzalcoatl.skill.sc-quetzalcoatl-1";
const QUETZAL_FLAME_RESOLVE = "core.quetzal-flame-resolve";
const QUETZAL_SUNSTONE_ID = "servant.quetzalcoatl.skill.sc-quetzalcoatl-2";
const QUETZAL_SUNSTONE_RESOLVE = "core.quetzal-sunstone-resolve";
const QUETZAL_SUNSTONE_OUTPOST = "sunstone-outpost";
const QUETZAL_SUNSTONE_PROPHECY = "sunstone-prophecy";

function quetzalHasActiveStrengthBasic(state: GameState, player: PlayerState, definitions: Record<string, CardDefinition>): boolean {
  return player.attack.some((instanceId) => {
    const card = state.cards[instanceId];
    const definition = card ? definitions[card.definitionId] : undefined;
    return Boolean(card?.active && card.face === "up" && definition?.basic === true
      && getCardInstanceAttributes(card, definition, state, definitions).includes("力量"));
  });
}

function quetzalFlameRecord(state: GameState, playerId: string): { round: number; instanceIds: string[] } {
  const store = (state.modeState.quetzalFlamePlayedByPlayer as Record<string, { round: number; instanceIds: string[] }> | undefined) ?? {};
  const current = store[playerId]?.round === state.round ? store[playerId] : { round: state.round, instanceIds: [] };
  store[playerId] = current;
  state.modeState.quetzalFlamePlayedByPlayer = store;
  return current;
}

function applyQuetzalFlameStrengthBonus(state: GameState, player: PlayerState, skillId: string): void {
  const record = quetzalFlameRecord(state, player.id);
  for (const instanceId of record.instanceIds) {
    const card = state.cards[instanceId];
    if (!card || card.ownerPlayerId !== player.id || card.zone !== "attack") continue;
    const modifierId = `${skillId}:strength-chain:${state.round}:${instanceId}`;
    card.powerModifiers = [
      ...(card.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
      { id: modifierId, sourceId: skillId, kind: "add", value: 1, duration: "round" },
    ];
  }
}

function runQuetzalFlameStep(context: SkillContext): unknown {
  const { state, player, skill, definitions, openDecision, randomInt, emitEvent } = context;
  if (!definitions) throw new Error("QUETZAL_FLAME_DEFINITIONS_REQUIRED");
  if (state.phase !== "action" || state.activePlayerId !== player.id || !findActiveOwnedSkillAttack(state, player.id, skill.id)) throw new Error("QUETZAL_FLAME_WINDOW_INVALID");
  if (quetzalHasActiveStrengthBasic(state, player, definitions)) throw new Error("QUETZAL_FLAME_STRENGTH_BASIC_ACTIVE");
  const random = new StateRandom();
  const drawn = drawCards(state, player.id, 1, randomInt ?? ((maxExclusive: number) => random.integer(state, maxExclusive)), definitions);
  const instanceId = drawn[0];
  if (!instanceId) return { playedInstanceId: null };
  const definition = definitions[state.cards[instanceId].definitionId];
  if (!definition) throw new Error("QUETZAL_FLAME_DEFINITION_MISSING");
  const play = addCardToAttack(state, player.id, instanceId, definitions, { payCost: true, bypassFaceUpPlayLimit: true });
  emitEvent?.("card.played", { playerId: player.id, instanceId, definitionId: definition.id, face: "up", paidMana: play.paidMana, attributes: getCardAttributes(definition), method: "effect", sourceId: skill.id });
  emitEvent?.("card.used", { playerId: player.id, instanceId, definitionId: definition.id, locationId: player.locationId, attributes: getCardAttributes(definition), method: "effect", sourceId: skill.id });
  const record = quetzalFlameRecord(state, player.id);
  if (!record.instanceIds.includes(instanceId)) record.instanceIds.push(instanceId);
  const attributes = getCardInstanceAttributes(state.cards[instanceId], definition, state, definitions);
  if (attributes.includes("力量")) applyQuetzalFlameStrengthBonus(state, player, skill.id);
  if (!attributes.includes("迅捷")) return { playedInstanceId: instanceId, attributes };

  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:repeat:${record.instanceIds.length}`;
  state.effectQueue.unshift({ effectId, handlerId: QUETZAL_FLAME_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "repeat" }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "quetzal-flame-repeat",
    options: [{ id: "repeat", label: "再次执行" }, { id: "stop", label: "停止" }],
    min: 1, max: 1, allowCancel: true, continuationEffectId: effectId, submissions: {},
  });
  return { playedInstanceId: instanceId, attributes, repeatAvailable: true };
}

export const useQuetzalFlame: SkillHandler = (context) => runQuetzalFlameStep(context);

const resolveQuetzalFlameRepeat: SkillHandler = (context) => {
  const { payload } = context;
  if (!isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("QUETZAL_FLAME_DECISION_INVALID");
  const decision = payload.decision;
  if (decision.status === "cancelled") return;
  const selection = Array.isArray(decision.selections) ? decision.selections[0] : undefined;
  if (decision.status !== "resolved" || (selection !== "repeat" && selection !== "stop")) throw new Error("QUETZAL_FLAME_DECISION_INVALID");
  if (selection === "stop") return;
  return runQuetzalFlameStep({ ...context, skill: { ...context.skill, id: QUETZAL_FLAME_ID } });
};

export const isQuetzalFlameLegal: SkillLegalityPredicate = (state, playerId, skill, _ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player && definitions && state.phase === "action" && state.activePlayerId === playerId
    && findActiveOwnedSkillAttack(state, playerId, skill.id) && !quetzalHasActiveStrengthBasic(state, player, definitions));
};

function openQuetzalSunstoneBottomChoice(state: GameState, player: PlayerState, skillId: string, openDecision: SkillContext["openDecision"]): void {
  if (player.hand.length < 2) throw new Error("QUETZAL_SUNSTONE_HAND_TOO_SMALL");
  const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skillId}:bottom`;
  state.effectQueue.unshift({ effectId, handlerId: QUETZAL_SUNSTONE_RESOLVE, sourceId: skillId, controllerPlayerId: player.id, payload: { stage: "bottom-cards", candidates: [...player.hand] }, createdAtRevision: state.revision });
  openDecision({
    decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "quetzal-sunstone-bottom-cards",
    options: player.hand.map((id) => ({ id, label: id })), min: 2, max: 2, allowCancel: false, continuationEffectId: effectId, submissions: {},
  });
}

const resolveQuetzalSunstoneBottom: SkillHandler = ({ state, player, skill, payload, definitions, randomInt, openDecision }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.previous) || !isRecord(payload.decision)) throw new Error("QUETZAL_SUNSTONE_DECISION_INVALID");
  const previous = payload.previous;
  const decision = payload.decision;
  const selections = Array.isArray(decision.selections) ? decision.selections.filter((id): id is string => typeof id === "string") : [];
  if (decision.status !== "resolved") throw new Error("QUETZAL_SUNSTONE_DECISION_INVALID");
  if (previous.stage === "draw-count") {
    if (selections.length !== 1 || !/^draw-[0-2]$/.test(selections[0])) throw new Error("QUETZAL_SUNSTONE_DECISION_INVALID");
    const count = Number(selections[0].slice(5));
    const random = new StateRandom();
    drawCards(state, player.id, count, randomInt ?? ((maxExclusive: number) => random.integer(state, maxExclusive)), definitions);
    openQuetzalSunstoneBottomChoice(state, player, skill.id, openDecision);
    return;
  }
  if (previous.stage !== "bottom-cards") throw new Error("QUETZAL_SUNSTONE_DECISION_INVALID");
  const candidates = Array.isArray(previous.candidates) ? previous.candidates.filter((id): id is string => typeof id === "string") : [];
  if (selections.length !== 2 || new Set(selections).size !== 2 || selections.some((id) => !candidates.includes(id) || !player.hand.includes(id))) throw new Error("QUETZAL_SUNSTONE_DECISION_INVALID");
  for (const instanceId of selections) {
    movePlayerCard(state, player.id, instanceId, "deck");
    state.cards[instanceId].face = "down";
    state.cards[instanceId].active = false;
  }
  return { bottomInstanceIds: selections };
};

export const useQuetzalSunstone: SkillHandler = ({ state, player, skill, payload, definitions, openDecision }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "combat.resolved") {
    const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
    const winnerIds = event && Array.isArray(event.winnerIds) ? event.winnerIds : [];
    if (player.flags.quetzalSunstoneRewardRound === state.round && winnerIds.includes(player.id)) {
      gainVictoryPoints(player, 4);
      delete player.flags.quetzalSunstoneRewardRound;
    }
    return;
  }
  if (!definitions) throw new Error("QUETZAL_SUNSTONE_DEFINITIONS_REQUIRED");
  const abilityId = readSkillAbilityId(payload);
  const sourceInstanceId = findActiveOwnedSkillAttack(state, player.id, skill.id);
  if (!sourceInstanceId) throw new Error("QUETZAL_SUNSTONE_SOURCE_INACTIVE");
  if (abilityId === QUETZAL_SUNSTONE_OUTPOST) {
    if (state.phase !== "outpost" || state.activePlayerId !== player.id) throw new Error("QUETZAL_SUNSTONE_OUTPOST_FORBIDDEN");
    closePlayerCard(state, player.id, sourceInstanceId, definitions);
    player.flags.quetzalSunstoneRewardRound = state.round;
    return;
  }
  if (abilityId === QUETZAL_SUNSTONE_PROPHECY) {
    if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("QUETZAL_SUNSTONE_PROPHECY_FORBIDDEN");
    const availableDraws = Math.min(2, player.deck.length + player.discard.length);
    const counts = [0, 1, 2].filter((count) => count <= availableDraws && player.hand.length + count >= 2);
    if (counts.length === 0) throw new Error("QUETZAL_SUNSTONE_HAND_TOO_SMALL");
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:draw-count`;
    state.effectQueue.unshift({ effectId, handlerId: QUETZAL_SUNSTONE_RESOLVE, sourceId: skill.id, controllerPlayerId: player.id, payload: { stage: "draw-count" }, createdAtRevision: state.revision });
    openDecision({
      decisionId: `${effectId}:decision`, ownerPlayerId: player.id, chooserPlayerIds: [player.id], kind: "quetzal-sunstone-draw-count",
      options: counts.map((count) => ({ id: `draw-${count}`, label: `抽${count}张牌` })), min: 1, max: 1, allowCancel: false, continuationEffectId: effectId, submissions: {},
    });
    return;
  }
  throw new Error("QUETZAL_SUNSTONE_ABILITY_INVALID");
};

export const isQuetzalSunstoneLegal: SkillLegalityPredicate = (state, playerId, skill, ability, definitions) => {
  const player = state.players[playerId];
  if (!player || !ability || !definitions || !findActiveOwnedSkillAttack(state, playerId, skill.id)) return false;
  if (ability.id === QUETZAL_SUNSTONE_OUTPOST) return state.phase === "outpost";
  if (ability.id === QUETZAL_SUNSTONE_PROPHECY) return state.phase === "action" && player.hand.length + Math.min(2, player.deck.length + player.discard.length) >= 2;
  return false;
};

export const useDoubleDeploymentBonus: SkillHandler = ({ player, skill }) => {
  if (skill.doubleDeploymentBonus !== true || player.flags.deploymentBonusActive !== true) throw new Error("DEPLOYMENT_BONUS_NOT_AVAILABLE");
  const bonus = Number(player.flags.deploymentBonus ?? 0);
  if (!Number.isInteger(bonus) || bonus <= 0) throw new Error("DEPLOYMENT_BONUS_INVALID");
  player.flags.deploymentBonus = bonus * 2;
};

export const isDoubleDeploymentBonusLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  return Boolean(player && state.phase === "action" && skill.doubleDeploymentBonus === true
    && player.flags.deploymentBonusActive === true && Number(player.flags.deploymentBonus ?? 0) > 0);
};

/** Generic passive: unclaimed printed terrain spaces on the listed battlefields belong to the controller. */
export const useUnoccupiedTerrainAdvantage: SkillHandler = ({ state, player, skill, payload }) => {
  const payloadLocations = isRecord(payload) && Array.isArray(payload.locationIds)
    ? payload.locationIds.filter((id): id is "mountain" | "city" => id === "mountain" || id === "city")
    : [];
  const locationIds = skill.unoccupiedTerrainLocations ?? payloadLocations;
  if (locationIds.length === 0 || locationIds.some((id) => id !== "mountain" && id !== "city")) {
    throw new Error("UNOCCUPIED_TERRAIN_RULE_INVALID");
  }
  addUnoccupiedLocationAdvantageRule(state, {
    sourceId: skill.id,
    playerId: player.id,
    locationIds: [...locationIds],
  });
};

/** Darnic??Old Acquaintances?? mandatory Scorched Earth upkeep plus Air Support. */
export const useDarnicOldAcquaintances: SkillHandler = ({ state, player, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  if (eventType === "phase.transitioned") {
    const opponentId = state.activePlayerId;
    const locationId = player.locationId;
    if (!opponentId || opponentId === player.id || (locationId !== "mountain" && locationId !== "city")) return;
    const opponent = state.players[opponentId];
    if (!opponent || opponent.eliminated || opponent.locationId !== locationId) return;
    if (opponent.flags.deploymentBonusActive !== true || opponent.flags.deploymentLocationId !== locationId) return;
    if (!(state.board.outpostRecords[locationId] ?? []).includes(opponentId)) return;
    if (opponent.victoryPoints >= 2) {
      opponent.victoryPoints -= 2;
      return;
    }
    releaseBattlefieldAdvantages(state, opponentId, locationId);
    return;
  }

  const abilityId = isRecord(payload) && typeof payload.abilityId === "string" ? payload.abilityId : undefined;
  if (abilityId !== "air-support") throw new Error("DARNIC_OLD_ACQUAINTANCES_ABILITY_INVALID");
  if (state.phase !== "action" || state.activePlayerId !== player.id) throw new Error("DARNIC_AIR_SUPPORT_WINDOW_INVALID");
  const existing = player.flags.deploymentAdvantageMultiplierRound === state.round
    ? Number(player.flags.deploymentAdvantageMultiplier ?? 1)
    : 1;
  if (!Number.isFinite(existing) || existing < 0) throw new Error("DARNIC_AIR_SUPPORT_MULTIPLIER_INVALID");
  player.flags.deploymentAdvantageMultiplierRound = state.round;
  player.flags.deploymentAdvantageMultiplier = existing * 2;
};


export const useDefeatEngagedIfMoreAttacks: SkillHandler = ({ state, player, skill }) => {
  if (skill.defeatEngagedOpponentsIfMoreActiveAttacks !== true) throw new Error("ATTACK_COUNT_RULE_INVALID");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("ATTACK_COUNT_NOT_IN_BATTLE");
  const occupants = (state.board.locations[locationId] ?? []).filter((id) => !state.players[id]?.eliminated && !state.players[id]?.defeated);
  const opponents = occupants.filter((id) => id !== player.id).map((id) => state.players[id]);
  const ownCount = player.attack.filter((id) => state.cards[id]?.active && state.cards[id]?.face === "up").length;
  const opponentCount = opponents.reduce((sum, opponent) => sum + opponent.attack.filter((id) => state.cards[id]?.active && state.cards[id]?.face === "up").length, 0);
  if (opponents.length === 0 || ownCount <= opponentCount) throw new Error("ATTACK_COUNT_CONDITION_FALSE");
  for (const opponent of opponents) opponent.defeated = true;
};

export const isDefeatEngagedIfMoreAttacksLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player || skill.defeatEngagedOpponentsIfMoreActiveAttacks !== true || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  const opponents = (state.board.locations[player.locationId] ?? []).filter((id) => id !== playerId && !state.players[id]?.eliminated && !state.players[id]?.defeated);
  const ownCount = player.attack.filter((id) => state.cards[id]?.active && state.cards[id]?.face === "up").length;
  const opponentCount = opponents.reduce((sum, id) => sum + state.players[id].attack.filter((cardId) => state.cards[cardId]?.active && state.cards[cardId]?.face === "up").length, 0);
  return opponents.length > 0 && ownCount > opponentCount;
};


export const useManaThresholdVictoryPointLoss: SkillHandler = ({ state, player, skill }) => {
  const rule = skill.manaThresholdVictoryPointLoss;
  if (!rule) throw new Error("MANA_THRESHOLD_RULE_INVALID");
  const locationId = player.locationId;
  const opponents = new Set((locationId === "mountain" || locationId === "city") ? (state.board.locations[locationId] ?? []) : []);
  for (const target of Object.values(state.players)) {
    if (target.eliminated || target.mana < rule.threshold) continue;
    const loss = rule.amount + (target.id !== player.id && opponents.has(target.id) ? rule.opponentExtra : 0);
    target.victoryPoints = Math.max(0, target.victoryPoints - loss);
  }
};

export const isManaThresholdVictoryPointLossLegal: SkillLegalityPredicate = (state, playerId, skill) => {
  const player = state.players[playerId];
  if (!player || !skill.manaThresholdVictoryPointLoss || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return Object.values(state.players).some((target) => !target.eliminated && target.mana >= skill.manaThresholdVictoryPointLoss!.threshold);
};


export const useIbarakiRashomonGrudge: SkillHandler = ({ state, player, skill, payload, definitions, openDecision, emitEvent }) => {
  if (!skill.rashomonGrudge || skill.rashomonGrudge.powerLossScope !== "same-battlefield-opponents") throw new Error("IBARAKI_RASHOMON_RULE_INVALID");
  if (!definitions) throw new Error("IBARAKI_RASHOMON_DEFINITIONS_REQUIRED");
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("IBARAKI_RASHOMON_NOT_IN_BATTLE");
  const candidates = getIbarakiRashomonTargetIds(state, player.id, locationId, definitions);
  if (candidates.length === 0) throw new Error("IBARAKI_RASHOMON_NO_TARGET");
  const targetPlayerId = isRecord(payload) && typeof payload.targetPlayerId === "string" ? payload.targetPlayerId : undefined;
  if (!targetPlayerId) {
    const effectId = `${state.gameInstanceId}:${state.revision}:${player.id}:${skill.id}:rashomon`;
    state.effectQueue.push(createEffectFrame({
      effectId,
      handlerId: IBARAKI_RASHOMON_RESOLVE,
      sourceId: skill.id,
      controllerPlayerId: player.id,
      payload: { candidates, locationId },
      state,
    }));
    openDecision({
      decisionId: createSkillDecisionId(state, player.id, skill.id),
      ownerPlayerId: player.id,
      chooserPlayerIds: [player.id],
      kind: "ibaraki-rashomon-target",
      options: candidates.map((id) => ({ id, label: state.players[id]?.name ?? id })),
      min: 1,
      max: 1,
      allowCancel: false,
      continuationEffectId: effectId,
      submissions: {},
    });
    return;
  }
  resolveIbarakiRashomonTarget(state, player.id, skill.id, targetPlayerId, locationId, definitions, emitEvent);
};

export const isIbarakiRashomonGrudgeLegal: SkillLegalityPredicate = (state, playerId, skill, _ability, definitions) => {
  const player = state.players[playerId];
  return Boolean(player
    && skill.rashomonGrudge?.powerLossScope === "same-battlefield-opponents"
    && definitions
    && (player.locationId === "mountain" || player.locationId === "city")
    && getIbarakiRashomonTargetIds(state, playerId, player.locationId, definitions).length > 0);
};

const resolveIbarakiRashomonGrudge: SkillHandler = ({ state, player, skill, payload, definitions, emitEvent }) => {
  if (!definitions || !isRecord(payload) || !isRecord(payload.decision)) throw new Error("IBARAKI_RASHOMON_DECISION_INVALID");
  const decision = payload.decision;
  if (decision.status !== "resolved" || !Array.isArray(decision.selections) || decision.selections.length !== 1) throw new Error("IBARAKI_RASHOMON_DECISION_INVALID");
  const previous = isRecord(payload.previous) ? payload.previous : {};
  const locationId = previous.locationId === "mountain" || previous.locationId === "city" ? previous.locationId : player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("IBARAKI_RASHOMON_NOT_IN_BATTLE");
  resolveIbarakiRashomonTarget(state, player.id, skill.id, decision.selections[0], locationId, definitions, emitEvent);
};

function getIbarakiRashomonTargetIds(state: GameState, playerId: string, locationId: string, definitions: Record<string, CardDefinition>): string[] {
  const player = state.players[playerId];
  if (!player) return [];
  const remembered = new Set(player.sharedBattlefieldPlayerIdsThisRound ?? []);
  return Object.values(state.players)
    .filter((target) => target.id !== playerId
      && !target.eliminated
      && !target.defeated
      && target.hand.length > 0
      && target.locationId !== locationId
      && remembered.has(target.id)
      && canMovePlayerByEffect(state, target.id, locationId, definitions))
    .map((target) => target.id);
}

function canMovePlayerByEffect(state: GameState, playerId: string, locationId: string, definitions: Record<string, CardDefinition>): boolean {
  const draft = structuredClone(state);
  try {
    movePlayerByEffect(draft, playerId, locationId, definitions);
    return true;
  } catch {
    return false;
  }
}

function resolveIbarakiRashomonTarget(
  state: GameState,
  playerId: string,
  skillId: string,
  targetPlayerId: string,
  locationId: string,
  definitions: Record<string, CardDefinition>,
  emitEvent?: (type: string, payload: unknown) => void,
): void {
  if (!getIbarakiRashomonTargetIds(state, playerId, locationId, definitions).includes(targetPlayerId)) throw new Error("IBARAKI_RASHOMON_TARGET_INVALID");
  const target = state.players[targetPlayerId];
  const movement = movePlayerByEffect(state, targetPlayerId, locationId, definitions);
  emitEvent?.("player.moved", { playerId: targetPlayerId, ...movement });
  const index = new StateRandom().integer(state, target.hand.length);
  const instanceId = target.hand[index];
  const definition = definitions[state.cards[instanceId]?.definitionId ?? ""];
  if (!definition) throw new Error("IBARAKI_RASHOMON_CARD_DEFINITION_MISSING");
  const powerLoss = getPrintedCardBasePower(state, target, definition);
  movePlayerCard(state, target.id, instanceId, "discard");
  const discarded = state.cards[instanceId];
  discarded.face = "up";
  discarded.active = false;
  discarded.residual = false;
  emitEvent?.("card.discarded", { playerId: target.id, instanceId, definitionId: definition.id, sourceId: skillId, random: true });
  for (const opponentId of state.board.locations[locationId] ?? []) {
    if (opponentId === playerId || state.players[opponentId]?.eliminated || state.players[opponentId]?.defeated) continue;
    const opponent = state.players[opponentId];
    opponent.flags.roundPowerBonus = Number(opponent.flags.roundPowerBonus ?? 0) - powerLoss;
  }
}


export const useHinakoBloodSong: SkillHandler = ({ state, player, skill }) => {
  const locationId = player.locationId;
  if (locationId !== "mountain" && locationId !== "city") throw new Error("HINAKO_BLOOD_SONG_NOT_IN_BATTLE");
  let targetCount = 0;
  for (const opponentId of state.board.locations[locationId] ?? []) {
    if (opponentId === player.id || state.players[opponentId]?.eliminated) continue;
    for (const instanceId of state.players[opponentId].attack) {
      const instance = state.cards[instanceId];
      if (!instance?.active || instance.face !== "up") continue;
      const modifierId = `${skill.id}:blood-song:${instance.instanceId}:${state.round}`;
      instance.powerModifiers = [
        ...(instance.powerModifiers ?? []).filter((modifier) => modifier.id !== modifierId),
        { id: modifierId, sourceId: skill.id, kind: "add", value: -2, duration: "round" },
      ];
      targetCount += 1;
    }
  }
  if (targetCount === 0) throw new Error("HINAKO_BLOOD_SONG_NO_TARGET");
};

export const isHinakoBloodSongLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  if (!player || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return (state.board.locations[player.locationId] ?? []).some((opponentId) => opponentId !== playerId
    && !state.players[opponentId]?.eliminated
    && state.players[opponentId].attack.some((instanceId) => {
      const instance = state.cards[instanceId];
      return Boolean(instance?.active && instance.face === "up");
    }));
};

function removeCardFromAllPlayerZones(state: GameState, instanceId: string): void {
  for (const candidate of Object.values(state.players)) {
    for (const zone of playerCardZones) {
      const list = candidate[zone];
      const index = list.indexOf(instanceId);
      if (index >= 0) list.splice(index, 1);
    }
  }
}


export const useOuterGodLife: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = (payload as { eventType?: unknown } | undefined)?.eventType;
  if (eventType === "combat.resolved") {
    for (const [key, value] of Object.entries(player.flags)) {
      if (!key.startsWith("outerGodLifeReturn:") || typeof value !== "string") continue;
      const [roundText, targetPlayerId] = value.split("|");
      if (Number(roundText) !== state.round) continue;
      const instanceId = key.slice("outerGodLifeReturn:".length);
      const card = state.cards[instanceId];
      const target = state.players[targetPlayerId] ?? player;
      // Temporary Foreigner Class cards never enter a discard pile; the generic
      // temporary cleanup removes them at round end. Drop only this delayed-return marker.
      if (card?.temporary) {
        delete player.flags[key];
        continue;
      }
      // A generic delayed cleanup (for example Gate to Nowhere) may keep active
      // Outer God Life cards in play until the whole Combat phase ends.  Do not
      // consume the ordinary after-fight return while that cleanup is armed.
      if (player.flags.outerGodLifeDeckCleanupRound === state.round
        && card?.zone === "attack" && card.active && card.face === "up") continue;
      if (card) {
        clearCardStateBoundToClose(card);
        removeCardFromAllPlayerZones(state, instanceId);
        target.discard.push(instanceId);
        card.ownerPlayerId = target.id;
        card.controllerPlayerId = target.id;
        card.zone = "discard";
        card.face = "down";
        card.active = false;
        card.residual = false;
      }
      delete player.flags[key];
    }
    return;
  }

  const activeInstances = player.attack.filter((instanceId) => {
    const card = state.cards[instanceId];
    return card?.definitionId === skill.id && card.active && card.face === "up";
  });
  if (activeInstances.length === 0) throw new Error("OUTER_GOD_LIFE_CARD_MISSING");
  const target = Object.values(state.players).find((candidate) => candidate.servantId === skill.ownerId && !candidate.eliminated);
  player.flags.roundPowerBonus = Number(player.flags.roundPowerBonus ?? 0) + 6;
  if (target && target.id !== player.id) target.flags.roundPowerBonus = Number(target.flags.roundPowerBonus ?? 0) + 6;
  const returnPlayerId = target?.id ?? player.id;
  for (const instanceId of activeInstances) {
    player.flags[`outerGodLifeReturn:${instanceId}`] = `${state.round}|${returnPlayerId}`;
  }
};

export const isDefeatCombatParticipantsLegal: SkillLegalityPredicate = (state, playerId) => {
  const player = state.players[playerId];
  if (!player || (player.locationId !== "mountain" && player.locationId !== "city")) return false;
  return (state.board.locations[player.locationId] ?? []).filter((id) => !state.players[id]?.eliminated).length >= 2;
};

const ARAYA_TRIPLE_BOUNDARY_ID = "master.araya.skill.s1";
const ARAYA_PARADOX_SPIRAL_ID = "master.araya.skill.ascension";


export const useArayaTripleBoundary: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType !== "player.deployed" || event.playerId !== player.id) throw new Error("ARAYA_TRIPLE_BOUNDARY_TRIGGER_INVALID");
  const locationId = event.locationId;
  if (locationId !== "mountain" && locationId !== "city") return;
  // Base rules: terrain advantage exists only in the two battlefield D-slots.
  // Being deployed to the battlefield after those slots are occupied does not
  // increase Triple Boundary, although an already-built permanent advantage
  // still applies while Araya is at that location.
  if (!(state.board.outpostRecords[locationId] ?? []).includes(player.id)) return;
  incrementPersistentLocationAdvantage(state, {
    sourceId: skill.id,
    playerId: player.id,
    locationId,
    amount: 1,
    max: 5,
    mode: "replace",
  });
};


export const useArayaParadoxSpiral: SkillHandler = ({ state, player, skill, payload }) => {
  const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
  const event = isRecord(payload) && isRecord(payload.event) ? payload.event : {};
  if (eventType !== "skill.unlocked" || event.playerId !== player.id || event.skillId !== skill.id) {
    throw new Error("ARAYA_PARADOX_SPIRAL_TRIGGER_INVALID");
  }
  addEffectiveLocationRule(state, {
    sourceId: skill.id,
    playerId: player.id,
    treatedAs: "workshop",
    actualLocationIds: ["mountain", "city"],
    persistentAdvantageSourceId: ARAYA_TRIPLE_BOUNDARY_ID,
    persistentAdvantageAtLeast: 5,
  });
  addSameLocationRestrictionRule(state, {
    sourceId: skill.id,
    controllerPlayerId: player.id,
    activeWhenControllerAtEffectiveLocation: "workshop",
    blockOpponentExit: true,
    requireOpponentFaceDownStandardAttack: true,
  });
};

