function removeFromAllLocations(state: GameState, playerId: string): void {
  for (const players of Object.values(state.board.locations)) {
    const index = players.indexOf(playerId);
    if (index >= 0) players.splice(index, 1);
  }
}

function sameBattlefieldOpponentIds(state: GameState, playerId: string, locationId: string): string[] {
  return (state.board.locations[locationId] ?? []).filter((id) => id !== playerId && !state.players[id]?.eliminated);
}

const structuredLocationOrder = ["workshop", "mountain", "city", "scouting"];

function isStructuredAdjacentLocation(state: GameState, currentLocationId: unknown, targetLocationId: string): boolean {
  return typeof currentLocationId === "string" && areLocationsAdjacentByMovementArrows(state, currentLocationId, targetLocationId);
}

function isStructuredAbilityEventMatch(ability: { kind: string; activation?: { phase?: string } }, eventType: string): boolean {
  if (ability.kind === "play_trigger") return eventType === "card.played";
  if (ability.kind === "residual") return true;
  if (ability.kind === "passive") {
    const phase = ability.activation?.phase;
    if (eventType === "phase.transitioned" && typeof phase === "string") return true;
    return true;
  }
  return false;
}

function assertStructuredAbilityLegal(
  state: GameState,
  player: GameState["players"][string],
  skill: { id: string },
  ability: {
    conditions?: Array<Record<string, unknown>>;
    effects?: Array<{ target?: unknown; type?: string }>;
    creates?: Array<Record<string, unknown>>;
    copies?: Array<Record<string, unknown>>;
  },
  payload: unknown,
  definitions?: Record<string, CardDefinition>,
): void {
  assertStructuredConditions(state, player, skill, ability.conditions ?? [], payload, definitions);
  const preflightEffects = [
    ...(ability.effects ?? []),
    ...(ability.creates ?? []).map((create) => ({ ...create, type: "create_card_instances" })),
    ...(ability.copies ?? []).map((copy) => ({ ...copy, type: "copy_selected_card" })),
  ];
  for (const effect of preflightEffects) {
    switch (effect.type) {
      case "choose_locations":
      case "choose-locations": {
        const candidates = structuredLocationCandidates(state, player, effect, definitions);
        if (candidates.length === 0 && effect.skipIfNoCandidates === true) break;
        const { min } = structuredCardChoiceBounds(effect, candidates.length);
        if (candidates.length < min) throw new Error("STRUCTURED_SKILL_LOCATION_SELECTION_UNAVAILABLE");
        break;
      }
      case "choose_each_player_option":
      case "choose-each-player-option": {
        const candidates = filterStructuredPlayerCandidates(
          state, player,
          resolveStructuredTargetPlayerIds(state, player, payload, effect.candidateTarget ?? effect.target ?? "all_opponents"),
          effect, definitions,
        );
        if (candidates.length === 0 && effect.skipIfNoCandidates === true) break;
        if (candidates.length === 0) throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_UNAVAILABLE");
        const options = Array.isArray(effect.options) ? effect.options.filter(isRecord) : [];
        if (options.length === 0 || options.some((option) => typeof option.id !== "string" || !option.id)) throw new Error("STRUCTURED_SKILL_CHOICE_OPTIONS_REQUIRED");
        break;
      }
      case "choose_each_player_cards":
      case "choose-each-player-cards": {
        if (!definitions) throw new Error("STRUCTURED_SKILL_CARD_DEFINITIONS_REQUIRED");
        const rawCandidates = filterStructuredPlayerCandidates(state, player, resolveStructuredTargetPlayerIds(state, player, payload, effect.candidateTarget ?? effect.target ?? "all_opponents"), effect, definitions);
        const minCandidateCount = Number(effect.minCandidateCount ?? 1);
        if (!Number.isInteger(minCandidateCount) || minCandidateCount < 1) throw new Error("STRUCTURED_SKILL_CARD_SELECTION_COUNT_INVALID");
        const eligible = rawCandidates.filter((chooserId) => structuredChoiceCards(state, player, { ...effect, target: chooserId }, payload, definitions, skill.id).length >= minCandidateCount);
        if (eligible.length === 0 && effect.skipIfNoCandidates === true) break;
        if (eligible.length === 0) throw new Error("STRUCTURED_SKILL_CARD_SELECTION_UNAVAILABLE");
        break;
      }
      case "choose_players":
      case "choose-players": {
        const candidates = filterStructuredPlayerCandidates(
          state, player,
          resolveStructuredTargetPlayerIds(state, player, payload, effect.candidateTarget ?? effect.candidates ?? "all_opponents"),
          effect, definitions,
        );
        if (candidates.length === 0 && effect.skipIfNoCandidates === true) break;
        structuredCardChoiceBounds(effect, candidates.length);
        break;
      }
      case "choose_cards":
      case "choose-cards": {
        if (isStructuredSelectedTarget(effect.target ?? "controller") && !hasStructuredSelectedPlayerPayload(payload)) break;
        const dependencyKey = typeof effect.sameBasePowerAsPayloadKey === "string" ? effect.sameBasePowerAsPayloadKey
          : typeof effect.sameAttributeAsPayloadKey === "string" ? effect.sameAttributeAsPayloadKey
            : undefined;
        // A previous serialized choice may create the reference selection later in
        // this same ability.  Preflight validates that second choice when the
        // continuation actually reaches it, not before the first decision exists.
        if (dependencyKey && !hasStructuredSelectionPayload(payload, { payloadKey: dependencyKey }, dependencyKey)) break;
        const candidates = structuredChoiceCards(state, player, effect, payload, definitions, skill.id);
        if (candidates.length === 0 && effect.skipIfNoCandidates === true) break;
        const { min } = structuredCardChoiceBounds(effect, candidates.length);
        // Some triggered/compound abilities create their future choice candidates
        // in an earlier effect (for example, draw then play).  skipIfNoCandidates
        // is an authored execution policy, so legality must not reject the whole
        // ability before those earlier effects have run.
        if (candidates.length < min && effect.skipIfNoCandidates !== true) throw new Error("STRUCTURED_SKILL_CARD_SELECTION_UNAVAILABLE");
        break;
      }
      case "move_selected_cards":
      case "move-selected-cards":
      case "transfer_selected_cards":
      case "transfer-selected-cards":
        resolveStructuredTargetPlayerIds(state, player, payload, effect.target ?? "controller");
        if (hasStructuredSelectionPayload(payload, effect, "selectedInstanceIds")) {
          resolveStructuredCardSelection(payload, effect, "selectedInstanceIds");
        }
        break;
      case "ensure_event_deck_count":
      case "ensure-event-deck-count": {
        if (effect.deferPreflight === true) break;
        const count = resolveStructuredAmount(effect.count ?? 1, { payload, state, player, skill, definitions });
        if (state.board.eventDeck.length + state.board.eventDiscard.length < count) throw new Error("STRUCTURED_SKILL_EVENT_SELECTION_UNAVAILABLE");
        break;
      }
      case "transfer_mana":
      case "transfer-mana": {
        const amount = resolveStructuredAmount(effect.amount ?? 0, { payload, state, player, skill, definitions });
        const sourcePlayerIds = resolveStructuredTargetPlayerIds(state, player, payload, effect.from ?? effect.source, definitions);
        const targetPlayerIds = resolveStructuredTargetPlayerIds(state, player, payload, effect.target ?? "controller", definitions);
        if (sourcePlayerIds.length !== 1 || targetPlayerIds.length !== 1 || sourcePlayerIds[0] === targetPlayerIds[0]) throw new Error("STRUCTURED_SKILL_TRANSFER_TARGET_INVALID");
        if (effect.requireExact === true) {
          const draft = structuredClone(state) as GameState;
          const actualTransferred = transferMana(draft.players[sourcePlayerIds[0]], draft.players[targetPlayerIds[0]], amount);
          if (actualTransferred !== amount) throw new Error("STRUCTURED_SKILL_TRANSFER_AMOUNT_UNAVAILABLE");
        }
        break;
      }
      case "gain_mana":
      case "gain-mana":
      case "gain_victory_points":
      case "gain-victory-points":
      case "gain_victory_points_per_target":
      case "gain-victory-points-per-target":
      case "lose_victory_points":
      case "lose-victory-points":
      case "transfer_victory_points":
      case "transfer-victory-points":
      case "lose_victory_points_per_matching_cards":
      case "lose-victory-points-per-matching-cards":
      case "transfer_matching_cards":
      case "transfer-matching-cards":
      case "close_source_card":
      case "close-source-card":
      case "play_selected_cards":
      case "play-selected-cards":
      case "copy_selected_card":
      case "copy-selected-card":
      case "draw_cards":
      case "draw-cards":
      case "discard_all_hand":
      case "discard-all-hand":
      case "remove_cards_in_zone":
      case "remove-cards-in-zone":
      case "return_card_by_definition":
      case "return-card-by-definition":
      case "return_cards_by_definitions":
      case "return-cards-by-definitions":
      case "combat_power_bonus":
      case "combat-power-bonus":
      case "clear_player_status_and_source_card_power_bonus":
      case "clear-player-status-and-source-card-power-bonus":
      case "add_player_flag_number":
      case "add-player-flag-number":
      case "increment_player_flag":
      case "increment-player-flag":
      case "defeat_player":
      case "defeat-player":
        if (isStructuredSelectedTarget(effect.target ?? "controller") && !hasStructuredSelectedPlayerPayload(payload)) break;
        resolveStructuredTargetPlayerIds(state, player, payload, effect.target ?? "controller", definitions);
        break;
      case "set_selected_cards_face":
      case "set-selected-cards-face":
        if (!hasStructuredSelectionPayload(payload, effect, "selectedInstanceIds")) break;
        resolveStructuredTargetPlayerIds(state, player, payload, effect.target ?? "controller");
        resolveStructuredCardSelection(payload, effect, "selectedInstanceIds");
        break;
      case "close_selected_card":
      case "close-selected-card":
        if (hasStructuredSelectionPayload(payload, effect, "targetInstanceId")) resolveStructuredCardSelection(payload, effect, "targetInstanceId");
        break;
      case "discard_selected_cards":
      case "discard-selected-cards":
        resolveStructuredTargetPlayerIds(state, player, payload, effect.target ?? "controller");
        if (hasStructuredSelectionPayload(payload, effect, "discardInstanceIds")) resolveStructuredCardSelection(payload, effect, "discardInstanceIds");
        break;
      case "look_target_deck_top_discard_selected_keep_rest":
      case "look-target-deck-top-discard-selected-keep-rest":
        if (payload === undefined) break;
        resolveStructuredTargetPlayerIds(state, player, payload, effect.target);
        resolveStructuredCardSelection(payload, effect, "discardInstanceIds");
        break;
      case "look_deck_top_choose_one_to_hand_discard_rest":
      case "look-deck-top-choose-one-to-hand-discard-rest": {
        if (payload === undefined) break;
        const count = resolveStructuredAmount(effect.count, { payload });
        const selectedInstanceId = resolveStructuredCardSelection(payload, effect, "selectedInstanceId")[0];
        if (!selectedInstanceId || !player.deck.slice(0, count).includes(selectedInstanceId)) {
          throw new Error("STRUCTURED_SKILL_DECK_SELECTION_INVALID");
        }
        break;
      }
      case "schedule_combat_power_bonus_from_selected_card":
      case "schedule-combat-power-bonus-from-selected-card":
      case "gain_mana_from_selected_card_base_power":
      case "gain-mana-from-selected-card-base-power":
        if (payload === undefined) break;
        resolveStructuredCardSelection(payload, effect, "targetInstanceId");
        break;
      case "gain_victory_points_if_selected_card_base_power_greater":
      case "gain-victory-points-if-selected-card-base-power-greater":
        if (payload === undefined) break;
        resolveStructuredCardSelection(payload, { payloadKey: effect.leftPayloadKey }, "leftInstanceId");
        resolveStructuredCardSelection(payload, { payloadKey: effect.rightPayloadKey }, "rightInstanceId");
        resolveStructuredTargetPlayerIds(state, player, payload, effect.target ?? "controller");
        break;
      case "close_owned_active_cards_by_definition":
      case "close-owned-active-cards-by-definition":
        break;
      default:
        break;
    }
  }
}

function hasStructuredEventSelectionPayload(payload: unknown, key: string): boolean {
  return Boolean(isRecord(payload) && Array.isArray(payload[key]) || isRecord(payload) && isRecord(payload.data) && Array.isArray(payload.data[key]));
}

function hasStructuredSelectedPlayerPayload(payload: unknown): boolean {
  return Boolean(isRecord(payload) && typeof payload.targetPlayerId === "string"
    || isRecord(payload) && isRecord(payload.data) && typeof payload.data.targetPlayerId === "string"
    || isRecord(payload) && isRecord(payload.event) && isRecord(payload.event.data) && typeof payload.event.data.targetPlayerId === "string");
}

function isStructuredSelectedTarget(target: unknown): boolean {
  const scope = isRecord(target) && typeof target.scope === "string" ? target.scope : typeof target === "string" ? target : undefined;
  return scope === "selected_player"
    || scope === "selected_players"
    || scope === "selected_any_player"
    || scope === "selected_same_location_player"
    || scope === "selected_same_battlefield_player"
    || scope === "selected_same_battlefield_opponent"
    || scope === "selected_card_owners";
}

function assertStructuredConditions(
  state: GameState,
  player: GameState["players"][string],
  skill: { id: string },
  conditions: Array<Record<string, unknown>>,
  payload: unknown,
  definitions?: Record<string, CardDefinition>,
): void {
  for (const condition of conditions) {
    switch (condition.type) {
      case "player_flag_equals": {
        const key = condition.key;
        if (typeof key !== "string" || !key) throw new Error("STRUCTURED_SKILL_FLAG_CONDITION_INVALID");
        if (player.flags[key] !== condition.value) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "player_flag_number_at_least": {
        const key = condition.key;
        const value = Number(condition.value);
        if (typeof key !== "string" || !key || !Number.isInteger(value)) throw new Error("STRUCTURED_SKILL_FLAG_CONDITION_INVALID");
        if (Number(player.flags[key] ?? Number.NEGATIVE_INFINITY) < value) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "player_flag_number_current_round": {
        const key = condition.key;
        if (typeof key !== "string" || !key) throw new Error("STRUCTURED_SKILL_FLAG_CONDITION_INVALID");
        if (Number(player.flags[key] ?? Number.NEGATIVE_INFINITY) !== state.round) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "player_flag_number_not_current_round": {
        const key = condition.key;
        if (typeof key !== "string" || !key) throw new Error("STRUCTURED_SKILL_FLAG_CONDITION_INVALID");
        if (Number(player.flags[key] ?? Number.NEGATIVE_INFINITY) === state.round) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "player_flag_number_equals_event_field":
      case "player-flag-number-equals-event-field": {
        const key = condition.key;
        const field = condition.field;
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const expected = typeof field === "string" && Number.isInteger(event?.[field]) ? Number(event[field]) : undefined;
        if (typeof key !== "string" || !key || expected === undefined) throw new Error("STRUCTURED_SKILL_FLAG_CONDITION_INVALID");
        if (Number(player.flags[key] ?? Number.NEGATIVE_INFINITY) !== expected) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "player_flag_number_not_event_field":
      case "player-flag-number-not-event-field": {
        const key = condition.key;
        const field = condition.field;
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const expected = typeof field === "string" && Number.isInteger(event?.[field]) ? Number(event[field]) : undefined;
        if (typeof key !== "string" || !key || expected === undefined) throw new Error("STRUCTURED_SKILL_FLAG_CONDITION_INVALID");
        if (Number(player.flags[key] ?? Number.NEGATIVE_INFINITY) === expected) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "target_command_seals_at_most": {
        const targetPlayerIds = resolveStructuredTargetPlayerIds(state, player, payload, condition.target ?? "controller");
        const value = Number(condition.value);
        if (targetPlayerIds.length !== 1 || !Number.isInteger(value) || value < 0) throw new Error("STRUCTURED_SKILL_COMMAND_SEAL_CONDITION_INVALID");
        const before = resolveStructuredCommandSealBefore(payload, targetPlayerIds[0]);
        if (before > value) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "target_command_seals_equals": {
        const targetPlayerIds = resolveStructuredTargetPlayerIds(state, player, payload, condition.target ?? "controller");
        const value = Number(condition.value);
        if (targetPlayerIds.length !== 1 || !Number.isInteger(value) || value < 0) throw new Error("STRUCTURED_SKILL_COMMAND_SEAL_CONDITION_INVALID");
        const before = resolveStructuredCommandSealBefore(payload, targetPlayerIds[0]);
        if (before !== value) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "command_seals_at_least": {
        const targetPlayerIds = resolveStructuredTargetPlayerIds(state, player, payload, condition.target ?? "controller");
        const value = resolveStructuredAmount(condition.value ?? 1, { payload, state, player, skill, definitions });
        if (!Number.isInteger(value) || value < 0 || targetPlayerIds.length === 0) throw new Error("STRUCTURED_SKILL_COMMAND_SEAL_CONDITION_INVALID");
        if (targetPlayerIds.some((targetPlayerId) => state.players[targetPlayerId].commandSeals < value)) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "any_of": {
        const nested = Array.isArray(condition.conditions) ? condition.conditions.filter(isRecord) : [];
        if (nested.length === 0) throw new Error("STRUCTURED_SKILL_CONDITION_INVALID");
        let matched = false;
        for (const candidate of nested) {
          try {
            assertStructuredConditions(state, player, skill, [candidate], payload, definitions);
            matched = true;
            break;
          } catch (error) {
            if (!(error instanceof Error) || error.message !== "STRUCTURED_SKILL_CONDITION_NOT_MET") throw error;
          }
        }
        if (!matched) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "implies": {
        const when = Array.isArray(condition.when) ? condition.when.filter(isRecord) : [];
        const required = Array.isArray(condition.require) ? condition.require.filter(isRecord) : Array.isArray(condition.then) ? condition.then.filter(isRecord) : [];
        if (when.length === 0 || required.length === 0) throw new Error("STRUCTURED_SKILL_CONDITION_INVALID");
        let applies = false;
        try {
          assertStructuredConditions(state, player, skill, when, payload, definitions);
          applies = true;
        } catch (error) {
          if (!(error instanceof Error) || error.message !== "STRUCTURED_SKILL_CONDITION_NOT_MET") throw error;
        }
        if (applies) assertStructuredConditions(state, player, skill, required, payload, definitions);
        break;
      }
      case "phase_is": {
        if (typeof condition.phase !== "string" || state.phase !== condition.phase) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "current_situation_id_is":
      case "current-situation-id-is": {
        if (typeof condition.situationId !== "string" || state.modeState.currentSituationId !== condition.situationId) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "scheduled_payload_present": {
        if (!isRecord(payload) || !isRecord(payload.scheduled)) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_number_compare":
      case "event-number-compare": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const field = condition.field;
        const left = typeof field === "string" ? Number(event?.[field]) : Number.NaN;
        const right = resolveStructuredAmount(condition.right ?? condition.value, { allowNegative: true, payload, state, player, skill, definitions });
        const operator = condition.operator ?? condition.op;
        if (!Number.isFinite(left) || !["eq", "ne", "lt", "lte", "gt", "gte"].includes(String(operator))) throw new Error("STRUCTURED_SKILL_EVENT_NUMBER_COMPARE_INVALID");
        const matched = operator === "eq" ? left === right
          : operator === "ne" ? left !== right
            : operator === "lt" ? left < right
              : operator === "lte" ? left <= right
                : operator === "gt" ? left > right
                  : left >= right;
        if (!matched) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_location_is":
      case "event-location-is": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        if (typeof condition.locationId !== "string" || event?.locationId !== condition.locationId) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_type_is": {
        const eventType = isRecord(payload) && typeof payload.eventType === "string" ? payload.eventType : undefined;
        if (typeof condition.eventType !== "string" || eventType !== condition.eventType) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_player_is_controller": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        if (event?.playerId !== player.id) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_player_is_opponent": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const eventPlayerId = typeof event?.playerId === "string" ? event.playerId : undefined;
        if (!eventPlayerId || eventPlayerId === player.id || !state.players[eventPlayerId] || state.players[eventPlayerId].eliminated) {
          throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        }
        break;
      }
      case "event_location_equals_controller": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        if (typeof event?.locationId !== "string" || event.locationId !== player.locationId) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_location_not_controller": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        if (typeof event?.locationId !== "string" || event.locationId === player.locationId) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_location_not": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        if (typeof condition.locationId !== "string" || typeof event?.locationId !== "string" || event.locationId === condition.locationId) {
          throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        }
        break;
      }
      case "event_definition_is_self": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        if (event?.definitionId !== skill.id) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_skill_id_is": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        if (typeof condition.skillId !== "string" || event?.skillId !== condition.skillId) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_face_is": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        if (typeof condition.face !== "string" || event?.face !== condition.face) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "situation_forbids_attribute": {
        const attribute = condition.attribute;
        const restrictions = state.modeState.situationRestrictions as { forbiddenAttributes?: string[] } | undefined;
        if (typeof attribute !== "string" || !(restrictions?.forbiddenAttributes ?? []).includes(attribute)) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "true_name_hidden": {
        if (player.trueNameRevealed) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "true_name_revealed": {
        if (!player.trueNameRevealed) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_scouting_rewarded_controller": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const gains = event && isRecord(event.victoryPoints) ? event.victoryPoints : undefined;
        if (event?.scoutingPlayerId !== player.id || !gains || !Number.isFinite(Number(gains[player.id])) || Number(gains[player.id]) <= 0) {
          throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        }
        break;
      }
            case "event_player_won_combat": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const winnerIds = Array.isArray(event?.winnerIds) ? event.winnerIds : [];
        const powers = isRecord(event?.powers) ? event.powers : {};
        if (!Object.prototype.hasOwnProperty.call(powers, player.id) || !winnerIds.includes(player.id)) {
          throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        }
        break;
      }
      case "event_player_lost_combat": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const winnerIds = Array.isArray(event?.winnerIds) ? event.winnerIds : [];
        const powers = isRecord(event?.powers) ? event.powers : {};
        if (!Object.prototype.hasOwnProperty.call(powers, player.id) || winnerIds.includes(player.id)) {
          throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        }
        break;
      }
      case "event_combat_has_attribute": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const attributes = isRecord(event?.attributes) ? event.attributes : undefined;
        const attribute = condition.attribute;
        if (!attributes || typeof attribute !== "string") throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        const matched = Object.values(attributes).some((value) => Array.isArray(value) && value.includes(attribute));
        if (!matched) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_combat_opponent_count_equals": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const powers = isRecord(event?.powers) ? event.powers : {};
        const expected = Number(condition.value ?? condition.count ?? 0);
        if (!Number.isInteger(expected) || expected < 0 || !Object.prototype.hasOwnProperty.call(powers, player.id)) {
          throw new Error("STRUCTURED_SKILL_CONDITION_INVALID");
        }
        const opponents = Object.keys(powers).filter((id) => id !== player.id && Boolean(state.players[id]) && !state.players[id].eliminated);
        if (opponents.length !== expected) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_round_victory_points_gain_crosses": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const eventPlayerId = typeof event?.playerId === "string" ? event.playerId : undefined;
        const eventRound = Number(event?.round);
        const delta = Number(event?.delta);
        const threshold = Number(condition.threshold ?? condition.value);
        if (!eventPlayerId || !Number.isInteger(eventRound) || !Number.isFinite(delta) || !Number.isInteger(threshold) || threshold < 0 || delta <= 0) {
          throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        }
        const prior = state.eventLog.reduce((sum, logged) => {
          if (logged.type !== "player.victory-points.changed" || !isRecord(logged.payload)) return sum;
          if (logged.payload.playerId !== eventPlayerId || Number(logged.payload.round) !== eventRound) return sum;
          const loggedDelta = Number(logged.payload.delta);
          return sum + (Number.isFinite(loggedDelta) && loggedDelta > 0 ? loggedDelta : 0);
        }, 0);
        if (!(prior < threshold && prior + delta >= threshold)) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_eliminated_same_battlefield_player": {
        const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
        const eliminated = Array.isArray(event?.eliminatedThisRound) ? event.eliminatedThisRound.filter((id): id is string => typeof id === "string") : [];
        const previousLocations = isRecord(event?.previousLocations) ? event.previousLocations : undefined;
        const controllerLocation = typeof previousLocations?.[player.id] === "string" ? String(previousLocations[player.id]) : player.locationId;
        if (controllerLocation !== "mountain" && controllerLocation !== "city") throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        const matched = eliminated.some((id) => id !== player.id
          && state.players[id]
          && (typeof previousLocations?.[id] === "string" ? previousLocations[id] : state.players[id].locationId) === controllerLocation);
        if (!matched) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "round_victory_points_gained_equals": {
        const expected = Number(condition.value ?? condition.amount ?? 0);
        if (!Number.isInteger(expected) || expected < 0 || Number(player.flags.roundVictoryPointsGained ?? 0) !== expected) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "same_location_player_count_equals": {
        const expected = Number(condition.value ?? condition.count);
        const count = player.locationId ? (state.board.locations[player.locationId] ?? []).filter((id) => !state.players[id]?.eliminated).length : 0;
        if (!Number.isInteger(expected) || expected < 0 || count !== expected) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "victory_points_is_lowest": {
        const alive = Object.values(state.players).filter((candidate) => !candidate.eliminated);
        const lowest = Math.min(...alive.map((candidate) => candidate.victoryPoints));
        if (player.victoryPoints !== lowest) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "victory_points_is_first": {
        const alive = Object.values(state.players).filter((candidate) => !candidate.eliminated);
        const highest = Math.max(...alive.map((candidate) => candidate.victoryPoints));
        if (player.victoryPoints !== highest) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "has_status": {
        const status = condition.status;
        if (typeof status !== "string" || !status) throw new Error("STRUCTURED_SKILL_STATUS_KEY_INVALID");
        if (!player.statuses.includes(status)) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "lacks_status": {
        const status = condition.status;
        if (typeof status !== "string" || !status) throw new Error("STRUCTURED_SKILL_STATUS_KEY_INVALID");
        if (player.statuses.includes(status)) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "source_owned": {
        const zones = [...player.masterSkills, ...player.servantSkills, ...player.attack, ...player.hand];
        if (!zones.some((instanceId) => {
          const instance = state.cards[instanceId];
          return instance?.definitionId === skill.id || instance?.definitionId === `card.skill.${skill.id}`;
        })) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "source_active": {
        if (!player.attack.some((instanceId) => {
          const instance = state.cards[instanceId];
          return (instance?.definitionId === skill.id || instance?.definitionId === `card.skill.${skill.id}`) && instance.active && instance.face === "up";
        })) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "owned_active_card_by_definition": {
        const definitionId = condition.definitionId;
        if (typeof definitionId !== "string" || !definitionId) throw new Error("STRUCTURED_SKILL_CARD_DEFINITION_INVALID");
        const found = player.attack.some((instanceId) => {
          const instance = state.cards[instanceId];
          return instance?.ownerPlayerId === player.id && instance.definitionId === definitionId && instance.active && instance.face === "up";
        });
        if (!found) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "location_is": {
        if (typeof condition.locationId !== "string" || player.locationId !== condition.locationId) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "location_in": {
        if (!Array.isArray(condition.locationIds) || !condition.locationIds.includes(player.locationId)) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "at_battlefield": {
        if (player.locationId !== "mountain" && player.locationId !== "city") throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "target_count_at_least": {
        const scope = condition.scope;
        const count = condition.count;
        if (!Number.isInteger(count) || Number(count) < 0) {
          throw new Error("STRUCTURED_SKILL_TARGET_COUNT_CONDITION_INVALID");
        }
        const target = isRecord(condition.target) ? condition.target : typeof scope === "string" ? { scope } : undefined;
        if (!target || resolveStructuredTargetPlayerIds(state, player, payload, target, definitions).length < Number(count)) {
          throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        }
        break;
      }
      case "target_count_equals": {
        const scope = condition.scope;
        const count = condition.count;
        if (!Number.isInteger(count) || Number(count) < 0) {
          throw new Error("STRUCTURED_SKILL_TARGET_COUNT_CONDITION_INVALID");
        }
        const target = isRecord(condition.target) ? condition.target : typeof scope === "string" ? { scope } : undefined;
        if (!target || resolveStructuredTargetPlayerIds(state, player, payload, target, definitions).length !== Number(count)) {
          throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        }
        break;
      }
      case "has_active_basic_attack": {
        if (!definitions || !player.attack.some((instanceId) => {
          const instance = state.cards[instanceId];
          return Boolean(instance?.active && instance.face === "up" && definitions[instance.definitionId]?.basic === true);
        })) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "engaged_opponent_victory_points_greater_than_controller": {
        const locationId = player.locationId;
        if ((locationId !== "mountain" && locationId !== "city") || !(state.board.locations[locationId] ?? []).some((id) => {
          const target = state.players[id];
          return id !== player.id && Boolean(target && !target.eliminated && target.victoryPoints > player.victoryPoints);
        })) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "event_count_at_least":
      case "event-count-at-least": {
        const count = Number(condition.value ?? condition.count ?? 1);
        if (!Number.isInteger(count) || count < 0) throw new Error("STRUCTURED_SKILL_EVENT_COUNT_CONDITION_INVALID");
        const candidates = structuredChoiceEvents(state, player, condition, definitions);
        if (candidates.length < count) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "card_count_at_least":
      case "card-count-at-least": {
        const value = Number(condition.value ?? condition.count ?? 1);
        if (!Number.isInteger(value) || value < 0) throw new Error("STRUCTURED_SKILL_CARD_COUNT_INVALID");
        const candidates = structuredChoiceCards(state, player, condition, payload, definitions, skill.id);
        if (candidates.length < value) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "selected_cards_all_have_attribute":
      case "selected-cards-all-have-attribute": {
        if (!definitions || typeof condition.attribute !== "string") throw new Error("STRUCTURED_SKILL_CONDITION_INVALID");
        const payloadKey = typeof condition.payloadKey === "string" ? condition.payloadKey : "selectedInstanceIds";
        const ids = resolveStructuredCardSelection(payload, { payloadKey }, payloadKey);
        if (ids.length === 0 || ids.some((id) => {
          const definition = definitions[state.cards[id]?.definitionId ?? ""];
          return !definition || !getCardAttributes(definition).includes(condition.attribute as never);
        })) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      case "metric_compare":
      case "metric-compare": {
        const left = resolveStructuredAmount(condition.left, { allowNegative: true, payload, state, player, skill, definitions });
        const right = resolveStructuredAmount(condition.right, { allowNegative: true, payload, state, player, skill, definitions });
        const operator = condition.operator ?? condition.op;
        const matched = operator === "eq" ? left === right
          : operator === "ne" ? left !== right
            : operator === "lt" ? left < right
              : operator === "lte" ? left <= right
                : operator === "gt" ? left > right
                  : operator === "gte" ? left >= right
                    : false;
        if (!["eq", "ne", "lt", "lte", "gt", "gte"].includes(String(operator))) throw new Error("STRUCTURED_SKILL_METRIC_COMPARE_INVALID");
        if (!matched) throw new Error("STRUCTURED_SKILL_CONDITION_NOT_MET");
        break;
      }
      default:
        throw new Error("STRUCTURED_SKILL_CONDITION_UNSUPPORTED");
    }
  }
}

function resolveStructuredCommandSealBefore(payload: unknown, targetPlayerId: string): number {
  const losses = isRecord(payload) && isRecord(payload.commandSealLosses) ? payload.commandSealLosses : undefined;
  const record = losses && isRecord(losses[targetPlayerId]) ? losses[targetPlayerId] : undefined;
  const before = record?.before;
  if (!Number.isInteger(before) || Number(before) < 0) throw new Error("STRUCTURED_SKILL_COMMAND_SEAL_CONDITION_INVALID");
  return Number(before);
}

function resolveStructuredAmount(
  value: unknown,
  options: {
    allowNegative?: boolean;
    payload?: unknown;
    state?: GameState;
    player?: GameState["players"][string];
    skill?: { id: string };
    definitions?: Record<string, CardDefinition>;
  } = {},
): number {
  const valid = (candidate: unknown): candidate is number => Number.isInteger(candidate)
    && (options.allowNegative === true || Number(candidate) >= 0);
  if (valid(value)) return Number(value);
  if (isRecord(value) && value.type === "constant" && valid(value.value)) return Number(value.value);
  if (isRecord(value) && value.type === "metric") {
    const source = value.source ?? "controller";
    if (source !== "controller" && source !== "this_card" && source !== "selected_card" && source !== "selected_player") throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    if (!options.state || !options.player) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    let resolved: number;
    switch (value.metric) {
      case "mana": resolved = options.player.mana; break;
      case "combat_power": {
        if (!options.definitions) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = calculateCombatPower(options.state, options.player, options.definitions, options.player.locationId === "mountain" || options.player.locationId === "city" ? options.player.locationId : undefined);
        break;
      }
      case "victory_points": resolved = options.player.victoryPoints; break;
      case "round_number": resolved = options.state.round; break;
      case "movement_distance_this_round": resolved = Number(options.player.flags.movementDistanceThisRound ?? 0); break;
      case "locations_passed_this_round": {
        const locations = Array.isArray(options.player.locationsPassedThisRound) ? options.player.locationsPassedThisRound : [];
        if (value.locationIds !== undefined) {
          if (!Array.isArray(value.locationIds) || value.locationIds.some((item) => typeof item !== "string" || !item)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
          resolved = locations.filter((locationId) => value.locationIds.includes(locationId)).length;
        } else {
          resolved = locations.length;
        }
        break;
      }
      case "deployment_bonus": resolved = options.player.flags.deploymentBonusActive === true ? Number(options.player.flags.deploymentBonus ?? 0) : 0; break;
      case "hand_size": resolved = options.player.hand.length; break;
      case "deck_size": resolved = options.player.deck.length; break;
      case "discard_size": resolved = options.player.discard.length; break;
      case "controlled_attack_count": resolved = options.player.attack.length; break;
      case "active_attack_count": resolved = options.player.attack.filter((instanceId) => {
        const instance = options.state?.cards[instanceId];
        return instance?.active && instance.face === "up";
      }).length; break;
      case "engaged_opponent_count":
      case "same_battlefield_opponent_count":
        resolved = options.player.locationId === "mountain" || options.player.locationId === "city"
          ? sameBattlefieldOpponentIds(options.state, options.player.id, options.player.locationId).length
          : 0;
        break;
      case "same_location_opponent_count":
        resolved = (options.state.board.locations[options.player.locationId] ?? []).filter((id) => id !== options.player?.id && !options.state?.players[id]?.eliminated).length;
        break;
      case "players_with_status_count": {
        const status = typeof value.status === "string" ? value.status : undefined;
        if (!status) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = Object.values(options.state.players).filter((candidate) => candidate.statuses.includes(status)).length;
        break;
      }
      case "source_card_active_round_count": {
        if (!options.skill) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const sourceInstanceId = resolveStructuredSourceInstanceId(options.state, options.player, options.payload, options.skill);
        const playedRound = options.state.cards[sourceInstanceId]?.playedRound;
        if (!Number.isInteger(playedRound) || Number(playedRound) > options.state.round) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = options.state.round - Number(playedRound) + 1;
        break;
      }
      case "source_card_base_power": {
        if (!options.skill || !options.definitions) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const sourceInstanceId = resolveStructuredSourceInstanceId(options.state, options.player, options.payload, options.skill);
        const definition = options.definitions[options.state.cards[sourceInstanceId]?.definitionId ?? ""];
        if (!definition) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = getPrintedCardBasePower(options.state, options.player, definition);
        break;
      }
      case "source_card_current_power": {
        if (!options.skill || !options.definitions) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const sourceInstanceId = resolveStructuredSourceInstanceId(options.state, options.player, options.payload, options.skill);
        resolved = calculateCombatCardPower(
          options.state,
          options.player,
          sourceInstanceId,
          options.definitions,
          options.player.locationId === "mountain" || options.player.locationId === "city" ? options.player.locationId : undefined,
        );
        break;
      }
      case "selected_card_printed_cost":
      case "selected_card_base_power": {
        if (!options.definitions || !isRecord(value)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const payloadKey = typeof value.payloadKey === "string" ? value.payloadKey : "selectedInstanceIds";
        const selected = resolveStructuredCardSelection(options.payload, { payloadKey }, payloadKey);
        if (selected.length !== 1) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const selectedInstance = options.state.cards[selected[0]];
        const definition = options.definitions[selectedInstance?.definitionId ?? ""];
        const selectedController = selectedInstance ? options.state.players[selectedInstance.controllerPlayerId] : undefined;
        if (!definition || !selectedController) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = value.metric === "selected_card_printed_cost" ? definition.cost : getPrintedCardBasePower(options.state, selectedController, definition);
        break;
      }
      case "event_printed_victory_points": {
        const event = isRecord(options.payload) && isRecord(options.payload.event) ? options.payload.event : undefined;
        const amount = event?.printedEventVictoryPoints;
        if (!Number.isInteger(amount)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = Number(amount);
        break;
      }
      case "selected_event_victory_points": {
        if (!options.definitions) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const selected = resolveStructuredEventSelection(options.payload, typeof value.payloadKey === "string" ? value.payloadKey : "selectedEventIds");
        if (selected.length !== 1) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const points = Number((options.definitions[selected[0]] as CardDefinition & { victoryPoints?: number } | undefined)?.victoryPoints);
        if (!Number.isInteger(points) || points < 0) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = points;
        break;
      }
      case "selected_event_victory_points_sum": {
        if (!options.definitions) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const selected = resolveStructuredEventSelection(options.payload, typeof value.payloadKey === "string" ? value.payloadKey : "selectedEventIds");
        resolved = selected.reduce((sum, eventId) => {
          const points = Number((options.definitions?.[eventId] as CardDefinition & { victoryPoints?: number } | undefined)?.victoryPoints);
          if (!Number.isInteger(points) || points < 0) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
          return sum + points;
        }, 0);
        break;
      }
      case "matching_event_victory_points": {
        if (!options.definitions || !isRecord(value)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const eventIds = structuredChoiceEvents(options.state, options.player, value, options.definitions);
        resolved = eventIds.reduce((sum, eventId) => {
          const points = Number((options.definitions?.[eventId] as CardDefinition & { victoryPoints?: number } | undefined)?.victoryPoints);
          if (!Number.isInteger(points) || points < 0) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
          return sum + points;
        }, 0);
        break;
      }
      case "selected_player_event_combat_power": {
        const event = isRecord(options.payload) && isRecord(options.payload.event) ? options.payload.event : undefined;
        const powers = isRecord(event?.powers) ? event.powers : undefined;
        const targetPlayerId = isRecord(options.payload) && typeof options.payload.targetPlayerId === "string" ? options.payload.targetPlayerId : undefined;
        const power = targetPlayerId && powers ? powers[targetPlayerId] : undefined;
        if (!Number.isInteger(power)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = Number(power);
        break;
      }
      case "selected_card_count": {
        if (!isRecord(value)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        const payloadKey = typeof value.payloadKey === "string" ? value.payloadKey : "selectedInstanceIds";
        resolved = resolveStructuredCardSelection(options.payload, { payloadKey }, payloadKey).length;
        break;
      }
      default: throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    }
    if (!valid(resolved)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    return resolved;
  }
  if (isRecord(value) && value.type === "formula") {
    const args = Array.isArray(value.args)
      ? value.args.map((arg) => resolveStructuredAmount(arg, { ...options, allowNegative: true }))
      : [];
    const op = value.op;
    let resolved: number;
    switch (op) {
      case "add": resolved = args.reduce((sum, arg) => sum + arg, 0); break;
      case "subtract":
        if (args.length !== 2) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = args[0] - args[1];
        break;
      case "multiply": resolved = args.reduce((product, arg) => product * arg, 1); break;
      case "floor_divide":
        if (args.length !== 2 || args[1] === 0) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = Math.floor(args[0] / args[1]);
        break;
      case "ceil_divide":
        if (args.length !== 2 || args[1] === 0) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = Math.ceil(args[0] / args[1]);
        break;
      case "min":
        if (args.length === 0) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = Math.min(...args);
        break;
      case "max":
        if (args.length === 0) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = Math.max(...args);
        break;
      case "abs":
        if (args.length !== 1) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
        resolved = Math.abs(args[0]);
        break;
      default: throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    }
    if (!valid(resolved)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    return resolved;
  }
  if (isRecord(value) && (value.type === "payload_count" || value.type === "payload-count")) {
    const key = typeof value.key === "string" ? value.key : undefined;
    const payloadValue = key && isRecord(options.payload) && Array.isArray(options.payload[key])
      ? options.payload[key].length
      : key && isRecord(options.payload) && isRecord(options.payload.data) && Array.isArray(options.payload.data[key])
        ? options.payload.data[key].length
        : key && isRecord(options.payload) && isRecord(options.payload.event) && isRecord(options.payload.event.data) && Array.isArray(options.payload.event.data[key])
          ? options.payload.event.data[key].length
          : undefined;
    const multiply = Number(value.multiply ?? 1);
    const add = Number(value.add ?? 0);
    const min = Number(value.min ?? (options.allowNegative === true ? Number.NEGATIVE_INFINITY : 0));
    const max = Number(value.max ?? Number.POSITIVE_INFINITY);
    if (payloadValue === undefined || !Number.isFinite(multiply) || !Number.isFinite(add)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    const resolved = payloadValue * multiply + add;
    if (!valid(resolved) || resolved < min || resolved > max) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    return resolved;
  }
  if (isRecord(value) && (value.type === "payload_number" || value.type === "payload-number" || value.type === "payload_number_plus" || value.type === "payload-number-plus")) {
    const key = typeof value.key === "string" ? value.key : undefined;
    const payloadValue = key && isRecord(options.payload) && Number.isInteger(options.payload[key])
      ? Number(options.payload[key])
      : key && isRecord(options.payload) && isRecord(options.payload.data) && Number.isInteger(options.payload.data[key])
        ? Number(options.payload.data[key])
        : key && isRecord(options.payload) && isRecord(options.payload.scheduled) && Number.isInteger(options.payload.scheduled[key])
          ? Number(options.payload.scheduled[key])
          : undefined;
    const add = Number(value.add ?? 0);
    const multiply = Number(value.multiply ?? 1);
    const min = Number(value.min ?? (options.allowNegative === true ? Number.NEGATIVE_INFINITY : 0));
    const max = Number(value.max ?? Number.POSITIVE_INFINITY);
    if (payloadValue === undefined || !Number.isFinite(add) || !Number.isFinite(multiply)) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    const resolved = payloadValue * multiply + add;
    if (!valid(resolved) || resolved < min || resolved > max) throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
    return resolved;
  }
  throw new Error("STRUCTURED_SKILL_AMOUNT_INVALID");
}

function resolveStructuredTargetPlayerIds(
  state: GameState,
  player: GameState["players"][string],
  payload: unknown,
  target: unknown,
  definitions?: Record<string, CardDefinition>,
): string[] {
  if (target === undefined || target === "controller") return [player.id];
  if (target === "selected_player") return [resolveStructuredSelectedPlayerId(state, player, payload)];
  if (target === "decision_player") {
    const decisionPlayerId = isRecord(payload) && typeof payload.decisionPlayerId === "string" ? payload.decisionPlayerId : undefined;
    if (!decisionPlayerId || !state.players[decisionPlayerId] || state.players[decisionPlayerId].eliminated) throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
    return [decisionPlayerId];
  }

  if (typeof target === "string" && state.players[target]) {
    const targetPlayer = state.players[target];
    if (targetPlayer.eliminated) throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
    return [target];
  }
  const scope = isRecord(target) && typeof target.scope === "string" ? target.scope : typeof target === "string" ? target : undefined;
  let targetPlayerIds: string[];
  switch (scope) {
    case "controller":
      targetPlayerIds = [player.id];
      break;
    case "selected_any_player":
      targetPlayerIds = [resolveStructuredSelectedPlayerId(state, player, payload, { allowSelf: true })];
      break;
    case "selected_player":
      targetPlayerIds = [resolveStructuredSelectedPlayerId(state, player, payload)];
      break;
    case "selected_players": {
      const selected = isRecord(payload) && Array.isArray(payload.targetPlayerIds) ? payload.targetPlayerIds : [];
      targetPlayerIds = selected.filter((id): id is string => typeof id === "string" && id !== player.id && Boolean(state.players[id]) && !state.players[id].eliminated);
      if (targetPlayerIds.length !== selected.length) throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
      break;
    }
    case "selected_same_location_player": {
      const targetPlayerId = resolveStructuredSelectedPlayerId(state, player, payload, { allowSelf: true });
      if (!(state.board.locations[player.locationId] ?? []).includes(targetPlayerId)) {
        throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
      }
      targetPlayerIds = [targetPlayerId];
      break;
    }
    case "selected_same_battlefield_player": {
      const targetPlayerId = resolveStructuredSelectedPlayerId(state, player, payload, { allowSelf: true });
      if ((player.locationId !== "mountain" && player.locationId !== "city")
        || !(state.board.locations[player.locationId] ?? []).includes(targetPlayerId)) {
        throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
      }
      targetPlayerIds = [targetPlayerId];
      break;
    }
    case "selected_same_battlefield_opponent": {
      const targetPlayerId = resolveStructuredSelectedPlayerId(state, player, payload);
      if (player.locationId !== "mountain" && player.locationId !== "city"
        || !sameBattlefieldOpponentIds(state, player.id, player.locationId).includes(targetPlayerId)) {
        throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
      }
      targetPlayerIds = [targetPlayerId];
      break;
    }
    case "same_location_players":
      targetPlayerIds = (state.board.locations[player.locationId] ?? [])
        .filter((id) => !state.players[id]?.eliminated);
      break;
    case "same_battlefield_players":
      targetPlayerIds = (player.locationId !== "mountain" && player.locationId !== "city")
        ? []
        : (state.board.locations[player.locationId] ?? []).filter((id) => !state.players[id]?.eliminated);
      break;
    case "same_location_opponents":
      targetPlayerIds = (state.board.locations[player.locationId] ?? [])
        .filter((id) => id !== player.id && !state.players[id]?.eliminated);
      break;
    case "same_battlefield_opponents":
    case "engaged_opponents": {
      targetPlayerIds = player.locationId !== "mountain" && player.locationId !== "city"
        ? []
        : sameBattlefieldOpponentIds(state, player.id, player.locationId);
      break;
    }
    case "event_player": {
      const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
      const eventPlayerId = typeof event?.playerId === "string" ? event.playerId : undefined;
      if (!eventPlayerId || !state.players[eventPlayerId] || state.players[eventPlayerId].eliminated) {
        throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
      }
      targetPlayerIds = [eventPlayerId];
      break;
    }
    case "event_combat_winners":
    case "combat_winners": {
      const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
      const winnerIds = Array.isArray(event?.winnerIds) ? event.winnerIds : [];
      targetPlayerIds = winnerIds.filter((id): id is string => typeof id === "string" && Boolean(state.players[id]) && !state.players[id].eliminated);
      break;
    }
    case "event_defeated_players": {
      const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
      const defeatedPlayerIds = Array.isArray(event?.defeatedPlayerIds) ? event.defeatedPlayerIds : [];
      targetPlayerIds = defeatedPlayerIds.filter((id): id is string => typeof id === "string" && Boolean(state.players[id]));
      break;
    }
    case "event_combat_losers":
    case "combat_losers": {
      const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
      const winnerIds = Array.isArray(event?.winnerIds) ? event.winnerIds : [];
      const powers = isRecord(event?.powers) ? event.powers : {};
      // Event targets are derived from the frozen combat payload. Do not drop a loser merely because a later
      // settlement step marked them eliminated before passive processing.
      targetPlayerIds = Object.keys(powers).filter((id) => !winnerIds.includes(id) && Boolean(state.players[id]));
      break;
    }
    case "event_combat_opponents": {
      const event = isRecord(payload) && isRecord(payload.event) ? payload.event : undefined;
      const powers = isRecord(event?.powers) ? event.powers : {};
      if (!Object.prototype.hasOwnProperty.call(powers, player.id)) throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
      targetPlayerIds = Object.keys(powers).filter((id) => id !== player.id && Boolean(state.players[id]) && !state.players[id].eliminated);
      break;
    }
    case "turn_order_next_player": {
      const seat = state.turnOrder.indexOf(player.id);
      if (seat < 0 || state.turnOrder.length < 2) { targetPlayerIds = []; break; }
      let nextId: string | undefined;
      for (let offset = 1; offset < state.turnOrder.length; offset += 1) {
        const candidateId = state.turnOrder[(seat + offset) % state.turnOrder.length];
        if (candidateId !== player.id && state.players[candidateId] && !state.players[candidateId].eliminated) { nextId = candidateId; break; }
      }
      targetPlayerIds = nextId ? [nextId] : [];
      break;
    }
    case "turn_order_after_controller": {
      const seat = state.turnOrder.indexOf(player.id);
      targetPlayerIds = seat < 0 ? [] : state.turnOrder.slice(seat + 1)
        .filter((id) => Boolean(state.players[id]) && !state.players[id].eliminated);
      break;
    }
    case "selected_card_owners": {
      const instanceIds = resolveStructuredCardSelection(payload, target as Record<string, unknown>, "selectedInstanceId");
      targetPlayerIds = [...new Set(instanceIds.map((instanceId) => state.cards[instanceId]?.ownerPlayerId)
        .filter((id): id is string => typeof id === "string" && Boolean(state.players[id]) && !state.players[id].eliminated))];
      break;
    }
    case "source_card_creator": {
      if (!definitions || !isRecord(target) || typeof target.linkedSkillId !== "string") {
        throw new Error("STRUCTURED_SKILL_SOURCE_CARD_INVALID");
      }
      const linkedSkillId = target.linkedSkillId;
      const sourceInstanceId = [...player.attack, ...player.masterSkills, ...player.servantSkills, ...player.hand].find((instanceId) => {
        const instance = state.cards[instanceId];
        const definition = instance ? definitions[instance.definitionId] : undefined;
        return instance?.definitionId === linkedSkillId || definition?.linkedSkillId === linkedSkillId;
      });
      const creatorPlayerId = sourceInstanceId ? state.cards[sourceInstanceId]?.createdByPlayerId : undefined;
      if (!creatorPlayerId || creatorPlayerId === player.id || !state.players[creatorPlayerId] || state.players[creatorPlayerId].eliminated) {
        throw new Error("STRUCTURED_SKILL_SOURCE_CREATOR_INVALID");
      }
      targetPlayerIds = [creatorPlayerId];
      break;
    }
    case "players_with_status": {
      const status = isRecord(target) && typeof target.status === "string" ? target.status : undefined;
      if (!status) throw new Error("STRUCTURED_SKILL_TARGET_STATUS_INVALID");
      targetPlayerIds = Object.values(state.players).filter((candidate) => !candidate.eliminated && candidate.statuses.includes(status)).map((candidate) => candidate.id);
      break;
    }
    case "all_opponents":
      targetPlayerIds = Object.values(state.players)
        .filter((candidate) => candidate.id !== player.id && !candidate.eliminated)
        .map((candidate) => candidate.id);
      break;
    case "all_players":
      targetPlayerIds = Object.values(state.players)
        .filter((candidate) => !candidate.eliminated)
        .map((candidate) => candidate.id);
      break;
    default:
      throw new Error("STRUCTURED_SKILL_TARGET_SCOPE_UNSUPPORTED");
  }
  const filters = isRecord(target) && Array.isArray(target.where) ? target.where : [];
  const filteredPlayerIds = targetPlayerIds.filter((targetPlayerId) => structuredTargetFilterMatches(state, player, targetPlayerId, filters, definitions));
  if (isStructuredSelectedTarget(target) && filteredPlayerIds.length !== targetPlayerIds.length) {
    throw new Error("STRUCTURED_SKILL_TARGET_FILTER_NOT_MET");
  }
  return filteredPlayerIds;
}

function structuredTargetFilterMatches(
  state: GameState,
  player: GameState["players"][string],
  targetPlayerId: string,
  filters: unknown[],
  definitions?: Record<string, CardDefinition>,
): boolean {
  const targetPlayer = state.players[targetPlayerId];
  if (!targetPlayer) return false;
  for (const filter of filters) {
    if (!isRecord(filter)) throw new Error("STRUCTURED_SKILL_TARGET_FILTER_INVALID");
    switch (filter.type) {
      case "player_flag_greater_than_mana_ratio": {
        const key = filter.key;
        const numerator = Number(filter.numerator ?? 1);
        const denominator = Number(filter.denominator ?? 1);
        if (typeof key !== "string" || !key || !Number.isFinite(numerator) || !Number.isFinite(denominator) || denominator === 0) {
          throw new Error("STRUCTURED_SKILL_TARGET_FILTER_INVALID");
        }
        if (!(Number(targetPlayer.flags[key] ?? 0) > targetPlayer.mana * numerator / denominator)) return false;
        break;
      }
      case "player_flag_number_not_current_round": {
        const key = filter.key;
        if (typeof key !== "string" || !key) throw new Error("STRUCTURED_SKILL_TARGET_FILTER_INVALID");
        if (Number(targetPlayer.flags[key] ?? 0) === state.round) return false;
        break;
      }
      case "player_flag_equals_controller_location": {
        const key = filter.key;
        if (typeof key !== "string" || !key) throw new Error("STRUCTURED_SKILL_TARGET_FILTER_INVALID");
        if (targetPlayer.flags[key] !== player.locationId) return false;
        break;
      }
      case "does_not_control_card_definition": {
        if (!definitions) throw new Error("STRUCTURED_SKILL_TARGET_FILTER_INVALID");
        const definitionIds = Array.isArray(filter.definitionIds) ? filter.definitionIds.filter((id): id is string => typeof id === "string") : [];
        const zones = Array.isArray(filter.zones) ? filter.zones.filter((zone): zone is string => typeof zone === "string") : ["attack"];
        if (definitionIds.length === 0) throw new Error("STRUCTURED_SKILL_TARGET_FILTER_INVALID");
        const zoneIds = zones.flatMap((zone) => zone === "attack" ? targetPlayer.attack
          : zone === "hand" ? targetPlayer.hand
            : zone === "deck" ? targetPlayer.deck
              : zone === "discard" ? targetPlayer.discard
                : zone === "master-skills" ? targetPlayer.masterSkills
                  : zone === "servant-skills" ? targetPlayer.servantSkills : []);
        const controls = zoneIds.some((instanceId) => {
          const instance = state.cards[instanceId];
          if (!instance || !definitionIds.includes(instance.definitionId)) return false;
          if (filter.activeOnly === true && !instance.active) return false;
          if (filter.face === "up" && instance.face !== "up") return false;
          if (filter.face === "down" && instance.face !== "down") return false;
          return true;
        });
        if (controls) return false;
        break;
      }
      case "face_up_cards_played_this_round_at_least": {
        const count = Number(filter.count ?? 1);
        if (!Number.isInteger(count) || count < 0) throw new Error("STRUCTURED_SKILL_TARGET_FILTER_INVALID");
        if (Number(targetPlayer.flags.faceUpCardsPlayedThisRound ?? 0) < count) return false;
        break;
      }
      case "no_attack_played_this_round_with_attribute": {
        if (!definitions || typeof filter.attribute !== "string") throw new Error("STRUCTURED_SKILL_TARGET_FILTER_INVALID");
        const matched = targetPlayer.attack.some((instanceId) => {
          const instance = state.cards[instanceId];
          const definition = instance ? definitions[instance.definitionId] : undefined;
          return instance?.playedRound === state.round && Boolean(definition) && getCardAttributes(definition!).includes(filter.attribute as never);
        });
        if (matched) return false;
        break;
      }
      default:
        throw new Error("STRUCTURED_SKILL_TARGET_FILTER_UNSUPPORTED");
    }
  }
  return true;
}

function resolveStructuredSelectedPlayerId(
  state: GameState,
  player: GameState["players"][string],
  payload: unknown,
  options: { allowSelf?: boolean } = {},
): string {
  const targetPlayerId = isRecord(payload) && typeof payload.targetPlayerId === "string"
    ? payload.targetPlayerId
    : isRecord(payload) && isRecord(payload.data) && typeof payload.data.targetPlayerId === "string"
      ? payload.data.targetPlayerId
      : isRecord(payload) && isRecord(payload.event) && isRecord(payload.event.data) && typeof payload.event.data.targetPlayerId === "string"
        ? payload.event.data.targetPlayerId
        : isRecord(payload) && isRecord(payload.scheduled) && typeof payload.scheduled.targetPlayerId === "string"
          ? payload.scheduled.targetPlayerId
          : undefined;
  if (!targetPlayerId || (targetPlayerId === player.id && !options.allowSelf) || !state.players[targetPlayerId] || state.players[targetPlayerId].eliminated) {
    throw new Error("STRUCTURED_SKILL_TARGET_PLAYER_INVALID");
  }
  return targetPlayerId;
}

function findStructuredSourceInstanceId(
  state: GameState,
  player: GameState["players"][string],
  skillId: string,
  payload: unknown,
): string | undefined {
  const explicit = isRecord(payload) && typeof payload.sourceInstanceId === "string"
    ? payload.sourceInstanceId
    : isRecord(payload) && isRecord(payload.event) && typeof payload.event.instanceId === "string"
      ? payload.event.instanceId
      : undefined;
  if (explicit && state.cards[explicit]?.ownerPlayerId === player.id) return explicit;
  return [...player.attack, ...player.masterSkills, ...player.servantSkills].find((instanceId) => {
    const instance = state.cards[instanceId];
    return instance?.definitionId === skillId || instance?.definitionId === `card.skill.${skillId}`;
  });
}

function resolveStructuredSourceInstanceId(
  state: GameState,
  player: GameState["players"][string],
  payload: unknown,
  skill?: { id: string },
): string {
  const sourceInstanceId = isRecord(payload) && typeof payload.sourceInstanceId === "string"
    ? payload.sourceInstanceId
    : isRecord(payload) && isRecord(payload.event) && typeof payload.event.instanceId === "string"
      ? payload.event.instanceId
      : isRecord(payload) && isRecord(payload.scheduled) && typeof payload.scheduled.sourceInstanceId === "string"
        ? payload.scheduled.sourceInstanceId
        : skill
          ? [...player.attack, ...player.masterSkills, ...player.servantSkills, ...player.hand].find((instanceId) => {
            const instance = state.cards[instanceId];
            return instance?.definitionId === skill.id || instance?.definitionId === `card.skill.${skill.id}`;
          })
          : undefined;
  const instance = sourceInstanceId ? state.cards[sourceInstanceId] : undefined;
  if (!sourceInstanceId || !instance || instance.ownerPlayerId !== player.id) throw new Error("STRUCTURED_SKILL_SOURCE_CARD_INVALID");
  return sourceInstanceId;
}

type StructuredChoiceOption = Record<string, unknown> & { id: string };

function resolveStructuredChoiceOption(
  state: GameState,
  player: GameState["players"][string],
  skillId: string,
  effect: Record<string, unknown>,
  payload: unknown,
): StructuredChoiceOption {
  const options = Array.isArray(effect.options) ? effect.options.filter(isRecord) : [];
  if (options.length === 0) throw new Error("STRUCTURED_SKILL_CHOICE_OPTIONS_REQUIRED");
  const selectedId = resolveStructuredChoiceId(payload);
  if (!selectedId) throw new Error("STRUCTURED_SKILL_CHOICE_REQUIRED");
  const option = options.find((item): item is StructuredChoiceOption => typeof item.id === "string" && item.id === selectedId);
  if (!option) throw new Error("STRUCTURED_SKILL_CHOICE_INVALID");
  if (isStructuredChoiceAlreadyUsed(state, player, skillId, effect, option.id)) throw new Error("STRUCTURED_SKILL_CHOICE_ALREADY_USED");
  try {
    assertStructuredConditions(state, player, { id: skillId }, Array.isArray(option.conditions) ? option.conditions.filter(isRecord) : [], payload);
  } catch {
    throw new Error("STRUCTURED_SKILL_CHOICE_UNAVAILABLE");
  }
  return option;
}

function resolveStructuredChoiceId(payload: unknown): string | undefined {
  if (!isRecord(payload)) return undefined;
  if (typeof payload.choiceId === "string") return payload.choiceId;
  if (typeof payload.optionId === "string") return payload.optionId;
  if (isRecord(payload.choice) && typeof payload.choice.optionId === "string") return payload.choice.optionId;
  if (isRecord(payload.data)) {
    if (typeof payload.data.choiceId === "string") return payload.data.choiceId;
    if (typeof payload.data.optionId === "string") return payload.data.optionId;
  }
  const decision = isRecord(payload.decision) ? payload.decision : isRecord(payload.data) && isRecord(payload.data.decision) ? payload.data.decision : undefined;
  if (decision && Array.isArray(decision.selections) && typeof decision.selections[0] === "string") return decision.selections[0];
  if (isRecord(payload.event) && isRecord(payload.event.data)) return resolveStructuredChoiceId(payload.event.data);
  return undefined;
}

function structuredChoiceRecordKey(skillId: string, effect: Record<string, unknown>, optionId: string): string | undefined {
  const record = isRecord(effect.recordChoice) ? effect.recordChoice : undefined;
  if (!record) return undefined;
  const scopeKey = typeof record.key === "string" && record.key.length > 0
    ? record.key
    : typeof effect.id === "string" && effect.id.length > 0
      ? effect.id
      : undefined;
  return scopeKey ? `structuredChoice:${skillId}:${scopeKey}:${optionId}` : undefined;
}

function isStructuredChoiceAlreadyUsed(
  state: GameState,
  player: GameState["players"][string],
  skillId: string,
  effect: Record<string, unknown>,
  optionId: string,
): boolean {
  const key = structuredChoiceRecordKey(skillId, effect, optionId);
  if (!key) return false;
  const record = isRecord(effect.recordChoice) ? effect.recordChoice : undefined;
  const value = player.flags[key];
  return record?.scope === "round" ? value === state.round : value === true;
}

function rememberStructuredChoice(
  state: GameState,
  player: GameState["players"][string],
  skillId: string,
  effect: Record<string, unknown>,
  optionId: string,
): void {
  const key = structuredChoiceRecordKey(skillId, effect, optionId);
  if (!key) return;
  const record = isRecord(effect.recordChoice) ? effect.recordChoice : undefined;
  player.flags[key] = record?.scope === "round" ? state.round : true;
  if (record?.scope === "round") player.flags[`structuredRoundFlag:${key}`] = state.round;
  if (record?.scope === "until_source_closed") {
    const sourceInstanceId = findStructuredSourceInstanceId(state, player, skillId, undefined);
    if (!sourceInstanceId) throw new Error("STRUCTURED_SKILL_CHOICE_SOURCE_REQUIRED");
    player.flags[`structuredChoiceResetOnClose:${sourceInstanceId}:${key}`] = true;
  }
}

function forgetStructuredChoice(
  player: GameState["players"][string],
  skillId: string,
  effect: Record<string, unknown>,
  optionId: string,
): void {
  const key = structuredChoiceRecordKey(skillId, effect, optionId);
  if (!key) return;
  delete player.flags[key];
  const suffix = `:${key}`;
  for (const flagKey of Object.keys(player.flags)) {
    if (flagKey.startsWith("structuredChoiceResetOnClose:") && flagKey.endsWith(suffix)) delete player.flags[flagKey];
  }
}

function hasStructuredSelectionPayload(payload: unknown, effect: Record<string, unknown>, fallbackKey: string): boolean {
  if (!isRecord(payload)) return false;
  const key = typeof effect.payloadKey === "string" && effect.payloadKey.length > 0 ? effect.payloadKey : fallbackKey;
  const value = payload[key] ?? payload[fallbackKey];
  return typeof value === "string" || Array.isArray(value);
}

function resolveStructuredCardSelection(payload: unknown, effect: Record<string, unknown>, defaultPayloadKey: string): string[] {
  const payloadKey = typeof effect.payloadKey === "string" && effect.payloadKey.length > 0 ? effect.payloadKey : defaultPayloadKey;
  const values = isRecord(payload) && typeof payload[payloadKey] === "string"
    ? [payload[payloadKey]]
    : isRecord(payload) && Array.isArray(payload[payloadKey])
    ? payload[payloadKey]
    : isRecord(payload) && isRecord(payload.data) && typeof payload.data[payloadKey] === "string"
      ? [payload.data[payloadKey]]
      : isRecord(payload) && isRecord(payload.data) && Array.isArray(payload.data[payloadKey])
        ? payload.data[payloadKey]
        : isRecord(payload) && isRecord(payload.event) && isRecord(payload.event.data) && typeof payload.event.data[payloadKey] === "string"
          ? [payload.event.data[payloadKey]]
          : isRecord(payload) && isRecord(payload.event) && isRecord(payload.event.data) && Array.isArray(payload.event.data[payloadKey])
            ? payload.event.data[payloadKey]
            : undefined;
  if (!values || values.some((value) => typeof value !== "string")) throw new Error("STRUCTURED_SKILL_CARD_SELECTION_INVALID");
  const instanceIds = values as string[];
  if (new Set(instanceIds).size !== instanceIds.length) throw new Error("STRUCTURED_SKILL_CARD_SELECTION_DUPLICATE");
  return instanceIds;
}

function resolveStructuredOptionalCardSelection(payload: unknown, effect: Record<string, unknown>, defaultPayloadKey: string): string[] | undefined {
  try {
    return resolveStructuredCardSelection(payload, effect, defaultPayloadKey);
  } catch (error) {
    if (error instanceof Error && error.message === "STRUCTURED_SKILL_CARD_SELECTION_INVALID") return undefined;
    throw error;
  }
}

function assertStructuredSelectionCount(instanceIds: string[], effect: Record<string, unknown>): void {
  const count = Number.isInteger(effect.count) ? Number(effect.count) : undefined;
  const min = Number.isInteger(effect.minCount) ? Number(effect.minCount)
    : Number.isInteger(effect.min) ? Number(effect.min)
      : count ?? 0;
  const max = effect.maxCount === "all" || effect.max === "all" ? instanceIds.length
    : Number.isInteger(effect.maxCount) ? Number(effect.maxCount)
      : Number.isInteger(effect.max) ? Number(effect.max)
        : count ?? instanceIds.length;
  if (min < 0 || max < min) throw new Error("STRUCTURED_SKILL_CARD_SELECTION_COUNT_INVALID");
  if (instanceIds.length < min || instanceIds.length > max) throw new Error("STRUCTURED_SKILL_CARD_SELECTION_COUNT_INVALID");
}

function isCardInStructuredPlayerZone(player: GameState["players"][string], instanceId: string, zone: string): boolean {
  switch (zone) {
    case "hand":
      return player.hand.includes(instanceId);
    case "deck":
      return player.deck.includes(instanceId);
    case "discard":
      return player.discard.includes(instanceId);
    case "attack":
      return player.attack.includes(instanceId);
    case "master-skills":
    case "masterSkills":
      return player.masterSkills.includes(instanceId);
    case "servant-skills":
    case "servantSkills":
      return player.servantSkills.includes(instanceId);
    default:
      throw new Error("STRUCTURED_SKILL_CARD_ZONE_UNSUPPORTED");
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}
